}

export async function analyzeLogoForBranding(logo: ImageFile): Promise<{ colors: string[] }> {
  const model = 'gemini-2.5-flash';

  const imagePart = {
    inlineData: {
      data: logo.base64,
      mimeType: logo.mimeType,
    },
  };

  const textPart = {
    text: "Analyze the provided logo image and identify its main color palette. Extract up to 5 primary and secondary colors. Return the response as a JSON object with a single key 'colors', which is an array of hex color code strings (e.g., {\"colors\": [\"#FFFFFF\", \"#000000\"]}).",
  };

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: model,
      contents: { parts: [imagePart, textPart] },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            colors: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          }
        }
      },
      safetySettings: safetySettings,
    });

    if(!response.text) {
      const safetyText = response.candidates?.[0]?.finishReason;
      if (safetyText && safetyText !== 'STOP') {
          throw new Error(`Logo analysis failed due to safety settings: ${safetyText}`);
      }
      throw new Error('Model returned no data for logo analysis.');
    }

    const result = JSON.parse(response.text.trim());
    if (result && Array.isArray(result.colors)) {
        return result;
    } else {
        throw new Error("Invalid JSON format from logo analysis.");
    }

  } catch (error) {
    console.error('Error analyzing logo:', error);
    let errorMessage = 'An unknown error occurred while analyzing the logo.';
    if (error instanceof Error) {
        const msg = error.message.toLowerCase();
        if (msg.includes('api key not valid')) {
            errorMessage = 'Your API key is not valid. Please check your API key and try again.';
        } else if (msg.includes('quota')) {
            errorMessage = 'You have exceeded your API quota. Please check your billing account or try again later.';
        } else if (msg.includes('safety settings')) {
            errorMessage = `Logo analysis was blocked due to safety settings.`;
        } else if (msg.includes('json')) {
            errorMessage = `Failed to parse analysis response. The model may have returned invalid JSON.`;
        } else {
             errorMessage = `Failed to analyze logo. Details: ${error.message}`;
        }
    }
    throw new Error(errorMessage);
  }
}

export async function generateSpeech(text: string, styleInstructions: string, voiceName: string): Promise<AudioFile> {
  const model = 'gemini-2.5-flash-preview-tts';

  let instructions = "Read aloud in a warm and friendly tone";
  if (styleInstructions.trim()) {
      instructions += ` ${styleInstructions.trim()}`;
  }

  const promptText = `${instructions}: ${text}`;

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: [{ parts: [{ text: promptText }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: voiceName },
          },
        },
      },
      safetySettings: safetySettings,
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

    if (base64Audio) {
      return {
        base64: base64Audio,
        name: 'generated-audio.wav',
      };
    }

    const safetyText = response.candidates?.[0]?.finishReason;
    if (safetyText && safetyText !== 'STOP') {
      throw new Error(`Audio generation failed due to safety settings: ${safetyText}`);
    }

    throw new Error('No audio was generated by the model.');

  } catch (error) {
    console.error('Error calling Gemini API for speech generation:', error);
    let errorMessage = 'An unknown error occurred while generating the audio.';
    if (error instanceof Error) {
      const msg = error.message.toLowerCase();
      if (msg.includes('api key not valid')) {
        errorMessage = 'Your API key is not valid. Please check your API key and try again.';
      } else if (msg.includes('quota')) {
        errorMessage = 'You have exceeded your API quota. Please check your billing account or try again later.';
      } else if (msg.includes('safety settings')) {
        errorMessage = `Audio generation was blocked due to safety settings. Please adjust your text.`;
      } else {
        errorMessage = `Failed to generate audio. Details: ${error.message}`;
      }
    }
    throw new Error(errorMessage);
  }
}

export async function analyzeProductForCampaign(productImages: ImageFile[]): Promise<string> {
    const model = 'gemini-2.5-flash';

    const parts: Part[] = [];
    productImages.forEach(img => {
      parts.push({
        inlineData: {
          data: img.base64,
          mimeType: img.mimeType,
        }
      });
    });

    const prompt = `Analyze these product image(s). Identify the product type, its likely target audience, and the best environment for it. 
    Return a concise 2-sentence description describing the product and a suitable lifestyle context. 
    Example: "This is a premium organic face serum in a dropper bottle. It fits perfectly in a minimalist, spa-like bathroom setting with soft lighting and natural elements."`;

    parts.push({ text: prompt });

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: model,
            contents: { parts: parts },
            safetySettings: safetySettings,
        });

        if (!response.text) {
             throw new Error('Model returned no analysis text.');
        }

        return response.text.trim();

    } catch (error) {
        console.error('Error analyzing product for campaign:', error);
        throw new Error('Failed to analyze product category.');
    }
}

import React, { useCallback, useEffect } from 'react';
import { CampaignStudioProject, ImageFile, CampaignResult, CampaignScenario } from '../types';
import { resizeImage } from '../utils';
import { analyzeProductForCampaign, generateImage, editImage } from '../services/geminiService';
import ImageWorkspace from './ImageWorkspace';
import BrandingResultsGrid from './BrandingResultsGrid'; // Resuing similar grid layout

const CAMPAIGN_SCENARIOS: CampaignScenario[] = [
    'Front View (Hero)', '45° Angle (Depth)', 'Top-Down (Flat Lay)', 
    'Close-Up (Texture)', 'Lifestyle (In Context)', 'Creative (Artistic)'
];

// Helper to construct prompts based on the analyzed product context + specific angles for Instagram
const getCampaignPrompt = (scenario: CampaignScenario, productContext: string): string => {
    const baseRequirement = `Create a high-quality, professional Instagram Feed photo (4:5 aspect ratio) featuring the product described as: "${productContext}". Do not include any text or logos overlay. `;

    switch (scenario) {
        case 'Front View (Hero)':
            return baseRequirement + `Scene: A perfectly symmetrical, eye-level hero shot of the product. Clean, studio lighting that highlights the product's shape and branding. Background should be simple or a subtle gradient that matches the product's color palette.`;
        case '45° Angle (Depth)':
            return baseRequirement + `Scene: A 3/4 angle shot showing the product's depth and dimension. Good for showing packaging details. Soft, directional lighting to create gentle shadows.`;
        case 'Top-Down (Flat Lay)':
            return baseRequirement + `Scene: An artistic top-down flat lay composition. Arrange the product with complementary props (ingredients, tools, or decor items) on a textured surface. The composition should be balanced and aesthetically pleasing for a Pinterest/Instagram style post.`;
        case 'Close-Up (Texture)':
            return baseRequirement + `Scene: An extreme close-up (macro shot) focusing on the texture, material, and premium details of the product. The depth of field should be shallow (bokeh effect) to blur the background completely. Highlight the quality of the build or ingredients.`;
        case 'Lifestyle (In Context)':
             return baseRequirement + `Scene: Place the product in its ideal natural environment (e.g., a home, office, gym, or nature) where it belongs. The lighting should be natural and inviting. The mood is aspirational. Focus on how the product fits into a daily routine.`;
        case 'Creative (Artistic)':
             return baseRequirement + `Scene: A creative, artistic composition. Use dynamic lighting, interesting shadows, or a unique prop setup to make the product stand out. This should look like a high-end editorial campaign shot.`;
        default:
            return baseRequirement;
    }
};

const GreenCheckIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-green-500 flex-shrink-0 mt-0.5" viewBox="0 0 20 20" fill="currentColor">
        <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
    </svg>
);

const CampaignStudio: React.FC<{
    project: CampaignStudioProject;
    setProject: React.Dispatch<React.SetStateAction<CampaignStudioProject>>;
}> = ({ project, setProject }) => {

    const handleFileUpload = async (files: File[]) => {
        if (!files || files.length === 0) return;

        setProject(s => ({ ...s, isUploading: true, error: null }));
        let currentError: string | null = null;

        const filePromises = files.map(file => {
            return new Promise<ImageFile | null>(async (resolve) => {
                if (!file.type.startsWith('image/')) {
                    if (!currentError) currentError = `File '${file.name}' is not a supported image type.`;
                    resolve(null);
                    return;
                }
                try {
                    const resizedFile = await resizeImage(file, 2048, 2048);
                    const reader = new FileReader();
                    reader.onloadend = () => {
                        const base64String = reader.result as string;
                        resolve({
                            base64: base64String.split(',')[1],
                            mimeType: resizedFile.type,
                            name: resizedFile.name
                        });
                    };
                    reader.onerror = () => {
                        if (!currentError) currentError = `Error reading file '${resizedFile.name}'.`;
                        resolve(null);
                    };
                    reader.readAsDataURL(resizedFile);
                } catch (err) {
                    console.error(`Error processing ${file.name}:`, err);
                    if (!currentError) currentError = `Could not process file '${file.name}'.`;
                    resolve(null);
                }
            });
        });

        const results = await Promise.all(filePromises);
        const validImages = results.filter((img): img is ImageFile => img !== null);

        setProject(s => ({
            ...s,
            productImages: [...s.productImages, ...validImages],
            error: currentError,
            isUploading: false,
            // Reset results if it's the first upload, but allow adding more without reset if desired. 
            // For now, let's keep previous results unless manually cleared or generated again.
        }));
    };

    // Paste event listener
    useEffect(() => {
        const handlePaste = (e: ClipboardEvent) => {
            if (e.clipboardData && e.clipboardData.files.length > 0) {
                e.preventDefault();
                const files = Array.from(e.clipboardData.files);
                handleFileUpload(files);
            }
        };

        window.addEventListener('paste', handlePaste);
        return () => window.removeEventListener('paste', handlePaste);
    }, []);

    const handleRemoveImage = (index: number) => {
        setProject(s => {
            const newImages = s.productImages.filter((_, i) => i !== index);
            return { 
                ...s, 
                productImages: newImages,
                // If all images removed, clear analysis
                productAnalysis: newImages.length === 0 ? null : s.productAnalysis,
                results: newImages.length === 0 ? [] : s.results
            };
        });
    };

    const onGenerate = useCallback(async () => {
        if (project.productImages.length === 0) {
            setProject(s => ({ ...s, error: 'Please upload at least one product image.' }));
            return;
        }

        setProject(s => ({ ...s, isAnalyzing: true, isGenerating: true, error: null, results: [] }));

        try {
            // 1. Analyze the product (using all uploaded images)
            let analysis = project.productAnalysis;
            if (!analysis) {
                analysis = await analyzeProductForCampaign(project.productImages);
                setProject(s => ({ ...s, productAnalysis: analysis, isAnalyzing: false }));
            } else {
                setProject(s => ({ ...s, isAnalyzing: false }));
            }

            // 2. Initialize placeholders for the 6 specific angles
            const initialResults = CAMPAIGN_SCENARIOS.map(scenario => ({
                scenario, image: null, isLoading: true, error: null, editPrompt: '', isEditing: false
            } as any)); // cast to match generic structure

            setProject(s => ({ ...s, results: initialResults }));

            // 3. Generate images in parallel
            const generationPromises = CAMPAIGN_SCENARIOS.map(scenario => {
                const prompt = getCampaignPrompt(scenario, analysis!);
                // Pass all product images to the generator
                return generateImage(project.productImages, prompt, null)
                    .then(image => ({ status: 'fulfilled' as const, value: { scenario, image } }))
                    .catch(error => ({ status: 'rejected' as const, reason: { scenario, error } }));
            });

            const settledResults = await Promise.all(generationPromises);

            settledResults.forEach(result => {
                if (result.status === 'fulfilled') {
                    const { scenario, image } = result.value;
                    setProject(s => ({
                        ...s,
                        results: s.results.map(r => r.scenario === scenario ? { ...r, image, isLoading: false } : r)
                    }));
                } else {
                    const { scenario, error } = result.reason;
                    setProject(s => ({
                        ...s,
                        results: s.results.map(r => r.scenario === scenario ? { ...r, error: error.message || 'Failed', isLoading: false } : r)
                    }));
                }
            });

        } catch (err) {
            const errorMessage = err instanceof Error ? err.message : 'An error occurred during campaign generation.';
            setProject(s => ({ ...s, error: errorMessage, isAnalyzing: false }));
        } finally {
            setProject(s => ({ ...s, isGenerating: false }));
        }

    }, [project.productImages, project.productAnalysis, setProject]);

    const handleImageEdit = async (scenario: CampaignScenario) => {
        const resultToEdit = project.results.find(r => r.scenario === scenario);
        if (!resultToEdit || !resultToEdit.image || !resultToEdit.editPrompt.trim()) return;

        setProject(s => ({ ...s, results: s.results.map(r => r.scenario === scenario ? { ...r, isEditing: true, error: null } : r) }));
        try {
            const newImage = await editImage(resultToEdit.image, resultToEdit.editPrompt);
            setProject(s => ({ ...s, results: s.results.map(r => r.scenario === scenario ? { ...r, image: newImage, isEditing: false, editPrompt: '' } : r) }));
        } catch (err) {
            const errorMessage = err instanceof Error ? err.message : 'Edit failed.';
            setProject(s => ({ ...s, results: s.results.map(r => r.scenario === scenario ? { ...r, error: errorMessage, isEditing: false } : r) }));
        }
    };

    const handleSetEditPrompt = (scenario: CampaignScenario, prompt: string) => {
        setProject(s => ({ ...s, results: s.results.map(r => r.scenario === scenario ? { ...r, editPrompt: prompt } : r) }));
    };

    return (
        <main className="w-full max-w-7xl flex flex-col gap-4 pt-4 pb-8 flex-grow">
            {/* Header & Upload */}
            <div className="glass-card rounded-2xl p-4 flex flex-col md:flex-row items-center gap-4">
                <div className="w-full md:w-64 flex-shrink-0">
                    <h3 className="text-sm font-bold text-[var(--color-text-medium)] text-center mb-2">Upload Image(s)</h3>
                    {/* Using ImageWorkspace for multi-upload support */}
                    <div className="w-full">
                         <ImageWorkspace
                            productImages={project.productImages}
                            onProductImagesUpload={handleFileUpload}
                            onProductImageRemove={handleRemoveImage}
                            isUploading={project.isUploading}
                        />
                    </div>
                </div>
                <div className="flex-grow text-center md:text-left self-stretch flex flex-col justify-center">
                    <h2 className="text-xl font-bold text-[var(--color-text-base)]">Instagram Campaign Studio</h2>
                    <p className="text-md text-[var(--color-text-secondary)] mt-1">
                        Upload one or more product photos. You can drag & drop or paste (Ctrl+V) images. 
                        AI will generate 6 unique Instagram feed posts covering different angles and styles.
                    </p>
                    {project.productAnalysis && (
                        <div className="mt-3 p-3 rounded-xl bg-green-500/5 border border-green-500/20 text-left animate-in fade-in duration-500">
                            <h4 className="text-xs font-bold text-green-500 uppercase tracking-wider mb-2 flex items-center gap-1">
                                AI Analysis & Style
                            </h4>
                            <div className="space-y-2">
                                {project.productAnalysis.split('.').filter(s => s.trim().length > 0).map((point, idx) => (
                                    <div key={idx} className="flex items-start gap-2 text-sm text-green-400/90 font-medium">
                                        <GreenCheckIcon />
                                        <span className="leading-tight">{point.trim()}.</span>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}
                </div>
                <div className="w-full md:w-auto flex-shrink-0 self-center">
                    <button
                        onClick={onGenerate}
                        disabled={project.productImages.length === 0 || project.isGenerating || project.isUploading}
                        className="w-full bg-gradient-to-r from-[var(--color-accent)] to-[var(--color-accent-dark)] hover:from-[var(--color-accent-dark)] hover:to-[var(--color-accent-darker)] text-[var(--color-text-base)] font-bold py-3 px-8 rounded-lg text-lg transition-all duration-300 ease-in-out disabled:opacity-50 disabled:cursor-not-allowed shadow-lg hover:shadow-2xl hover:shadow-[var(--color-accent)]/20 disabled:shadow-none transform hover:-translate-y-1 disabled:transform-none whitespace-nowrap"
                    >
                        {project.isUploading ? 'Uploading...' : project.isAnalyzing ? 'Analyzing...' : project.isGenerating ? 'Generating 6 Posts...' : 'Generate 6 Feed Posts'}
                    </button>
                </div>
            </div>

            {project.error && <div className="bg-[rgba(var(--color-accent-rgb),0.2)] border border-[rgba(var(--color-accent-rgb),0.5)] text-[var(--color-accent-light)] px-4 py-3 rounded-lg" role="alert">{project.error}</div>}

            {/* Results */}
            {project.results.length > 0 && (
                <div className="glass-card rounded-2xl p-4">
                     <h3 className="text-xl font-bold text-[var(--color-text-base)] mb-4">Instagram Campaign Assets</h3>
                     <BrandingResultsGrid 
                        results={project.results.map(r => ({ ...r, category: r.scenario as any }))}
                        onImageEdit={(cat) => handleImageEdit(cat as any)}
                        onSetEditPrompt={(cat, p) => handleSetEditPrompt(cat as any, p)}
                     />
                </div>
            )}
        </main>
    );
};

