// Helper to construct prompts based on the analyzed product context + specific angles for Social Media
const getCampaignPrompt = (scenario: CampaignScenario, productContext: string, styleInstruction: string): string => {
    let baseRequirement = `Create a high-quality, professional Social Media Feed photo (4:5 aspect ratio) featuring the product described as: "${productContext}". Do not include any text or logos overlay. `;

    // Append custom style instructions if provided
    if (styleInstruction) {
        baseRequirement += `Style Requirement: ${styleInstruction}. `;
    }

    switch (scenario) {
        case 'Front View (Hero)':
            return baseRequirement + `Scene: A perfectly symmetrical, eye-level hero shot of the product. Clean, studio lighting that highlights the product's shape and branding. Background should be simple or a subtle gradient that matches the product's color palette.`;
        case '45° Angle (Depth)':
            return baseRequirement + `Scene: A 3/4 angle shot showing the product's depth and dimension. Good for showing packaging details. Soft, directional lighting to create gentle shadows.`;
        case 'Top-Down (Flat Lay)':
            return baseRequirement + `Scene: An artistic top-down flat lay composition. Arrange the product with complementary props (ingredients, tools, or decor items) on a textured surface. The composition should be balanced and aesthetically pleasing for a Pinterest/Social Media style post.`;
        case 'Close-Up (Texture)':
            return baseRequirement + `Scene: An extreme close-up (macro shot) focusing on the texture, material, and premium details of the product. The depth of field should be shallow (bokeh effect) to blur the background completely. Highlight the quality of the build or ingredients.`;
        case 'Lifestyle (In Context)':
             return baseRequirement + `Scene: Place the product in its ideal natural environment (e.g., a home, office, gym, or nature) where it belongs. The lighting should be natural and inviting. The mood is aspirational. Focus on how the product fits into a daily routine.`;
        case 'Creative (Artistic)':
             return baseRequirement + `Scene: A creative, artistic composition. Use dynamic lighting, interesting shadows, or a unique prop setup to make the product stand out. This should look like a high-end editorial campaign shot.`;
        default:
            return baseRequirement;
    }
};

