import React, { useState, useRef, useEffect } from 'react';

interface ImageCropperProps {
  file: File;
  onConfirm: (croppedFile: File) => void;
  onCancel: () => void;
}

type AspectRatio = {
    label: string;
    value: number; // width / height
    icon: React.ReactNode;
};

const RATIOS: AspectRatio[] = [
    { 
        label: '1:1', 
        value: 1, 
        icon: <div className="w-5 h-5 border-2 border-current rounded-sm"></div> 
    },
    { 
        label: '4:5', 
        value: 4/5, 
        icon: <div className="w-4 h-5 border-2 border-current rounded-sm"></div> 
    },
    { 
        label: '16:9', 
        value: 16/9, 
        icon: <div className="w-6 h-3.5 border-2 border-current rounded-sm"></div> 
    },
    { 
        label: '9:16', 
        value: 9/16, 
        icon: <div className="w-3.5 h-6 border-2 border-current rounded-sm"></div> 
    },
    { 
        label: '4:3', 
        value: 4/3, 
        icon: <div className="w-5 h-4 border-2 border-current rounded-sm"></div> 
    },
     { 
        label: 'Free', 
        value: 0, 
        icon: <svg xmlns="http://www.w3.org/2000/svg" className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" /></svg> 
    }
];

const ImageCropper: React.FC<ImageCropperProps> = ({ file, onConfirm, onCancel }) => {
    const [imageSrc, setImageSrc] = useState<string | null>(null);
    const [currentRatio, setCurrentRatio] = useState<number>(1); // Default 1:1
    const [scale, setScale] = useState(1);
    const [position, setPosition] = useState({ x: 0, y: 0 });
    const [isDragging, setIsDragging] = useState(false);
    const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

    const imgRef = useRef<HTMLImageElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const reader = new FileReader();
        reader.onload = () => setImageSrc(reader.result as string);
        reader.readAsDataURL(file);
    }, [file]);

    // Reset position when ratio changes
    useEffect(() => {
        setPosition({ x: 0, y: 0 });
        setScale(1);
    }, [currentRatio]);

    const handlePointerDown = (e: React.PointerEvent) => {
        setIsDragging(true);
        setDragStart({ x: e.clientX - position.x, y: e.clientY - position.y });
    };

    const handlePointerMove = (e: React.PointerEvent) => {
        if (!isDragging) return;
        setPosition({
            x: e.clientX - dragStart.x,
            y: e.clientY - dragStart.y
        });
    };

    const handlePointerUp = () => {
        setIsDragging(false);
    };

    const getCroppedImg = async () => {
        if (!imgRef.current || !containerRef.current) return;

        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        const image = imgRef.current;

        // The visible area in the DOM
        const containerRect = containerRef.current.getBoundingClientRect();

        const outputWidth = 1080; // Standardize output width
        const outputHeight = currentRatio === 0 ? 1080 : outputWidth / currentRatio;

        canvas.width = outputWidth;
        canvas.height = outputHeight;

        if (!ctx) return;

        // Clear background
        ctx.fillStyle = '#000000';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // Scale Factor: Output Width / DOM Container Width
        const scaleFactor = outputWidth / containerRect.width;

        ctx.translate(canvas.width / 2, canvas.height / 2);
        ctx.translate(position.x * scaleFactor, position.y * scaleFactor);
        ctx.scale(scale * scaleFactor, scale * scaleFactor);

        const imgRatio = image.naturalWidth / image.naturalHeight;
        let domImgWidth, domImgHeight;

        if (containerRect.width / containerRect.height > imgRatio) {
             domImgHeight = containerRect.height;
             domImgWidth = domImgHeight * imgRatio;
        } else {
             domImgWidth = containerRect.width;
             domImgHeight = domImgWidth / imgRatio;
        }

        ctx.drawImage(
            image, 
            -domImgWidth / 2, 
            -domImgHeight / 2, 
            domImgWidth, 
            domImgHeight
        );

        canvas.toBlob((blob) => {
            if (blob) {
                const newFile = new File([blob], file.name, { type: 'image/jpeg' });
                onConfirm(newFile);
            }
        }, 'image/jpeg', 0.95);
    };

    if (!imageSrc) return null;

    // Viewport dimensions
    const viewportSize = 300;

    // For extreme aspect ratios (like 9:16), height might be too big.
    const maxBoxH = 400;
    const maxBoxW = 350;

    let renderW = maxBoxW;
    let renderH = maxBoxW;

    if (currentRatio !== 0) {
        if (currentRatio > 1) {
             renderW = maxBoxW;
             renderH = maxBoxW / currentRatio;
        } else {
             renderH = maxBoxH;
             renderW = maxBoxH * currentRatio;
        }
    } else {
        // Free mode default (square)
         renderW = 300;
         renderH = 300;
    }

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/90 backdrop-blur-sm p-4">
            <div className="w-full max-w-lg bg-[#1a1a1a] rounded-2xl overflow-hidden flex flex-col shadow-2xl border border-white/10 animate-in fade-in zoom-in-95 duration-200">
                <div className="p-4 border-b border-white/10 flex justify-between items-center">
                    <h3 className="text-white font-bold">Crop Image</h3>
                    <button onClick={onCancel} className="text-white/60 hover:text-white">
                        <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                </div>

                <div className="flex-grow bg-[#0f0f0f] relative overflow-hidden flex items-center justify-center p-8 select-none touch-none h-[500px]">
                    <div 
                        ref={containerRef}
                        className="relative overflow-hidden shadow-[0_0_0_9999px_rgba(0,0,0,0.7)] border-2 border-white/50"
                        style={{ width: renderW, height: renderH }}
                        onPointerDown={handlePointerDown}
                        onPointerMove={handlePointerMove}
                        onPointerUp={handlePointerUp}
                        onPointerLeave={handlePointerUp}
                    >
                        <div 
                            className="w-full h-full flex items-center justify-center"
                        >
                            <img 
                                ref={imgRef}
                                src={imageSrc} 
                                alt="Crop target" 
                                style={{
                                    transform: `translate(${position.x}px, ${position.y}px) scale(${scale})`,
                                    maxHeight: '100%',
                                    maxWidth: '100%',
                                    objectFit: 'contain', // Initial fit
                                    pointerEvents: 'none'
                                }}
                            />
                        </div>
                        {/* Grid Overlay */}
                        <div className="absolute inset-0 pointer-events-none opacity-30">
                            <div className="w-full h-1/3 border-b border-white"></div>
                            <div className="w-full h-1/3 border-b border-white top-2/3 absolute"></div>
                            <div className="h-full w-1/3 border-r border-white absolute top-0"></div>
                            <div className="h-full w-1/3 border-r border-white absolute top-0 left-2/3"></div>
                        </div>
                    </div>
                </div>

                <div className="p-4 bg-[#1a1a1a] flex flex-col gap-4">
                    {/* Zoom Slider */}
                    <div className="flex items-center gap-3 px-2">
                        <span className="text-xs text-white/60">Zoom</span>
                        <input 
                            type="range" 
                            min="0.5" 
                            max="3" 
                            step="0.1" 
                            value={scale} 
                            onChange={(e) => setScale(parseFloat(e.target.value))}
                            className="flex-grow h-1 bg-white/20 rounded-lg appearance-none cursor-pointer accent-[var(--color-accent)]"
                        />
                    </div>

                    {/* Aspect Ratios */}
                    <div className="flex justify-between gap-2 overflow-x-auto pb-2 suggestions-scrollbar">
                        {RATIOS.map(ratio => (
                            <button
                                key={ratio.label}
                                onClick={() => setCurrentRatio(ratio.value)}
                                className={`flex flex-col items-center gap-1 min-w-[3rem] p-2 rounded-lg transition-colors ${
                                    currentRatio === ratio.value 
                                    ? 'bg-white/10 text-[var(--color-accent)]' 
                                    : 'text-white/50 hover:text-white hover:bg-white/5'
                                }`}
                            >
                                {ratio.icon}
                                <span className="text-[10px] font-medium">{ratio.label}</span>
                            </button>
                        ))}
                    </div>

                    <div className="flex gap-3">
                         <button 
                            onClick={() => onConfirm(file)} // Skip crop
                            className="flex-1 py-3 rounded-xl font-bold text-sm bg-white/5 text-white/80 hover:bg-white/10 transition-colors"
                        >
                            Skip
                        </button>
                        <button 
                            onClick={getCroppedImg}
                            className="flex-1 py-3 rounded-xl font-bold text-sm bg-[var(--color-accent)] text-white hover:bg-[var(--color-accent-dark)] transition-colors"
                        >
                            Crop & Upload
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ImageCropper;

import React, { useState } from 'react';
import { ImageFile } from '../types';
