interface ImageUploaderProps {
  onFileUpload: (files: File[]) => void;
  images: ImageFile[];
  title: string;
  id: string;
  multiple?: boolean;
  onRemove?: (index: number) => void;
  isUploading?: boolean;
}

const UploadIcon = () => (
