const LoadingSpinnerSmall = () => (
    <div className="flex justify-center items-center">
        <div className="animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-[var(--color-accent)]"></div>
    </div>
);


const ImageUploader: React.FC<ImageUploaderProps> = ({ onFileUpload, images, title, id, multiple = false, onRemove, isUploading = false }) => {
  const [isDragging, setIsDragging] = useState(false);
  const [fileQueue, setFileQueue] = useState<File[]>([]);
  const [processedFiles, setProcessedFiles] = useState<File[]>([]);
  const [currentFile, setCurrentFile] = useState<File | null>(null);

  const processUploadQueue = (incomingFiles: File[]) => {
      // Start the queue
      setProcessedFiles([]);
      setFileQueue(incomingFiles);
      if (incomingFiles.length > 0) {
          setCurrentFile(incomingFiles[0]);
      }
  };

  const handleDragEnter = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.dataTransfer.items && e.dataTransfer.items.length > 0) {
      setIsDragging(true);
    }
  };

  const handleDragLeave = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
  };

  const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
  };

  const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      const files = Array.from(e.dataTransfer.files).filter((file: File) => file.type.startsWith('image/'));
       if (files.length > 0) {
        if (multiple) {
            processUploadQueue(files);
        } else {
            processUploadQueue([files[0]]);
        }
      }
      e.dataTransfer.clearData();
    }
  };

  const handleInputChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (files && files.length > 0) {
      const imageFiles = Array.from(files).filter((file: File) => file.type.startsWith('image/'));
      if (imageFiles.length > 0) {
        processUploadQueue(imageFiles);
      }
    }
    event.target.value = ''; // Allow re-uploading the same file
  };

  const handleCropConfirm = (croppedFile: File) => {
      const nextProcessed = [...processedFiles, croppedFile];
      setProcessedFiles(nextProcessed);

      const remaining = fileQueue.slice(1);
      setFileQueue(remaining);

      if (remaining.length > 0) {
          setCurrentFile(remaining[0]);
      } else {
          setCurrentFile(null);
          // All done
          onFileUpload(nextProcessed);
      }
  };

  const handleCropCancel = () => {
      setFileQueue([]);
      setProcessedFiles([]);
      setCurrentFile(null);
  };

  return (
    <div 
      className="w-full relative"
      onDragEnter={handleDragEnter}
      onDragLeave={handleDragLeave}
      onDragOver={handleDragOver}
      onDrop={handleDrop}
    >
      <label htmlFor={id} className="cursor-pointer group">
        <div className={`relative border-2 rounded-xl text-center transition-all duration-300 bg-black/10 backdrop-blur-sm flex flex-col justify-center items-center aspect-square ${isDragging ? 'border-solid border-[var(--color-accent)]' : 'border-dashed border-[rgba(var(--color-accent-rgb),0.3)] group-hover:border-[rgba(var(--color-accent-rgb),0.8)]'}`}>
          {images.length > 0 ? (
            <div className="absolute inset-0 w-full h-full group/image">
