        <div className={`relative border-2 rounded-xl text-center transition-all duration-300 bg-black/10 backdrop-blur-sm flex flex-col justify-center items-center aspect-square ${isDragging ? 'border-solid border-[var(--color-accent)]' : 'border-dashed border-[rgba(var(--color-accent-rgb),0.3)] group-hover:border-[rgba(var(--color-accent-rgb),0.8)]'}`}>
          {images.length > 0 ? (
            <div className="absolute inset-0 w-full h-full group/image">
                <img src={`data:${images[0].mimeType};base64,${images[0].base64}`} alt={title} className="w-full h-full object-contain rounded-xl" />
                {onRemove && (
                    <button
                        onClick={(e) => { e.preventDefault(); e.stopPropagation(); onRemove(0); }}
                        className="absolute top-2 right-2 z-10 bg-black/50 text-[var(--color-text-base)] rounded-full p-1 opacity-0 group-hover/image:opacity-100 hover:bg-black/70 transition-all"
                        aria-label={`Remove image`}
                    >
                        <XIcon />
                    </button>
                )}
            </div>
          ) : isUploading ? (
            <div className="flex flex-col items-center p-4">
              <LoadingSpinnerSmall />
              <p className="mt-2 text-sm text-[var(--color-text-secondary)]">Processing...</p>
            </div>
          ) : (
            <div className="flex flex-col items-center p-4">
              <UploadIcon />
              <p className="mt-2 text-sm text-[var(--color-text-secondary)] group-hover:text-[var(--color-text-base)] transition-colors">{title}</p>
              <p className="mt-1 text-xs text-[var(--color-text-muted)]">or drag and drop</p>
            </div>
          )}
        </div>
      </label>
      <input id={id} type="file" className="hidden" accept="image/*" onChange={handleInputChange} multiple={multiple} disabled={isUploading} />
       {isDragging && !isUploading && (
          <div className="absolute inset-0 bg-black/60 flex flex-col items-center justify-center rounded-xl backdrop-blur-sm pointer-events-none">
              <UploadIcon />
              <p className="text-lg text-[var(--color-text-base)] mt-2 font-semibold">Drop image to upload</p>
          </div>
      )}

      {currentFile && (
          <ImageCropper 
            file={currentFile} 
            onConfirm={handleCropConfirm} 
            onCancel={handleCropCancel} 
          />
      )}
    </div>
  );
};

