import React, { useState, useRef, useEffect } from 'react';

interface ImageCropperProps {
  file: File;
  onConfirm: (croppedFile: File) => void;
  onCancel: () => void;
}

type AspectRatio = {
    label: string;
    value: number; // width / height
    icon: React.ReactNode;
};

const RATIOS: AspectRatio[] = [
    { 
        label: '1:1', 
        value: 1, 
        icon: <div className="w-3 h-3 border border-current rounded-[1px]"></div> 
    },
    { 
        label: '4:5', 
        value: 4/5, 
        icon: <div className="w-2.5 h-3 border border-current rounded-[1px]"></div> 
    },
    { 
        label: '16:9', 
        value: 16/9, 
        icon: <div className="w-4 h-2.5 border border-current rounded-[1px]"></div> 
    },
    { 
        label: '9:16', 
        value: 9/16, 
        icon: <div className="w-2.5 h-4 border border-current rounded-[1px]"></div> 
    },
     { 
        label: 'Free', 
        value: 0, 
        icon: <svg xmlns="http://www.w3.org/2000/svg" className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" /></svg> 
    }
];

const CheckIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
    </svg>
);

const XIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
    </svg>
);

const ImageCropper: React.FC<ImageCropperProps> = ({ file, onConfirm, onCancel }) => {
    const [imageSrc, setImageSrc] = useState<string | null>(null);
    const [currentRatio, setCurrentRatio] = useState<number>(1); // Default 1:1
    const [scale, setScale] = useState(1);
    const [position, setPosition] = useState({ x: 0, y: 0 });
    const [isDragging, setIsDragging] = useState(false);
    const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

    const imgRef = useRef<HTMLImageElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const reader = new FileReader();
        reader.onload = () => setImageSrc(reader.result as string);
        reader.readAsDataURL(file);
    }, [file]);

    // Reset position when ratio changes
    useEffect(() => {
        setPosition({ x: 0, y: 0 });
        setScale(1);
    }, [currentRatio]);

    const handlePointerDown = (e: React.PointerEvent) => {
        setIsDragging(true);
        setDragStart({ x: e.clientX - position.x, y: e.clientY - position.y });
    };

    const handlePointerMove = (e: React.PointerEvent) => {
        if (!isDragging) return;
        setPosition({
            x: e.clientX - dragStart.x,
            y: e.clientY - dragStart.y
        });
    };

    const handlePointerUp = () => {
        setIsDragging(false);
    };

    const getCroppedImg = async () => {
        if (!imgRef.current || !containerRef.current) return;

        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        const image = imgRef.current;

        const containerRect = containerRef.current.getBoundingClientRect();

        // Output dimensions
        const outputWidth = 1080;
        const outputHeight = currentRatio === 0 ? 1080 : outputWidth / currentRatio;

        canvas.width = outputWidth;
        canvas.height = outputHeight;

        if (!ctx) return;

        // Fill black background
        ctx.fillStyle = '#000000';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // Scale Factor between DOM display and actual Canvas output
        const scaleFactor = outputWidth / containerRect.width;

        ctx.translate(canvas.width / 2, canvas.height / 2);
        ctx.translate(position.x * scaleFactor, position.y * scaleFactor);
        ctx.scale(scale * scaleFactor, scale * scaleFactor);

        // Determine draw size to cover the crop area based on image aspect ratio
        const imgRatio = image.naturalWidth / image.naturalHeight;
        let domImgWidth, domImgHeight;

        // Logic to cover the container area
        // Note: The container IS the crop area visually in this design
        if (containerRect.width / containerRect.height > imgRatio) {
             domImgHeight = containerRect.height;
             domImgWidth = domImgHeight * imgRatio;
        } else {
             domImgWidth = containerRect.width;
             domImgHeight = domImgWidth / imgRatio;
        }

        ctx.drawImage(
            image, 
            -domImgWidth / 2, 
            -domImgHeight / 2, 
            domImgWidth, 
            domImgHeight
        );

        canvas.toBlob((blob) => {
            if (blob) {
                const newFile = new File([blob], file.name, { type: 'image/jpeg' });
                onConfirm(newFile);
            }
        }, 'image/jpeg', 0.95);
    };

    if (!imageSrc) return null;

    return (
        <div className="absolute inset-0 z-20 bg-black flex flex-col overflow-hidden animate-in fade-in duration-200">
            {/* Crop Area */}
            <div className="flex-grow relative overflow-hidden bg-[#121212] flex items-center justify-center cursor-move touch-none">
                 {/* The visual crop box container */}
                <div 
                    ref={containerRef}
                    className="relative overflow-hidden shadow-2xl border border-white/30"
                    style={{
                         // Dynamic sizing for the crop box within the available space
                         // If ratio is 1, it's a square. If 16:9, wide.
                         // We use percentages relative to parent container for responsiveness
                         width: currentRatio === 0 ? '80%' : currentRatio >= 1 ? '80%' : `${80 * currentRatio}%`,
                         aspectRatio: currentRatio === 0 ? '1/1' : `${currentRatio}`,
                         maxHeight: '80%'
                    }}
                    onPointerDown={handlePointerDown}
                    onPointerMove={handlePointerMove}
                    onPointerUp={handlePointerUp}
                    onPointerLeave={handlePointerUp}
                    onWheel={(e) => {
                         // Optional: Allow zoom with wheel
                         e.preventDefault();
                         const newScale = Math.min(Math.max(0.5, scale - e.deltaY * 0.001), 3);
                         setScale(newScale);
                    }}
                >
                    <div className="w-full h-full flex items-center justify-center">
                        <img 
                            ref={imgRef}
                            src={imageSrc} 
                            alt="Crop target" 
                            style={{
                                transform: `translate(${position.x}px, ${position.y}px) scale(${scale})`,
                                width: '100%',
                                height: '100%',
                                objectFit: 'cover', // This ensures image fills the crop box initially
                                pointerEvents: 'none'
                            }}
                            draggable={false}
                        />
                    </div>
                     {/* Grid lines */}
                    <div className="absolute inset-0 pointer-events-none opacity-20">
                         <div className="w-full h-full grid grid-cols-3 grid-rows-3">
                             <div className="border-r border-b border-white"></div>
                             <div className="border-r border-b border-white"></div>
                             <div className="border-b border-white"></div>
                             <div className="border-r border-b border-white"></div>
                             <div className="border-r border-b border-white"></div>
                             <div className="border-b border-white"></div>
                             <div className="border-r border-white"></div>
                             <div className="border-r border-white"></div>
                             <div></div>
                         </div>
                    </div>
                </div>

                 {/* Instruction overlay (fades out?) - keeping it simple for now */}
            </div>

            {/* Controls Bar */}
            <div className="flex-shrink-0 bg-black/80 backdrop-blur-md border-t border-white/10 p-2 flex flex-col gap-2">
                <div className="flex justify-between items-center gap-2">
                    {/* Ratio Selector */}
                    <div className="flex-grow flex gap-2 overflow-x-auto suggestions-scrollbar items-center pb-1">
                        {RATIOS.map(ratio => (
                            <button
                                key={ratio.label}
                                onClick={() => setCurrentRatio(ratio.value)}
                                className={`flex flex-col items-center justify-center p-1.5 rounded-md transition-all flex-shrink-0 min-w-[36px] ${
                                    currentRatio === ratio.value 
                                    ? 'bg-white text-black scale-105' 
                                    : 'text-white/60 hover:text-white hover:bg-white/10'
                                }`}
                                title={ratio.label}
                            >
                                {ratio.icon}
                                <span className="text-[9px] font-bold mt-0.5">{ratio.label}</span>
                            </button>
                        ))}
                    </div>

                    {/* Actions */}
                    <div className="flex items-center gap-1 pl-2 border-l border-white/10">
                        <button 
                            onClick={onCancel}
                            className="p-2 rounded-full text-white/70 hover:text-red-400 hover:bg-white/5 transition-colors"
                            title="Cancel"
                        >
                            <XIcon />
                        </button>
                        <button 
                            onClick={getCroppedImg}
                            className="p-2 rounded-full bg-[var(--color-accent)] text-white hover:bg-[var(--color-accent-dark)] shadow-lg transition-colors"
                            title="Confirm Crop"
                        >
                            <CheckIcon />
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

