    </svg>
);

const XIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
    </svg>
);

const ImageCropper: React.FC<ImageCropperProps> = ({ file, onConfirm, onCancel }) => {
    const [imageSrc, setImageSrc] = useState<string | null>(null);
    const [currentRatio, setCurrentRatio] = useState<number>(1); // Default 1:1

    // Transform state: x/y are pixels relative to top-left of crop container
    const [transform, setTransform] = useState({ x: 0, y: 0, scale: 1 });
    const [isDragging, setIsDragging] = useState(false);

    // Refs for drag logic
    const dragStartRef = useRef({ x: 0, y: 0 });
    const transformStartRef = useRef({ x: 0, y: 0 });

    const imgRef = useRef<HTMLImageElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const originalSizeRef = useRef({ w: 0, h: 0 });

    useEffect(() => {
        const reader = new FileReader();
        reader.onload = () => setImageSrc(reader.result as string);
        reader.readAsDataURL(file);
    }, [file]);

    // Initialize crop when image loads or ratio changes
    const resetCrop = useCallback(() => {
        if (!containerRef.current || !originalSizeRef.current.w) return;

        const contW = containerRef.current.clientWidth;
        const contH = containerRef.current.clientHeight;
        const imgW = originalSizeRef.current.w;
        const imgH = originalSizeRef.current.h;

        // Calculate "Cover" scale: The image must fill the container
        const scaleX = contW / imgW;
        const scaleY = contH / imgH;
        const scale = Math.max(scaleX, scaleY); // Cover logic

        // Center the image
        const x = (contW - imgW * scale) / 2;
        const y = (contH - imgH * scale) / 2;

        setTransform({ x, y, scale });
    }, []);

    // Trigger reset when ratio changes (after layout update)
    useEffect(() => {
        // Small timeout to allow DOM layout to update based on new aspect ratio style
        const timer = setTimeout(resetCrop, 50);
        return () => clearTimeout(timer);
    }, [currentRatio, resetCrop]);

    const onImageLoad = (e: React.SyntheticEvent<HTMLImageElement>) => {
        const img = e.currentTarget;
        originalSizeRef.current = { w: img.naturalWidth, h: img.naturalHeight };

        // If "Original" ratio is selected (value 0), update currentRatio based on image
        if (currentRatio === 0) {
             // We don't change state here to avoid loops, just let the render logic handle it
        }
        resetCrop();
    };

    const handlePointerDown = (e: React.PointerEvent) => {
        e.preventDefault();
        setIsDragging(true);
        dragStartRef.current = { x: e.clientX, y: e.clientY };
        transformStartRef.current = { x: transform.x, y: transform.y };
    };

    const handlePointerMove = (e: React.PointerEvent) => {
        if (!isDragging) return;
        e.preventDefault();

        const dx = e.clientX - dragStartRef.current.x;
        const dy = e.clientY - dragStartRef.current.y;

        setTransform(prev => ({
            ...prev,
            x: transformStartRef.current.x + dx,
            y: transformStartRef.current.y + dy
        }));
    };

    const handlePointerUp = () => {
        setIsDragging(false);
    };

    const handleWheel = (e: React.WheelEvent) => {
        // Simple zoom
        e.preventDefault(); // Prevent page scroll
        const zoomSpeed = 0.001;
        const newScale = Math.max(0.1, Math.min(transform.scale - e.deltaY * zoomSpeed, 10));
        setTransform(prev => ({ ...prev, scale: newScale }));
    };

    const getCroppedImg = async () => {
        if (!imgRef.current || !containerRef.current || !originalSizeRef.current.w) return;

        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');

        // Target resolution (High Quality)
        const canvasWidth = 1080;
        // Determine height based on current visual aspect ratio
        let targetRatio = currentRatio;
        if (targetRatio === 0) {
            // If free/original, use the container's rendered ratio
            targetRatio = containerRef.current.clientWidth / containerRef.current.clientHeight;
        }

        const canvasHeight = canvasWidth / targetRatio;

        canvas.width = canvasWidth;
        canvas.height = canvasHeight;

        if (!ctx) return;

        // Fill black background (useful if image doesn't cover fully)
        ctx.fillStyle = '#000000';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // Math: Map CSS Transform to Canvas Draw
        // visualWidth = originalW * scale
        // containerWidth (visual viewport) corresponds to canvasWidth
        // Factor = canvasWidth / containerWidth
        const pixelRatio = canvasWidth / containerRef.current.clientWidth;

        const drawX = transform.x * pixelRatio;
        const drawY = transform.y * pixelRatio;
        const drawW = originalSizeRef.current.w * transform.scale * pixelRatio;
        const drawH = originalSizeRef.current.h * transform.scale * pixelRatio;

        // Enable high quality scaling
        ctx.imageSmoothingEnabled = true;
        ctx.imageSmoothingQuality = 'high';

        ctx.drawImage(
            imgRef.current, 
            0, 0, originalSizeRef.current.w, originalSizeRef.current.h, // Source bounds
            drawX, drawY, drawW, drawH // Dest bounds
        );

        canvas.toBlob((blob) => {
            if (blob) {
                const newFile = new File([blob], file.name.replace(/\.[^/.]+$/, "") + "_cropped.jpg", { type: 'image/jpeg' });
                onConfirm(newFile);
            }
        }, 'image/jpeg', 0.95);
    };

    if (!imageSrc) return null;

    // Calculate container style for Aspect Ratio
    // If ratio is 0 (original), we try to fit within the parent bounds while maintaining image aspect
    let containerStyle: React.CSSProperties = {
        width: '100%',
        height: '100%', 
    };

    if (currentRatio !== 0) {
        // Enforce aspect ratio within the parent bounds
        // This is a bit tricky with pure CSS 'aspect-ratio' if parent is flexible, 
        // but 'aspectRatio' property works well in modern browsers.
        containerStyle = {
             aspectRatio: `${currentRatio}`,
             maxHeight: '100%',
             maxWidth: '100%',
             // We center it visually in the overlay
             margin: 'auto'
        };
    } else if (originalSizeRef.current.w > 0) {
         // Original ratio
         const natRatio = originalSizeRef.current.w / originalSizeRef.current.h;
         containerStyle = {
             aspectRatio: `${natRatio}`,
             maxHeight: '100%',
             maxWidth: '100%',
             margin: 'auto'
        };
    }

    return (
        <div className="absolute inset-0 z-50 bg-[#121212] flex flex-col animate-in fade-in duration-200 select-none">

            {/* Viewport Area */}
            <div className="flex-grow flex items-center justify-center p-4 overflow-hidden relative touch-none">

                 {/* The Crop Box (Mask) */}
                <div 
                    ref={containerRef}
                    className="relative overflow-hidden shadow-[0_0_0_9999px_rgba(0,0,0,0.8)] border border-white/50 bg-[#1a1a1a]"
                    style={containerStyle}
                    onPointerDown={handlePointerDown}
                    onPointerMove={handlePointerMove}
                    onPointerUp={handlePointerUp}
                    onPointerLeave={handlePointerUp}
                    onWheel={handleWheel}
                >
                    <img 
                        ref={imgRef}
                        src={imageSrc} 
                        alt="Crop target"
                        onLoad={onImageLoad}
                        style={{
                            position: 'absolute',
                            left: 0,
                            top: 0,
                            transform: `translate3d(${transform.x}px, ${transform.y}px, 0) scale(${transform.scale})`,
                            transformOrigin: '0 0',
                            maxWidth: 'none',
                            maxHeight: 'none',
                            willChange: 'transform',
                            pointerEvents: 'none' // Let events bubble to container
                        }}
                        draggable={false}
                    />

                    {/* Grid Overlay */}
                    <div className="absolute inset-0 pointer-events-none opacity-30 grid grid-cols-3 grid-rows-3">
                         <div className="border-r border-b border-white"></div>
                         <div className="border-r border-b border-white"></div>
                         <div className="border-b border-white"></div>
                         <div className="border-r border-b border-white"></div>
                         <div className="border-r border-b border-white"></div>
                         <div className="border-b border-white"></div>
                         <div className="border-r border-white"></div>
                         <div className="border-r border-white"></div>
                         <div></div>
                    </div>
                </div>
            </div>

            {/* Controls Bar */}
            <div className="flex-shrink-0 bg-[#0f0f0f] border-t border-white/10 p-2 flex flex-col gap-2 z-10">
                <div className="flex justify-between items-center gap-2">
                    {/* Ratio Selector */}
                    <div className="flex-grow flex gap-3 overflow-x-auto suggestions-scrollbar items-center pb-1 px-1">
                        {RATIOS.map(ratio => (
                            <button
                                key={ratio.label}
                                onClick={() => setCurrentRatio(ratio.value)}
                                className={`flex flex-col items-center justify-center p-1.5 rounded-md transition-all flex-shrink-0 min-w-[36px] ${
                                    currentRatio === ratio.value 
                                    ? 'bg-white text-black scale-105' 
                                    : 'text-white/60 hover:text-white hover:bg-white/10'
                                }`}
                                title={ratio.label}
                            >
                                {ratio.icon}
                                <span className="text-[9px] font-bold mt-1">{ratio.label}</span>
                            </button>
                        ))}
                    </div>

                    {/* Actions */}
                    <div className="flex items-center gap-2 pl-2 border-l border-white/10">
                        <button 
                            onClick={onCancel}
                            className="p-2 rounded-full text-white/70 hover:text-red-400 hover:bg-white/5 transition-colors"
                            title="Cancel"
                        >
                            <XIcon />
                        </button>
                        <button 
                            onClick={getCroppedImg}
                            className="p-2 rounded-full bg-[var(--color-accent)] text-white hover:bg-[var(--color-accent-dark)] shadow-lg transition-colors transform active:scale-95"
                            title="Confirm Crop"
                        >
                            <CheckIcon />
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

