        if (!ctx) return;

        ctx.fillStyle = '#000000';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        const pixelRatio = canvasWidth / containerRef.current.clientWidth;

        const drawX = transform.x * pixelRatio;
        const drawY = transform.y * pixelRatio;
        const drawW = originalSizeRef.current.w * transform.scale * pixelRatio;
        const drawH = originalSizeRef.current.h * transform.scale * pixelRatio;

        ctx.imageSmoothingEnabled = true;
        ctx.imageSmoothingQuality = 'high';

        ctx.drawImage(
            imgRef.current, 
            0, 0, originalSizeRef.current.w, originalSizeRef.current.h, 
            drawX, drawY, drawW, drawH
        );

        canvas.toBlob((blob) => {
            if (blob) {
                const newFile = new File([blob], file.name.replace(/\.[^/.]+$/, "") + "_cropped.jpg", { type: 'image/jpeg' });
                onConfirm(newFile);
            }
        }, 'image/jpeg', 0.95);
    };

    if (!imageSrc) return null;

    let containerStyle: React.CSSProperties = { width: '100%', height: '100%' };

    if (currentRatio !== 0) {
        containerStyle = { aspectRatio: `${currentRatio}`, maxHeight: '70vh', maxWidth: '100%', margin: 'auto' };
    } else if (originalSizeRef.current.w > 0) {
         const natRatio = originalSizeRef.current.w / originalSizeRef.current.h;
         containerStyle = { aspectRatio: `${natRatio}`, maxHeight: '70vh', maxWidth: '100%', margin: 'auto' };
    }

    return (
        <div className="fixed inset-0 z-[100] bg-black/95 backdrop-blur-sm flex items-center justify-center p-4 animate-in fade-in duration-200">
            <div className="w-full max-w-4xl h-full max-h-[90vh] flex flex-col bg-[#121212] rounded-2xl overflow-hidden border border-white/10 shadow-2xl">

                {/* Header */}
                <div className="flex justify-between items-center p-4 border-b border-white/10 bg-[#1a1a1a]">
                    <h3 className="text-white font-bold text-lg">Crop Image</h3>
                     <div className="flex gap-2">
                        <button onClick={onCancel} className="p-2 rounded-full text-white/70 hover:text-white hover:bg-white/10 transition-colors" title="Cancel">
                            <XIcon />
                        </button>
                     </div>
                </div>

                {/* Workspace */}
                <div className="flex-grow flex items-center justify-center p-8 bg-[#0f0f0f] relative overflow-hidden touch-none select-none">
                    <div 
                        ref={containerRef}
                        className="relative overflow-hidden shadow-[0_0_0_9999px_rgba(0,0,0,0.85)] border-2 border-white/50 bg-[#1a1a1a]"
                        style={containerStyle}
                        onPointerDown={handlePointerDown}
                        onPointerMove={handlePointerMove}
                        onPointerUp={handlePointerUp}
                        onPointerLeave={handlePointerUp}
                        onWheel={handleWheel}
                    >
                        <img 
                            ref={imgRef}
                            src={imageSrc} 
                            alt="Crop target"
                            onLoad={onImageLoad}
                            style={{
                                position: 'absolute',
                                left: 0,
                                top: 0,
                                transform: `translate3d(${transform.x}px, ${transform.y}px, 0) scale(${transform.scale})`,
                                transformOrigin: '0 0',
                                maxWidth: 'none',
                                maxHeight: 'none',
                                willChange: 'transform',
                                pointerEvents: 'none'
                            }}
                            draggable={false}
                        />

                        {/* Grid */}
                        <div className="absolute inset-0 pointer-events-none opacity-40 grid grid-cols-3 grid-rows-3">
                            <div className="border-r border-b border-white"></div>
                            <div className="border-r border-b border-white"></div>
                            <div className="border-b border-white"></div>
                            <div className="border-r border-b border-white"></div>
                            <div className="border-r border-b border-white"></div>
                            <div className="border-b border-white"></div>
                            <div className="border-r border-white"></div>
                            <div className="border-r border-white"></div>
                            <div></div>
                        </div>
                    </div>
                </div>

                {/* Footer Controls */}
                <div className="p-4 bg-[#1a1a1a] border-t border-white/10 flex flex-col md:flex-row items-center justify-between gap-4">
                    <div className="flex gap-2 overflow-x-auto suggestions-scrollbar max-w-full pb-2 md:pb-0">
                         {RATIOS.map(ratio => (
                            <button
                                key={ratio.label}
                                onClick={() => setCurrentRatio(ratio.value)}
                                className={`flex flex-col items-center justify-center px-4 py-2 rounded-lg transition-all min-w-[60px] ${
                                    currentRatio === ratio.value 
                                    ? 'bg-white text-black font-bold' 
                                    : 'text-white/60 hover:text-white hover:bg-white/10'
                                }`}
                            >
                                {ratio.icon}
                                <span className="text-[10px] mt-1">{ratio.label}</span>
                            </button>
                        ))}
                    </div>

                    <div className="flex items-center gap-3 w-full md:w-auto">
                        <button 
                            onClick={onCancel}
                            className="flex-1 md:flex-none px-6 py-3 rounded-xl font-bold text-sm bg-white/5 text-white/80 hover:bg-white/10 transition-colors"
                        >
                            Cancel
