                        <button 
                            onClick={getCroppedImg}
                            className="flex-1 md:flex-none px-8 py-3 rounded-xl font-bold text-sm bg-[var(--color-accent)] text-white hover:bg-[var(--color-accent-dark)] shadow-lg transition-colors flex items-center justify-center gap-2"
