}

const ImageWorkspace: React.FC<ImageWorkspaceProps> = ({ 
  productImages, 
  onProductImagesUpload, 
  onProductImageRemove,
  isUploading,
  onProductImageUpdate
}) => {
  const [editingIndex, setEditingIndex] = useState<number | null>(null);

  const handleAddMoreUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (files && files.length > 0) {
      const imageFiles = Array.from(files).filter((file: File) => file.type.startsWith('image/'));
      if (imageFiles.length > 0) {
          onProductImagesUpload(imageFiles);
      }
    }
    event.target.value = ''; // Allow re-uploading the same file
  };

  const handleCropConfirm = async (croppedFile: File) => {
    if (editingIndex === null || !onProductImageUpdate) return;

    const reader = new FileReader();
    reader.onloadend = () => {
        const base64String = reader.result as string;
        const newImageFile: ImageFile = {
            base64: base64String.split(',')[1],
            mimeType: croppedFile.type,
            name: croppedFile.name
        };
        // If editing index 0, it comes from the uploader, handled there? 
        // No, ImageWorkspace renders list from index 1 for thumbnails, but uploader handles index 0?
        // Wait, ImageWorkspace.tsx renders ImageUploader for the MAIN area (usually first image if >0, or dropzone).
        // And then thumbnails for slice(1).

        // Actually, let's look at the mapping logic. 
        // Uploader handles index 0.
        // Thumbnails handle index + 1.

        // The list below is productImages.slice(1).map...
        // so index in map is 0, which corresponds to productImages[1].
        // So the actual index to update is editingIndex.

        onProductImageUpdate(editingIndex, newImageFile);
        setEditingIndex(null);
    };
    reader.readAsDataURL(croppedFile);
  };

  return (
    <div className="flex flex-col gap-2 h-full w-full">
        <div className="w-full aspect-square relative">
            <div className="absolute inset-0">
                <ImageUploader
                    id="product-uploader"
                    title="Upload Image(s)"
                    images={productImages}
                    onFileUpload={onProductImagesUpload}
                    multiple={true}
                    onRemove={onProductImageRemove}
                    isUploading={isUploading && productImages.length === 0}
                    onImageUpdate={onProductImageUpdate} // Allow cropping the main image (index 0)
                />
            </div>
        </div>

        {/* Thumbnail Bar */}
        {productImages.length > 0 && (
          <div className="w-full h-16">
            <div className="h-full w-full overflow-x-auto flex flex-row items-center gap-2 suggestions-scrollbar pb-1">
              {productImages.slice(1).map((image, index) => (
                <div key={index + 1} className="h-14 w-14 flex-shrink-0 relative group/image">
                  <img src={`data:${image.mimeType};base64,${image.base64}`} alt={`Product image ${index + 2}`} className="w-full h-full object-cover rounded-md" />

                  {/* Overlay Controls */}
                  <div className="absolute inset-0 bg-black/40 opacity-0 group-hover/image:opacity-100 transition-opacity flex items-center justify-center gap-1">
                      {onProductImageUpdate && (
                         <button
                            onClick={() => setEditingIndex(index + 1)}
                            className="bg-black/60 text-white rounded-full p-1 hover:bg-[var(--color-accent)] transition-colors"
                            title="Crop"
                        >
                            <CropIcon />
                        </button>
                      )}
                      <button
                        onClick={() => onProductImageRemove(index + 1)}
                        className="bg-black/60 text-white rounded-full p-1 hover:bg-red-500 transition-colors"
                        title="Remove"
                      >
                        <XIcon />
                      </button>
                  </div>
                </div>
              ))}
              {/* Add more button */}
               <label htmlFor="add-more-uploader" className="cursor-pointer group h-14 w-14 flex-shrink-0">
                  <div className="h-full w-full rounded-md border border-dashed border-[rgba(var(--color-accent-rgb),0.3)] hover:border-[rgba(var(--color-accent-rgb),0.8)] flex flex-col items-center justify-center text-[var(--color-text-secondary)] hover:text-[var(--color-text-base)] transition-colors">
                      {isUploading ? (
                        <div className="animate-spin rounded-full h-4 w-4 border-t-2 border-b-2 border-[var(--color-accent)]"></div>
                      ) : (
                        <PlusIcon />
                      )}
                  </div>
               </label>
               <input 
                 id="add-more-uploader" 
                 type="file" 
                 className="hidden" 
                 accept="image/*" 
                 onChange={handleAddMoreUpload} 
                 multiple 
                 disabled={isUploading}
               />
            </div>
          </div>
        )}

        {/* Cropper for Thumbnails */}
        {editingIndex !== null && productImages[editingIndex] && (
             <ImageCropper 
                file={base64ToFile(productImages[editingIndex].base64, productImages[editingIndex].mimeType, productImages[editingIndex].name)}
                onConfirm={handleCropConfirm}
                onCancel={() => setEditingIndex(null)}
            />
        )}
    </div>
  );
};

