import React, { useEffect, useRef, useCallback } from 'react';
import { CreatorStudioProject, HistoryItem, ImageFile } from '../types';
import { analyzeStyleImage, translateText, generateImage, editImage } from '../services/geminiService';
import { resizeImage } from '../utils';
import CustomizationPanel from './CustomizationPanel';
import ImageWorkspace from './ImageWorkspace';
import PromptEditor, { PromptSuggestions } from './PromptEditor';
import HistoryPanel from './HistoryPanel';
import ResultDisplay from './ResultDisplay';
import ImageUploader from './ImageUploader';

interface CreatorStudioProps {
  project: CreatorStudioProject;
  setProject: React.Dispatch<React.SetStateAction<CreatorStudioProject>>;
}

const CreatorStudio: React.FC<CreatorStudioProps> = ({
  project,
  setProject,
}) => {

  const translateTimeoutRef = useRef<number | null>(null);
  const translationRequestCounter = useRef(0);

  const updateActiveProjectState = useCallback((updater: (projectDraft: CreatorStudioProject) => void) => {
    setProject(currentProject => {
      const projectToUpdate = { ...currentProject };
      updater(projectToUpdate);
      return projectToUpdate;
    });
  }, [setProject]);

  // Analyze style image when it changes for the active project
  useEffect(() => {
    // Only analyze if we have an image, no description yet, aren't currently analyzing, and have no prior error.
    if (project?.styleImage && !project.styleDescription && !project.isAnalyzingStyle && !project.error) {
      const getStyleDescription = async () => {
        updateActiveProjectState(p => { 
          p.isAnalyzingStyle = true;
          p.error = null;
        });
        try {
          const description = await analyzeStyleImage(project.styleImage as ImageFile);
          updateActiveProjectState(p => { p.styleDescription = description; });
        } catch (err) {
          console.error(err);
          updateActiveProjectState(p => {
            p.error = err instanceof Error ? err.message : "Could not analyze the style image.";
            p.styleDescription = null;
          });
        } finally {
          updateActiveProjectState(p => { p.isAnalyzingStyle = false; });
        }
      };
      getStyleDescription();
    } else if (!project?.styleImage && project?.styleDescription) {
      // If image was removed but description remains, clear it
      updateActiveProjectState(p => { p.styleDescription = null; });
    }
  }, [
    project?.id,
    project?.styleImage, 
    project?.styleDescription,
    project?.isAnalyzingStyle,
    project?.error,
    updateActiveProjectState
  ]);

  // Generate prompt automatically based on active project state, if not manually edited
  useEffect(() => {
    if (!project || !project.isPromptAutoGenerated) {
      return;
    }

    const { productImages, styleImage, options, isAnalyzingStyle, styleDescription } = project;

    if (productImages.length === 0 && !styleImage) {
      if(project.prompt !== '') {
          updateActiveProjectState(p => { p.prompt = ''; });
      }
      return;
    }

    let newPrompt = `Generate a high-resolution, professional photograph`;
    if (productImages.length > 0) {
      newPrompt += ` of the subject in the provided image${productImages.length > 1 ? 's' : ''}`;
    }
    newPrompt += `.

Key requirements:
- Lighting: Illuminate the scene with a ${options.lightingStyle} style. The lighting should be flattering and highlight the subject's details.
- Camera Perspective: Capture the subject from a ${options.cameraPerspective}.
- Background: The background should be clean, non-distracting, and complementary to the subject. A subtle, high-end studio setting is preferred.
- Overall Mood: The image should feel premium, clean, and aspirational.`;

    if (styleImage) {
      if (isAnalyzingStyle) {
          newPrompt += `\n\n- Style Reference: Analyzing the provided style reference image...`;
      } else if (styleDescription) {
          newPrompt += `\n\n- Style Reference: Strictly adhere to the aesthetic of the provided style reference image, which has a ${styleDescription}. The goal is to make the subject look as if it belongs in the same visual world.`;
      } else {
            newPrompt += `\n\n- Style Reference: Strictly adhere to the aesthetic, color palette, texture, and overall mood of the provided style reference image. The goal is to make the subject look as if it belongs in the same visual world as the style reference.`;
      }
    }

    if(project.prompt !== newPrompt) {
        updateActiveProjectState(p => { p.prompt = newPrompt; });
    }
  }, [
    project?.id,
    project?.isPromptAutoGenerated,
    project?.productImages, 
    project?.styleImage, 
    project?.options, 
    project?.isAnalyzingStyle, 
    project?.styleDescription,
    updateActiveProjectState
  ]);

  // Auto-translate prompt if it contains Arabic
  useEffect(() => {
    const arabicRegex = /[\u0600-\u06FF]/;

    if (!project || project.isPromptAutoGenerated) {
        if (project?.translatedPrompt || project?.isTranslating) {
            updateActiveProjectState(p => { 
                p.translatedPrompt = null;
                p.isTranslating = false;
            });
        }
        return;
    }

    if (translateTimeoutRef.current) {
        clearTimeout(translateTimeoutRef.current);
    }

    const promptToTranslate = project.prompt;

    if (!arabicRegex.test(promptToTranslate) || !promptToTranslate.trim()) {
        if (project.translatedPrompt || project.isTranslating) {
            updateActiveProjectState(p => {
                p.translatedPrompt = null;
                p.isTranslating = false;
            });
        }
        return;
    }

    translateTimeoutRef.current = window.setTimeout(async () => {
        translationRequestCounter.current += 1;
        const currentRequestId = translationRequestCounter.current;

        updateActiveProjectState(p => {
            p.isTranslating = true;
            p.error = null;
        });

        try {
            const translated = await translateText(promptToTranslate);
            if (translationRequestCounter.current === currentRequestId) {
                updateActiveProjectState(p => {
                    if (p.prompt === promptToTranslate) {
                        p.translatedPrompt = translated;
                    }
                });
            }
        } catch (err) {
            console.error(err);
            if (translationRequestCounter.current === currentRequestId) {
                updateActiveProjectState(p => {
                    p.error = err instanceof Error ? err.message : 'Translation failed.';
                });
            }
        } finally {
            if (translationRequestCounter.current === currentRequestId) {
                updateActiveProjectState(p => {
                   p.isTranslating = false;
                });
            }
        }
    }, 700);

  }, [project?.prompt, project?.isPromptAutoGenerated, updateActiveProjectState]);

  const handleGenerate = useCallback(async () => {
    if (!project || !project.prompt) {
      updateActiveProjectState(p => { p.error = 'Please write a prompt to generate an image.'; });
      return;
    }
    const currentPrompt = project.prompt;

    updateActiveProjectState(p => {
        p.isLoading = true;
        p.error = null;
        p.generatedImage = null;
    });

    try {
      const result = await generateImage(project.productImages, project.prompt, project.styleImage);
      updateActiveProjectState(p => {
          p.generatedImage = result;
          const newHistoryItem: HistoryItem = { image: result, prompt: currentPrompt };
          p.history = [newHistoryItem, ...p.history];
      });
    } catch (err) {
      console.error(err);
      updateActiveProjectState(p => { 
        p.error = err instanceof Error ? err.message : 'An unknown error occurred during image generation.';
      });
    } finally {
      updateActiveProjectState(p => { p.isLoading = false; });
    }
  }, [project, updateActiveProjectState]);

  const handleImageEdit = useCallback(async () => {
    if (!project?.generatedImage || !project.editPrompt) {
      updateActiveProjectState(p => { p.error = 'Please enter an edit instruction.'; });
      return;
    }

    const { generatedImage, editPrompt } = project;

    updateActiveProjectState(p => {
        p.isEditing = true;
        p.error = null;
    });

    try {
      const result = await editImage(generatedImage, editPrompt);
      updateActiveProjectState(p => {
          p.generatedImage = result;
          const newHistoryItem: HistoryItem = { image: result, prompt: editPrompt };
          p.history = [newHistoryItem, ...p.history];
          p.editPrompt = ''; // Clear prompt after success
      });
    } catch (err) {
      console.error(err);
      updateActiveProjectState(p => { 
        p.error = err instanceof Error ? err.message : 'An unknown error occurred during image editing.';
      });
    } finally {
      updateActiveProjectState(p => { p.isEditing = false; });
    }
  }, [project, updateActiveProjectState]);


  const handleFileUpload = (updater: (files: ImageFile[]) => void, target: 'product' | 'style') => async (files: File[]) => {
      if (!files || files.length === 0) return;

      updateActiveProjectState(p => {
        p.uploadingTarget = target;
        p.error = null;
      });
      let currentError: string | null = null;

      const filePromises = files.map(file => {
          return new Promise<ImageFile | null>(async (resolve) => {
              if (!file.type.startsWith('image/')) {
                  if(!currentError) currentError = `File '${file.name}' is not a supported image type.`;
                  resolve(null);
                  return;
              }

              try {
                  const resizedFile = await resizeImage(file, 2048, 2048);
                  const reader = new FileReader();
                  reader.onloadend = () => {
                      const base64String = reader.result as string;
                      resolve({
                          base64: base64String.split(',')[1],
                          mimeType: resizedFile.type,
                          name: resizedFile.name
                      });
                  };
                  reader.onerror = () => {
                      if(!currentError) currentError = `Error reading file '${resizedFile.name}'.`;
                      resolve(null);
                  };
                  reader.readAsDataURL(resizedFile);
              } catch (err) {
                  console.error(`Error processing ${file.name}:`, err);
                  if (!currentError) currentError = `Could not process file '${file.name}'.`;
                  resolve(null);
              }
          });
      });

      const results = await Promise.all(filePromises);

      const validImages = results.filter((img): img is ImageFile => img !== null);
      if (validImages.length > 0) {
          updater(validImages);
      }

      updateActiveProjectState(p => {
        p.error = currentError;
        p.uploadingTarget = null;
      });
  };

  const handleSetPrompt = (prompt: string) => updateActiveProjectState(p => {
    p.prompt = prompt;
    p.isPromptAutoGenerated = false;
  });

  const handleResetPrompt = useCallback(() => {
    updateActiveProjectState(p => {
        p.isPromptAutoGenerated = true;
    });
  }, [updateActiveProjectState]);

  const handleSetStyleImage = (image: ImageFile | null) => updateActiveProjectState(p => { 
    p.styleImage = image; 
    // Clear style description and error to trigger fresh analysis or clear state
    p.styleDescription = null;
    p.error = null;
  });

  const handleSingleFileUpload = handleFileUpload(files => handleSetStyleImage(files[0]), 'style');
  const handleMultipleFilesUpload = handleFileUpload(files => updateActiveProjectState(p => { p.productImages = [...p.productImages, ...files]; }), 'product');

  const handleRemoveProductImage = (indexToRemove: number) => {
    updateActiveProjectState(p => {
      p.productImages = p.productImages.filter((_, index) => index !== indexToRemove);
    });
  };

  const handleUpdateProductImage = (indexToUpdate: number, newImage: ImageFile) => {
    updateActiveProjectState(p => {
        const newImages = [...p.productImages];
        newImages[indexToUpdate] = newImage;
        p.productImages = newImages;
    });
  };

  const handleRemoveStyleImage = () => {
    updateActiveProjectState(p => {
      p.styleImage = null;
      p.styleDescription = null;
      p.error = null;
    });
  };

  const handleUpdateStyleImage = (index: number, newImage: ImageFile) => {
       // Since style is single image, index is always 0
       updateActiveProjectState(p => {
          p.styleImage = newImage;
          p.styleDescription = null; // Re-analyze needed
       });
  };

  const handleHistorySelectImage = (image: ImageFile) => {
    updateActiveProjectState(p => { p.generatedImage = image; });
  };

  const handleUseTranslation = (translatedText: string) => {
    updateActiveProjectState(p => {
      p.prompt = translatedText;
      p.isPromptAutoGenerated = false;
      p.translatedPrompt = null;
      p.isTranslating = false;
    });
  };

  if (!project) {
    return (
      <div className="flex-grow w-full flex flex-col items-center justify-center">
        <div className="animate-spin rounded-full h-16 w-16 border-t-2 border-b-2 border-[var(--color-accent)]"></div>
      </div>
    );
  }

  return (
    <main className="w-full grid grid-cols-1 lg:grid-cols-2 gap-6 pt-4 pb-12 items-start">
        {/* --- LEFT COLUMN: INPUTS --- */}
        <div className="flex flex-col gap-4 order-1">

            {/* 1. Upload Area (Side-by-Side) */}
            <div className="grid grid-cols-2 gap-4 mb-6">
                {/* Product Image */}
                <div className="glass-card p-3 rounded-2xl flex flex-col gap-2 items-center">
                    <h3 className="text-sm font-bold text-[var(--color-text-medium)] text-center">Upload Image(s)</h3>
                    <div className="w-full max-w-[200px]">
                        <ImageWorkspace
                            productImages={project.productImages}
                            onProductImagesUpload={handleMultipleFilesUpload}
                            onProductImageRemove={handleRemoveProductImage}
                            isUploading={project.uploadingTarget === 'product'}
                            onProductImageUpdate={handleUpdateProductImage}
                        />
                    </div>
                </div>

                {/* Style Reference */}
                <div className="glass-card p-3 rounded-2xl flex flex-col gap-2 items-center">
                    <h3 className="text-sm font-bold text-[var(--color-text-medium)] text-center">Style Ref</h3>
                    <div className="w-full max-w-[200px] relative">
                         <div className="w-full aspect-square relative">
                            <ImageUploader 
                                id="style-uploader"
                                title="Style Image"
                                images={project.styleImage ? [project.styleImage] : []}
                                onFileUpload={handleSingleFileUpload}
                                onRemove={handleRemoveStyleImage}
                                onImageUpdate={handleUpdateStyleImage}
                            />
                             {(project.uploadingTarget === 'style' || project.isAnalyzingStyle) && (
                                <div className="absolute inset-0 bg-black/60 flex flex-col items-center justify-center rounded-xl backdrop-blur-sm pointer-events-none z-20">
                                    <div className="animate-spin rounded-full h-6 w-6 border-t-2 border-b-2 border-[var(--color-accent)]"></div>
                                    <p className="text-xs text-[var(--color-text-base)] mt-2">{project.uploadingTarget === 'style' ? 'Processing...' : 'Analyzing...'}</p>
                                </div>
                            )}
                         </div>
                    </div>
                </div>
            </div>

            {/* 2. Options */}
            <CustomizationPanel
                options={project.options}
                setOptions={(newOptions) => updateActiveProjectState(p => { p.options = newOptions; })}
            />

            {/* 3. Prompt */}
            <PromptEditor
                prompt={project.prompt}
                setPrompt={handleSetPrompt}
                isAutoGenerated={project.isPromptAutoGenerated}
                onResetPrompt={handleResetPrompt}
                translatedPrompt={project.translatedPrompt}
                isTranslating={project.isTranslating}
                onUseTranslation={handleUseTranslation}
            />

             {/* 4. Action Button */}
            <div className="w-full">
                <button
                    onClick={handleGenerate}
                    disabled={project.isLoading || project.isEditing || !project.prompt || project.isAnalyzingStyle || !!project.uploadingTarget}
                    className="w-full bg-gradient-to-r from-[var(--color-accent)] to-[var(--color-accent-dark)] hover:from-[var(--color-accent-dark)] hover:to-[var(--color-accent-darker)] text-[var(--color-text-base)] font-bold py-4 px-8 rounded-xl text-xl transition-all duration-300 ease-in-out disabled:opacity-50 disabled:cursor-not-allowed shadow-xl hover:shadow-2xl hover:shadow-[var(--color-accent)]/20 disabled:shadow-none transform hover:-translate-y-1 disabled:transform-none"
                >
                    {project.isAnalyzingStyle ? 'Analyzing Style...' : project.uploadingTarget ? 'Processing Image...' : project.isLoading ? 'Generating...' : 'Generate Image'}
                </button>
            </div>

            {/* 5. Prompt Suggestions - Moved Here */}
            <PromptSuggestions 
                setPrompt={handleSetPrompt} 
                currentPrompt={project.prompt} 
            />

            {project.error && <div className="bg-[rgba(var(--color-accent-rgb),0.2)] border border-[rgba(var(--color-accent-rgb),0.5)] text-[var(--color-accent-light)] px-4 py-3 rounded-lg text-sm" role="alert">{project.error}</div>}

        </div>

        {/* --- RIGHT COLUMN: RESULT (Static) --- */}
        <div className="flex flex-col gap-4 pb-4 order-2">
             <div className="glass-card rounded-2xl p-4 flex flex-col">
                <h3 className="text-xl font-bold text-[var(--color-text-base)] mb-4">Result</h3>
                <div className="flex-grow flex flex-col justify-center min-h-[300px]">
                    <ResultDisplay 
                        imageFile={project.generatedImage}
                        isLoading={project.isLoading}
                        isEditing={project.isEditing}
                        editPrompt={project.editPrompt}
                        setEditPrompt={(prompt) => updateActiveProjectState(p => { p.editPrompt = prompt; })}
                        onImageEdit={handleImageEdit}
                    />
                </div>
             </div>
             {/* 6. History (Below Results) */}
            <HistoryPanel history={project.history} onSelect={handleHistorySelectImage} />
        </div>
    </main>
  );
};

export default CreatorStudio;

import React, { useCallback } from 'react';
import { ImageFile, ShotType, PhotoshootDirectorProject } from '../types';
import { resizeImage } from '../utils';
import { generateImage, editImage } from '../services/geminiService';
import ImageUploader from './ImageUploader';
import ShotTypeSelector from './ShotTypeSelector';
import ResultsGrid from './ResultsGrid';

interface PhotoshootDirectorProps {
  project: PhotoshootDirectorProject;
  setProject: React.Dispatch<React.SetStateAction<PhotoshootDirectorProject>>;
}

const PhotoshootDirector: React.FC<PhotoshootDirectorProps> = ({ project, setProject }) => {

    const onGenerate = useCallback(async () => {
    if (!project || project.productImages.length === 0 || project.selectedShotTypes.length === 0) {
      setProject(s => ({ ...s, error: 'Please upload a product image and select at least one shot type.' }));
      return;
    }

    setProject(s => ({
      ...s,
      isGenerating: true,
      error: null,
      results: s.selectedShotTypes.map(shotType => ({
        shotType,
        image: null,
        isLoading: true,
        error: null,
        editPrompt: '',
        isEditing: false,
      })),
    }));

    const generationPromises = project.selectedShotTypes.map(shotType => {
      let prompt = `A high-resolution, professional photograph of the subject from the provided image. The desired shot is: '${shotType}'. The background should be clean, non-distracting, and complementary to the subject.`;
      if (project.customStylePrompt) {
        prompt += ` Additional style requirements: ${project.customStylePrompt}`;
      }
      return generateImage(project.productImages, prompt, null)
        .then(image => ({ status: 'fulfilled' as const, value: { shotType, image } }))
        .catch(error => ({ status: 'rejected' as const, reason: { shotType, error } }));
    });

    const settledResults = await Promise.all(generationPromises);

    settledResults.forEach(result => {
      if (result.status === 'fulfilled') {
        const { shotType, image } = result.value;
        setProject(s => ({
          ...s,
          results: s.results.map(r => r.shotType === shotType ? { ...r, image, isLoading: false } : r),
        }));
      } else {
        const { shotType, error } = result.reason;
        console.error(`Failed to generate image for ${shotType}:`, error);
        setProject(s => ({
          ...s,
          results: s.results.map(r => r.shotType === shotType ? { ...r, error: error.message || 'Generation failed', isLoading: false } : r),
        }));
      }
    });

    setProject(s => ({ ...s, isGenerating: false }));
  }, [project, setProject]);


  const handleFileUpload = async (files: File[]) => {
    if (!files || files.length === 0) return;

    setProject(s => ({ ...s, isUploading: true, error: null }));
    let currentError: string | null = null;

    const filePromises = files.map(file => {
      return new Promise<ImageFile | null>(async (resolve) => {
        if (!file.type.startsWith('image/')) {
          if (!currentError) currentError = `File '${file.name}' is not a supported image type.`;
          resolve(null);
          return;
        }
        try {
          const resizedFile = await resizeImage(file, 2048, 2048);
          const reader = new FileReader();
          reader.onloadend = () => {
            const base64String = reader.result as string;
            resolve({
              base64: base64String.split(',')[1],
              mimeType: resizedFile.type,
              name: resizedFile.name
            });
          };
          reader.onerror = () => {
            if (!currentError) currentError = `Error reading file '${resizedFile.name}'.`;
            resolve(null);
          };
          reader.readAsDataURL(resizedFile);
        } catch (err) {
          console.error(`Error processing ${file.name}:`, err);
          if (!currentError) currentError = `Could not process file '${file.name}'.`;
          resolve(null);
        }
      });
    });

    const results = await Promise.all(filePromises);
    const validImages = results.filter((img): img is ImageFile => img !== null);

    setProject(s => ({
      ...s,
      productImages: [...s.productImages, ...validImages],
      error: currentError,
      isUploading: false,
    }));
  };

  const handleRemoveImage = (indexToRemove: number) => {
    setProject(s => ({
      ...s,
      productImages: s.productImages.filter((_, index) => index !== indexToRemove),
    }));
  };

  const handleImageUpdate = (index: number, newImage: ImageFile) => {
      setProject(s => {
          const newImages = [...s.productImages];
          if (index >= 0 && index < newImages.length) {
              newImages[index] = newImage;
          }
          return { ...s, productImages: newImages };
      });
  };

  const handleSetEditPrompt = (shotType: ShotType, prompt: string) => {
    setProject(s => ({
        ...s,
        results: s.results.map(r => 
            r.shotType === shotType ? { ...r, editPrompt: prompt } : r
        ),
    }));
  };

  const handleImageEdit = async (shotType: ShotType) => {
    const resultToEdit = project.results.find(r => r.shotType === shotType);
    if (!resultToEdit || !resultToEdit.image || !resultToEdit.editPrompt.trim()) {
      setProject(s => ({ ...s, error: 'Cannot edit: image or prompt is missing.' }));
      return;
    }

    setProject(s => ({
      ...s,
      results: s.results.map(r => 
        r.shotType === shotType ? { ...r, isEditing: true, error: null } : r
      ),
    }));

    try {
      const newImage = await editImage(resultToEdit.image, resultToEdit.editPrompt);
      setProject(s => ({
        ...s,
        results: s.results.map(r => 
          r.shotType === shotType 
            ? { ...r, image: newImage, isEditing: false, editPrompt: '' } 
            : r
        ),
      }));
    } catch (err) {
      console.error(`Failed to edit image for ${shotType}:`, err);
      const errorMessage = err instanceof Error ? err.message : 'An unknown error occurred during image editing.';
      setProject(s => ({
        ...s,
        results: s.results.map(r => 
          r.shotType === shotType ? { ...r, error: errorMessage, isEditing: false } : r
        ),
      }));
    }
  };

  if (!project) {
    return (
        <main className="w-full max-w-7xl flex items-center justify-center gap-8 pt-8 pb-12 flex-grow">
            <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-[var(--color-accent)]"></div>
            <p className="text-[var(--color-text-secondary)]">Loading Photoshoot Director...</p>
        </main>
    );
  }

  return (
    <main className="w-full flex flex-col gap-4 pt-4 pb-8">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4 flex-grow">
        {/* Left Column: Controls */}
        <div className="lg:col-span-1 flex flex-col gap-4">
          <div className="glass-card rounded-2xl p-4">
            <h3 className="text-lg font-bold text-[var(--color-text-base)] mb-4">1. Upload Image(s)</h3>
            <ImageUploader
              id="photoshoot-uploader"
              title="Upload Image(s)"
              images={project.productImages}
              onFileUpload={handleFileUpload}
              onRemove={handleRemoveImage}
              isUploading={project.isUploading}
              onImageUpdate={handleImageUpdate}
            />
          </div>
          <ShotTypeSelector
            selected={project.selectedShotTypes}
            onChange={(selected) => setProject(s => ({ ...s, selectedShotTypes: selected }))}
            customStylePrompt={project.customStylePrompt}
            onCustomStylePromptChange={(prompt) => setProject(s => ({...s, customStylePrompt: prompt }))}
          />
          <div className="w-full px-4 py-2">
            <button
                onClick={onGenerate}
                disabled={project.isGenerating || project.isUploading || project.productImages.length === 0 || project.selectedShotTypes.length === 0}
                className="w-full bg-gradient-to-r from-[var(--color-accent)] to-[var(--color-accent-dark)] hover:from-[var(--color-accent-dark)] hover:to-[var(--color-accent-darker)] text-[var(--color-text-base)] font-bold py-3 px-8 rounded-lg text-lg transition-all duration-300 ease-in-out disabled:opacity-50 disabled:cursor-not-allowed shadow-lg hover:shadow-2xl hover:shadow-[var(--color-accent)]/20 disabled:shadow-none transform hover:-translate-y-1 disabled:transform-none"
            >
                {project.isGenerating ? 'Generating...' : `Generate ${project.selectedShotTypes.length} Shot${project.selectedShotTypes.length === 1 ? '' : 's'}`}
            </button>
          </div>
        </div>

        {/* Right Column: Results */}
        <div className="lg:col-span-2 flex flex-col gap-6">
          <div className="flex flex-col flex-grow glass-card rounded-2xl p-4">
              <div className="flex justify-between items-center mb-4">
                  <h3 className="text-lg font-bold text-[var(--color-text-base)]">3. Generated Results</h3>
              </div>
               {project.error && <div className="mb-4 bg-[rgba(var(--color-accent-rgb),0.2)] border border-[rgba(var(--color-accent-rgb),0.5)] text-[var(--color-accent-light)] px-4 py-3 rounded-lg" role="alert">{project.error}</div>}
              <ResultsGrid 
                results={project.results} 
                onImageEdit={handleImageEdit}
                onSetEditPrompt={handleSetEditPrompt}
              />
          </div>
        </div>
      </div>
    </main>
  );
};

export default PhotoshootDirector;

import React, { useCallback } from 'react';
import { ImageFile, BrandingStudioProject, BrandingResultCategory, AspectRatio } from '../types';
import { resizeImage } from '../utils';
import { analyzeLogoForBranding, generateImage, editImage } from '../services/geminiService';
import ImageUploader from './ImageUploader';
import BrandingResultsGrid from './BrandingResultsGrid';
import { ASPECT_RATIOS } from '../constants';

const MOCKUP_CATEGORIES: BrandingResultCategory[] = [
    'Logo Construction Grid', 'Typography Showcase', 'Logo Color Variations', 'Monochrome Version',
    '3D Glass Logo', 'Business Card Mockup', '3D Glass App Icon', 'Creative Pen Mockup',
    'Merchandise (Tote Bag)', 'Pencil Sketch Logo', 'Notebook Mockup', 'Waving Flag Mockup'
];

const getPromptForCategory = (category: BrandingResultCategory, aspectRatio: AspectRatio): string => {
    const aspectRatioRequirement = ` The final image must have a ${aspectRatio} aspect ratio.`;
    const compositionRequirement = ` The final image composition must have a ${aspectRatio} aspect ratio.`;

    switch (category) {
        case 'Logo Construction Grid':
            return "Create a technical brand guideline image. Display the provided logo on a light grid, showing construction lines, proportions (e.g., '2x', '3x'), and a clear space margin around it. The style should be clean, precise, and professional, like an architectural blueprint for the logo." + aspectRatioRequirement;
        case 'Typography Showcase':
            return "Create a brand typography specimen sheet. Analyze the font style used in the provided logo. Recreate that typographic style to display the full English alphabet in uppercase (A-Z), lowercase (a-z), and numbers (0-9). The characters should be arranged neatly on a clean, minimalist background. Add the title 'Brand Font' at the top of the image. The final image should look like a professional brand guideline page." + aspectRatioRequirement;
        case 'Logo Color Variations':
            return "Create a brand guideline image showing logo color variations. Display four versions of the provided logo, each on a different solid-colored background derived from the brand's main colors (e.g., primary, accent, dark, and light). The layout should be a clean 2x2 grid." + aspectRatioRequirement;
        case 'Monochrome Version':
            return 'A high-contrast, single-color (white) version of the provided logo, presented on a black background. The result should be sharp and minimalist.' + aspectRatioRequirement;
        case '3D Glass Logo':
            return "Create a photorealistic 3D mockup of the provided logo rendered in glossy, translucent glass. The logo should be set against a dark, moody background with subtle studio lighting and soft reflections." + aspectRatioRequirement;
        case 'Business Card Mockup':
            return "A photorealistic mockup of a premium, thick-stock business card with textured paper, featuring the provided logo. The card is placed on a stylish surface like dark wood or marble." + compositionRequirement;
        case '3D Glass App Icon':
            return "Create a photorealistic 3D app icon from the provided logo. The icon should be rendered in glossy, translucent glass with subtle internal light effects. Place the icon against a pure black background to make it stand out. The lighting should be soft and create beautiful reflections on the glass surface." + aspectRatioRequirement;
        case 'Creative Pen Mockup':
            return "A photorealistic mockup of a high-end, elegant pen with the provided logo subtly engraved on its clip. The pen is resting on a clean, minimalist surface with soft lighting." + compositionRequirement;
        case 'Merchandise (Tote Bag)':
            return "A photorealistic lifestyle mockup of the provided logo printed on a high-quality canvas tote bag. The bag is being held by a stylish person in an urban setting." + compositionRequirement;
        case 'Pencil Sketch Logo':
            return "Create a photorealistic, artistic sketch of the provided logo as if it were hand-drawn with a graphite pencil on textured white paper. The sketch should show realistic pencil strokes, shading, and texture. The style should be artistic and detailed." + aspectRatioRequirement;
        case 'Notebook Mockup':
            return "A photorealistic mockup of a premium Moleskine-style notebook. The provided logo is elegantly debossed on the cover. The notebook is placed on a creative desk setup with other stationery items." + compositionRequirement;
        case 'Waving Flag Mockup':
            return "A photorealistic mockup of the provided logo on a large, majestic flag waving gently in the wind against a clear sky. The fabric should show realistic texture and folds. The overall mood should be epic and inspiring." + compositionRequirement;
        default:
            return `A professional product shot of the provided logo.` + aspectRatioRequirement;
    }
}

const BrandingStudio: React.FC<{
  project: BrandingStudioProject;
  setProject: React.Dispatch<React.SetStateAction<BrandingStudioProject>>;
}> = ({ project, setProject }) => {

    const handleFileUpload = async (files: File[]) => {
        if (!files || files.length === 0) return;
        const file = files[0];

        setProject(s => ({ ...s, isUploading: true, error: null }));
        try {
            if (!file.type.startsWith('image/')) {
                throw new Error(`File '${file.name}' is not a supported image type.`);
            }
            const resizedFile = await resizeImage(file, 1024, 1024);
            const reader = new FileReader();
            reader.onloadend = () => {
                const base64String = reader.result as string;
                setProject(s => ({
                    ...s,
                    logo: { base64: base64String.split(',')[1], mimeType: resizedFile.type, name: resizedFile.name },
                    isUploading: false,
                    // Reset previous results when new logo is uploaded
                    results: [],
                    colors: [],
                }));
            };
            reader.onerror = () => { throw new Error(`Error reading file '${resizedFile.name}'.`); };
            reader.readAsDataURL(resizedFile);
        } catch (err) {
            console.error(err);
            const errorMessage = err instanceof Error ? err.message : 'Could not process file.';
            setProject(s => ({ ...s, error: errorMessage, isUploading: false }));
        }
    };

    const handleRemoveLogo = () => {
        setProject(s => ({ ...s, logo: null, results: [], colors: [], error: null }));
    };

    const handleUpdateLogo = (index: number, newImage: ImageFile) => {
        setProject(s => ({ ...s, logo: newImage, results: [], colors: [] }));
    };

    const onGenerate = useCallback(async () => {
        if (!project.logo) {
            setProject(s => ({...s, error: 'Please upload a logo to begin.'}));
            return;
        }

        // 1. Analyze Logo for Colors
        setProject(s => ({...s, isAnalyzing: true, isGenerating: true, error: null, colors: [], results: []}));
        try {
            const analysis = await analyzeLogoForBranding(project.logo);
            setProject(s => ({...s, colors: analysis.colors, isAnalyzing: false}));

            // 2. Prepare mockups generation
            const initialResults = MOCKUP_CATEGORIES.map(category => ({
                category, image: null, isLoading: true, error: null, editPrompt: '', isEditing: false
            }));
            setProject(s => ({...s, results: initialResults}));

            // 3. Generate all mockups in parallel
            const generationPromises = MOCKUP_CATEGORIES.map(category => {
                const prompt = getPromptForCategory(category, project.aspectRatio);
                return generateImage([project.logo!], prompt, null)
                    .then(image => ({ status: 'fulfilled' as const, value: { category, image } }))
                    .catch(error => ({ status: 'rejected' as const, reason: { category, error } }));
            });

            const settledResults = await Promise.all(generationPromises);

            settledResults.forEach(result => {
                if (result.status === 'fulfilled') {
                    const { category, image } = result.value;
                    setProject(s => ({...s, results: s.results.map(r => r.category === category ? { ...r, image, isLoading: false } : r)}));
                } else {
                    const { category, error } = result.reason;
                    console.error(`Failed to generate image for ${category}:`, error);
                    setProject(s => ({ ...s, results: s.results.map(r => r.category === category ? { ...r, error: error.message || 'Generation failed', isLoading: false } : r)}));
                }
            });

        } catch(err) {
            const errorMessage = err instanceof Error ? err.message : 'An unknown error occurred during analysis.';
            setProject(s => ({...s, error: errorMessage, isAnalyzing: false }));
        } finally {
            setProject(s => ({...s, isGenerating: false}));
        }

    }, [project.logo, project.aspectRatio, setProject]);

    const handleSetEditPrompt = (category: BrandingResultCategory, prompt: string) => {
        setProject(s => ({ ...s, results: s.results.map(r => r.category === category ? { ...r, editPrompt: prompt } : r)}));
    };

    const handleImageEdit = async (category: BrandingResultCategory) => {
        const resultToEdit = project.results.find(r => r.category === category);
        if (!resultToEdit || !resultToEdit.image || !resultToEdit.editPrompt.trim()) return;

        setProject(s => ({...s, results: s.results.map(r => r.category === category ? { ...r, isEditing: true, error: null } : r)}));
        try {
            const newImage = await editImage(resultToEdit.image, resultToEdit.editPrompt);
            setProject(s => ({...s, results: s.results.map(r => r.category === category ? { ...r, image: newImage, isEditing: false, editPrompt: '' } : r)}));
        } catch (err) {
            const errorMessage = err instanceof Error ? err.message : 'An unknown error occurred during image editing.';
            setProject(s => ({...s, results: s.results.map(r => r.category === category ? { ...r, error: errorMessage, isEditing: false } : r)}));
        }
    };

    if (!project) return <div>Loading...</div>;

    const isLoading = project.isUploading || project.isAnalyzing || project.isGenerating;

    return (
        <main className="w-full max-w-7xl flex flex-col gap-4 pt-4 pb-8 flex-grow">
            {/* --- CONTROLS --- */}
            <div className="glass-card rounded-2xl p-4 flex flex-col md:flex-row items-center gap-4">
                <div className="w-full md:w-48 flex-shrink-0">
                    <ImageUploader
                        id="branding-logo-uploader"
                        title="Upload Your Logo"
                        images={project.logo ? [project.logo] : []}
                        onFileUpload={handleFileUpload}
                        onRemove={handleRemoveLogo}
                        isUploading={project.isUploading}
                        onImageUpdate={handleUpdateLogo}
                    />
                </div>
                <div className="flex-grow text-center md:text-left">
                    <h2 className="text-xl font-bold text-[var(--color-text-base)]">Branding Studio</h2>
                    <p className="text-md text-[var(--color-text-secondary)] mt-1">Upload your logo to generate a complete brand identity kit, from colors and fonts to professional mockups.</p>
                     <div className="mt-4">
                        <h4 className="text-sm font-semibold text-[var(--color-text-medium)] mb-2">Mockup Aspect Ratio</h4>
                        <div className="flex justify-center md:justify-start gap-2 flex-wrap">
                            {ASPECT_RATIOS.map(ratio => (
                                <button
                                    key={ratio.value}
                                    onClick={() => setProject(s => ({ ...s, aspectRatio: ratio.value as AspectRatio }))}
                                    className={`px-3 py-1.5 text-xs font-semibold rounded-full transition-colors ${
                                        project.aspectRatio === ratio.value 
                                        ? 'bg-[var(--color-accent)] text-white' 
                                        : 'bg-black/20 text-[var(--color-text-secondary)] hover:text-[var(--color-text-base)]'
                                    }`}
                                >
                                    {ratio.value}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
                <button
                    onClick={onGenerate}
                    disabled={!project.logo || isLoading}
                    className="w-full md:w-auto flex-shrink-0 bg-gradient-to-r from-[var(--color-accent)] to-[var(--color-accent-dark)] hover:from-[var(--color-accent-dark)] hover:to-[var(--color-accent-darker)] text-[var(--color-text-base)] font-bold py-3 px-8 rounded-lg text-lg transition-all duration-300 ease-in-out disabled:opacity-50 disabled:cursor-not-allowed shadow-lg hover:shadow-2xl hover:shadow-[var(--color-accent)]/20 disabled:shadow-none transform hover:-translate-y-1 disabled:transform-none"
                >
                    {project.isUploading ? 'Uploading...' : project.isAnalyzing ? 'Analyzing...' : project.isGenerating ? 'Generating...' : 'Generate Branding'}
                </button>
            </div>

            {project.error && <div className="bg-[rgba(var(--color-accent-rgb),0.2)] border border-[rgba(var(--color-accent-rgb),0.5)] text-[var(--color-accent-light)] px-4 py-3 rounded-lg" role="alert">{project.error}</div>}

            {/* --- BRAND IDENTITY RESULTS --- */}
            {(project.colors.length > 0) && !project.isAnalyzing && (
                <div className="glass-card rounded-2xl p-4">
                    <h3 className="text-xl font-bold text-[var(--color-text-base)] mb-4">Brand Identity Kit</h3>
                    <div>
                        <h4 className="text-md font-semibold text-[var(--color-text-medium)] mb-3">Color Palette</h4>
                        <div className="flex flex-wrap gap-3">
                            {project.colors.map((color, index) => (
                                <div key={index} className="text-center">
                                    <div className="w-16 h-16 rounded-lg border border-white/10" style={{backgroundColor: color}}></div>
                                    <p className="text-xs mt-1.5 font-mono text-[var(--color-text-secondary)]">{color}</p>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            )}

            {/* --- MOCKUP RESULTS --- */}
            {project.results.length > 0 && (
                <div className="glass-card rounded-2xl p-4">
                    <h3 className="text-xl font-bold text-[var(--color-text-base)] mb-4">Brand Mockups & Guidelines</h3>
                     <BrandingResultsGrid
                        results={project.results}
                        onImageEdit={handleImageEdit}
                        onSetEditPrompt={handleSetEditPrompt}
                     />
                </div>
            )}
        </main>
    );
};

export default BrandingStudio;

