                                className="col-span-2 bg-[rgba(var(--color-text-base-rgb),0.1)] hover:bg-[rgba(var(--color-text-base-rgb),0.2)] text-[var(--color-text-base)] font-medium py-3 px-4 rounded-xl transition-all flex items-center justify-center gap-2"
                            >
                                <ResetIcon /> Reset All
                            </button>
                        )}
                    </div>
                    {project.generatedImage && (
                        <div className="mt-2">
                             <button 
                                onClick={resetSliders}
                                className="w-full bg-[rgba(var(--color-text-base-rgb),0.05)] hover:bg-[rgba(var(--color-text-base-rgb),0.1)] text-[var(--color-text-secondary)] hover:text-[var(--color-text-base)] font-medium py-2 px-4 rounded-xl transition-all flex items-center justify-center gap-2 text-sm"
                            >
                                <ResetIcon /> Reset All Sliders
                            </button>
                        </div>
                     )}
                </div>
            </div>

            {/* --- RIGHT COLUMN: CONTROLS (4 cols) --- */}
            <div className="lg:col-span-4 flex flex-col gap-4 order-3">
                <div className="glass-card rounded-2xl p-1 flex mb-2">
                     {(['Face', 'Head', 'Body', 'Retouch'] as ControlCategory[]).map(cat => (
                         <button
                            key={cat}
                            onClick={() => setProject(s => ({ ...s, activeCategory: cat }))}
                            className={`flex-1 flex items-center justify-center gap-2 py-2.5 rounded-xl text-sm font-medium transition-all ${project.activeCategory === cat ? 'bg-[var(--color-accent)] text-white shadow-md' : 'text-[var(--color-text-secondary)] hover:bg-[rgba(var(--color-text-base-rgb),0.05)] hover:text-[var(--color-text-base)]'}`}
                         >
                             {cat === 'Face' && <FaceIcon />}
                             {cat === 'Head' && <HeadIcon />}
                             {cat === 'Body' && <BodyIcon />}
                             {cat === 'Retouch' && <RetouchIcon />}
                             {cat}
                         </button>
                     ))}
                </div>

                <div className="glass-card rounded-2xl p-5 flex flex-col gap-6 h-full">
                    {/* Presets */}
                    {project.activeCategory === 'Face' && (
                         <div className="mb-2">
                            <h4 className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-wider mb-3">Emotion Preset</h4>
                            <div className="grid grid-cols-3 gap-2">
                                {['Neutral', 'Happy', 'Sad', 'Angry', 'Surprised'].map(preset => (
                                    <button 
                                        key={preset}
                                        onClick={() => preset === 'Neutral' ? resetSliders() : applyPreset(preset)}
                                        className="bg-[rgba(var(--color-text-base-rgb),0.05)] hover:bg-[rgba(var(--color-text-base-rgb),0.1)] border border-[rgba(var(--color-text-base-rgb),0.1)] text-[var(--color-text-secondary)] hover:text-[var(--color-text-base)] text-xs font-medium py-1.5 rounded-lg transition-colors"
                                    >
                                        {preset}
                                    </button>
                                ))}
                            </div>
                         </div>
                    )}

                    {/* Sliders */}
                    <div className="flex flex-col gap-5 overflow-y-auto max-h-[600px] pr-2 suggestions-scrollbar">
                        {activeSliders.map(slider => (
                            <div key={slider.id} className="flex flex-col gap-2">
                                <div className="flex justify-between items-center">
                                    <label htmlFor={slider.id} className="text-sm font-medium text-[var(--color-text-base)]">{slider.label}</label>
                                    <span className="text-xs font-mono bg-[rgba(var(--color-accent-rgb),0.1)] text-[var(--color-accent-light)] px-2 py-0.5 rounded">{slider.value.toFixed(2)}</span>
                                </div>
                                <input 
                                    type="range" 
                                    id={slider.id}
                                    min={slider.min} 
                                    max={slider.max} 
                                    step={slider.step}
                                    value={slider.value}
                                    onChange={(e) => handleSliderChange(slider.id, parseFloat(e.target.value))}
                                    className="w-full h-2 bg-[rgba(var(--color-text-base-rgb),0.1)] rounded-lg appearance-none cursor-pointer accent-[var(--color-accent)] focus:outline-none focus:ring-2 focus:ring-[var(--color-accent)]/50"
                                />
                            </div>
                        ))}
                        {activeSliders.length === 0 && (
                             <p className="text-center text-[var(--color-text-muted)] text-sm py-8">No sliders available for this category yet.</p>
                        )}
                    </div>
                </div>
            </div>

        </main>
    );
};

