    { 
        label: '4:3', 
        value: 4/3, 
        icon: <div className="w-7 h-5 border-2 border-white rounded-sm bg-white/20"></div> 
    }
];

const LoadingSpinner = () => (
    <div className="animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-white"></div>
);

const ImageCropper: React.FC<ImageCropperProps> = ({ file, onConfirm, onCancel }) => {
    const [isProcessing, setIsProcessing] = useState(false);

    const handleAutoCrop = async (ratioValue: number) => {
        setIsProcessing(true);

        try {
            // 1. Create an image element to read dimensions
            const img = new Image();
            const objectUrl = URL.createObjectURL(file);

            await new Promise((resolve, reject) => {
                img.onload = resolve;
                img.onerror = reject;
                img.src = objectUrl;
            });

            // 2. Calculate crop dimensions (Center Crop)
            const canvas = document.createElement('canvas');
            const ctx = canvas.getContext('2d');

            if (!ctx) throw new Error('Could not get canvas context');

            const sourceWidth = img.naturalWidth;
            const sourceHeight = img.naturalHeight;
            const sourceRatio = sourceWidth / sourceHeight;

            let drawWidth, drawHeight, offsetX, offsetY;

            // If source is wider than target ratio, crop width (pillarbox style logic turned to crop)
            if (sourceRatio > ratioValue) {
                drawHeight = sourceHeight;
                drawWidth = sourceHeight * ratioValue;
                offsetX = (sourceWidth - drawWidth) / 2;
                offsetY = 0;
            } else {
                // Source is taller than target ratio, crop height
                drawWidth = sourceWidth;
                drawHeight = sourceWidth / ratioValue;
                offsetX = 0;
                offsetY = (sourceHeight - drawHeight) / 2;
            }

            // Set canvas size to the cropped size (High Quality)
            canvas.width = drawWidth;
            canvas.height = drawHeight;

            // Draw the cropped portion
            ctx.drawImage(
                img,
                offsetX, offsetY, drawWidth, drawHeight, // Source rectangle
                0, 0, drawWidth, drawHeight // Destination rectangle
            );

            // 3. Convert back to file
            canvas.toBlob((blob) => {
                if (blob) {
                    const newFile = new File([blob], file.name, { type: file.type });
                    onConfirm(newFile);
                }
                URL.revokeObjectURL(objectUrl);
                setIsProcessing(false);
            }, file.type, 0.95);

        } catch (error) {
            console.error("Auto crop failed", error);
            setIsProcessing(false);
            onCancel(); // Fallback
        }
    };

    return (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex flex-col items-center justify-center animate-in fade-in duration-200 p-4 text-white">

            {isProcessing ? (
                <div className="flex flex-col items-center gap-2">
                    <LoadingSpinner />
                    <p className="text-sm font-medium">Cropping...</p>
                </div>
            ) : (
                <>
                    <h3 className="text-lg font-bold mb-6 text-white drop-shadow-md">Select Aspect Ratio</h3>

                    <div className="flex flex-wrap justify-center gap-4 mb-8">
                        {RATIOS.map((ratio) => (
                            <button
                                key={ratio.label}
                                onClick={() => handleAutoCrop(ratio.value)}
                                className="flex flex-col items-center gap-2 group transition-transform hover:scale-110 active:scale-95"
                                title={`Crop to ${ratio.label}`}
                            >
                                <div className="p-3 rounded-xl bg-white/10 group-hover:bg-white/20 border border-white/10 group-hover:border-[var(--color-accent)] transition-all shadow-lg">
                                    {ratio.icon}
                                </div>
                                <span className="text-xs font-medium text-white/80 group-hover:text-white">{ratio.label}</span>
                            </button>
                        ))}
                    </div>

                    <button 
                        onClick={onCancel}
                        className="px-6 py-2 rounded-full bg-white/10 hover:bg-white/20 text-sm font-medium transition-colors border border-white/10"
                    >
                        Cancel
                    </button>
                </>
            )}
        </div>
    );
};

