  onConfirm: (croppedFile: File) => void;
  onCancel: () => void;
}

type AspectRatio = {
    label: string;
    value: number; // width / height
    icon: React.ReactNode;
};

const RATIOS: AspectRatio[] = [
    { 
        label: '1:1', 
        value: 1, 
        icon: <div className="w-6 h-6 border-2 border-current rounded-sm"></div> 
    },
    { 
