    },
    { 
        label: '9:16', 
        value: 9/16, 
        icon: <div className="w-5 h-8 border-2 border-current rounded-sm"></div> 
    },
    { 
        label: '4:3', 
        value: 4/3, 
        icon: <div className="w-7 h-5 border-2 border-current rounded-sm"></div> 
    }
];

const CheckIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
    </svg>
);

const BackIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M10 19l-7-7m0 0l7-7m-7 7h18" />
    </svg>
);

const XIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
    </svg>
);

const ImageCropper: React.FC<ImageCropperProps> = ({ file, onConfirm, onCancel }) => {
    const [mode, setMode] = useState<'select' | 'edit'>('select');
    const [selectedRatio, setSelectedRatio] = useState<number>(1);
    const [imageSrc, setImageSrc] = useState<string | null>(null);

    // Transform state for the image inside the crop box
    const [transform, setTransform] = useState({ x: 0, y: 0, scale: 1 });
    const [isDragging, setIsDragging] = useState(false);
    const dragStartRef = useRef({ x: 0, y: 0 });
    const transformStartRef = useRef({ x: 0, y: 0 });

    const containerRef = useRef<HTMLDivElement>(null);
    const imgRef = useRef<HTMLImageElement>(null);
    const naturalSizeRef = useRef({ w: 0, h: 0 });

    useEffect(() => {
        const objectUrl = URL.createObjectURL(file);
        setImageSrc(objectUrl);
        return () => URL.revokeObjectURL(objectUrl);
    }, [file]);

    // Initialize crop position (Center & Cover)
    const initCrop = useCallback(() => {
        if (!containerRef.current || !naturalSizeRef.current.w) return;

        const contW = containerRef.current.clientWidth;
        const contH = containerRef.current.clientHeight;
        const imgW = naturalSizeRef.current.w;
        const imgH = naturalSizeRef.current.h;

        // Calculate scale to cover the container
        const scaleX = contW / imgW;
        const scaleY = contH / imgH;
        const scale = Math.max(scaleX, scaleY);

        // Center the image
        const x = (contW - imgW * scale) / 2;
        const y = (contH - imgH * scale) / 2;

        setTransform({ x, y, scale });
    }, []);

    // Re-initialize when entering edit mode or resizing
    useEffect(() => {
        if (mode === 'edit') {
            const timer = setTimeout(initCrop, 100);
            return () => clearTimeout(timer);
        }
    }, [mode, selectedRatio, initCrop]);

    const handleRatioClick = (ratioValue: number) => {
        setSelectedRatio(ratioValue);
        setMode('edit');
    };

    const handlePointerDown = (e: React.PointerEvent) => {
        e.preventDefault();
        setIsDragging(true);
        dragStartRef.current = { x: e.clientX, y: e.clientY };
        transformStartRef.current = { x: transform.x, y: transform.y };
    };

    const handlePointerMove = (e: React.PointerEvent) => {
        if (!isDragging) return;
        e.preventDefault();
        const dx = e.clientX - dragStartRef.current.x;
        const dy = e.clientY - dragStartRef.current.y;
        setTransform(prev => ({
            ...prev,
            x: transformStartRef.current.x + dx,
            y: transformStartRef.current.y + dy
        }));
    };

    const handlePointerUp = () => {
        setIsDragging(false);
    };

    const handleCrop = () => {
        if (!naturalSizeRef.current.w || !containerRef.current) return;

        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        // Target Resolution (High Quality)
        const targetWidth = 1500;
        const targetHeight = targetWidth / selectedRatio;

        canvas.width = targetWidth;
        canvas.height = targetHeight;

        // Fill background
        ctx.fillStyle = '#000000';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // Map visible transform to canvas coordinates
        const pixelRatio = targetWidth / containerRef.current.clientWidth;

        const drawX = transform.x * pixelRatio;
        const drawY = transform.y * pixelRatio;
        const drawW = naturalSizeRef.current.w * transform.scale * pixelRatio;
        const drawH = naturalSizeRef.current.h * transform.scale * pixelRatio;

        ctx.imageSmoothingEnabled = true;
        ctx.imageSmoothingQuality = 'high';

        const img = new Image();
        img.src = imageSrc!;

        ctx.drawImage(img, drawX, drawY, drawW, drawH);

        canvas.toBlob((blob) => {
            if (blob) {
                const newFile = new File([blob], file.name, { type: file.type });
                onConfirm(newFile);
            }
        }, file.type, 0.95);
    };

    if (!imageSrc) return null;

    return (
        <div className="fixed inset-0 z-[9999] bg-black/95 backdrop-blur-md flex flex-col items-center justify-center animate-in fade-in duration-200">

            {/* SELECT MODE */}
            {mode === 'select' && (
                <div className="relative w-full max-w-lg bg-[#1a1a1a] border border-white/10 rounded-2xl p-8 flex flex-col items-center gap-6 shadow-2xl">
                    <button 
                        onClick={onCancel}
                        className="absolute top-4 right-4 text-white/50 hover:text-white transition-colors"
                    >
                        <XIcon />
                    </button>

                    <h3 className="text-xl font-bold text-white">Select Aspect Ratio</h3>

                    <div className="grid grid-cols-3 gap-4 w-full">
                        {RATIOS.map((ratio) => (
                            <button
                                key={ratio.label}
                                onClick={() => handleRatioClick(ratio.value)}
                                className="flex flex-col items-center justify-center gap-3 p-4 rounded-xl bg-white/5 hover:bg-[var(--color-accent)]/20 border border-white/10 hover:border-[var(--color-accent)] transition-all group"
                            >
                                <div className="text-white/70 group-hover:text-[var(--color-accent)] transition-colors">
                                    {ratio.icon}
                                </div>
                                <span className="text-sm font-medium text-white/80 group-hover:text-white">{ratio.label}</span>
                            </button>
                        ))}
                    </div>
                </div>
            )}

            {/* EDIT MODE */}
            {mode === 'edit' && (
                <div className="w-full h-full flex flex-col">
                    {/* Header */}
                    <div className="flex-shrink-0 h-16 bg-[#1a1a1a] border-b border-white/10 flex items-center justify-between px-4 sm:px-8">
                        <button 
                            onClick={() => setMode('select')}
                            className="flex items-center gap-2 text-white/70 hover:text-white transition-colors px-3 py-2 rounded-lg hover:bg-white/5"
                        >
                            <BackIcon />
                            <span className="hidden sm:inline text-sm font-medium">Change Ratio</span>
                        </button>

                        <h3 className="text-white font-semibold">Adjust Crop</h3>

                        <button 
                            onClick={onCancel}
                            className="p-2 rounded-full text-white/70 hover:text-white hover:bg-white/10 transition-colors"
                        >
                            <XIcon />
                        </button>
                    </div>

                    {/* Workspace */}
                    <div className="flex-grow relative overflow-hidden flex items-center justify-center bg-[#050505] p-8 cursor-move touch-none select-none">
                        <div 
                            ref={containerRef}
                            style={{ aspectRatio: selectedRatio }}
                            className="relative w-full h-full max-w-5xl max-h-[75vh] shadow-[0_0_0_9999px_rgba(0,0,0,0.9)] border-2 border-[var(--color-accent)] outline outline-1 outline-white/20"
                            onPointerDown={handlePointerDown}
                            onPointerMove={handlePointerMove}
                            onPointerUp={handlePointerUp}
                            onPointerLeave={handlePointerUp}
                        >
                            <img 
                                ref={imgRef}
                                src={imageSrc} 
                                alt="Crop target" 
                                className="absolute top-0 left-0 max-w-none max-h-none select-none pointer-events-none origin-top-left will-change-transform"
                                style={{
                                    transform: `translate3d(${transform.x}px, ${transform.y}px, 0) scale(${transform.scale})`,
                                    width: naturalSizeRef.current.w > 0 ? naturalSizeRef.current.w : 'auto', 
                                }}
                                onLoad={(e) => {
                                    naturalSizeRef.current = { w: e.currentTarget.naturalWidth, h: e.currentTarget.naturalHeight };
                                    initCrop(); 
                                }}
                                draggable={false}
                            />

                            {/* Grid Overlay */}
                            <div className="absolute inset-0 pointer-events-none opacity-30 grid grid-cols-3 grid-rows-3">
                                <div className="border-r border-b border-white"></div>
                                <div className="border-r border-b border-white"></div>
                                <div className="border-b border-white"></div>
                                <div className="border-r border-b border-white"></div>
                                <div className="border-r border-b border-white"></div>
                                <div className="border-b border-white"></div>
                                <div className="border-r border-white"></div>
                                <div className="border-r border-white"></div>
                                <div></div>
                            </div>
                        </div>

                        <div className="absolute bottom-6 bg-black/60 backdrop-blur-md px-4 py-2 rounded-full text-white/80 text-sm pointer-events-none border border-white/10">
                            Drag to pan • Pinch/Scroll to zoom (Coming soon)
                        </div>
                    </div>

                    {/* Footer */}
                    <div className="flex-shrink-0 h-20 bg-[#1a1a1a] border-t border-white/10 flex items-center justify-center gap-4 px-6">
                        <button 
                            onClick={onCancel}
                            className="px-8 py-3 rounded-xl text-white/70 hover:text-white hover:bg-white/10 text-sm font-bold transition-colors"
                        >
                            Cancel
                        </button>
                        <button 
                            onClick={handleCrop}
                            className="px-10 py-3 rounded-xl bg-[var(--color-accent)] text-white hover:bg-[var(--color-accent-dark)] shadow-lg shadow-[var(--color-accent)]/20 text-sm font-bold transition-transform active:scale-95 flex items-center gap-2"
                        >
                            <CheckIcon />
                            Apply Crop
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
};

