const MagicIcon = () => <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-2" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M5 2a1 1 0 011 1v1h1a1 1 0 010 2H6v1a1 1 0 11-2 0V6H3a1 1 0 110-2h1V3a1 1 0 011-1zm12 10a1 1 0 011 1v1h1a1 1 0 110 2h-1v1a1 1 0 11-2 0v-1h-1a1 1 0 110-2h1v-1a1 1 0 011-1zM10 2a1 1 0 011 1v1a1 1 0 11-2 0V3a1 1 0 011-1zm0 14a1 1 0 011 1v1a1 1 0 11-2 0v-1a1 1 0 011-1zM4.156 5.156a1 1 0 011.414-1.414l.707.707a1 1 0 01-1.414 1.414l-.707-.707zm11.314 11.314a1 1 0 011.414-1.414l.707.707a1 1 0 01-1.414 1.414l-.707-.707zm-8.485 2.122a1 1 0 01-1.414 1.414l-.707-.707a1 1 0 011.414-1.414l.707.707zM15.844 5.156a1 1 0 011.414 1.414l-.707.707a1 1 0 01-1.414-1.414l.707-.707z" clipRule="evenodd" /></svg>;

const ImageCropper: React.FC<ImageCropperProps> = ({ file, onConfirm, onCancel }) => {
    const [activeTool, setActiveTool] = useState<'crop' | 'expand'>('crop');
    const [selectedRatio, setSelectedRatio] = useState<number>(1);
    const [imageSrc, setImageSrc] = useState<string | null>(null);
    const [isGenerating, setIsGenerating] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [expandPrompt, setExpandPrompt] = useState("Seamlessly fill the empty space to extend the background naturally.");

    // Transform state
    const [transform, setTransform] = useState({ x: 0, y: 0, scale: 1 });
    const [isDragging, setIsDragging] = useState(false);
    const dragStartRef = useRef({ x: 0, y: 0 });
    const transformStartRef = useRef({ x: 0, y: 0 });

    const containerRef = useRef<HTMLDivElement>(null);
    const imgRef = useRef<HTMLImageElement>(null);
    const naturalSizeRef = useRef({ w: 0, h: 0 });

    useEffect(() => {
        const objectUrl = URL.createObjectURL(file);
        setImageSrc(objectUrl);
        return () => URL.revokeObjectURL(objectUrl);
    }, [file]);

    // Initialize position based on tool
    const initTransform = useCallback(() => {
        if (!containerRef.current || !naturalSizeRef.current.w) return;

        const contW = containerRef.current.clientWidth;
        const contH = containerRef.current.clientHeight;
        const imgW = naturalSizeRef.current.w;
        const imgH = naturalSizeRef.current.h;

        let scale, x, y;

        if (activeTool === 'crop') {
            // Cover: Image fills container
            const scaleX = contW / imgW;
            const scaleY = contH / imgH;
            scale = Math.max(scaleX, scaleY);
        } else {
            // Contain: Image fits inside container (expand mode)
            const scaleX = (contW * 0.8) / imgW; // 80% size to show expansion area
            const scaleY = (contH * 0.8) / imgH;
            scale = Math.min(scaleX, scaleY);
        }

        x = (contW - imgW * scale) / 2;
        y = (contH - imgH * scale) / 2;

        setTransform({ x, y, scale });
    }, [activeTool]);

    // Re-initialize when entering edit mode, changing ratio, or changing tool
    useEffect(() => {
        const timer = setTimeout(initTransform, 50);
        return () => clearTimeout(timer);
    }, [selectedRatio, initTransform, activeTool]);

    const handlePointerDown = (e: React.PointerEvent) => {
        e.preventDefault();
        setIsDragging(true);
        dragStartRef.current = { x: e.clientX, y: e.clientY };
        transformStartRef.current = { x: transform.x, y: transform.y };
    };

    const handlePointerMove = (e: React.PointerEvent) => {
        if (!isDragging) return;
        e.preventDefault();
        const dx = e.clientX - dragStartRef.current.x;
        const dy = e.clientY - dragStartRef.current.y;
        setTransform(prev => ({
            ...prev,
            x: transformStartRef.current.x + dx,
            y: transformStartRef.current.y + dy
        }));
    };

    const handlePointerUp = () => {
        setIsDragging(false);
    };

    // Shared canvas capture logic
    const getCanvasData = (targetWidth: number): { canvas: HTMLCanvasElement, ctx: CanvasRenderingContext2D } | null => {
        if (!naturalSizeRef.current.w || !containerRef.current) return null;

        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        if (!ctx) return null;

        const targetHeight = targetWidth / selectedRatio;
        canvas.width = targetWidth;
        canvas.height = targetHeight;

        // Fill background based on tool
        ctx.fillStyle = activeTool === 'expand' ? '#FFFFFF' : '#000000'; // White for expand helps blending sometimes, or can be transparent
        if (activeTool === 'expand') {
             // Use transparent for expand so model fills it? 
             // Actually, for editImage, providing a transparent area often helps the model understand it needs to fill it.
             // But canvas toBlob with jpeg makes it black/white. Let's stick to clear.
             ctx.clearRect(0, 0, canvas.width, canvas.height);
        } else {
             ctx.fillRect(0, 0, canvas.width, canvas.height);
        }

        // Map visible transform to canvas coordinates
        const pixelRatio = targetWidth / containerRef.current.clientWidth;

        const drawX = transform.x * pixelRatio;
        const drawY = transform.y * pixelRatio;
        const drawW = naturalSizeRef.current.w * transform.scale * pixelRatio;
        const drawH = naturalSizeRef.current.h * transform.scale * pixelRatio;

        ctx.imageSmoothingEnabled = true;
        ctx.imageSmoothingQuality = 'high';

        const img = new Image();
        img.src = imageSrc!;

        ctx.drawImage(img, drawX, drawY, drawW, drawH);
        return { canvas, ctx };
    };

    const handleCrop = () => {
        const data = getCanvasData(1500);
        if (!data) return;

        data.canvas.toBlob((blob) => {
            if (blob) {
                const newFile = new File([blob], file.name, { type: file.type });
                onConfirm(newFile);
            }
        }, file.type, 0.95);
    };

    const handleExpand = async () => {
        setIsGenerating(true);
        setError(null);

        const data = getCanvasData(1500);
        if (!data) {
             setIsGenerating(false);
             return;
        }

        // Convert canvas to base64 for API
        const base64 = data.canvas.toDataURL('image/png').split(',')[1];
        const imageFile: ImageFile = { base64, mimeType: 'image/png', name: 'expand_input.png' };

        try {
            const result = await expandImage(imageFile, expandPrompt);

            // Convert result back to File object
            const byteString = atob(result.base64);
            const ab = new ArrayBuffer(byteString.length);
            const ia = new Uint8Array(ab);
            for (let i = 0; i < byteString.length; i++) {
                ia[i] = byteString.charCodeAt(i);
            }
            const newFile = new File([ab], 'expanded_image.png', { type: 'image/png' });
            onConfirm(newFile);

        } catch (err) {
            console.error(err);
