    const [selectedRatio, setSelectedRatio] = useState<number>(1);
    const [imageSrc, setImageSrc] = useState<string | null>(null);
    const [isGenerating, setIsGenerating] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [expandPrompt, setExpandPrompt] = useState("Seamlessly fill the empty space to extend the background naturally.");

    // Transform state
    const [transform, setTransform] = useState({ x: 0, y: 0, scale: 1 });
    const [isDragging, setIsDragging] = useState(false);
    const dragStartRef = useRef({ x: 0, y: 0 });
    const transformStartRef = useRef({ x: 0, y: 0 });

    const containerRef = useRef<HTMLDivElement>(null);
    const imgRef = useRef<HTMLImageElement>(null);
    const naturalSizeRef = useRef({ w: 0, h: 0 });

    useEffect(() => {
        const objectUrl = URL.createObjectURL(file);
        setImageSrc(objectUrl);
        // Lock body scroll
        document.body.style.overflow = 'hidden';

        return () => {
            URL.revokeObjectURL(objectUrl);
            document.body.style.overflow = 'auto';
        };
    }, [file]);

    // Initialize position based on tool
    const initTransform = useCallback(() => {
        if (!containerRef.current || !naturalSizeRef.current.w) return;

        const contW = containerRef.current.clientWidth;
        const contH = containerRef.current.clientHeight;
        const imgW = naturalSizeRef.current.w;
        const imgH = naturalSizeRef.current.h;

        let scale, x, y;

        if (activeTool === 'crop') {
            // Cover: Image fills container
            const scaleX = contW / imgW;
            const scaleY = contH / imgH;
            scale = Math.max(scaleX, scaleY);
        } else {
            // Contain: Image fits inside container (expand mode)
            const scaleX = (contW * 0.8) / imgW; // 80% size to show expansion area
            const scaleY = (contH * 0.8) / imgH;
            scale = Math.min(scaleX, scaleY);
        }

        x = (contW - imgW * scale) / 2;
        y = (contH - imgH * scale) / 2;

        setTransform({ x, y, scale });
    }, [activeTool]);

    // Re-initialize when entering edit mode, changing ratio, or changing tool
    useEffect(() => {
        const timer = setTimeout(initTransform, 50);
        return () => clearTimeout(timer);
    }, [selectedRatio, initTransform, activeTool]);

    const handlePointerDown = (e: React.PointerEvent) => {
        e.preventDefault();
        setIsDragging(true);
        dragStartRef.current = { x: e.clientX, y: e.clientY };
