        // Prevent default only works if passive is false, but React synthetic event wrapper 
        // doesn't support passive option easily. However, since the modal covers screen and body
        // has overflow hidden, main page won't scroll. We mostly need to stop propagation.
        e.stopPropagation();

        const rect = containerRef.current.getBoundingClientRect();
        // Mouse position relative to container
        const offsetX = e.clientX - rect.left;
        const offsetY = e.clientY - rect.top;

        // Zoom speed
        const delta = -e.deltaY * 0.001; 

