        // Formula: newPos = mousePos - (mousePos - oldPos) * (newScale / oldScale)
        const scaleRatio = newScale / transform.scale;
        const newX = offsetX - (offsetX - transform.x) * scaleRatio;
        const newY = offsetY - (offsetY - transform.y) * scaleRatio;

