                                    transform: `translate3d(${transform.x}px, ${transform.y}px, 0) scale(${transform.scale})`,
                                    width: naturalSizeRef.current.w > 0 ? naturalSizeRef.current.w : 'auto', 
                                    opacity: isGenerating ? 0.5 : 1
                                }}
                                onLoad={(e) => {
                                    naturalSizeRef.current = { w: e.currentTarget.naturalWidth, h: e.currentTarget.naturalHeight };
                                    initTransform(); 
                                }}
                                draggable={false}
                            />

                            {/* Loading Overlay */}
                            {isGenerating && (
                                <div className="absolute inset-0 z-50 flex flex-col items-center justify-center">
                                    <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-[var(--color-accent)]"></div>
                                    <p className="text-white text-sm mt-3 font-medium animate-pulse">Expanding Image...</p>
                                </div>
                            )}

                            {/* Grid Overlay (Crop only) */}
                            {activeTool === 'crop' && (
                                <div className="absolute inset-0 pointer-events-none opacity-30 grid grid-cols-3 grid-rows-3 z-20">
                                    <div className="border-r border-b border-white"></div>
                                    <div className="border-r border-b border-white"></div>
                                    <div className="border-b border-white"></div>
                                    <div className="border-r border-b border-white"></div>
                                    <div className="border-r border-b border-white"></div>
                                    <div className="border-b border-white"></div>
                                    <div className="border-r border-white"></div>
                                    <div className="border-r border-white"></div>
                                    <div></div>
                                </div>
                            )}
                        </div>

                        <div className="absolute bottom-6 bg-black/60 backdrop-blur-md px-4 py-2 rounded-full text-white/80 text-sm pointer-events-none border border-white/10 shadow-lg">
                            <span className="hidden sm:inline">Scroll to Zoom • </span>Drag to Pan
                        </div>

                         {error && (
                            <div className="absolute top-6 bg-red-500/90 text-white px-6 py-3 rounded-lg shadow-xl text-sm font-medium animate-in slide-in-from-top-4">
                                {error}
                            </div>
                        )}
                    </div>
                </div>

                {/* Footer Action */}
                <div className="flex-shrink-0 h-20 bg-[#1a1a1a] border-t border-white/10 flex items-center justify-end gap-4 px-6">
                    <button 
                        onClick={onCancel}
                        disabled={isGenerating}
                        className="px-6 py-2.5 rounded-xl text-white/70 hover:text-white hover:bg-white/10 text-sm font-bold transition-colors disabled:opacity-50"
                    >
                        Cancel
                    </button>

                    {activeTool === 'crop' ? (
                        <button 
                            onClick={handleCrop}
                            className="px-8 py-2.5 rounded-xl bg-[var(--color-accent)] text-white hover:bg-[var(--color-accent-dark)] shadow-lg shadow-[var(--color-accent)]/20 text-sm font-bold transition-transform active:scale-95 flex items-center gap-2"
                        >
                            <CheckIcon /> Apply Crop
                        </button>
                    ) : (
                        <button 
                            onClick={handleExpand}
                            disabled={isGenerating}
                            className="px-8 py-2.5 rounded-xl bg-gradient-to-r from-purple-600 to-blue-600 text-white hover:from-purple-700 hover:to-blue-700 shadow-lg text-sm font-bold transition-transform active:scale-95 flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                            {isGenerating ? 'Generating...' : <><MagicIcon /> Generate Fill</>}
                        </button>
                    )}
                </div>
            </div>
        </div>
    );
};

