                    {/* Expand Prompt (Conditional) */}
                    {activeTool === 'expand' && (
                        <div className="flex-1 p-4 animate-in fade-in slide-in-from-right-4">
                             <h4 className="text-[10px] font-bold text-white/40 uppercase mb-2 flex items-center gap-2">
                                <MagicIcon /> AI Prompt
