                    {/* Placeholder for balance if crop selected */}
                    {activeTool === 'crop' && (
                         <div className="flex-1 flex items-center justify-center text-white/20 text-sm italic p-4">
                            Drag image to position • Scroll to zoom
                         </div>
                    )}
                </div>
            </div>
        </div>
    );
};

