  // Using gemini-3-flash-preview for text generation tasks
  const model = 'gemini-3-flash-preview';

  const prompt = `Expand the following idea into a detailed and creative prompt for a text-to-image AI model. The prompt should be a single, rich paragraph describing a scene, including details about the subject, setting, lighting, colors, and overall mood. Do not include any headers, lists, or introductory text like "Here is the prompt:". Just provide the final prompt itself.

  Idea: "${instructions}"`;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: model,
      contents: prompt,
      safetySettings: safetySettings,
    });

    if(!response.text) {
      const safetyText = response.candidates?.[0]?.finishReason;
      if (safetyText && safetyText !== 'STOP') {
          throw new Error(`Prompt generation failed due to safety settings: ${safetyText}`);
      }
      throw new Error('Model returned no text for the prompt.');
    }

    return response.text.trim();

  } catch (error) {
    console.error('Error generating prompt from text:', error);
    let errorMessage = 'An unknown error occurred while generating the prompt.';
    if (error instanceof Error) {
        const msg = error.message.toLowerCase();
        if (msg.includes('api key not valid')) {
            errorMessage = 'Your API key is not valid. Please check your API key and try again.';
        } else if (msg.includes('quota')) {
            errorMessage = 'You have exceeded your API quota. Please check your billing account or try again later.';
        } else if (msg.includes('safety settings')) {
            errorMessage = `Prompt generation was blocked due to safety settings.`;
        } else {
             errorMessage = `Failed to generate prompt. Details: ${error.message}`;
        }
    }
    throw new Error(errorMessage);
  }
}

export async function analyzeStyleImage(styleImage: ImageFile): Promise<string> {
