const CampaignStudio: React.FC<{
    project: CampaignStudioProject;
    setProject: React.Dispatch<React.SetStateAction<CampaignStudioProject>>;
}> = ({ project, setProject }) => {

    // Ensure state properties exist (Defensive)
    const currentMode = project.mode || 'auto';
    const currentIdeas = project.customIdeas || ['', '', ''];
    const currentMood = project.selectedMood || 'Original';
    const currentCustomPrompt = project.customPrompt || '';

    const handleFileUpload = async (files: File[]) => {
        if (!files || files.length === 0) return;
        setProject(s => ({ ...s, isUploading: true, error: null }));

        const filePromises = files.map(file => {
            return new Promise<ImageFile | null>(async (resolve) => {
                if (!file.type.startsWith('image/')) { resolve(null); return; }
                try {
                    const resizedFile = await resizeImage(file, 2048, 2048);
                    const reader = new FileReader();
                    reader.onloadend = () => {
                        resolve({ base64: (reader.result as string).split(',')[1], mimeType: resizedFile.type, name: resizedFile.name });
                    };
                    reader.readAsDataURL(resizedFile);
                } catch (err) { resolve(null); }
            });
        });

        const results = await Promise.all(filePromises);
        const validImages = results.filter((img): img is ImageFile => img !== null);
        if (validImages.length === 0) { setProject(s => ({ ...s, isUploading: false })); return; }

        const combinedImages = [...(project.productImages || []), ...validImages];
        setProject(s => ({ ...s, productImages: combinedImages, isUploading: false, isAnalyzing: true, productAnalysis: '' }));

        try {
            const analysis = await analyzeProductForCampaign(combinedImages);
            setProject(s => ({ ...s, productAnalysis: analysis, isAnalyzing: false }));
        } catch (err) { setProject(s => ({ ...s, isAnalyzing: false })); }
    };

    const handleRemoveImage = (index: number) => {
        setProject(s => {
            const newImages = (s.productImages || []).filter((_, i) => i !== index);
            return { ...s, productImages: newImages, productAnalysis: newImages.length === 0 ? null : s.productAnalysis, results: newImages.length === 0 ? [] : s.results };
        });
    };

    const handleUpdateImage = (index: number, newImage: ImageFile) => {
         setProject(s => {
            const newImages = [...(s.productImages || [])];
            if (index >= 0 && index < newImages.length) newImages[index] = newImage;
            return { ...s, productImages: newImages };
        });
    };

    const updateCustomIdea = (index: number, value: string) => {
        setProject(s => {
            const newIdeas = [...(s.customIdeas || ['', '', ''])];
            newIdeas[index] = value;
            return { ...s, customIdeas: newIdeas };
        });
    };

    const onGenerate = useCallback(async () => {
        if (!project.productImages || project.productImages.length === 0) {
            setProject(s => ({ ...s, error: 'Please upload at least one product image.' }));
            return;
        }

        if (currentMode === 'custom') {
            const hasIdeas = currentIdeas.some(idea => idea.trim() !== '');
            if (!hasIdeas) {
                setProject(s => ({ ...s, error: 'Please enter at least one post idea.' }));
                return;
            }
        }

        setProject(s => ({ ...s, isAnalyzing: true, isGenerating: true, error: null, results: [] }));

        try {
            let analysis = project.productAnalysis;
            if (!analysis) {
                analysis = await analyzeProductForCampaign(project.productImages);
                setProject(s => ({ ...s, productAnalysis: analysis, isAnalyzing: false }));
            } else {
                setProject(s => ({ ...s, isAnalyzing: false }));
            }

            let scenariosToRun: string[] = [];
            if (currentMode === 'auto') {
                scenariosToRun = CAMPAIGN_SCENARIOS;
            } else {
                scenariosToRun = currentIdeas.map((idea, i) => idea.trim() ? `Custom Post ${i + 1}` : null).filter((id): id is string => id !== null);
            }

            const initialResults = scenariosToRun.map(scenario => ({
                scenario, image: null, isLoading: true, error: null, editPrompt: '', isEditing: false
            }));

            setProject(s => ({ ...s, results: initialResults as any }));

            const generationPromises = scenariosToRun.map((scenario) => {
                let prompt = '';
                if (currentMode === 'auto') {
                     const moodValue = CAMPAIGN_MOODS.find(m => m.label === currentMood)?.value || '';
                     const combinedStyle = [moodValue, currentCustomPrompt.trim()].filter(Boolean).join(' ');
                     prompt = getCampaignPrompt(scenario, analysis!, combinedStyle);
                } else {
                    const ideaIndex = parseInt(scenario.replace('Custom Post ', '')) - 1;
                    const specificIdea = currentIdeas[ideaIndex];
                    prompt = `Create a high-end Social Media campaign photo based on:
                    Product: "${analysis}". Idea: "${specificIdea}". Style: "${currentCustomPrompt}". 
                    Constraint: No text. Focus on visual storytelling.`;
                }
                return generateImage(project.productImages, prompt, null)
                    .then(image => ({ status: 'fulfilled' as const, value: { scenario, image } }))
                    .catch(error => ({ status: 'rejected' as const, reason: { scenario, error } }));
            });

            const settledResults = await Promise.all(generationPromises);
            settledResults.forEach(result => {
                if (result.status === 'fulfilled') {
                    const { scenario, image } = result.value;
                    setProject(s => ({ ...s, results: (s.results || []).map(r => r.scenario === scenario ? { ...r, image, isLoading: false } : r) }));
                } else {
                    const { scenario, error } = result.reason;
                    setProject(s => ({ ...s, results: (s.results || []).map(r => r.scenario === scenario ? { ...r, error: error.message || 'Failed', isLoading: false } : r) }));
                }
            });
        } catch (err) {
            setProject(s => ({ ...s, error: err instanceof Error ? err.message : 'Error occurred', isAnalyzing: false }));
        } finally {
            setProject(s => ({ ...s, isGenerating: false }));
        }
    }, [project.productImages, project.productAnalysis, currentMood, currentCustomPrompt, currentMode, currentIdeas, setProject]);

    const handleImageEdit = async (scenario: CampaignScenario) => {
        const resultToEdit = (project.results || []).find(r => r.scenario === scenario);
        if (!resultToEdit || !resultToEdit.image || !resultToEdit.editPrompt.trim()) return;
        setProject(s => ({ ...s, results: (s.results || []).map(r => r.scenario === scenario ? { ...r, isEditing: true, error: null } : r) }));
        try {
            const newImage = await editImage(resultToEdit.image, resultToEdit.editPrompt);
            setProject(s => ({ ...s, results: (s.results || []).map(r => r.scenario === scenario ? { ...r, image: newImage, isEditing: false, editPrompt: '' } : r) }));
        } catch (err) {
            setProject(s => ({ ...s, results: (s.results || []).map(r => r.scenario === scenario ? { ...r, error: 'Edit failed', isEditing: false } : r) }));
        }
    };

    const handleSetEditPrompt = (scenario: CampaignScenario, prompt: string) => {
        setProject(s => ({ ...s, results: (s.results || []).map(r => r.scenario === scenario ? { ...r, editPrompt: prompt } : r) }));
    };

    return (
        <main className="w-full max-w-7xl flex flex-col gap-4 pt-4 pb-8 flex-grow">
            <div className="glass-card rounded-2xl p-4 flex flex-col md:flex-row items-start gap-6">
                <div className="w-full md:w-64 flex-shrink-0">
                    <h3 className="text-sm font-bold text-[var(--color-text-medium)] text-center mb-2">Upload Image(s)</h3>
                    <div className="w-full">
                         <ImageWorkspace
                            productImages={project.productImages || []}
                            onProductImagesUpload={handleFileUpload}
                            onProductImageRemove={handleRemoveImage}
                            isUploading={project.isUploading}
                            onProductImageUpdate={handleUpdateImage}
                        />
                    </div>
                </div>

                <div className="flex-grow w-full flex flex-col gap-4">
                    <div>
                        <h2 className="text-xl font-bold text-[var(--color-text-base)]">Creative Campaign Studio</h2>
                        <p className="text-md text-[var(--color-text-secondary)] mt-1">Generate creative Social Media assets.</p>
                    </div>

                    <div className="flex bg-black/20 rounded-lg p-1 w-full sm:w-fit self-center sm:self-start">
                        <button onClick={() => setProject(s => ({ ...s, mode: 'auto' }))} className={`px-6 py-2 rounded-md text-sm font-semibold transition-all ${currentMode === 'auto' ? 'bg-[var(--color-accent)] text-white' : 'text-[var(--color-text-secondary)]'}`}>Auto Mode</button>
                        <button onClick={() => setProject(s => ({ ...s, mode: 'custom' }))} className={`px-6 py-2 rounded-md text-sm font-semibold transition-all ${currentMode === 'custom' ? 'bg-[var(--color-accent)] text-white' : 'text-[var(--color-text-secondary)]'}`}>Custom Mode</button>
                    </div>

                    {currentMode === 'auto' && (
                        <div className="flex flex-col gap-3 animate-in fade-in">
                             <div className="flex flex-wrap gap-2">
                                {CAMPAIGN_MOODS.map(mood => (
                                    <button key={mood.label} onClick={() => setProject(s => ({ ...s, selectedMood: mood.label }))} className={`px-3 py-1.5 text-xs font-semibold rounded-full border ${currentMood === mood.label ? 'bg-[var(--color-accent)] text-white border-[var(--color-accent)]' : 'bg-black/20 text-[var(--color-text-secondary)] border-transparent'}`}>{mood.label}</button>
                                ))}
                             </div>
                             <input type="text" value={currentCustomPrompt} onChange={(e) => setProject(s => ({ ...s, customPrompt: e.target.value }))} placeholder="Custom Style / Color..." className="w-full glass-input rounded-md px-3 py-2 text-sm"/>
                        </div>
                    )}

                    {currentMode === 'custom' && (
                        <div className="flex flex-col gap-4 animate-in fade-in">
                             <input type="text" value={currentCustomPrompt} onChange={(e) => setProject(s => ({ ...s, customPrompt: e.target.value }))} placeholder="Campaign Style & Mood..." className="w-full glass-input rounded-xl px-4 py-3 text-sm"/>
                             <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                                {[0, 1, 2].map((i) => (
                                    <textarea key={i} value={currentIdeas[i] || ''} onChange={(e) => updateCustomIdea(i, e.target.value)} rows={3} className="w-full glass-input rounded-xl p-3 text-sm resize-none" placeholder={`Post Idea ${i + 1}...`}/>
                                ))}
                             </div>
                        </div>
                    )}

                    {(project.productAnalysis !== null || project.isAnalyzing) && (
                        <div className="p-3 rounded-xl bg-green-500/5 border border-green-500/20 mt-2 relative">
                            {project.isAnalyzing && <div className="absolute inset-0 bg-black/20 backdrop-blur-[1px] z-10 flex items-center justify-center rounded-xl"><div className="animate-spin rounded-full h-6 w-6 border-t-2 border-green-500"></div></div>}
                            <textarea value={project.productAnalysis || ''} onChange={(e) => setProject(s => ({ ...s, productAnalysis: e.target.value }))} className="w-full bg-transparent border-none rounded-md p-2 text-sm text-green-400 focus:outline-none resize-y min-h-[60px]" placeholder="AI Analysis..."/>
                        </div>
                    )}

                    <button onClick={onGenerate} disabled={!project.productImages || project.productImages.length === 0 || project.isGenerating} className="w-full bg-[var(--color-accent)] text-white font-bold py-3 rounded-lg text-lg disabled:opacity-50">
                        {project.isGenerating ? 'Generating...' : `Generate ${currentMode === 'auto' ? '6 Scenarios' : 'Custom Campaign'}`}
                    </button>
                </div>
            </div>

            {(project.results || []).length > 0 && (
                <div className="glass-card rounded-2xl p-4">
                     <h3 className="text-xl font-bold mb-4">Campaign Assets</h3>
                     <BrandingResultsGrid 
                        results={(project.results || []).map(r => ({ ...r, category: r.scenario as any }))}
                        onImageEdit={(cat) => handleImageEdit(cat as any)}
                        onSetEditPrompt={(cat, p) => handleSetEditPrompt(cat as any, p)}
                        gridClassName="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4"
                     />
                </div>
            )}
        </main>
    );
};

