        const resultToEdit = results.find(r => r && r.scenario === scenario);
        if (!resultToEdit || !resultToEdit.image || !resultToEdit.editPrompt.trim()) return;

        setProject(s => ({ ...s, results: (s.results || []).map(r => r.scenario === scenario ? { ...r, isEditing: true, error: null } : r) }));
        try {
            const newImage = await editImage(resultToEdit.image, resultToEdit.editPrompt);
            setProject(s => ({ ...s, results: (s.results || []).map(r => r.scenario === scenario ? { ...r, image: newImage, isEditing: false, editPrompt: '' } : r) }));
        } catch (err) {
            setProject(s => ({ ...s, results: (s.results || []).map(r => r.scenario === scenario ? { ...r, error: 'Edit failed', isEditing: false } : r) }));
        }
    };

    return (
        <main className="w-full max-w-7xl flex flex-col gap-4 pt-4 pb-8 flex-grow">
            <div className="glass-card rounded-2xl p-4 flex flex-col md:flex-row items-start gap-6">
                <div className="w-full md:w-64 flex-shrink-0">
                    <h3 className="text-sm font-bold text-[var(--color-text-medium)] text-center mb-2">Upload Image(s)</h3>
                    <ImageWorkspace
                        productImages={productImages}
                        onProductImagesUpload={handleFileUpload}
                        onProductImageRemove={(idx) => setProject(s => ({ ...s, productImages: (s.productImages || []).filter((_, i) => i !== idx) }))}
                        isUploading={safeProject.isUploading}
                    />
                </div>

                <div className="flex-grow w-full flex flex-col gap-4">
                    <div>
                        <h2 className="text-xl font-bold text-[var(--color-text-base)]">Creative Campaign Studio</h2>
                        <p className="text-md text-[var(--color-text-secondary)] mt-1">Generate creative Social Media assets automatically or with custom ideas.</p>
                    </div>

                    <div className="flex bg-black/20 rounded-lg p-1 w-full sm:w-fit self-center sm:self-start">
                        <button onClick={() => setProject(s => ({ ...s, mode: 'auto' }))} className={`px-6 py-2 rounded-md text-sm font-semibold transition-all ${currentMode === 'auto' ? 'bg-[var(--color-accent)] text-white' : 'text-[var(--color-text-secondary)]'}`}>Auto Scenarios</button>
                        <button onClick={() => setProject(s => ({ ...s, mode: 'custom' }))} className={`px-6 py-2 rounded-md text-sm font-semibold transition-all ${currentMode === 'custom' ? 'bg-[var(--color-accent)] text-white' : 'text-[var(--color-text-secondary)]'}`}>Custom Ideas</button>
                    </div>

                    {currentMode === 'auto' && (
                        <div className="flex flex-col gap-3 animate-in fade-in">
                             <div className="flex flex-wrap gap-2">
                                {CAMPAIGN_MOODS.map(mood => (
                                    <button key={mood.label} onClick={() => setProject(s => ({ ...s, selectedMood: mood.label }))} className={`px-3 py-1.5 text-xs font-semibold rounded-full border ${currentMood === mood.label ? 'bg-[var(--color-accent)] text-white border-[var(--color-accent)]' : 'bg-black/20 text-[var(--color-text-secondary)] border-transparent'}`}>{mood.label}</button>
                                ))}
                             </div>
                             <input type="text" value={currentCustomPrompt} onChange={(e) => setProject(s => ({ ...s, customPrompt: e.target.value }))} placeholder="Additional Style Instructions..." className="w-full glass-input rounded-md px-3 py-2 text-sm"/>
                        </div>
                    )}

                    {currentMode === 'custom' && (
                        <div className="flex flex-col gap-4 animate-in fade-in">
                             <input type="text" value={currentCustomPrompt} onChange={(e) => setProject(s => ({ ...s, customPrompt: e.target.value }))} placeholder="Global Campaign Style & Mood..." className="w-full glass-input rounded-xl px-4 py-3 text-sm"/>
                             <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                                {[0, 1, 2].map((i) => (
                                    <textarea key={i} value={currentIdeas[i] || ''} onChange={(e) => updateCustomIdea(i, e.target.value)} rows={3} className="w-full glass-input rounded-xl p-3 text-sm resize-none" placeholder={`Post Idea ${i + 1}...`}/>
                                ))}
                             </div>
                        </div>
                    )}

                    {(safeProject.productAnalysis !== null || safeProject.isAnalyzing) && (
                        <div className="p-3 rounded-xl bg-green-500/5 border border-green-500/20 mt-2 relative">
                            {safeProject.isAnalyzing && <div className="absolute inset-0 bg-black/20 backdrop-blur-[1px] z-10 flex items-center justify-center rounded-xl"><div className="animate-spin rounded-full h-6 w-6 border-t-2 border-b-2 border-green-500"></div></div>}
                            <textarea value={safeProject.productAnalysis || ''} onChange={(e) => setProject(s => ({ ...s, productAnalysis: e.target.value }))} className="w-full bg-transparent border-none rounded-md p-2 text-sm text-green-400 focus:outline-none resize-y min-h-[60px]" placeholder="AI Analyzing product..."/>
                        </div>
                    )}

                    <button onClick={onGenerate} disabled={productImages.length === 0 || safeProject.isGenerating} className="w-full bg-[var(--color-accent)] text-white font-bold py-3 rounded-lg text-lg disabled:opacity-50 shadow-lg transform active:scale-[0.98] transition-all">
                        {safeProject.isGenerating ? 'Generating Assets...' : `Generate Campaign`}
                    </button>
                </div>
            </div>

            {safeProject.error && <div className="bg-red-500/20 border border-red-500/50 text-red-200 px-4 py-3 rounded-lg text-sm">{safeProject.error}</div>}

            {results.filter(r => !!r).length > 0 && (
                <div className="glass-card rounded-2xl p-4">
                     <h3 className="text-xl font-bold mb-4 text-[var(--color-text-base)]">Generated Campaign Assets</h3>
                     <BrandingResultsGrid 
                        results={results.filter(r => !!r).map(r => ({ 
                            ...r, 
                            category: r.scenario || 'Post',
                            editPrompt: r.editPrompt || '',
                            isEditing: !!r.isEditing,
                            isLoading: !!r.isLoading,
                            error: r.error || null,
                            image: r.image || null
                        }))}
                        onImageEdit={(cat) => handleImageEdit(cat)}
                        onSetEditPrompt={(cat, p) => handleSetEditPrompt(cat, p)}
                        gridClassName="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4"
                     />
                </div>
            )}
        </main>
    );
};

export default CampaignStudio;

import React, { useState } from 'react';
import { createPortal } from 'react-dom';
import { BrandingResult, BrandingResultCategory } from '../types';

const LoadingSpinner = () => (
    <div className="flex justify-center items-center h-full">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-[var(--color-accent)]"></div>
    </div>
);

const ErrorIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12 text-red-400" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.5}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
    </svg>
);

const DownloadIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1.5" viewBox="0 0 20 20" fill="currentColor">
        <path fillRule="evenodd" d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" />
    </svg>
);

const ImageResultCard: React.FC<{ 
    result: BrandingResult;
    onImageEdit: (category: any) => void;
    onSetEditPrompt: (category: any, prompt: string) => void;
}> = ({ result, onImageEdit, onSetEditPrompt }) => {
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [isDownloading, setIsDownloading] = useState(false);

    if (!result) return null;

    const safeCategory = result.category || 'Generated Asset';

    const openModal = () => {
        if (result.image && !result.isLoading && !result.isEditing) setIsModalOpen(true);
    };
    const closeModal = () => setIsModalOpen(false);

    const handleDownload = (resolution: '2k' | '4k') => {
        if (!result.image) return;
        setIsDownloading(true);
        const img = new Image();
        img.src = `data:${result.image.mimeType};base64,${result.image.base64}`;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const ctx = canvas.getContext('2d');
            if (!ctx) {
                setIsDownloading(false); return;
            };
            const targetWidth = resolution === '4k' ? 4096 : 2048;
            const aspectRatio = img.width / img.height;
            canvas.width = targetWidth;
            canvas.height = targetWidth / aspectRatio;
            ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
            const fileNameCategory = String(safeCategory).replace(/\s+/g, '-').toLowerCase();
            const link = document.createElement('a');
            link.download = `Jenta-branding-${fileNameCategory}-${resolution}.png`;
            link.href = canvas.toDataURL('image/png');
            link.click();
            setIsDownloading(false);
        }
        img.onerror = () => setIsDownloading(false);
    };

    return (
        <div className="flex flex-col gap-2">
            <h4 className="text-sm font-semibold text-center text-[var(--color-text-medium)] truncate">{safeCategory}</h4>
            <div 
                onClick={openModal}
                className={`w-full aspect-square bg-black/20 backdrop-blur-sm rounded-xl flex items-center justify-center overflow-hidden relative group transition-all ${result.image && !result.isLoading ? 'cursor-pointer' : ''}`}
            >
                {(result.isLoading || result.isEditing) && <LoadingSpinner />}
                {!result.isLoading && !result.isEditing && result.error && (
                    <div className="flex flex-col items-center text-center p-2">
                        <ErrorIcon />
                        <p className="text-xs text-red-300 mt-2">{result.error}</p>
                    </div>
                )}
                {!result.isLoading && !result.isEditing && result.image && (
                    <>
                        <img 
                            src={`data:${result.image.mimeType};base64,${result.image.base64}`} 
                            alt={`Generated Result for ${safeCategory}`} 
                            className="object-contain w-full h-full"
                        />
                         <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                                <path strokeLinecap="round" strokeLinejoin="round" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0zM10 7v3m0 0v3m0-3h3m-3 0H7" />
                            </svg>
                        </div>
                    </>
                )}
            </div>

            {result.image && !result.isLoading && (
                <div className="flex flex-col gap-2">
                    <textarea
                        value={result.editPrompt || ''}
                        onChange={(e) => onSetEditPrompt(result.category, e.target.value)}
                        rows={2}
                        className="w-full glass-input rounded-md p-2 text-xs leading-relaxed transition-all"
                        placeholder="Refine this image..."
                        disabled={result.isEditing}
                    />
                    <button
                        onClick={() => onImageEdit(result.category)}
                        disabled={result.isEditing || !result.editPrompt?.trim()}
                        className="w-full text-sm bg-gradient-to-r from-[var(--color-accent)] to-[var(--color-accent-dark)] text-[var(--color-text-base)] font-bold py-2 rounded-lg disabled:opacity-50 transform active:scale-95 transition-all"
                    >
                        {result.isEditing ? 'Working...' : 'Apply Edit'}
                    </button>
                    <div className="flex gap-2">
                        <button 
                            onClick={() => handleDownload('2k')}
                            disabled={isDownloading || result.isEditing}
                            className="flex-1 text-xs inline-flex items-center justify-center bg-white/5 hover:bg-white/10 border border-white/10 text-[var(--color-text-base)] py-2 rounded-md transition-colors disabled:opacity-50"
                        > <DownloadIcon /> 2K </button>
                        <button 
                            onClick={() => handleDownload('4k')}
                            disabled={isDownloading || result.isEditing}
                            className="flex-1 text-xs inline-flex items-center justify-center bg-white/5 hover:bg-white/10 border border-white/10 text-[var(--color-text-base)] py-2 rounded-md transition-colors disabled:opacity-50"
                        > <DownloadIcon /> 4K </button>
                    </div>
                </div>
            )}

            {isModalOpen && result.image && createPortal(
                <div className="fixed inset-0 bg-black/95 backdrop-blur-xl flex items-center justify-center z-[9999] p-4" onClick={closeModal} >
                    <img
                        src={`data:${result.image.mimeType};base64,${result.image.base64}`}
                        alt={`Enlarged result`}
                        className="max-w-full max-h-full object-contain shadow-2xl rounded-lg"
                        onClick={(e) => e.stopPropagation()}
                    />
                    <button onClick={closeModal} className="absolute top-6 right-6 text-white bg-black/40 rounded-full p-2 hover:bg-black/60 transition-colors backdrop-blur-sm" >
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                        </svg>
                    </button>
                </div>,
                document.body
            )}
        </div>
    );
};

const BrandingResultsGrid: React.FC<{
  results: BrandingResult[];
  onImageEdit: (category: any) => void;
  onSetEditPrompt: (category: any, prompt: string) => void;
  gridClassName?: string;
}> = ({ results, onImageEdit, onSetEditPrompt, gridClassName }) => {
