import React, { useCallback } from 'react';
import { CampaignStudioProject, ImageFile, CampaignResult, CampaignScenario } from '../types';
import { resizeImage } from '../utils';
import { analyzeProductForCampaign, generateImage, editImage } from '../services/geminiService';
import ImageWorkspace from './ImageWorkspace';
import BrandingResultsGrid from './BrandingResultsGrid';

const CAMPAIGN_SCENARIOS: CampaignScenario[] = [
    'Creative Usage (Action)', 
    'Human Usage (Lifestyle)', 
    'Surreal Composition (Art)', 
    'Narrative Flat Lay (Story)', 
    'Cinematic Hero (Impact)', 
    'Textured Macro (Sensory)'
];

const CAMPAIGN_MOODS = [
    { label: 'Original', value: '' },
    { label: 'Minimalist White', value: 'Clean, high-key white minimalist aesthetic' },
    { label: 'Dark Luxury', value: 'Low-key, dramatic dark luxury aesthetic with gold accents' },
    { label: 'Pastel Pop', value: 'Soft, playful pastel colors and bright lighting' },
    { label: 'Nature Green', value: 'Organic, fresh aesthetic with green tones and natural elements' },
    { label: 'Ocean Blue', value: 'Cool, refreshing aesthetic with blue tones' },
    { label: 'Warm Gold', value: 'Warm, sunny, golden hour aesthetic' },
    { label: 'Cyberpunk Neon', value: 'Futuristic, high-contrast neon lighting' },
];

const getCampaignPrompt = (scenario: CampaignScenario, productContext: string, styleInstruction: string): string => {
    let baseRequirement = `Create a high-end Social Media campaign photo. Product: "${productContext || 'Product'}". No text/watermarks. `;
    if (styleInstruction) baseRequirement += `Style: ${styleInstruction}. `;
    const scenarioPrompts: Record<string, string> = {
        'Creative Usage (Action)': 'Action-oriented editorial shot.',
        'Human Usage (Lifestyle)': 'Natural lifestyle connection.',
        'Surreal Composition (Art)': 'Avant-garde art installation.',
        'Narrative Flat Lay (Story)': 'Storytelling flat lay.',
        'Cinematic Hero (Impact)': 'Dramatic hero shot.',
        'Textured Macro (Sensory)': 'Extreme macro detail.'
    };
    return baseRequirement + (scenarioPrompts[scenario] || 'Professional campaign shot.');
};

const CampaignStudio: React.FC<{
    project: CampaignStudioProject;
    setProject: React.Dispatch<React.SetStateAction<CampaignStudioProject>>;
}> = ({ project, setProject }) => {

    if (!project) return null;

    const productImages = Array.isArray(project.productImages) ? project.productImages : [];
    const results = Array.isArray(project.results) ? project.results : [];
    const currentIdeas = Array.isArray(project.customIdeas) ? project.customIdeas : ['', '', ''];
    const currentMode = project.mode || 'auto';
    const currentMood = project.selectedMood || 'Original';
    const currentCustomPrompt = project.customPrompt || '';

    const handleFileUpload = async (files: File[]) => {
        if (!files || files.length === 0) return;
        setProject(s => ({ ...s, isUploading: true, error: null }));
        try {
            const filePromises = files.map(file => {
                return new Promise<ImageFile | null>(async (resolve) => {
                    if (!file || !file.type.startsWith('image/')) { resolve(null); return; }
                    try {
                        const resizedFile = await resizeImage(file, 2048, 2048);
                        const reader = new FileReader();
                        reader.onloadend = () => {
                            resolve({ base64: (reader.result as string).split(',')[1], mimeType: resizedFile.type, name: resizedFile.name });
                        };
                        reader.readAsDataURL(resizedFile);
                    } catch (err) { resolve(null); }
                });
            });
            const uploaded = await Promise.all(filePromises);
            const validImages = uploaded.filter((img): img is ImageFile => img !== null);
            if (validImages.length > 0) {
                const combined = [...productImages, ...validImages];
                setProject(s => ({ ...s, productImages: combined, isUploading: false, isAnalyzing: true }));
                const analysis = await analyzeProductForCampaign(combined);
                setProject(s => ({ ...s, productAnalysis: analysis, isAnalyzing: false }));
            } else {
                setProject(s => ({ ...s, isUploading: false }));
            }
        } catch (err) {
            setProject(s => ({ ...s, isUploading: false, isAnalyzing: false, error: "Upload failed" }));
        }
    };

    const updateCustomIdea = (index: number, value: string) => {
        setProject(s => {
            const nextIdeas = [...(Array.isArray(s.customIdeas) ? s.customIdeas : ['', '', ''])];
            nextIdeas[index] = value || '';
            return { ...s, customIdeas: nextIdeas };
        });
    };

    const onGenerate = useCallback(async () => {
        if (productImages.length === 0) {
            setProject(s => ({ ...s, error: 'Please upload a product image first.' }));
            return;
        }
        setProject(s => ({ ...s, isGenerating: true, error: null, results: [] }));
        try {
            let analysis = project.productAnalysis || await analyzeProductForCampaign(productImages);
            let scenariosToRun = currentMode === 'auto' ? CAMPAIGN_SCENARIOS : currentIdeas.map((idea, i) => (idea || '').trim() ? `Custom Post ${i + 1}` : null).filter((id): id is string => id !== null);
            if (scenariosToRun.length === 0) throw new Error("Please enter at least one idea.");
            const initialResults = scenariosToRun.map(scenario => ({
                scenario, image: null, isLoading: true, error: null, editPrompt: '', isEditing: false
            }));
            setProject(s => ({ ...s, results: initialResults as any }));
            const promises = scenariosToRun.map((scenario) => {
                let prompt = '';
                if (currentMode === 'auto') {
                     const moodV = CAMPAIGN_MOODS.find(m => m.label === currentMood)?.value || '';
                     prompt = getCampaignPrompt(scenario, analysis, [moodV, currentCustomPrompt.trim()].filter(Boolean).join(' '));
                } else {
                    const idx = parseInt(scenario.replace('Custom Post ', '')) - 1;
                    prompt = `Professional Shot: ${analysis}. Idea: ${currentIdeas[idx] || 'Campaign'}. Style: ${currentCustomPrompt}.`;
                }
                return generateImage(productImages, prompt, null).then(image => ({ scenario, image })).catch(error => ({ scenario, error: error.message }));
            });
            const completed = await Promise.all(promises);
            setProject(s => {
                const nextResults = Array.isArray(s.results) ? [...s.results] : [];
                completed.forEach(res => {
                    const idx = nextResults.findIndex(r => r && r.scenario === res.scenario);
                    if (idx !== -1) {
                        if ('image' in res) nextResults[idx] = { ...nextResults[idx], image: res.image, isLoading: false };
                        else nextResults[idx] = { ...nextResults[idx], error: res.error, isLoading: false };
                    }
                });
                return { ...s, results: nextResults };
            });
        } catch (err) {
            setProject(s => ({ ...s, error: err instanceof Error ? err.message : 'Error', isGenerating: false }));
        } finally {
            setProject(s => ({ ...s, isGenerating: false }));
        }
    }, [productImages, project.productAnalysis, currentMood, currentCustomPrompt, currentMode, currentIdeas, setProject]);

    const handleSetEditPrompt = (scenarioId: string, text: string) => {
        setProject(s => {
            if (!s.results) return s;
            return {
                ...s,
                results: s.results.map(r => r && r.scenario === scenarioId ? { ...r, editPrompt: text } : r)
            };
        });
    };

    const handleImageEdit = async (scenarioId: string) => {
        const result = results.find(r => r && r.scenario === scenarioId);
        if (!result || !result.image || !result.editPrompt.trim()) return;
        setProject(s => ({ ...s, results: (s.results || []).map(r => r.scenario === scenarioId ? { ...r, isEditing: true, error: null } : r) }));
        try {
            const edited = await editImage(result.image, result.editPrompt);
            setProject(s => ({ ...s, results: (s.results || []).map(r => r.scenario === scenarioId ? { ...r, image: edited, isEditing: false, editPrompt: '' } : r) }));
        } catch (err) {
            setProject(s => ({ ...s, results: (s.results || []).map(r => r.scenario === scenarioId ? { ...r, error: 'Edit failed', isEditing: false } : r) }));
        }
    };

    return (
        <main className="w-full max-w-7xl flex flex-col gap-4 pt-4 pb-8 flex-grow">
            <div className="glass-card rounded-2xl p-4 flex flex-col md:flex-row items-start gap-6">
                <div className="w-full md:w-64 flex-shrink-0">
                    <h3 className="text-sm font-bold text-[var(--color-text-medium)] text-center mb-2 uppercase">Product Source</h3>
                    <ImageWorkspace
                        productImages={productImages}
                        onProductImagesUpload={handleFileUpload}
                        onProductImageRemove={(idx) => setProject(s => ({ ...s, productImages: productImages.filter((_, i) => i !== idx) }))}
                        isUploading={project.isUploading}
                    />
                </div>
                <div className="flex-grow w-full flex flex-col gap-4">
                    <h2 className="text-xl font-bold text-[var(--color-text-base)]">Creative Campaign Studio</h2>
                    <div className="flex bg-black/20 rounded-lg p-1 w-full sm:w-fit">
                        <button onClick={() => setProject(s => ({ ...s, mode: 'auto' }))} className={`px-6 py-2 rounded-md text-xs font-bold uppercase transition-all ${currentMode === 'auto' ? 'bg-[var(--color-accent)] text-white' : 'text-[var(--color-text-secondary)]'}`}>Auto Mode</button>
                        <button onClick={() => setProject(s => ({ ...s, mode: 'custom' }))} className={`px-6 py-2 rounded-md text-xs font-bold uppercase transition-all ${currentMode === 'custom' ? 'bg-[var(--color-accent)] text-white' : 'text-[var(--color-text-secondary)]'}`}>Custom Mode</button>
                    </div>
                    {currentMode === 'auto' ? (
                        <div className="flex flex-col gap-3">
                             <div className="flex flex-wrap gap-2">
                                {CAMPAIGN_MOODS.map(mood => (
                                    <button key={mood.label} onClick={() => setProject(s => ({ ...s, selectedMood: mood.label }))} className={`px-3 py-1.5 text-[10px] font-bold uppercase rounded-full border ${currentMood === mood.label ? 'bg-[var(--color-accent)] text-white border-[var(--color-accent)]' : 'bg-black/20 text-[var(--color-text-secondary)] border-white/5'}`}>{mood.label}</button>
                                ))}
                             </div>
                             <input type="text" value={currentCustomPrompt} onChange={(e) => setProject(s => ({ ...s, customPrompt: e.target.value }))} placeholder="Global style or color theme..." className="w-full glass-input rounded-xl px-4 py-2.5 text-sm"/>
                        </div>
                    ) : (
                        <div className="flex flex-col gap-4">
                             <input type="text" value={currentCustomPrompt} onChange={(e) => setProject(s => ({ ...s, customPrompt: e.target.value }))} placeholder="Global style or color theme..." className="w-full glass-input rounded-xl px-4 py-2.5 text-sm"/>
                             <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                                {[0, 1, 2].map((i) => (
                                    <textarea key={i} value={currentIdeas[i] || ''} onChange={(e) => updateCustomIdea(i, e.target.value)} rows={3} className="w-full glass-input rounded-xl p-3 text-xs resize-none" placeholder={`Describe Post Idea ${i + 1}...`}/>
                                ))}
                             </div>
                        </div>
                    )}
                    <button onClick={onGenerate} disabled={productImages.length === 0 || project.isGenerating} className="w-full bg-[var(--color-accent)] text-white font-bold py-3.5 rounded-xl disabled:opacity-50 transition-all">
                        {project.isGenerating ? 'Generating Assets...' : 'Generate Campaign Assets'}
                    </button>
                </div>
            </div>
            {results.length > 0 && (
                <div className="glass-card rounded-2xl p-4">
                     <h3 className="text-lg font-bold mb-4 uppercase">Campaign Results</h3>
                     <BrandingResultsGrid 
                        results={results.map(r => ({ ...r, category: r.scenario as any }))}
                        onImageEdit={handleImageEdit}
                        onSetEditPrompt={handleSetEditPrompt}
                        gridClassName="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6"
                     />
                </div>
            )}
        </main>
    );
};

