import React, { useState } from 'react';
import { createPortal } from 'react-dom';
import { BrandingResult } from '../types';

const LoadingSpinner = () => (
    <div className="flex justify-center items-center h-full">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-[var(--color-accent)]"></div>
    </div>
);

const ImageResultCard: React.FC<{ 
    result: BrandingResult;
    onImageEdit: (id: string) => void;
    onSetEditPrompt: (id: string, prompt: string) => void;
}> = ({ result, onImageEdit, onSetEditPrompt }) => {
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [isDownloading, setIsDownloading] = useState(false);

    if (!result) return null;

    const id = String(result.category || 'Asset');

    const handleDownload = (resolution: '2k' | '4k') => {
        if (!result.image) return;
        setIsDownloading(true);
        const img = new Image();
        img.src = `data:${result.image.mimeType};base64,${result.image.base64}`;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const ctx = canvas.getContext('2d');
            if (!ctx) { setIsDownloading(false); return; }
            const targetWidth = resolution === '4k' ? 4096 : 2048;
            canvas.width = targetWidth;
            canvas.height = targetWidth / (img.width / img.height);
            ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
            const link = document.createElement('a');
            link.download = `Jenta-${id}-${resolution}.png`;
            link.href = canvas.toDataURL('image/png');
            link.click();
            setIsDownloading(false);
        };
        img.onerror = () => setIsDownloading(false);
    };

    return (
        <div className="flex flex-col gap-2">
            <h4 className="text-sm font-semibold text-center text-[var(--color-text-medium)] truncate">{id}</h4>
            <div 
                onClick={() => result.image && !result.isLoading && setIsModalOpen(true)}
                className={`w-full aspect-square bg-black/20 backdrop-blur-sm rounded-xl flex items-center justify-center overflow-hidden relative group transition-all ${result.image ? 'cursor-pointer border border-transparent hover:border-[var(--color-accent)]' : ''}`}
            >
                {(result.isLoading || result.isEditing) && <LoadingSpinner />}
                {!result.isLoading && !result.isEditing && result.image && (
                    <img src={`data:${result.image.mimeType};base64,${result.image.base64}`} alt={id} className="object-contain w-full h-full" />
                )}
                {!result.isLoading && !result.isEditing && result.error && (
                    <div className="text-center p-2">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-red-400 mx-auto mb-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                        <p className="text-[10px] text-red-300">{result.error}</p>
                    </div>
                )}
            </div>

            {result.image && !result.isLoading && (
                <div className="flex flex-col gap-2">
                    <textarea
                        value={result.editPrompt || ''}
                        onChange={(e) => onSetEditPrompt(id, e.target.value)}
                        rows={2}
                        className="w-full glass-input rounded-md p-2 text-xs focus:ring-1 focus:ring-[var(--color-accent)]"
                        placeholder="Refine this image..."
                        disabled={result.isEditing}
                    />
                    <button
                        onClick={() => onImageEdit(id)}
                        disabled={result.isEditing || !(result.editPrompt || '').trim()}
                        className="w-full text-sm bg-gradient-to-r from-[var(--color-accent)] to-[var(--color-accent-dark)] text-white font-bold py-2 rounded-lg disabled:opacity-50 active:scale-95 transition-all"
                    >
                        {result.isEditing ? 'Working...' : 'Apply Edit'}
                    </button>
                    <div className="flex gap-2">
                        <button onClick={() => handleDownload('2k')} disabled={isDownloading} className="flex-1 text-[10px] bg-white/5 hover:bg-white/10 py-2 rounded-md transition-colors">Download 2K</button>
                        <button onClick={() => handleDownload('4k')} disabled={isDownloading} className="flex-1 text-[10px] bg-white/5 hover:bg-white/10 py-2 rounded-md transition-colors">Download 4K</button>
                    </div>
                </div>
            )}

            {isModalOpen && result.image && createPortal(
                <div className="fixed inset-0 bg-black/95 flex items-center justify-center z-[9999] p-4 animate-in fade-in" onClick={() => setIsModalOpen(false)} >
                    <img src={`data:${result.image.mimeType};base64,${result.image.base64}`} className="max-w-full max-h-full object-contain shadow-2xl" onClick={(e) => e.stopPropagation()} />
                    <button className="absolute top-4 right-4 text-white/50 hover:text-white"><svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg></button>
                </div>,
                document.body
            )}
        </div>
    );
};

const BrandingResultsGrid: React.FC<{
  results: BrandingResult[];
  onImageEdit: (id: string) => void;
  onSetEditPrompt: (id: string, prompt: string) => void;
  gridClassName?: string;
}> = ({ results, onImageEdit, onSetEditPrompt, gridClassName }) => {
  const safeResults = Array.isArray(results) ? results : [];

  if (safeResults.length === 0) return null;

  return (
    <div className={gridClassName || "grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4"}>
