                            className="object-contain w-full h-full cursor-pointer"
                            onClick={() => setIsFullViewOpen(true)}
                        />
                        <div className="absolute bottom-3 right-3 flex gap-2">
                             <button 
                                onClick={() => setIsEditModalOpen(true)}
                                className="p-2.5 rounded-xl bg-[var(--color-accent)] text-white shadow-lg transform hover:scale-110 active:scale-95 transition-all"
                                title="Refine Image"
                             >
                                <MagicWandIcon />
                             </button>
                        </div>
                    </>
                ) : result.error ? (
                    <div className="p-4 text-center">
                        <p className="text-[10px] text-red-300">{result.error}</p>
                    </div>
                ) : null}
            </div>

            {result.image && !result.isLoading && !result.isEditing && (
                <div className="flex gap-1.5 px-1">
                    <button onClick={() => handleDownload('2k')} disabled={isDownloading} className="flex-1 text-[9px] font-bold bg-white/5 hover:bg-white/10 py-1.5 rounded-lg border border-white/5 transition-colors uppercase">2K</button>
