const ResultDisplay: React.FC<ResultDisplayProps> = ({ 
    imageFile, 
    isLoading,
    isEditing,
    editPrompt,
    setEditPrompt,
    onImageEdit,
}) => {
    const [isDownloading, setIsDownloading] = useState(false);
    const [isFullViewOpen, setIsFullViewOpen] = useState(false);
    const [isEditModalOpen, setIsEditModalOpen] = useState(false);

    useEffect(() => {
        const handleKeyDown = (event: KeyboardEvent) => {
            if (event.key === 'Escape') {
                setIsFullViewOpen(false);
                setIsEditModalOpen(false);
            }
        };

        if (isFullViewOpen || isEditModalOpen) {
            window.addEventListener('keydown', handleKeyDown);
            document.body.style.overflow = 'hidden';
        } else {
            document.body.style.overflow = 'auto';
        }

        return () => {
            window.removeEventListener('keydown', handleKeyDown);
            document.body.style.overflow = 'auto';
        };
    }, [isFullViewOpen, isEditModalOpen]);


    const handleDownload = (resolution: '2k' | '4k') => {
        if (!imageFile) return;

        setIsDownloading(true);
        const img = new Image();
        img.src = `data:${imageFile.mimeType};base64,${imageFile.base64}`;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const ctx = canvas.getContext('2d');
            if (!ctx) {
                setIsDownloading(false);
                return;
            };

            const targetWidth = resolution === '4k' ? 4096 : 2048;
            const aspectRatio = img.width / img.height;

            canvas.width = targetWidth;
            canvas.height = targetWidth / aspectRatio;

            ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

            const link = document.createElement('a');
            link.download = `Jenta-byMahmoudReda-generated-${resolution}-${Date.now()}.png`;
            link.href = canvas.toDataURL('image/png');
            link.click();
            setIsDownloading(false);
        }
        img.onerror = () => {
             setIsDownloading(false);
        }
    };

    return (
        <div className="w-full flex flex-col gap-4">
            <div className="w-full aspect-square bg-black/10 backdrop-blur-sm rounded-xl flex items-center justify-center overflow-hidden relative border border-white/5">
                {(isLoading || isEditing) && <LoadingSpinner />}
                {!(isLoading || isEditing) && !imageFile && <span className="text-[var(--color-text-muted)] font-tajawal">سيظهر التصميم هنا</span>}
                {!(isLoading || isEditing) && imageFile && (
                     <button onClick={() => setIsFullViewOpen(true)} className="w-full h-full focus:outline-none transition-transform hover:scale-[1.01]" aria-label="Enlarge generated image">
                        <img 
                            src={`data:${imageFile.mimeType};base64,${imageFile.base64}`} 
                            alt="Generated Result" 
                            className="object-contain w-full h-full cursor-pointer"
                        />
                    </button>
                )}
            </div>
            {imageFile && !isLoading && (
                <>
                <div className="flex flex-col gap-3">
                    <button
                        onClick={() => setIsEditModalOpen(true)}
                        disabled={isEditing}
                        className="w-full bg-[var(--color-accent)] hover:bg-[var(--color-accent-dark)] text-white font-bold py-3 px-4 rounded-xl text-md transition-all flex items-center justify-center gap-2 shadow-lg active:scale-95 disabled:opacity-50"
                    >
                        <MagicWandIcon />
                        {isEditing ? 'Generating...' : 'Refine with AI / تعديل التصميم'}
                    </button>
                </div>

                <div className="w-full border-t border-[rgba(var(--color-text-base-rgb,229,231,206),0.1)] my-1"></div>

                <div className="flex gap-4">
                    <button 
                        onClick={() => handleDownload('2k')}
                        disabled={isDownloading || isEditing}
                        className="flex-1 inline-flex items-center justify-center bg-white/5 hover:bg-white/10 border border-white/10 text-[var(--color-text-base)] font-bold py-3 px-4 rounded-xl transition-all disabled:opacity-50 text-sm"
                    >
                        <DownloadIcon />
                        2K
                    </button>
                    <button 
                        onClick={() => handleDownload('4k')}
                        disabled={isDownloading || isEditing}
                        className="flex-1 inline-flex items-center justify-center bg-white/5 hover:bg-white/10 border border-white/10 text-[var(--color-text-base)] font-bold py-3 px-4 rounded-xl transition-all disabled:opacity-50 text-sm"
                    >
                        <DownloadIcon />
                        4K
                    </button>
                </div>
                </>
            )}

            {/* Edit Modal */}
            <EditModal 
                isOpen={isEditModalOpen}
                onClose={() => setIsEditModalOpen(false)}
                initialPrompt={editPrompt}
                isEditing={isEditing}
                onApply={(p) => {
                    setEditPrompt(p);
                    // Minimal delay to ensure state propagates
                    setTimeout(() => onImageEdit(), 50);
                }}
            />

            {/* Full Image View */}
            {isFullViewOpen && imageFile && createPortal(
                <div 
                    className="fixed inset-0 bg-black/95 backdrop-blur-lg flex items-center justify-center z-[9999] p-4 animate-in fade-in duration-300"
                    onClick={() => setIsFullViewOpen(false)}
                    role="dialog"
