const ResultDisplay: React.FC<ResultDisplayProps> = ({ 
    imageFile, 
    isLoading,
    isEditing,
    editPrompt,
    setEditPrompt,
    onImageEdit,
}) => {
    const [isDownloading, setIsDownloading] = useState(false);
    const [isFullViewOpen, setIsFullViewOpen] = useState(false);
    const [isEditModalOpen, setIsEditModalOpen] = useState(false);

    useEffect(() => {
        const handleKeyDown = (event: KeyboardEvent) => {
            if (event.key === 'Escape') {
                setIsFullViewOpen(false);
                setIsEditModalOpen(false);
            }
        };

        if (isFullViewOpen || isEditModalOpen) {
            window.addEventListener('keydown', handleKeyDown);
            document.body.style.overflow = 'hidden';
        }

        return () => {
            window.removeEventListener('keydown', handleKeyDown);
            document.body.style.overflow = 'auto';
        };
    }, [isFullViewOpen, isEditModalOpen]);


    const handleDownload = (resolution: '2k' | '4k') => {
        if (!imageFile) return;

        setIsDownloading(true);
        const img = new Image();
        img.src = `data:${imageFile.mimeType};base64,${imageFile.base64}`;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const ctx = canvas.getContext('2d');
            if (!ctx) {
                setIsDownloading(false);
                return;
            };

            const targetWidth = resolution === '4k' ? 4096 : 2048;
            const aspectRatio = img.width / img.height;

            canvas.width = targetWidth;
            canvas.height = targetWidth / aspectRatio;

            ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

            const link = document.createElement('a');
            link.download = `Jenta-Result-${resolution}-${Date.now()}.png`;
            link.href = canvas.toDataURL('image/png');
            link.click();
            setIsDownloading(false);
        }
        img.onerror = () => {
             setIsDownloading(false);
        }
    };

    return (
        <div className="w-full flex flex-col gap-4">
            <div className="w-full aspect-square bg-black/10 backdrop-blur-sm rounded-2xl flex items-center justify-center overflow-hidden relative border border-white/5 shadow-inner">
                {(isLoading || isEditing) && <LoadingSpinner />}
                {!(isLoading || isEditing) && !imageFile && (
                    <div className="flex flex-col items-center gap-3 opacity-40">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1}><path strokeLinecap="round" strokeLinejoin="round" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                        <span className="text-sm font-medium">Result will appear here</span>
                    </div>
                )}
                {!(isLoading || isEditing) && imageFile && (
                     <button onClick={() => setIsFullViewOpen(true)} className="w-full h-full focus:outline-none group" aria-label="Enlarge generated image">
                        <img 
                            src={`data:${imageFile.mimeType};base64,${imageFile.base64}`} 
                            alt="Generated Result" 
                            className="object-contain w-full h-full cursor-pointer transition-transform duration-500 group-hover:scale-105"
                        />
                    </button>
                )}
            </div>

            {imageFile && !isLoading && (
                <>
                <div className="flex flex-col gap-3">
                    <button
                        onClick={() => setIsEditModalOpen(true)}
                        disabled={isEditing}
                        className="w-full bg-[var(--color-accent)] hover:bg-[var(--color-accent-dark)] text-white font-bold py-4 px-6 rounded-2xl text-lg transition-all flex items-center justify-center gap-3 shadow-xl active:scale-95 disabled:opacity-50 group"
                    >
                        <div className="group-hover:rotate-12 transition-transform">
                            <MagicWandIcon />
                        </div>
                        {isEditing ? 'Generating Edits...' : 'Refine with AI'}
                    </button>
                </div>

                <div className="w-full border-t border-white/5 my-1"></div>

                <div className="flex gap-4">
                    <button 
                        onClick={() => handleDownload('2k')}
                        disabled={isDownloading || isEditing}
                        className="flex-1 inline-flex items-center justify-center bg-white/5 hover:bg-white/10 border border-white/5 text-white font-bold py-3 px-4 rounded-xl transition-all disabled:opacity-50 text-sm"
                    >
                        <DownloadIcon />
                        Download 2K
                    </button>
                    <button 
                        onClick={() => handleDownload('4k')}
                        disabled={isDownloading || isEditing}
                        className="flex-1 inline-flex items-center justify-center bg-white/5 hover:bg-white/10 border border-white/5 text-white font-bold py-3 px-4 rounded-xl transition-all disabled:opacity-50 text-sm"
                    >
                        <DownloadIcon />
                        Download 4K
                    </button>
                </div>
                </>
            )}

            <EditModal 
                isOpen={isEditModalOpen}
                onClose={() => setIsEditModalOpen(false)}
                initialPrompt={editPrompt}
                isEditing={isEditing}
                onApply={(p) => {
                    setEditPrompt(p);
                    setTimeout(() => onImageEdit(), 50);
                }}
            />

            {isFullViewOpen && imageFile && createPortal(
                <div 
                    className="fixed inset-0 bg-black/95 backdrop-blur-md flex items-center justify-center z-[9999] p-4 animate-in fade-in duration-300"
                    onClick={() => setIsFullViewOpen(false)}
                    role="dialog"
                    aria-modal="true"
                >
                    <img
                        src={`data:${imageFile.mimeType};base64,${imageFile.base64}`}
                        alt="Full view result"
                        className="max-w-full max-h-full object-contain shadow-2xl rounded-lg"
                        onClick={(e) => e.stopPropagation()}
                    />
                    <button 
                        onClick={() => setIsFullViewOpen(false)} 
                        className="absolute top-6 right-6 text-white/50 hover:text-white transition-colors p-2"
                        aria-label="Close"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                        </svg>
                    </button>
                </div>,
                document.body
            )}
        </div>
    );
};

