            setIsDownloading(false);
        };
        img.onerror = () => setIsDownloading(false);
    };

    return (
        <div className="flex flex-col gap-2 group/card">
            <h4 className="text-[11px] font-bold text-center text-[var(--color-text-muted)] uppercase tracking-widest truncate">{id}</h4>

            <div className="relative w-full aspect-square bg-black/20 backdrop-blur-sm rounded-2xl overflow-hidden border border-white/5 group-hover/card:border-[var(--color-accent)]/30 transition-all">
                {(result.isLoading || result.isEditing) ? (
                    <LoadingSpinner />
                ) : result.image ? (
                    <>
                        <img 
                            src={`data:${result.image.mimeType};base64,${result.image.base64}`} 
                            alt={id} 
                            className="object-contain w-full h-full cursor-pointer"
                            onClick={() => setIsFullViewOpen(true)}
                        />
                        <div className="absolute bottom-3 right-3 flex gap-2">
                             <button 
                                onClick={() => setIsEditModalOpen(true)}
                                className="p-2.5 rounded-xl bg-[var(--color-accent)] text-white shadow-lg transform hover:scale-110 active:scale-95 transition-all"
                                title="Edit Asset"
                             >
                                <MagicWandIcon />
                             </button>
                        </div>
                    </>
                ) : result.error ? (
                    <div className="p-4 text-center">
                        <p className="text-[10px] text-red-300">{result.error}</p>
                    </div>
                ) : null}
            </div>

            {result.image && !result.isLoading && !result.isEditing && (
                <div className="flex gap-1.5 px-1 mt-1">
                    <button onClick={() => handleDownload('2k')} disabled={isDownloading} className="flex-1 text-[9px] font-bold bg-white/5 hover:bg-white/10 py-1.5 rounded-lg border border-white/5 transition-colors uppercase">2K</button>
                    <button onClick={() => handleDownload('4k')} disabled={isDownloading} className="flex-1 text-[9px] font-bold bg-white/5 hover:bg-white/10 py-1.5 rounded-lg border border-white/5 transition-colors uppercase">4K</button>
                </div>
            )}

            <EditModal 
                isOpen={isEditModalOpen}
                onClose={() => setIsEditModalOpen(false)}
                initialPrompt={result.editPrompt || ''}
                isEditing={!!result.isEditing}
                onApply={(p) => {
                    onSetEditPrompt(id, p);
                    setTimeout(() => onImageEdit(id), 50);
                }}
            />

            {isFullViewOpen && result.image && createPortal(
                <div className="fixed inset-0 bg-black/95 flex items-center justify-center z-[9999] p-4 animate-in fade-in" onClick={() => setIsFullViewOpen(false)}>
                    <img src={`data:${result.image.mimeType};base64,${result.image.base64}`} className="max-w-full max-h-full object-contain shadow-2xl" onClick={(e) => e.stopPropagation()} />
                </div>,
                document.body
            )}
        </div>
    );
};

