import React, { useCallback } from 'react';
import { ImageFile, ShotType, PhotoshootDirectorProject } from '../types';
import { resizeImage } from '../utils';
import { generateImage } from '../services/geminiService';
import ImageWorkspace from './ImageWorkspace';
import ShotTypeSelector from './ShotTypeSelector';
import ResultsGrid from './ResultsGrid';

interface PhotoshootDirectorProps {
  project: PhotoshootDirectorProject;
  setProject: React.Dispatch<React.SetStateAction<PhotoshootDirectorProject>>;
}

const PhotoshootDirector: React.FC<PhotoshootDirectorProps> = ({ project, setProject }) => {

    const onGenerate = useCallback(async () => {
    if (!project || project.productImages.length === 0 || project.selectedShotTypes.length === 0) {
      setProject(s => ({ ...s, error: 'Please upload a product image and select at least one shot type.' }));
      return;
    }

    setProject(s => ({
      ...s,
      isGenerating: true,
      error: null,
      results: s.selectedShotTypes.map(shotType => ({
        shotType,
        image: null,
        isLoading: true,
        error: null,
        editPrompt: '',
        isEditing: false,
      })),
    }));

    const generationPromises = project.selectedShotTypes.map(shotType => {
      let prompt = `A high-resolution, professional photograph of the subject from the provided image. The desired shot is: '${shotType}'. The background should be clean, non-distracting, and complementary to the subject.`;
      if (project.customStylePrompt) {
        prompt += ` Additional style requirements: ${project.customStylePrompt}`;
      }
      return generateImage(project.productImages, prompt, null)
        .then(image => ({ status: 'fulfilled' as const, value: { shotType, image } }))
        .catch(error => ({ status: 'rejected' as const, reason: { shotType, error } }));
    });

    const settledResults = await Promise.all(generationPromises);

    settledResults.forEach(result => {
      if (result.status === 'fulfilled') {
        const { shotType, image } = result.value;
        setProject(s => ({
          ...s,
          results: s.results.map(r => r.shotType === shotType ? { ...r, image, isLoading: false } : r),
        }));
      } else {
        const { shotType, error } = result.reason;
        console.error(`Failed to generate image for ${shotType}:`, error);
        setProject(s => ({
          ...s,
          results: s.results.map(r => r.shotType === shotType ? { ...r, error: error.message || 'Generation failed', isLoading: false } : r),
        }));
      }
    });

    setProject(s => ({ ...s, isGenerating: false }));
  }, [project, setProject]);


  const handleFileUpload = async (files: File[]) => {
    if (!files || files.length === 0) return;

    setProject(s => ({ ...s, isUploading: true, error: null }));
    let currentError: string | null = null;

    const filePromises = files.map(file => {
      return new Promise<ImageFile | null>(async (resolve) => {
        if (!file.type.startsWith('image/')) {
          if (!currentError) currentError = `File '${file.name}' is not a supported image type.`;
          resolve(null);
          return;
        }
        try {
          const resizedFile = await resizeImage(file, 2048, 2048);
          const reader = new FileReader();
          reader.onloadend = () => {
            const base64String = reader.result as string;
            resolve({
              base64: base64String.split(',')[1],
              mimeType: resizedFile.type,
              name: resizedFile.name
            });
          };
          reader.onerror = () => {
            if (!currentError) currentError = `Error reading file '${resizedFile.name}'.`;
            resolve(null);
          };
          reader.readAsDataURL(resizedFile);
        } catch (err) {
          console.error(`Error processing ${file.name}:`, err);
          if (!currentError) currentError = `Could not process file '${file.name}'.`;
          resolve(null);
        }
      });
    });

    const results = await Promise.all(filePromises);
    const validImages = results.filter((img): img is ImageFile => img !== null);

    setProject(s => ({
      ...s,
      productImages: [...s.productImages, ...validImages],
      error: currentError,
      isUploading: false,
    }));
  };

  const handleRemoveImage = (indexToRemove: number) => {
    setProject(s => ({
      ...s,
      productImages: s.productImages.filter((_, index) => index !== indexToRemove),
    }));
  };

  const handleImageUpdate = (index: number, newImage: ImageFile) => {
      setProject(s => {
          const newImages = [...s.productImages];
          if (index >= 0 && index < newImages.length) {
              newImages[index] = newImage;
          }
          return { ...s, productImages: newImages };
      });
  };

  if (!project) {
    return (
        <main className="w-full max-w-7xl flex items-center justify-center gap-8 pt-8 pb-12 flex-grow">
            <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-[var(--color-accent)]"></div>
            <p className="text-[var(--color-text-secondary)]">Loading Photoshoot Director...</p>
        </main>
    );
  }

  return (
    <main className="w-full flex flex-col gap-4 pt-4 pb-8">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4 flex-grow">
        {/* Left Column: Controls */}
        <div className="lg:col-span-1 flex flex-col gap-4">
          <div className="glass-card rounded-2xl p-4">
            <h3 className="text-lg font-bold text-[var(--color-text-base)] mb-4">1. Upload Image(s)</h3>
            <ImageWorkspace
              productImages={project.productImages}
              onProductImagesUpload={handleFileUpload}
              onProductImageRemove={handleRemoveImage}
              isUploading={project.isUploading}
              onProductImageUpdate={handleImageUpdate}
            />
          </div>
          <ShotTypeSelector
            selected={project.selectedShotTypes}
            onChange={(selected) => setProject(s => ({ ...s, selectedShotTypes: selected }))}
            customStylePrompt={project.customStylePrompt}
            onCustomStylePromptChange={(prompt) => setProject(s => ({...s, customStylePrompt: prompt }))}
          />
          <div className="w-full px-4 py-2">
            <button
                onClick={onGenerate}
                disabled={project.isGenerating || project.isUploading || project.productImages.length === 0 || project.selectedShotTypes.length === 0}
                className="w-full bg-gradient-to-r from-[var(--color-accent)] to-[var(--color-accent-dark)] hover:from-[var(--color-accent-dark)] hover:to-[var(--color-accent-darker)] text-[var(--color-text-base)] font-bold py-3 px-8 rounded-lg text-lg transition-all duration-300 ease-in-out disabled:opacity-50 disabled:cursor-not-allowed shadow-lg hover:shadow-2xl hover:shadow-[var(--color-accent)]/20 disabled:shadow-none transform hover:-translate-y-1 disabled:transform-none"
            >
                {project.isGenerating ? 'Generating...' : `Generate ${project.selectedShotTypes.length} Shot${project.selectedShotTypes.length === 1 ? '' : 's'}`}
            </button>
          </div>
        </div>

        {/* Right Column: Results */}
        <div className="lg:col-span-2 flex flex-col gap-6">
          <div className="flex flex-col flex-grow glass-card rounded-2xl p-4">
              <div className="flex justify-between items-center mb-4">
                  <h3 className="text-lg font-bold text-[var(--color-text-base)]">3. Generated Results</h3>
              </div>
               {project.error && <div className="mb-4 bg-[rgba(var(--color-accent-rgb),0.2)] border border-[rgba(var(--color-accent-rgb),0.5)] text-[var(--color-accent-light)] px-4 py-3 rounded-lg" role="alert">{project.error}</div>}
              <ResultsGrid 
                results={project.results} 
              />
          </div>
        </div>
      </div>
    </main>
  );
};

export default PhotoshootDirector;

import React, { useCallback } from 'react';
import { ImageFile, BrandingStudioProject, BrandingResultCategory, AspectRatio } from '../types';
import { resizeImage } from '../utils';
import { analyzeLogoForBranding, generateImage } from '../services/geminiService';
import ImageUploader from './ImageUploader';
import BrandingResultsGrid from './BrandingResultsGrid';
import { ASPECT_RATIOS } from '../constants';

const MOCKUP_CATEGORIES: BrandingResultCategory[] = [
    'Logo Construction Grid', 'Typography Showcase', 'Logo Color Variations', 'Monochrome Version',
    '3D Glass Logo', 'Business Card Mockup', '3D Glass App Icon', 'Creative Pen Mockup',
    'Merchandise (Tote Bag)', 'Pencil Sketch Logo', 'Notebook Mockup', 'Waving Flag Mockup'
];

const getPromptForCategory = (category: BrandingResultCategory, aspectRatio: AspectRatio): string => {
    const aspectRatioRequirement = ` The final image must have a ${aspectRatio} aspect ratio.`;
    switch (category) {
        case 'Logo Construction Grid':
            return "Create a technical brand guideline image. Display the provided logo on a light grid, showing construction lines, proportions, and a clear space margin around it." + aspectRatioRequirement;
        case 'Typography Showcase':
            return "Create a brand typography specimen sheet. Analyze the font style used in the provided logo and display full English alphabet neatly on a minimalist background." + aspectRatioRequirement;
        case 'Logo Color Variations':
            return "Create a brand guideline image showing logo color variations. Display four versions of the provided logo on different solid-colored backgrounds." + aspectRatioRequirement;
        case 'Monochrome Version':
            return 'A high-contrast, single-color (white) version of the provided logo, presented on a black background.' + aspectRatioRequirement;
        case '3D Glass Logo':
            return "Create a photorealistic 3D mockup of the provided logo rendered in glossy, translucent glass." + aspectRatioRequirement;
        case 'Business Card Mockup':
            return "A photorealistic mockup of a premium business card featuring the provided logo on marble background." + aspectRatioRequirement;
        case '3D Glass App Icon':
            return "Create a photorealistic 3D app icon from the provided logo in glossy translucent glass." + aspectRatioRequirement;
        case 'Creative Pen Mockup':
            return "A photorealistic mockup of a high-end elegant pen with the provided logo subtly engraved." + aspectRatioRequirement;
        case 'Merchandise (Tote Bag)':
            return "A photorealistic lifestyle mockup of the provided logo printed on a high-quality canvas tote bag." + aspectRatioRequirement;
        case 'Pencil Sketch Logo':
            return "Create a photorealistic artistic sketch of the provided logo as if hand-drawn with graphite pencil." + aspectRatioRequirement;
        case 'Notebook Mockup':
            return "A photorealistic mockup of a premium notebook with logo elegantly debossed on the cover." + aspectRatioRequirement;
        case 'Waving Flag Mockup':
            return "A photorealistic mockup of the provided logo on a large flag waving gently against a clear sky." + aspectRatioRequirement;
        default:
            return `A professional product shot of the provided logo.` + aspectRatioRequirement;
    }
}

const BrandingStudio: React.FC<{
  project: BrandingStudioProject;
  setProject: React.Dispatch<React.SetStateAction<BrandingStudioProject>>;
}> = ({ project, setProject }) => {

    const handleFileUpload = async (files: File[]) => {
        if (!files || files.length === 0) return;
        const file = files[0];
        setProject(s => ({ ...s, isUploading: true, error: null }));
        try {
            if (!file.type.startsWith('image/')) throw new Error(`Not an image type.`);
            const resizedFile = await resizeImage(file, 1024, 1024);
            const reader = new FileReader();
            reader.onloadend = () => {
                setProject(s => ({
                    ...s,
                    logo: { base64: (reader.result as string).split(',')[1], mimeType: resizedFile.type, name: resizedFile.name },
                    isUploading: false,
                    results: [],
                    colors: [],
                }));
            };
            reader.readAsDataURL(resizedFile);
        } catch (err) {
            setProject(s => ({ ...s, error: 'Upload failed', isUploading: false }));
        }
    };

    const handleRemoveLogo = () => setProject(s => ({ ...s, logo: null, results: [], colors: [], error: null }));
    const handleUpdateLogo = (index: number, newImage: ImageFile) => setProject(s => ({ ...s, logo: newImage, results: [], colors: [] }));

    const onGenerate = useCallback(async () => {
        if (!project.logo) return;
        setProject(s => ({...s, isAnalyzing: true, isGenerating: true, error: null, colors: [], results: []}));
        try {
            const analysis = await analyzeLogoForBranding(project.logo);
            setProject(s => ({...s, colors: analysis.colors, isAnalyzing: false}));
            const initialResults = MOCKUP_CATEGORIES.map(category => ({ category, image: null, isLoading: true, error: null, editPrompt: '', isEditing: false }));
            setProject(s => ({...s, results: initialResults}));
            const promises = MOCKUP_CATEGORIES.map(category => {
                const prompt = getPromptForCategory(category, project.aspectRatio);
                return generateImage([project.logo!], prompt, null)
                    .then(image => ({ status: 'fulfilled' as const, value: { category, image } }))
                    .catch(error => ({ status: 'rejected' as const, reason: { category, error } }));
            });
            const settledResults = await Promise.all(promises);
            settledResults.forEach(result => {
                if (result.status === 'fulfilled') {
                    const { category, image } = result.value;
                    setProject(s => ({...s, results: s.results.map(r => r.category === category ? { ...r, image, isLoading: false } : r)}));
                } else {
                    const { category, error } = result.reason;
                    setProject(s => ({ ...s, results: s.results.map(r => r.category === category ? { ...r, error: error.message || 'Generation failed', isLoading: false } : r)}));
                }
            });
        } catch(err) {
            setProject(s => ({...s, error: 'Analysis failed', isAnalyzing: false }));
        } finally {
            setProject(s => ({...s, isGenerating: false}));
        }
    }, [project.logo, project.aspectRatio, setProject]);

    if (!project) return null;

    return (
        <main className="w-full max-w-7xl flex flex-col gap-4 pt-4 pb-8 flex-grow">
            <div className="glass-card rounded-2xl p-4 flex flex-col md:flex-row items-center gap-4">
                <div className="w-full md:w-48 flex-shrink-0">
                    <ImageUploader
                        id="branding-logo-uploader"
                        title="Upload Logo"
                        images={project.logo ? [project.logo] : []}
                        onFileUpload={handleFileUpload}
                        onRemove={handleRemoveLogo}
                        isUploading={project.isUploading}
                        onImageUpdate={handleUpdateLogo}
                    />
                </div>
                <div className="flex-grow text-center md:text-left">
                    <h2 className="text-xl font-bold text-[var(--color-text-base)]">Branding Studio</h2>
                    <p className="text-sm text-[var(--color-text-secondary)] mt-1">Generate brand assets from your logo.</p>
                     <div className="mt-4 flex gap-2 flex-wrap">
                        {ASPECT_RATIOS.map(ratio => (
                            <button key={ratio.value} onClick={() => setProject(s => ({ ...s, aspectRatio: ratio.value as AspectRatio }))} className={`px-4 py-1.5 text-xs font-bold rounded-full transition-colors ${project.aspectRatio === ratio.value ? 'bg-[var(--color-accent)] text-white' : 'bg-black/20 text-[var(--color-text-secondary)] hover:text-white'}`}>{ratio.value}</button>
                        ))}
                    </div>
                </div>
                <button onClick={onGenerate} disabled={!project.logo || project.isGenerating} className="w-full md:w-auto bg-[var(--color-accent)] text-white font-bold py-3 px-8 rounded-xl shadow-lg transition-all disabled:opacity-50">
                    {project.isGenerating ? 'Generating...' : 'Generate Branding'}
                </button>
            </div>
            {project.colors.length > 0 && (
                <div className="glass-card rounded-2xl p-4">
                    <h3 className="text-lg font-bold mb-4">Color Palette</h3>
                    <div className="flex flex-wrap gap-4">
                        {project.colors.map((color, index) => (
                            <div key={index} className="text-center">
                                <div className="w-14 h-14 rounded-lg border border-white/10" style={{backgroundColor: color}}></div>
                                <p className="text-xs mt-1.5 font-mono opacity-60">{color}</p>
                            </div>
                        ))}
                    </div>
                </div>
            )}
            {project.results.length > 0 && (
                <div className="glass-card rounded-2xl p-4">
                    <h3 className="text-lg font-bold mb-4">Assets</h3>
                     <BrandingResultsGrid results={project.results} />
                </div>
            )}
        </main>
    );
};

export default BrandingStudio;

import React, { useCallback } from 'react';
import { CampaignStudioProject, ImageFile, BrandingResult } from '../types';
import { resizeImage } from '../utils';
import { analyzeProductForCampaign, generateImage } from '../services/geminiService';
import ImageWorkspace from './ImageWorkspace';
import BrandingResultsGrid from './BrandingResultsGrid';

const CAMPAIGN_SCENARIOS = ['Creative Usage', 'Lifestyle', 'Surreal Composition', 'Story Flat Lay', 'Cinematic Hero', 'Macro Sensory'];

const CAMPAIGN_MOODS = [
    { label: 'Original', value: '' },
    { label: 'Minimalist', value: 'Clean, minimalist aesthetic' },
    { label: 'Dark Luxury', value: 'Dramatic dark luxury with gold' },
    { label: 'Pastel Pop', value: 'Soft playful pastel colors' },
    { label: 'Nature', value: 'Organic fresh natural aesthetic' },
];

const CampaignStudio: React.FC<{
    project: CampaignStudioProject;
    setProject: React.Dispatch<React.SetStateAction<CampaignStudioProject>>;
}> = ({ project, setProject }) => {

    if (!project) return null;
    const productImages = project.productImages || [];
    const results = project.results || [];

    const handleFileUpload = async (files: File[]) => {
        if (!files || files.length === 0) return;
        setProject(s => ({ ...s, isUploading: true, error: null }));
        try {
            const uploaded = await Promise.all(files.map(async file => {
                const resized = await resizeImage(file, 2048, 2048);
                const reader = new FileReader();
                return new Promise<ImageFile>(res => {
                    reader.onloadend = () => res({ base64: (reader.result as string).split(',')[1], mimeType: resized.type, name: resized.name });
                    reader.readAsDataURL(resized);
                });
            }));
            const combined = [...productImages, ...uploaded];
            setProject(s => ({ ...s, productImages: combined, isUploading: false, isAnalyzing: true }));
            const analysis = await analyzeProductForCampaign(combined);
            setProject(s => ({ ...s, productAnalysis: analysis, isAnalyzing: false }));
        } catch (err) {
            setProject(s => ({ ...s, isUploading: false, isAnalyzing: false, error: "Upload failed" }));
        }
    };

    const onGenerate = useCallback(async () => {
        if (productImages.length === 0) return;
        setProject(s => ({ ...s, isGenerating: true, error: null, results: [] }));
        try {
            let analysis = project.productAnalysis || await analyzeProductForCampaign(productImages);
            let scenarios = CAMPAIGN_SCENARIOS;
            const initial = scenarios.map(scenario => ({ scenario, image: null, isLoading: true, error: null, editPrompt: '', isEditing: false }));
            setProject(s => ({ ...s, results: initial as any }));
            const promises = scenarios.map((scenario) => {
                const moodV = CAMPAIGN_MOODS.find(m => m.label === project.selectedMood)?.value || '';
                const prompt = `Professional Campaign: ${analysis}. Scenario: ${scenario}. Style: ${moodV} ${project.customPrompt}`;
                return generateImage(productImages, prompt, null).then(image => ({ scenario, image })).catch(error => ({ scenario, error: error.message }));
            });
            const completed = await Promise.all(promises);
            setProject(s => {
                const nextResults = [...s.results];
                completed.forEach(res => {
                    const idx = nextResults.findIndex(r => r && r.scenario === res.scenario);
                    if (idx !== -1) {
                        if ('image' in res) nextResults[idx] = { ...nextResults[idx], image: res.image, isLoading: false };
                        else nextResults[idx] = { ...nextResults[idx], error: res.error, isLoading: false };
                    }
                });
                return { ...s, results: nextResults };
            });
        } catch (err) {
            setProject(s => ({ ...s, error: 'Generation failed', isGenerating: false }));
        } finally {
            setProject(s => ({ ...s, isGenerating: false }));
        }
    }, [productImages, project.productAnalysis, project.selectedMood, project.customPrompt, setProject]);

    const safeGridResults: BrandingResult[] = results.map(r => ({
        category: r.scenario as any,
        image: r.image || null,
        isLoading: !!r.isLoading,
        isEditing: false,
        error: r.error || null,
        editPrompt: ''
    }));

    return (
        <main className="w-full max-w-7xl flex flex-col gap-4 pt-4 pb-8 flex-grow">
            <div className="glass-card rounded-2xl p-4 flex flex-col md:flex-row items-start gap-6">
                <div className="w-full md:w-64 flex-shrink-0">
                    <ImageWorkspace
                        productImages={productImages}
                        onProductImagesUpload={handleFileUpload}
                        onProductImageRemove={(idx) => setProject(s => ({ ...s, productImages: productImages.filter((_, i) => i !== idx) }))}
                        isUploading={project.isUploading}
                    />
                </div>
                <div className="flex-grow w-full flex flex-col gap-4">
                    <h2 className="text-xl font-bold">Campaign Studio</h2>
                    <div className="flex flex-wrap gap-2">
                        {CAMPAIGN_MOODS.map(mood => (
                            <button key={mood.label} onClick={() => setProject(s => ({ ...s, selectedMood: mood.label }))} className={`px-4 py-1.5 text-xs font-bold rounded-full transition-all border ${project.selectedMood === mood.label ? 'bg-[var(--color-accent)] text-white border-[var(--color-accent)]' : 'bg-black/20 text-white/60 border-white/5'}`}>{mood.label}</button>
                        ))}
                    </div>
                    <input type="text" value={project.customPrompt} onChange={(e) => setProject(s => ({ ...s, customPrompt: e.target.value }))} placeholder="Global style or color theme..." className="w-full glass-input rounded-xl px-4 py-2.5 text-sm"/>
                    <button onClick={onGenerate} disabled={productImages.length === 0 || project.isGenerating} className="w-full bg-[var(--color-accent)] text-white font-bold py-4 rounded-xl shadow-lg">
                        {project.isGenerating ? 'Generating Assets...' : 'Generate Campaign Assets'}
                    </button>
                </div>
            </div>
            {results.length > 0 && (
                <div className="glass-card rounded-2xl p-4">
                     <h3 className="text-lg font-bold mb-4">Results</h3>
                     <BrandingResultsGrid 
                        results={safeGridResults}
                        gridClassName="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6"
                     />
                </div>
            )}
        </main>
    );
};

export default CampaignStudio;

