  results: PhotoshootResult[];
  onEditResult?: (index: number, prompt: string) => void;
}> = ({ results, onEditResult }) => {
  const safeResults = Array.isArray(results) ? results.filter(r => !!r) : [];
  if (safeResults.length === 0) return null;

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
      {safeResults.map((result, idx) => (
        <ImageResult 
            key={`${result.shotType}-${idx}`} 
            result={result} 
            onEdit={(p) => onEditResult?.(idx, p)}
        />
      ))}
    </div>
  );
};

export default ResultsGrid;

import React, { useCallback } from 'react';
import { ImageFile, ShotType, PhotoshootDirectorProject } from '../types';
import { resizeImage } from '../utils';
import { generateImage, editImage } from '../services/geminiService';
import ImageWorkspace from './ImageWorkspace';
import ShotTypeSelector from './ShotTypeSelector';
import ResultsGrid from './ResultsGrid';

interface PhotoshootDirectorProps {
  project: PhotoshootDirectorProject;
  setProject: React.Dispatch<React.SetStateAction<PhotoshootDirectorProject>>;
}

const PhotoshootDirector: React.FC<PhotoshootDirectorProps> = ({ project, setProject }) => {

    const onGenerate = useCallback(async () => {
    if (!project || project.productImages.length === 0 || project.selectedShotTypes.length === 0) {
      setProject(s => ({ ...s, error: 'Please upload a product image and select at least one shot type.' }));
      return;
    }

    setProject(s => ({
      ...s,
      isGenerating: true,
      error: null,
      results: s.selectedShotTypes.map(shotType => ({
        shotType,
        image: null,
        isLoading: true,
        error: null,
        editPrompt: '',
        isEditing: false,
      })),
    }));

    const generationPromises = project.selectedShotTypes.map(shotType => {
      let prompt = `A high-resolution, professional photograph of the subject from the provided image. The desired shot is: '${shotType}'. The background should be clean, non-distracting, and complementary to the subject.`;
      if (project.customStylePrompt) {
        prompt += ` Additional style requirements: ${project.customStylePrompt}`;
      }
      return generateImage(project.productImages, prompt, null)
        .then(image => ({ status: 'fulfilled' as const, value: { shotType, image } }))
        .catch(error => ({ status: 'rejected' as const, reason: { shotType, error } }));
    });

    const settledResults = await Promise.all(generationPromises);

    settledResults.forEach(result => {
      if (result.status === 'fulfilled') {
        const { shotType, image } = result.value;
        setProject(s => ({
          ...s,
          results: s.results.map(r => r.shotType === shotType ? { ...r, image, isLoading: false } : r),
        }));
      } else {
        const { shotType, error } = result.reason;
        console.error(`Failed to generate image for ${shotType}:`, error);
        setProject(s => ({
          ...s,
          results: s.results.map(r => r.shotType === shotType ? { ...r, error: error.message || 'Generation failed', isLoading: false } : r),
        }));
      }
    });

    setProject(s => ({ ...s, isGenerating: false }));
  }, [project, setProject]);

  const handleEditResult = async (index: number, prompt: string) => {
      const result = project.results[index];
      if (!result || !result.image) return;

      setProject(s => {
          const newResults = [...s.results];
          newResults[index] = { ...newResults[index], isEditing: true, error: null };
          return { ...s, results: newResults };
      });

      try {
          const updated = await editImage(result.image, prompt);
          setProject(s => {
              const newResults = [...s.results];
              newResults[index] = { ...newResults[index], image: updated, isEditing: false };
              return { ...s, results: newResults };
          });
      } catch (err) {
          setProject(s => {
              const newResults = [...s.results];
              newResults[index] = { ...newResults[index], isEditing: false, error: err instanceof Error ? err.message : 'Edit failed' };
              return { ...s, results: newResults };
          });
      }
  };

  const handleFileUpload = async (files: File[]) => {
    if (!files || files.length === 0) return;

    setProject(s => ({ ...s, isUploading: true, error: null }));
    let currentError: string | null = null;

    const filePromises = files.map(file => {
      return new Promise<ImageFile | null>(async (resolve) => {
        if (!file.type.startsWith('image/')) {
          if (!currentError) currentError = `File '${file.name}' is not a supported image type.`;
          resolve(null);
          return;
        }
        try {
          const resizedFile = await resizeImage(file, 2048, 2048);
          const reader = new FileReader();
          reader.onloadend = () => {
            const base64String = reader.result as string;
            resolve({
              base64: base64String.split(',')[1],
              mimeType: resizedFile.type,
              name: resizedFile.name
            });
          };
          reader.onerror = () => {
            if (!currentError) currentError = `Error reading file '${resizedFile.name}'.`;
            resolve(null);
          };
          reader.readAsDataURL(resizedFile);
        } catch (err) {
          console.error(`Error processing ${file.name}:`, err);
          if (!currentError) currentError = `Could not process file '${file.name}'.`;
          resolve(null);
        }
      });
    });

    const results = await Promise.all(filePromises);
    const validImages = results.filter((img): img is ImageFile => img !== null);

    setProject(s => ({
      ...s,
      productImages: [...s.productImages, ...validImages],
      error: currentError,
      isUploading: false,
    }));
  };

  const handleRemoveImage = (indexToRemove: number) => {
    setProject(s => ({
      ...s,
      productImages: s.productImages.filter((_, index) => index !== indexToRemove),
    }));
  };

  const handleImageUpdate = (index: number, newImage: ImageFile) => {
      setProject(s => {
          const newImages = [...s.productImages];
          if (index >= 0 && index < newImages.length) {
              newImages[index] = newImage;
          }
          return { ...s, productImages: newImages };
      });
  };

  if (!project) {
    return (
        <main className="w-full max-w-7xl flex items-center justify-center gap-8 pt-8 pb-12 flex-grow">
            <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-[var(--color-accent)]"></div>
            <p className="text-[var(--color-text-secondary)]">Loading Photoshoot Director...</p>
        </main>
    );
  }

  return (
    <main className="w-full flex flex-col gap-4 pt-4 pb-8">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4 flex-grow">
        {/* Left Column: Controls */}
        <div className="lg:col-span-1 flex flex-col gap-4">
          <div className="glass-card rounded-2xl p-4">
            <h3 className="text-lg font-bold text-[var(--color-text-base)] mb-4">1. Upload Image(s)</h3>
            <ImageWorkspace
              productImages={project.productImages}
              onProductImagesUpload={handleFileUpload}
              onProductImageRemove={handleRemoveImage}
              isUploading={project.isUploading}
              onProductImageUpdate={handleImageUpdate}
            />
          </div>
          <ShotTypeSelector
            selected={project.selectedShotTypes}
            onChange={(selected) => setProject(s => ({ ...s, selectedShotTypes: selected }))}
            customStylePrompt={project.customStylePrompt}
            onCustomStylePromptChange={(prompt) => setProject(s => ({...s, customStylePrompt: prompt }))}
          />
          <div className="w-full px-4 py-2">
            <button
                onClick={onGenerate}
                disabled={project.isGenerating || project.isUploading || project.productImages.length === 0 || project.selectedShotTypes.length === 0}
                className="w-full bg-gradient-to-r from-[var(--color-accent)] to-[var(--color-accent-dark)] hover:from-[var(--color-accent-dark)] hover:to-[var(--color-accent-darker)] text-[var(--color-text-base)] font-bold py-3 px-8 rounded-lg text-lg transition-all duration-300 ease-in-out disabled:opacity-50 disabled:cursor-not-allowed shadow-lg hover:shadow-2xl hover:shadow-[var(--color-accent)]/20 disabled:shadow-none transform hover:-translate-y-1 disabled:transform-none"
            >
                {project.isGenerating ? 'Generating...' : `Generate ${project.selectedShotTypes.length} Shot${project.selectedShotTypes.length === 1 ? '' : 's'}`}
            </button>
          </div>
        </div>

        {/* Right Column: Results */}
        <div className="lg:col-span-2 flex flex-col gap-6">
          <div className="flex flex-col flex-grow glass-card rounded-2xl p-4">
              <div className="flex justify-between items-center mb-4">
                  <h3 className="text-lg font-bold text-[var(--color-text-base)]">3. Generated Results</h3>
              </div>
               {project.error && <div className="mb-4 bg-[rgba(var(--color-accent-rgb),0.2)] border border-[rgba(var(--color-accent-rgb),0.5)] text-[var(--color-accent-light)] px-4 py-3 rounded-lg" role="alert">{project.error}</div>}
              <ResultsGrid 
                results={project.results} 
                onEditResult={handleEditResult}
              />
          </div>
        </div>
      </div>
    </main>
  );
};

export default PhotoshootDirector;

import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { ImageFile } from '../types';

interface ResultDisplayProps {
  imageFile: ImageFile | null;
  isLoading: boolean;
  onEdit?: (prompt: string) => void;
  isEditing?: boolean;
}

const DownloadIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-2" viewBox="0 0 20 20" fill="currentColor">
        <path fillRule="evenodd" d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" />
    </svg>
);

const LoadingSpinner = ({ size = "h-16 w-16" }: { size?: string }) => (
    <div className="flex justify-center items-center h-full">
        <div className={`animate-spin rounded-full ${size} border-t-2 border-b-2 border-[var(--color-accent)]`}></div>
    </div>
);

const ResultDisplay: React.FC<ResultDisplayProps> = ({ 
    imageFile, 
    isLoading,
    onEdit,
    isEditing
}) => {
    const [isDownloading, setIsDownloading] = useState(false);
    const [isFullViewOpen, setIsFullViewOpen] = useState(false);
    const [localPrompt, setLocalPrompt] = useState('');

    useEffect(() => {
        const handleKeyDown = (event: KeyboardEvent) => {
            if (event.key === 'Escape') {
                setIsFullViewOpen(false);
            }
        };

        if (isFullViewOpen) {
            window.addEventListener('keydown', handleKeyDown);
            document.body.style.overflow = 'hidden';
        }

        return () => {
            window.removeEventListener('keydown', handleKeyDown);
            document.body.style.overflow = 'auto';
        };
    }, [isFullViewOpen]);


    const handleDownload = (resolution: '2k' | '4k') => {
        if (!imageFile) return;

        setIsDownloading(true);
        const img = new Image();
        img.src = `data:${imageFile.mimeType};base64,${imageFile.base64}`;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const ctx = canvas.getContext('2d');
            if (!ctx) {
                setIsDownloading(false);
                return;
            };

            const targetWidth = resolution === '4k' ? 4096 : 2048;
            const aspectRatio = img.width / img.height;

            canvas.width = targetWidth;
            canvas.height = targetWidth / aspectRatio;

            ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

            const link = document.createElement('a');
            link.download = `Jenta-Result-${resolution}-${Date.now()}.png`;
            link.href = canvas.toDataURL('image/png');
            link.click();
            setIsDownloading(false);
        }
        img.onerror = () => {
             setIsDownloading(false);
        }
    };

    const handleApplyEdit = () => {
        if (localPrompt.trim() && onEdit) {
            onEdit(localPrompt);
            setLocalPrompt('');
        }
    };

    return (
        <div className="w-full flex flex-col gap-4">
            {/* Main Result Area */}
            <div className="w-full aspect-square bg-black/10 backdrop-blur-sm rounded-3xl flex items-center justify-center overflow-hidden relative border border-white/5 shadow-inner group">
                {(isLoading || isEditing) && (
                    <div className="absolute inset-0 z-50 flex flex-col items-center justify-center bg-black/40 backdrop-blur-sm">
                        <LoadingSpinner />
                        <p className="mt-4 text-[10px] font-bold text-[var(--color-accent)] uppercase tracking-[0.2em] animate-pulse">
                            {isEditing ? 'Refining Design...' : 'Generating Design...'}
                        </p>
                    </div>
                )}

                {!isLoading && !isEditing && !imageFile && (
                    <div className="flex flex-col items-center gap-3 opacity-20">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1}><path strokeLinecap="round" strokeLinejoin="round" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                        <span className="text-xs font-bold uppercase tracking-widest">Result will appear here</span>
                    </div>
                )}

                {!isLoading && !isEditing && imageFile && (
                     <div className="w-full h-full relative">
                        <img 
                            src={`data:${imageFile.mimeType};base64,${imageFile.base64}`} 
                            alt="Generated Design" 
                            className="object-contain w-full h-full cursor-pointer transition-transform duration-700 group-hover:scale-[1.02]"
                            onClick={() => setIsFullViewOpen(true)}
                        />
                        {/* Overlay Hint */}
                        <div className="absolute inset-0 bg-black/20 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none flex items-center justify-center">
                            <span className="bg-black/60 backdrop-blur-md px-4 py-2 rounded-full border border-white/10 text-[10px] font-bold uppercase tracking-widest text-white">Click to Enlarge</span>
                        </div>
                    </div>
                )}
            </div>

            {imageFile && !isLoading && !isEditing && (
                <div className="animate-in slide-in-from-bottom-2 duration-500 space-y-3">
                    {/* Edit Section - NOW ABOVE BUTTONS */}
                    <div className="relative">
                        <input 
                            type="text"
                            value={localPrompt}
                            onChange={(e) => setLocalPrompt(e.target.value)}
                            placeholder="Describe changes to refine result..."
                            className="w-full bg-white/5 border border-white/10 rounded-2xl px-5 py-4 text-xs text-white focus:outline-none focus:border-[var(--color-accent)]/50 transition-all placeholder:text-white/20"
                            onKeyDown={(e) => e.key === 'Enter' && handleApplyEdit()}
                        />
                        <button 
                            onClick={handleApplyEdit}
                            disabled={!localPrompt.trim()}
                            className="absolute right-2 top-2 bottom-2 px-6 bg-[var(--color-accent)] hover:bg-[var(--color-accent-dark)] text-white text-[10px] font-black rounded-xl transition-all disabled:opacity-0 shadow-lg shadow-[var(--color-accent)]/20"
                        >
                            EDIT
                        </button>
                    </div>

                    <div className="flex gap-4">
                        <button 
                            onClick={() => handleDownload('2k')}
                            disabled={isDownloading}
                            className="flex-1 inline-flex items-center justify-center bg-white/5 hover:bg-white/10 border border-white/5 text-white font-bold py-4 px-4 rounded-2xl transition-all disabled:opacity-50 text-xs tracking-tighter"
                        >
                            <DownloadIcon />
                            DOWNLOAD 2K
                        </button>
                        <button 
                            onClick={() => handleDownload('4k')}
                            disabled={isDownloading}
                            className="flex-1 inline-flex items-center justify-center bg-[var(--color-accent)] hover:bg-[var(--color-accent-dark)] text-white font-bold py-4 px-4 rounded-2xl transition-all disabled:opacity-50 text-xs tracking-tighter shadow-lg shadow-[var(--color-accent)]/20"
                        >
                            <DownloadIcon />
                            DOWNLOAD 4K
                        </button>
                    </div>
                </div>
            )}

            {/* Fullscreen Preview */}
            {isFullViewOpen && imageFile && createPortal(
                <div 
                    className="fixed inset-0 bg-black/95 backdrop-blur-xl flex items-center justify-center z-[99999] p-4 animate-in fade-in duration-300"
                    onClick={() => setIsFullViewOpen(false)}
                >
                    <img
                        src={`data:${imageFile.mimeType};base64,${imageFile.base64}`}
                        alt="Full view result"
                        className="max-w-full max-h-full object-contain shadow-2xl rounded-2xl"
                        onClick={(e) => e.stopPropagation()}
                    />
                    <button 
                        onClick={() => setIsFullViewOpen(false)} 
                        className="absolute top-6 right-6 text-white/50 hover:text-white transition-all p-3 bg-white/5 rounded-full hover:bg-white/10 backdrop-blur-md"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                        </svg>
                    </button>
                </div>,
                document.body
            )}
        </div>
    );
};

