export async function analyzeLogoForBranding(logos: ImageFile[]): Promise<{ colors: string[] }> {
  const model = 'gemini-3-flash-preview';
  const parts: Part[] = [];

  logos.forEach(logo => {
      parts.push({
          inlineData: {
              data: logo.base64,
              mimeType: logo.mimeType,
          },
      });
  });

  parts.push({
    text: "Analyze the provided logo image(s) and identify their collective main color palette. Extract up to 5 primary and secondary colors. Return the response as a JSON object with a single key 'colors', which is an array of hex color code strings (e.g., {\"colors\": [\"#FFFFFF\", \"#000000\"]}).",
  });

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: model,
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            colors: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          }
        }
      },
      safetySettings: safetySettings,
    });

    if(!response.text) {
      const safetyText = response.candidates?.[0]?.finishReason;
      if (safetyText && safetyText !== 'STOP') {
          throw new Error(`Logo analysis failed due to safety settings: ${safetyText}`);
      }
      throw new Error('Model returned no data for logo analysis.');
    }

    const result = JSON.parse(response.text.trim());
    if (result && Array.isArray(result.colors)) {
        return result;
    } else {
        throw new Error("Invalid JSON format from logo analysis.");
    }

  } catch (error) {
    console.error('Error analyzing logos:', error);
    let errorMessage = 'An unknown error occurred while analyzing the logos.';
    if (error instanceof Error) {
        const msg = error.message.toLowerCase();
        if (msg.includes('api key not valid')) {
            errorMessage = 'Your API key is not valid. Please check your API key and try again.';
        } else if (msg.includes('quota')) {
            errorMessage = 'You have exceeded your API quota. Please check your billing account or try again later.';
        } else if (msg.includes('safety settings')) {
            errorMessage = `Logo analysis was blocked due to safety settings.`;
        } else if (msg.includes('json')) {
            errorMessage = `Failed to parse analysis response. The model may have returned invalid JSON.`;
        } else {
             errorMessage = `Failed to analyze logo. Details: ${error.message}`;
        }
    }
    throw new Error(errorMessage);
  }
}

export async function generateSpeech(text: string, styleInstructions: string, voiceName: string): Promise<AudioFile> {
  const model = 'gemini-2.5-flash-preview-tts';

  let instructions = "Read aloud in a warm and friendly tone";
  if (styleInstructions.trim()) {
      instructions += ` ${styleInstructions.trim()}`;
  }

  const promptText = `${instructions}: ${text}`;

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: [{ parts: [{ text: promptText }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: voiceName },
          },
        },
      },
      safetySettings: safetySettings,
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

    if (base64Audio) {
      return {
        base64: base64Audio,
        name: 'generated-audio.wav',
      };
    }

    const safetyText = response.candidates?.[0]?.finishReason;
    if (safetyText && safetyText !== 'STOP') {
      throw new Error(`Audio generation failed due to safety settings: ${safetyText}`);
    }

    throw new Error('No audio was generated by the model.');

  } catch (error) {
    console.error('Error calling Gemini API for speech generation:', error);
    let errorMessage = 'An unknown error occurred while generating the audio.';
    if (error instanceof Error) {
      const msg = error.message.toLowerCase();
      if (msg.includes('api key not valid')) {
        errorMessage = 'Your API key is not valid. Please check your API key and try again.';
      } else if (msg.includes('quota')) {
        errorMessage = 'You have exceeded your API quota. Please check your billing account or try again later.';
      } else if (msg.includes('safety settings')) {
        errorMessage = `Audio generation was blocked due to safety settings. Please adjust your text.`;
      } else {
        errorMessage = `Failed to generate audio. Details: ${error.message}`;
      }
    }
    throw new Error(errorMessage);
  }
}

export async function analyzeProductForCampaign(productImages: ImageFile[]): Promise<string> {
    const model = 'gemini-3-flash-preview';
    const parts: Part[] = [];
    productImages.forEach(img => {
      parts.push({
        inlineData: {
          data: img.base64,
          mimeType: img.mimeType,
        }
      });
    });

    const prompt = `Analyze these product image(s). Identify the product type, its likely target audience, and the best environment for it. 
    Return a concise 2-sentence description describing the product and a suitable lifestyle context. 
    Example: "This is a premium organic face serum in a dropper bottle. It fits perfectly in a minimalist, spa-like bathroom setting with soft lighting and natural elements."`;

    parts.push({ text: prompt });

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: model,
            contents: { parts: parts },
            safetySettings: safetySettings,
        });

        if (!response.text) {
             throw new Error('Model returned no analysis text.');
        }

        return response.text.trim();

    } catch (error) {
        console.error('Error analyzing product for campaign:', error);
        throw new Error('Failed to analyze product category.');
    }
}

import React, { useEffect, useRef, useCallback } from 'react';
import { CreatorStudioProject, ImageFile } from '../types';
import { analyzeStyleImage, translateText, generateImage, editImage } from '../services/geminiService';
import { resizeImage } from '../utils';
import CustomizationPanel from './CustomizationPanel';
import ImageWorkspace from './ImageWorkspace';
import PromptEditor, { PromptSuggestions } from './PromptEditor';
import HistoryPanel from './HistoryPanel';
import ResultDisplay from './ResultDisplay';

interface CreatorStudioProps {
  project: CreatorStudioProject;
  setProject: React.Dispatch<React.SetStateAction<CreatorStudioProject>>;
}

const CreatorStudio: React.FC<CreatorStudioProps> = ({
  project,
  setProject,
}) => {

  const translateTimeoutRef = useRef<number | null>(null);
  const translationRequestCounter = useRef(0);

  const updateActiveProjectState = useCallback((updater: (projectDraft: CreatorStudioProject) => void) => {
    setProject(currentProject => {
      const projectToUpdate = { ...currentProject };
      updater(projectToUpdate);
      return projectToUpdate;
    });
  }, [setProject]);

  // Analyze style image
  useEffect(() => {
    if (project?.styleImages?.length > 0 && !project.styleDescription && !project.isAnalyzingStyle && !project.error) {
      const getStyleDescription = async () => {
        updateActiveProjectState(p => { 
          p.isAnalyzingStyle = true;
          p.error = null;
        });
        try {
          const description = await analyzeStyleImage(project.styleImages);
          updateActiveProjectState(p => { p.styleDescription = description; });
        } catch (err) {
          console.error(err);
          updateActiveProjectState(p => {
            p.error = err instanceof Error ? err.message : "Could not analyze the style image.";
            p.styleDescription = null;
          });
        } finally {
          updateActiveProjectState(p => { p.isAnalyzingStyle = false; });
        }
      };
      getStyleDescription();
    } else if (project?.styleImages?.length === 0 && project?.styleDescription) {
      updateActiveProjectState(p => { p.styleDescription = null; });
    }
  }, [
    project?.id,
    project?.styleImages, 
    project?.styleDescription,
    project?.isAnalyzingStyle,
    project?.error,
    updateActiveProjectState
  ]);

  // Auto-generate prompt
  useEffect(() => {
    if (!project || !project.isPromptAutoGenerated) return;

    const { productImages, styleImages, options, isAnalyzingStyle, styleDescription } = project;

    if (productImages.length === 0 && styleImages.length === 0) {
      if(project.prompt !== '') updateActiveProjectState(p => { p.prompt = ''; });
      return;
    }

    let newPrompt = `Generate a high-resolution, professional photograph`;
    if (productImages.length > 0) {
      newPrompt += ` of the subject in the provided image${productImages.length > 1 ? 's' : ''}`;
    }
    newPrompt += `.

Key requirements:
- Lighting: ${options.lightingStyle}
- Perspective: ${options.cameraPerspective}
- Environment: Clean, high-end studio setting.`;

    if (styleImages.length > 0) {
      if (isAnalyzingStyle) newPrompt += `\n- Style: Analyzing reference...`;
      else if (styleDescription) newPrompt += `\n- Style: Match reference (${styleDescription}).`;
      else newPrompt += `\n- Style: Strictly follow style reference image(s).`;
    }

    if(project.prompt !== newPrompt) updateActiveProjectState(p => { p.prompt = newPrompt; });
  }, [
    project?.id,
    project?.isPromptAutoGenerated,
    project?.productImages, 
    project?.styleImages, 
    project?.options, 
    project?.isAnalyzingStyle, 
    project?.styleDescription,
    updateActiveProjectState
  ]);

  // Translation effect
  useEffect(() => {
    const arabicRegex = /[\u0600-\u06FF]/;
    if (!project || project.isPromptAutoGenerated) {
        if (project?.translatedPrompt || project?.isTranslating) {
            updateActiveProjectState(p => { p.translatedPrompt = null; p.isTranslating = false; });
        }
        return;
    }

    if (translateTimeoutRef.current) clearTimeout(translateTimeoutRef.current);
    const promptToTranslate = project.prompt;

    if (!arabicRegex.test(promptToTranslate) || !promptToTranslate.trim()) {
        if (project.translatedPrompt || project.isTranslating) {
            updateActiveProjectState(p => { p.translatedPrompt = null; p.isTranslating = false; });
        }
        return;
    }

    translateTimeoutRef.current = window.setTimeout(async () => {
        translationRequestCounter.current += 1;
        const currentRequestId = translationRequestCounter.current;
        updateActiveProjectState(p => { p.isTranslating = true; p.error = null; });

        try {
            const translated = await translateText(promptToTranslate);
            if (translationRequestCounter.current === currentRequestId) {
                updateActiveProjectState(p => { if (p.prompt === promptToTranslate) p.translatedPrompt = translated; });
            }
        } catch (err) {
            console.error(err);
            if (translationRequestCounter.current === currentRequestId) {
                updateActiveProjectState(p => { p.error = err instanceof Error ? err.message : 'Translation failed.'; });
            }
        } finally {
            if (translationRequestCounter.current === currentRequestId) {
                updateActiveProjectState(p => { p.isTranslating = false; });
            }
        }
    }, 700);
  }, [project?.prompt, project?.isPromptAutoGenerated, updateActiveProjectState]);

  const handleGenerate = useCallback(async () => {
    if (!project || !project.prompt) {
      updateActiveProjectState(p => { p.error = 'Please write a prompt.'; });
      return;
    }
    const currentPrompt = project.prompt;
    updateActiveProjectState(p => { p.isLoading = true; p.error = null; p.generatedImage = null; });

    try {
      const result = await generateImage(project.productImages, project.prompt, project.styleImages);
      updateActiveProjectState(p => {
          p.generatedImage = result;
          p.history = [{ image: result, prompt: currentPrompt }, ...p.history];
      });
    } catch (err) {
      console.error(err);
      updateActiveProjectState(p => { p.error = err instanceof Error ? err.message : 'Generation failed.'; });
    } finally {
      updateActiveProjectState(p => { p.isLoading = false; });
    }
  }, [project, updateActiveProjectState]);

  const handleImageEdit = async (editPromptText: string) => {
    if (!project.generatedImage) return;

    updateActiveProjectState(p => { p.isEditing = true; p.error = null; });
    try {
        const result = await editImage(project.generatedImage as ImageFile, editPromptText);
        updateActiveProjectState(p => {
            p.generatedImage = result;
            p.history = [{ image: result, prompt: editPromptText }, ...p.history];
        });
    } catch (err) {
        updateActiveProjectState(p => { p.error = err instanceof Error ? err.message : 'Edit failed'; });
    } finally {
        updateActiveProjectState(p => { p.isEditing = false; });
    }
  };


  const handleFileUpload = (updater: (files: ImageFile[]) => void, target: 'product' | 'style') => async (files: File[]) => {
      if (!files || files.length === 0) return;
      updateActiveProjectState(p => { p.uploadingTarget = target; p.error = null; });
      let currentError: string | null = null;

      const filePromises = files.map(file => {
          return new Promise<ImageFile | null>(async (resolve) => {
              if (!file.type.startsWith('image/')) {
                  if(!currentError) currentError = `File '${file.name}' not supported.`;
                  resolve(null); return;
              }
              try {
                  const resizedFile = await resizeImage(file, 2048, 2048);
                  const reader = new FileReader();
                  reader.onloadend = () => {
                      resolve({ base64: (reader.result as string).split(',')[1], mimeType: resizedFile.type, name: resizedFile.name });
                  };
                  reader.readAsDataURL(resizedFile);
              } catch (err) {
                  resolve(null);
              }
          });
      });

      const results = await Promise.all(filePromises);
      const validImages = results.filter((img): img is ImageFile => img !== null);
      if (validImages.length > 0) updater(validImages);
      updateActiveProjectState(p => { p.error = currentError; p.uploadingTarget = null; });
  };

  const handleSetPrompt = (prompt: string) => updateActiveProjectState(p => {
    p.prompt = prompt;
    p.isPromptAutoGenerated = false;
  });

  if (!project) return null;

  return (
    <main className="w-full grid grid-cols-1 lg:grid-cols-2 gap-6 pt-4 pb-12 items-start">
        <div className="flex flex-col gap-4 order-1">
            <div className="grid grid-cols-2 gap-4">
                <div className="glass-card p-3 rounded-2xl flex flex-col gap-2 items-center">
                    <h3 className="text-xs font-bold text-[var(--color-text-medium)] uppercase">Product</h3>
                    <ImageWorkspace
                        id="creator-product-uploader"
                        images={project.productImages}
                        onImagesUpload={handleFileUpload(files => updateActiveProjectState(p => { p.productImages = [...p.productImages, ...files]; }), 'product')}
                        onImageRemove={(idx) => updateActiveProjectState(p => { p.productImages = p.productImages.filter((_, i) => i !== idx); })}
                        isUploading={project.uploadingTarget === 'product'}
                        onImageUpdate={(idx, img) => updateActiveProjectState(p => { p.productImages[idx] = img; })}
                    />
                </div>
                <div className="glass-card p-3 rounded-2xl flex flex-col gap-2 items-center">
                    <h3 className="text-xs font-bold text-[var(--color-text-medium)] uppercase">Style</h3>
                    <ImageWorkspace 
                        id="creator-style-uploader"
                        title="Style Reference"
                        images={project.styleImages}
                        onImagesUpload={handleFileUpload(files => updateActiveProjectState(p => { p.styleImages = [...p.styleImages, ...files]; p.styleDescription = null; }), 'style')}
                        onImageRemove={(idx) => updateActiveProjectState(p => { p.styleImages = p.styleImages.filter((_, i) => i !== idx); p.styleDescription = null; })}
                        isUploading={project.uploadingTarget === 'style'}
                        onImageUpdate={(idx, img) => updateActiveProjectState(p => { p.styleImages[idx] = img; p.styleDescription = null; })}
                    />
                </div>
            </div>

            <CustomizationPanel options={project.options} setOptions={(opt) => updateActiveProjectState(p => { p.options = opt; })} />

            <PromptEditor
                prompt={project.prompt}
                setPrompt={handleSetPrompt}
                isAutoGenerated={project.isPromptAutoGenerated}
                onResetPrompt={() => updateActiveProjectState(p => { p.isPromptAutoGenerated = true; })}
                translatedPrompt={project.translatedPrompt}
                isTranslating={project.isTranslating}
                onUseTranslation={(t) => updateActiveProjectState(p => { p.prompt = t; p.isPromptAutoGenerated = false; p.translatedPrompt = null; })}
            />

            <PromptSuggestions setPrompt={handleSetPrompt} currentPrompt={project.prompt} />

            <button
                onClick={handleGenerate}
                disabled={project.isLoading || !project.prompt || !!project.uploadingTarget}
                className="w-full bg-[var(--color-accent)] hover:bg-[var(--color-accent-dark)] text-white font-bold py-4 rounded-xl text-lg shadow-lg transition-all transform hover:-translate-y-1 disabled:opacity-50 disabled:transform-none"
            >
                {project.isLoading ? 'Generating...' : 'Generate Image'}
            </button>

            {project.error && <div className="bg-red-500/20 border border-red-500/50 text-red-200 px-4 py-3 rounded-lg text-sm">{project.error}</div>}
        </div>

        <div className="flex flex-col gap-4 order-2">
             <div className="glass-card rounded-2xl p-4 min-h-[400px]">
                <ResultDisplay 
                    imageFile={project.generatedImage} 
                    isLoading={project.isLoading}
                    onEdit={handleImageEdit}
                    isEditing={project.isEditing}
                />
             </div>
            <HistoryPanel history={project.history} onSelect={(img) => updateActiveProjectState(p => { p.generatedImage = img; })} />
        </div>
    </main>
  );
};

export default CreatorStudio;

import React, { useCallback } from 'react';
import { ImageFile, BrandingStudioProject, BrandingResultCategory, AspectRatio } from '../types';
import { resizeImage } from '../utils';
import { analyzeLogoForBranding, generateImage } from '../services/geminiService';
import ImageWorkspace from './ImageWorkspace';
import BrandingResultsGrid from './BrandingResultsGrid';
import { ASPECT_RATIOS } from '../constants';

const MOCKUP_CATEGORIES: BrandingResultCategory[] = [
    'Logo Construction Grid', 'Typography Showcase', 'Logo Color Variations', 'Monochrome Version',
    '3D Glass Logo', 'Business Card Mockup', '3D Glass App Icon', 'Creative Pen Mockup',
    'Merchandise (Tote Bag)', 'Pencil Sketch Logo', 'Notebook Mockup', 'Waving Flag Mockup'
];

const getPromptForCategory = (category: BrandingResultCategory, aspectRatio: AspectRatio): string => {
    const aspectRatioRequirement = ` The final image must have a ${aspectRatio} aspect ratio.`;
    switch (category) {
        case 'Logo Construction Grid':
            return "Create a technical brand guideline image. Display the provided logo on a light grid, showing construction lines, proportions, and a clear space margin around it." + aspectRatioRequirement;
        case 'Typography Showcase':
            return "Create a brand typography specimen sheet. Analyze the font style used in the provided logo and display full English alphabet neatly on a minimalist background." + aspectRatioRequirement;
        case 'Logo Color Variations':
            return "Create a brand guideline image showing logo color variations. Display four versions of the provided logo on different solid-colored backgrounds." + aspectRatioRequirement;
        case 'Monochrome Version':
            return 'A high-contrast, single-color (white) version of the provided logo, presented on a black background.' + aspectRatioRequirement;
        case '3D Glass Logo':
            return "Create a photorealistic 3D mockup of the provided logo rendered in glossy, translucent glass." + aspectRatioRequirement;
        case 'Business Card Mockup':
            return "A photorealistic mockup of a premium business card featuring the provided logo on marble background." + aspectRatioRequirement;
        case '3D Glass App Icon':
            return "Create a photorealistic 3D app icon from the provided logo in glossy translucent glass." + aspectRatioRequirement;
        case 'Creative Pen Mockup':
            return "A photorealistic mockup of a high-end elegant pen with the provided logo subtly engraved." + aspectRatioRequirement;
        case 'Merchandise (Tote Bag)':
            return "A photorealistic lifestyle mockup of the provided logo printed on a high-quality canvas tote bag." + aspectRatioRequirement;
        case 'Pencil Sketch Logo':
            return "Create a photorealistic artistic sketch of the provided logo as if hand-drawn with graphite pencil." + aspectRatioRequirement;
        case 'Notebook Mockup':
            return "A photorealistic mockup of a premium notebook with logo elegantly debossed on the cover." + aspectRatioRequirement;
        case 'Waving Flag Mockup':
            return "A photorealistic mockup of the provided logo on a large flag waving gently against a clear sky." + aspectRatioRequirement;
        default:
            return `A professional product shot of the provided logo.` + aspectRatioRequirement;
    }
}

const BrandingStudio: React.FC<{
  project: BrandingStudioProject;
  setProject: React.Dispatch<React.SetStateAction<BrandingStudioProject>>;
}> = ({ project, setProject }) => {

    const handleFileUpload = async (files: File[]) => {
        if (!files || files.length === 0) return;
        setProject(s => ({ ...s, isUploading: true, error: null }));
        try {
            const uploaded = await Promise.all(files.map(async file => {
                const resized = await resizeImage(file, 1024, 1024);
                const reader = new FileReader();
                return new Promise<ImageFile>(res => {
                    reader.onloadend = () => res({ base64: (reader.result as string).split(',')[1], mimeType: resized.type, name: resized.name });
                    reader.readAsDataURL(resized);
                });
            }));
            setProject(s => ({
                ...s,
                logos: [...s.logos, ...uploaded],
                isUploading: false,
                results: [],
                colors: [],
            }));
        } catch (err) {
            setProject(s => ({ ...s, error: 'Upload failed', isUploading: false }));
        }
    };

    const handleRemoveLogo = (idx: number) => setProject(s => ({ ...s, logos: s.logos.filter((_, i) => i !== idx), results: [], colors: [], error: null }));
    const handleUpdateLogo = (idx: number, newImage: ImageFile) => setProject(s => {
        const nextLogos = [...s.logos];
        nextLogos[idx] = newImage;
        return { ...s, logos: nextLogos, results: [], colors: [] };
    });

    const onGenerate = useCallback(async () => {
        if (project.logos.length === 0) return;
        setProject(s => ({...s, isAnalyzing: true, isGenerating: true, error: null, colors: [], results: []}));
        try {
            const analysis = await analyzeLogoForBranding(project.logos);
            setProject(s => ({...s, colors: analysis.colors, isAnalyzing: false}));
            const initialResults = MOCKUP_CATEGORIES.map(category => ({ category, image: null, isLoading: true, error: null, editPrompt: '', isEditing: false }));
            setProject(s => ({...s, results: initialResults}));
            const promises = MOCKUP_CATEGORIES.map(category => {
                const prompt = getPromptForCategory(category, project.aspectRatio);
                return generateImage([project.logos[0]], prompt, null) // Primary logo as reference
                    .then(image => ({ status: 'fulfilled' as const, value: { category, image } }))
                    .catch(error => ({ status: 'rejected' as const, reason: { category, error } }));
            });
            const settledResults = await Promise.all(promises);
            settledResults.forEach(result => {
                if (result.status === 'fulfilled') {
                    const { category, image } = result.value;
                    setProject(s => ({...s, results: s.results.map(r => r.category === category ? { ...r, image, isLoading: false } : r)}));
                } else {
                    const { category, error } = result.reason;
                    setProject(s => ({ ...s, results: s.results.map(r => r.category === category ? { ...r, error: error.message || 'Generation failed', isLoading: false } : r)}));
                }
            });
        } catch(err) {
            setProject(s => ({...s, error: 'Analysis failed', isAnalyzing: false }));
        } finally {
            setProject(s => ({...s, isGenerating: false}));
        }
    }, [project.logos, project.aspectRatio, setProject]);

    if (!project) return null;

    return (
        <main className="w-full max-w-7xl flex flex-col gap-4 pt-4 pb-8 flex-grow">
            <div className="glass-card rounded-2xl p-4 flex flex-col md:flex-row items-center gap-4">
                <div className="w-full md:w-48 flex-shrink-0">
                    <ImageWorkspace
                        id="branding-logo-uploader"
                        title="Logo"
                        images={project.logos}
                        onImagesUpload={handleFileUpload}
                        onImageRemove={handleRemoveLogo}
                        isUploading={project.isUploading}
                        onImageUpdate={handleUpdateLogo}
                    />
                </div>
                <div className="flex-grow text-center md:text-left">
                    <h2 className="text-xl font-bold text-[var(--color-text-base)]">Branding Studio</h2>
                    <p className="text-sm text-[var(--color-text-secondary)] mt-1">Generate brand assets from your logo.</p>
                     <div className="mt-4 flex gap-2 flex-wrap">
                        {ASPECT_RATIOS.map(ratio => (
                            <button key={ratio.value} onClick={() => setProject(s => ({ ...s, aspectRatio: ratio.value as AspectRatio }))} className={`px-4 py-1.5 text-xs font-bold rounded-full transition-colors ${project.aspectRatio === ratio.value ? 'bg-[var(--color-accent)] text-white' : 'bg-black/20 text-[var(--color-text-secondary)] hover:text-white'}`}>{ratio.value}</button>
                        ))}
                    </div>
                </div>
                <button onClick={onGenerate} disabled={project.logos.length === 0 || project.isGenerating} className="w-full md:w-auto bg-[var(--color-accent)] text-white font-bold py-3 px-8 rounded-xl shadow-lg transition-all disabled:opacity-50">
                    {project.isGenerating ? 'Generating...' : 'Generate Branding'}
                </button>
            </div>
            {project.colors.length > 0 && (
                <div className="glass-card rounded-2xl p-4">
                    <h3 className="text-lg font-bold mb-4">Color Palette</h3>
                    <div className="flex flex-wrap gap-4">
                        {project.colors.map((color, index) => (
                            <div key={index} className="text-center">
                                <div className="w-14 h-14 rounded-lg border border-white/10" style={{backgroundColor: color}}></div>
                                <p className="text-xs mt-1.5 font-mono opacity-60">{color}</p>
                            </div>
                        ))}
                    </div>
                </div>
            )}
            {project.results.length > 0 && (
                <div className="glass-card rounded-2xl p-4">
                    <h3 className="text-lg font-bold mb-4">Assets</h3>
                     <BrandingResultsGrid results={project.results} />
                </div>
            )}
        </main>
    );
};

export default BrandingStudio;

import React, { useCallback, useState } from 'react';
import { ControllerStudioProject, ImageFile, ControlCategory, ControllerSlider, HistoryItem } from '../types';
import { resizeImage } from '../utils';
import { editImage } from '../services/geminiService';
import ImageWorkspace from './ImageWorkspace';
import HistoryPanel from './HistoryPanel';

interface ControllerStudioProps {
    project: ControllerStudioProject;
    setProject: React.Dispatch<React.SetStateAction<ControllerStudioProject>>;
