const PhotoshootDirector: React.FC<PhotoshootDirectorProps> = ({ project, setProject }) => {

    const onGenerate = useCallback(async () => {
    if (!project || project.productImages.length === 0 || project.selectedShotTypes.length === 0) {
      setProject(s => ({ ...s, error: 'Please upload a product image and select at least one shot type.' }));
      return;
    }

    setProject(s => ({
      ...s,
      isGenerating: true,
      error: null,
      results: s.selectedShotTypes.map(shotType => ({
        shotType,
        image: null,
        isLoading: true,
        error: null,
        editPrompt: '',
        isEditing: false,
      })),
    }));

    const generationPromises = project.selectedShotTypes.map(shotType => {
      let prompt = `A high-resolution, professional photograph of the subject from the provided image. The desired shot is: '${shotType}'. The background should be clean, non-distracting, and complementary to the subject.`;
      if (project.customStylePrompt) {
        prompt += ` Additional style requirements: ${project.customStylePrompt}`;
      }
      return generateImage(project.productImages, prompt, null)
        .then(image => ({ status: 'fulfilled' as const, value: { shotType, image } }))
        .catch(error => ({ status: 'rejected' as const, reason: { shotType, error } }));
    });

    const settledResults = await Promise.all(generationPromises);

    settledResults.forEach(result => {
      if (result.status === 'fulfilled') {
        const { shotType, image } = result.value;
        setProject(s => ({
          ...s,
          results: s.results.map(r => r.shotType === shotType ? { ...r, image, isLoading: false } : r),
        }));
      } else {
        const { shotType, error } = result.reason;
        console.error(`Failed to generate image for ${shotType}:`, error);
        setProject(s => ({
          ...s,
          results: s.results.map(r => r.shotType === shotType ? { ...r, error: error.message || 'Generation failed', isLoading: false } : r),
        }));
      }
    });

    setProject(s => ({ ...s, isGenerating: false }));
  }, [project, setProject]);

  const handleEditResult = async (index: number, prompt: string) => {
      const result = project.results[index];
      if (!result || !result.image) return;

      setProject(s => {
          const newResults = [...s.results];
          newResults[index] = { ...newResults[index], isEditing: true, error: null };
          return { ...s, results: newResults };
      });

      try {
          const updated = await editImage(result.image, prompt);
          setProject(s => {
              const newResults = [...s.results];
              newResults[index] = { ...newResults[index], image: updated, isEditing: false };
              return { ...s, results: newResults };
          });
      } catch (err) {
          setProject(s => {
              const newResults = [...s.results];
              newResults[index] = { ...newResults[index], isEditing: false, error: err instanceof Error ? err.message : 'Edit failed' };
              return { ...s, results: newResults };
          });
      }
  };

  const handleFileUpload = async (files: File[]) => {
    if (!files || files.length === 0) return;

    setProject(s => ({ ...s, isUploading: true, error: null }));
    let currentError: string | null = null;

    const filePromises = files.map(file => {
      return new Promise<ImageFile | null>(async (resolve) => {
        if (!file.type.startsWith('image/')) {
          if (!currentError) currentError = `File '${file.name}' is not a supported image type.`;
          resolve(null);
          return;
        }
        try {
          const resizedFile = await resizeImage(file, 2048, 2048);
          const reader = new FileReader();
          reader.onloadend = () => {
            const base64String = reader.result as string;
            resolve({
              base64: base64String.split(',')[1],
              mimeType: resizedFile.type,
              name: resizedFile.name
            });
          };
          reader.onerror = () => {
            if (!currentError) currentError = `Error reading file '${resizedFile.name}'.`;
            resolve(null);
          };
          reader.readAsDataURL(resizedFile);
        } catch (err) {
          console.error(`Error processing ${file.name}:`, err);
          if (!currentError) currentError = `Could not process file '${file.name}'.`;
          resolve(null);
        }
      });
    });

    const results = await Promise.all(filePromises);
    const validImages = results.filter((img): img is ImageFile => img !== null);

    setProject(s => ({
      ...s,
      productImages: [...s.productImages, ...validImages],
      error: currentError,
      isUploading: false,
    }));
  };

  const handleRemoveImage = (indexToRemove: number) => {
    setProject(s => ({
      ...s,
      productImages: s.productImages.filter((_, index) => index !== indexToRemove),
    }));
  };

  const handleImageUpdate = (index: number, newImage: ImageFile) => {
      setProject(s => {
          const newImages = [...s.productImages];
          if (index >= 0 && index < newImages.length) {
              newImages[index] = newImage;
          }
          return { ...s, productImages: newImages };
      });
  };

  if (!project) {
    return (
        <main className="w-full max-w-7xl flex items-center justify-center gap-8 pt-8 pb-12 flex-grow">
            <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-[var(--color-accent)]"></div>
            <p className="text-[var(--color-text-secondary)]">Loading Photoshoot Director...</p>
        </main>
    );
  }

  return (
    <main className="w-full flex flex-col gap-4 pt-4 pb-8">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4 flex-grow">
        {/* Left Column: Controls */}
        <div className="lg:col-span-1 flex flex-col gap-4">
          <div className="glass-card rounded-2xl p-4">
            <h3 className="text-lg font-bold text-[var(--color-text-base)] mb-4">1. Upload Image(s)</h3>
            <ImageWorkspace
              id="photoshoot-product-uploader"
              images={project.productImages}
              onImagesUpload={handleFileUpload}
              onImageRemove={handleRemoveImage}
              isUploading={project.isUploading}
              onImageUpdate={handleImageUpdate}
            />
          </div>
          <ShotTypeSelector
            selected={project.selectedShotTypes}
            onChange={(selected) => setProject(s => ({ ...s, selectedShotTypes: selected }))}
            customStylePrompt={project.customStylePrompt}
            onCustomStylePromptChange={(prompt) => setProject(s => ({...s, customStylePrompt: prompt }))}
          />
          <div className="w-full px-4 py-2">
            <button
                onClick={onGenerate}
                disabled={project.isGenerating || project.isUploading || project.productImages.length === 0 || project.selectedShotTypes.length === 0}
                className="w-full bg-gradient-to-r from-[var(--color-accent)] to-[var(--color-accent-dark)] hover:from-[var(--color-accent-dark)] hover:to-[var(--color-accent-darker)] text-[var(--color-text-base)] font-bold py-3 px-8 rounded-lg text-lg transition-all duration-300 ease-in-out disabled:opacity-50 disabled:cursor-not-allowed shadow-lg hover:shadow-2xl hover:shadow-[var(--color-accent)]/20 disabled:shadow-none transform hover:-translate-y-1 disabled:transform-none"
            >
                {project.isGenerating ? 'Generating...' : `Generate ${project.selectedShotTypes.length} Shot${project.selectedShotTypes.length === 1 ? '' : 's'}`}
            </button>
          </div>
        </div>

        {/* Right Column: Results */}
        <div className="lg:col-span-2 flex flex-col gap-6">
          <div className="flex flex-col flex-grow glass-card rounded-2xl p-4">
              <div className="flex justify-between items-center mb-4">
                  <h3 className="text-lg font-bold text-[var(--color-text-base)]">3. Generated Results</h3>
              </div>
               {project.error && <div className="mb-4 bg-[rgba(var(--color-accent-rgb),0.2)] border border-[rgba(var(--color-accent-rgb),0.5)] text-[var(--color-accent-light)] px-4 py-3 rounded-lg" role="alert">{project.error}</div>}
              <ResultsGrid 
                results={project.results} 
                onEditResult={handleEditResult}
              />
          </div>
        </div>
      </div>
    </main>
  );
};

export default PhotoshootDirector;

import React, { useCallback } from 'react';
import { CampaignStudioProject, ImageFile, BrandingResult } from '../types';
import { resizeImage } from '../utils';
import { analyzeProductForCampaign, generateImage, editImage } from '../services/geminiService';
import ImageWorkspace from './ImageWorkspace';
import BrandingResultsGrid from './BrandingResultsGrid';

const CAMPAIGN_SCENARIOS = [
    'Front View (Hero)', 
    '45° Angle (Depth)', 
    'Top-Down (Flat Lay)', 
    'Close-Up (Texture)', 
    'Side View (Profile)', 
    'Lifestyle (Context)'
];

const CAMPAIGN_MOODS = [
    { label: 'Original', value: '' },
    { label: 'Minimalist White', value: 'Clean, minimalist white studio aesthetic' },
    { label: 'Dark Luxury', value: 'Dramatic dark luxury with gold accents' },
    { label: 'Pastel Pop', value: 'Soft playful pastel colors' },
    { label: 'Nature Green', value: 'Organic fresh natural green aesthetic' },
    { label: 'Ocean Blue', value: 'Deep serene ocean blue tones' },
    { label: 'Warm Gold', value: 'Warm, golden hour luxury lighting' },
    { label: 'Cyberpunk Neon', value: 'Vibrant neon cyberpunk style' },
];

const CheckCircleIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-emerald-500 mt-0.5 flex-shrink-0" viewBox="0 0 20 20" fill="currentColor">
        <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
    </svg>
);

const CampaignStudio: React.FC<{
    project: CampaignStudioProject;
    setProject: React.Dispatch<React.SetStateAction<CampaignStudioProject>>;
}> = ({ project, setProject }) => {

    if (!project) return null;
    const productImages = project.productImages || [];
    const results = project.results || [];

    const handleFileUpload = async (files: File[]) => {
        if (!files || files.length === 0) return;
        setProject(s => ({ ...s, isUploading: true, error: null }));
        try {
            const uploaded = await Promise.all(files.map(async file => {
                const resized = await resizeImage(file, 2048, 2048);
                const reader = new FileReader();
                return new Promise<ImageFile>(res => {
                    reader.onloadend = () => res({ base64: (reader.result as string).split(',')[1], mimeType: resized.type, name: resized.name });
                    reader.readAsDataURL(resized);
                });
            }));
            const combined = [...productImages, ...uploaded];
            setProject(s => ({ ...s, productImages: combined, isUploading: false, isAnalyzing: true }));
            const analysis = await analyzeProductForCampaign(combined);
            setProject(s => ({ ...s, productAnalysis: analysis, isAnalyzing: false }));
        } catch (err) {
            setProject(s => ({ ...s, isUploading: false, isAnalyzing: false, error: "Upload failed" }));
        }
    };

    const handleRemoveProduct = (idx: number) => {
        setProject(s => ({ ...s, productImages: s.productImages.filter((_, i) => i !== idx) }));
    };

    const handleUpdateProduct = (idx: number, newImage: ImageFile) => {
        setProject(s => {
            const nextImages = [...s.productImages];
            nextImages[idx] = newImage;
            return { ...s, productImages: nextImages };
        });
    };

    const onGenerate = useCallback(async () => {
        if (productImages.length === 0) return;
        setProject(s => ({ ...s, isGenerating: true, error: null, results: [] }));
        try {
            let analysis = project.productAnalysis || await analyzeProductForCampaign(productImages);
            let scenarios = CAMPAIGN_SCENARIOS;
            const initial = scenarios.map(scenario => ({ scenario, image: null, isLoading: true, error: null, editPrompt: '', isEditing: false }));
            setProject(s => ({ ...s, results: initial as any }));
            const promises = scenarios.map((scenario) => {
                const moodV = CAMPAIGN_MOODS.find(m => m.label === project.selectedMood)?.value || '';
                const prompt = `Professional Campaign: ${analysis}. Scenario: ${scenario}. Style: ${moodV}. Additional user details: ${project.customPrompt}`;
                return generateImage(productImages, prompt, null).then(image => ({ scenario, image })).catch(error => ({ scenario, error: error.message }));
            });
            const completed = await Promise.all(promises);
            setProject(s => {
                const nextResults = [...s.results];
                completed.forEach(res => {
                    const idx = nextResults.findIndex(r => r && r.scenario === res.scenario);
                    if (idx !== -1) {
                        if ('image' in res) nextResults[idx] = { ...nextResults[idx], image: res.image, isLoading: false };
                        else nextResults[idx] = { ...nextResults[idx], error: res.error, isLoading: false };
                    }
                });
                return { ...s, results: nextResults };
            });
        } catch (err) {
            setProject(s => ({ ...s, error: 'Generation failed', isGenerating: false }));
        } finally {
            setProject(s => ({ ...s, isGenerating: false }));
        }
    }, [productImages, project.productAnalysis, project.selectedMood, project.customPrompt, setProject]);

    const handleEditResult = async (index: number, editPromptText: string) => {
        const resultToEdit = results[index];
        if (!resultToEdit || !resultToEdit.image) return;

        // Set local loading state
        setProject(s => {
            const nextResults = [...s.results];
            nextResults[index] = { ...nextResults[index], isEditing: true, error: null };
            return { ...s, results: nextResults };
        });

        try {
            const updatedImage = await editImage(resultToEdit.image, editPromptText);
            setProject(s => {
                const nextResults = [...s.results];
                nextResults[index] = { ...nextResults[index], image: updatedImage, isEditing: false };
                return { ...s, results: nextResults };
            });
        } catch (err) {
            console.error("Edit failed:", err);
            setProject(s => {
                const nextResults = [...s.results];
                nextResults[index] = { ...nextResults[index], isEditing: false, error: err instanceof Error ? err.message : "Edit failed" };
                return { ...s, results: nextResults };
            });
        }
    };

    const safeGridResults: BrandingResult[] = results.map(r => ({
        category: r.scenario as any,
        image: r.image || null,
        isLoading: !!r.isLoading,
        isEditing: !!r.isEditing,
        error: r.error || null,
        editPrompt: r.editPrompt || ''
    }));

    // Split analysis into bullet points for better display
    const analysisPoints = project.productAnalysis 
        ? project.productAnalysis.split('.').filter(p => p.trim().length > 10)
        : [];

    return (
        <main className="w-full flex flex-col gap-8 pt-4 pb-12 animate-in fade-in duration-700">
            {/* Control Panel */}
            <div className="glass-card rounded-[2rem] p-6 md:p-8 flex flex-col lg:flex-row gap-8 shadow-2xl">
                {/* Left: Product Selection */}
                <div className="w-full lg:w-72 flex-shrink-0">
                    <h3 className="text-xs font-bold text-white/40 uppercase tracking-[0.2em] mb-4 text-center">Upload Image(s)</h3>
                    <div className="aspect-square bg-black/20 rounded-3xl overflow-hidden border border-white/5">
                        <ImageWorkspace
                            id="campaign-product-uploader"
                            images={productImages}
                            onImagesUpload={handleFileUpload}
                            onImageRemove={handleRemoveProduct}
                            isUploading={project.isUploading}
                            onImageUpdate={handleUpdateProduct}
                        />
                    </div>
                </div>

                {/* Right: Campaign Controls */}
                <div className="flex-grow flex flex-col gap-6">
                    <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                        <div>
                            <h2 className="text-2xl font-black text-white tracking-tight">Social Media Campaign Studio</h2>
                            <p className="text-sm text-white/50 mt-1">AI will generate 6 unique Social Media feed posts with your desired mood.</p>
                        </div>
                        <button 
                            onClick={onGenerate} 
                            disabled={productImages.length === 0 || project.isGenerating} 
                            className="bg-[var(--color-accent)] hover:bg-[var(--color-accent-dark)] text-white font-black py-4 px-8 rounded-xl shadow-xl shadow-[var(--color-accent)]/20 transition-all active:scale-95 disabled:opacity-30 whitespace-nowrap"
                        >
                            {project.isGenerating ? 'Generating...' : 'Generate 6 Feed Posts'}
                        </button>
                    </div>

                    {/* Mood Selector */}
                    <div className="flex flex-col gap-3">
                        <div className="flex flex-wrap gap-2">
                            {CAMPAIGN_MOODS.map(mood => (
                                <button 
                                    key={mood.label} 
                                    onClick={() => setProject(s => ({ ...s, selectedMood: mood.label }))} 
                                    className={`px-5 py-2.5 text-xs font-bold rounded-full transition-all border ${
                                        project.selectedMood === mood.label 
                                        ? 'bg-[var(--color-accent)] text-white border-[var(--color-accent)] shadow-lg shadow-[var(--color-accent)]/20' 
                                        : 'bg-black/20 text-white/60 border-white/5 hover:border-white/20 hover:text-white'
                                    }`}
                                >
                                    {mood.label}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Custom Prompt */}
                    <div className="w-full">
                        <input 
                            type="text" 
                            value={project.customPrompt} 
                            onChange={(e) => setProject(s => ({ ...s, customPrompt: e.target.value }))} 
                            placeholder="Optional: Specify a dominant color or specific style details..." 
                            className="w-full glass-input rounded-xl px-5 py-4 text-sm font-medium focus:ring-2 focus:ring-[var(--color-accent)] border-white/10"
                        />
                    </div>

                    {/* Analysis Section */}
                    <div className={`transition-all duration-500 overflow-hidden ${project.productAnalysis || project.isAnalyzing ? 'opacity-100 max-h-96' : 'opacity-0 max-h-0'}`}>
                        <div className="bg-emerald-500/5 border border-emerald-500/20 rounded-2xl p-5">
                            <h4 className="text-[10px] font-black text-emerald-500/70 uppercase tracking-[0.2em] mb-3">AI Analysis & Style</h4>
                            {project.isAnalyzing ? (
                                <div className="flex items-center gap-3 text-emerald-400/60 animate-pulse">
                                    <div className="w-4 h-4 rounded-full border-2 border-current border-t-transparent animate-spin"></div>
                                    <span className="text-xs font-bold">Analyzing your product...</span>
                                </div>
                            ) : (
                                <ul className="flex flex-col gap-3">
                                    {analysisPoints.map((point, i) => (
                                        <li key={i} className="flex gap-3 text-xs font-medium text-emerald-400/80 leading-relaxed">
                                            <CheckCircleIcon />
                                            {point.trim()}.
                                        </li>
                                    ))}
                                </ul>
                            )}
                        </div>
                    </div>
                </div>
            </div>

            {/* Results Grid */}
            {results.length > 0 && (
                <div className="flex flex-col gap-6 animate-in slide-in-from-bottom-4 duration-1000">
                    <div className="flex items-center gap-4">
                        <h3 className="text-xl font-bold text-white tracking-tight">Social Media Campaign Assets</h3>
                        <div className="h-px flex-grow bg-white/5"></div>
                    </div>
                    <BrandingResultsGrid 
                        results={safeGridResults}
                        gridClassName="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6"
                        onEditResult={handleEditResult}
                    />
                </div>
            )}

            {project.error && (
                <div className="bg-red-500/10 border border-red-500/20 text-red-400 p-4 rounded-xl text-sm text-center">
                    {project.error}
                </div>
            )}
        </main>
    );
};

