export async function generateCampaignPlan(
    productImages: ImageFile[],
    logos: ImageFile[],
    userPrompt: string
): Promise<any[]> {
    const model = 'gemini-3-flash-preview';
    const parts: Part[] = [];

    productImages.forEach(img => parts.push({ inlineData: { data: img.base64, mimeType: img.mimeType } }));
    logos.forEach(img => parts.push({ inlineData: { data: img.base64, mimeType: img.mimeType } }));

    const instruction = `Act as a professional Creative Director. Based on the product/logo images and this goal: "${userPrompt}", generate 6 unique campaign post ideas. 
    Return a JSON array where each object has:
    - id: string
    - scenario: descriptive visual prompt for AI image generation (e.g., "A modern studio shot of the product on marble...")
    - caption: engaging social media caption (Arabic/English as appropriate)
    - tov: specific Tone of Voice for this post
    - schedule: recommended posting time/day
    Return ONLY the raw JSON array.`;

    parts.push({ text: instruction });

    try {
        const response = await ai.models.generateContent({
            model,
            contents: { parts },
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            id: { type: Type.STRING },
                            scenario: { type: Type.STRING },
                            caption: { type: Type.STRING },
                            tov: { type: Type.STRING },
                            schedule: { type: Type.STRING },
                        },
                        required: ["id", "scenario", "caption", "tov", "schedule"]
                    }
                }
            }
        });
        return JSON.parse(response.text.trim());
    } catch (err) {
        console.error("Plan generation failed:", err);
        throw err;
    }
}

export async function analyzeProductForCampaign(productImages: ImageFile[]): Promise<string> {
    const model = 'gemini-3-flash-preview';
    const parts: Part[] = [];
    productImages.forEach(img => parts.push({ inlineData: { data: img.base64, mimeType: img.mimeType } }));

    const prompt = `Analyze these product image(s). Return a concise 2-sentence description of the product and its best lifestyle context.`;
    parts.push({ text: prompt });

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model,
            contents: { parts },
        });
        return response.text.trim();
    } catch (error) {
        throw error;
    }
}

import React, { useCallback, useState } from 'react';
import { PlanStudioProject, ImageFile, PlanIdea } from '../types';
import { resizeImage } from '../utils';
import { generateCampaignPlan, generateImage } from '../services/geminiService';
import ImageWorkspace from './ImageWorkspace';

const MagicIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-2" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M13 10V3L4 14h7v7l9-11h-7z" />
    </svg>
);

const PlanStudio: React.FC<{
    project: PlanStudioProject;
    setProject: React.Dispatch<React.SetStateAction<PlanStudioProject>>;
}> = ({ project, setProject }) => {

    const handleFileUpload = (target: 'product' | 'logo') => async (files: File[]) => {
        if (!files || files.length === 0) return;
        setProject(s => ({ ...s, isUploading: true, error: null }));
        try {
            const uploaded = await Promise.all(files.map(async file => {
                const resized = await resizeImage(file, 2048, 2048);
                const reader = new FileReader();
                return new Promise<ImageFile>(res => {
                    reader.onloadend = () => res({ base64: (reader.result as string).split(',')[1], mimeType: resized.type, name: resized.name });
                    reader.readAsDataURL(resized);
                });
            }));
            setProject(s => ({
                ...s,
                [target === 'product' ? 'productImages' : 'logos']: [...(target === 'product' ? s.productImages : s.logos), ...uploaded],
                isUploading: false
            }));
        } catch (err) {
            setProject(s => ({ ...s, isUploading: false, error: "Upload failed" }));
        }
    };

    const onCreatePlan = async () => {
        if (project.productImages.length === 0) {
            setProject(s => ({ ...s, error: 'Please upload at least one product image.' }));
            return;
        }
        setProject(s => ({ ...s, isGeneratingPlan: true, error: null }));
        try {
            const plan = await generateCampaignPlan(project.productImages, project.logos, project.prompt);
            const ideas: PlanIdea[] = plan.map(p => ({
                ...p,
                image: null,
                isLoadingImage: false,
                imageError: null
            }));
            setProject(s => ({ ...s, ideas, isGeneratingPlan: false }));
        } catch (err) {
            setProject(s => ({ ...s, isGeneratingPlan: false, error: "Plan generation failed" }));
        }
    };

    const onGenerateIdeaImage = async (ideaId: string) => {
        const ideaIdx = project.ideas.findIndex(i => i.id === ideaId);
        if (ideaIdx === -1) return;

        setProject(s => {
            const next = [...s.ideas];
            next[ideaIdx] = { ...next[ideaIdx], isLoadingImage: true, imageError: null };
            return { ...s, ideas: next };
        });

        try {
            const textConstraint = "STRICTLY PRESERVE all original branding from the product images. NO EXTRA generated text in the scene.";
            const finalPrompt = `Professional commercial photography based on this scenario: ${project.ideas[ideaIdx].scenario}. Style: Photorealistic, high-end. ${textConstraint}`;
            const image = await generateImage(project.productImages, finalPrompt, null);

            setProject(s => {
                const next = [...s.ideas];
                next[ideaIdx] = { ...next[ideaIdx], image, isLoadingImage: false };
                return { ...s, ideas: next };
            });
        } catch (err) {
            setProject(s => {
                const next = [...s.ideas];
                next[ideaIdx] = { ...next[ideaIdx], isLoadingImage: false, imageError: "Failed to generate image" };
                return { ...s, ideas: next };
            });
        }
    };

    const updateIdea = (id: string, field: keyof PlanIdea, value: string) => {
        setProject(s => ({
            ...s,
            ideas: s.ideas.map(i => i.id === id ? { ...i, [field]: value } : i)
        }));
    };

    return (
        <main className="w-full flex flex-col gap-8 pt-4 pb-12 animate-in fade-in duration-700">
            <div className="glass-card rounded-[2.5rem] p-8 shadow-2xl">
                <h2 className="text-3xl font-black text-white tracking-tighter mb-6 flex items-center">
                    <MagicIcon /> STRATEGIC CAMPAIGN PLANNER
                </h2>

                <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                    {/* Left: Inputs */}
                    <div className="lg:col-span-4 flex flex-col gap-6">
                        <div className="flex flex-col gap-4">
                            <label className="text-[10px] font-black text-white/40 uppercase tracking-[0.2em] ml-1">Product/Service Reference</label>
                            <ImageWorkspace
                                id="plan-product-up"
                                images={project.productImages}
                                onImagesUpload={handleFileUpload('product')}
                                onImageRemove={(i) => setProject(s => ({ ...s, productImages: s.productImages.filter((_, idx) => idx !== i) }))}
                                isUploading={project.isUploading}
                            />
                        </div>
                        <div className="flex flex-col gap-4">
                            <label className="text-[10px] font-black text-white/40 uppercase tracking-[0.2em] ml-1">Account Logo (Branding Context)</label>
                            <ImageWorkspace
                                id="plan-logo-up"
                                images={project.logos}
                                onImagesUpload={handleFileUpload('logo')}
                                onImageRemove={(i) => setProject(s => ({ ...s, logos: s.logos.filter((_, idx) => idx !== i) }))}
                                isUploading={project.isUploading}
                                title="Upload Logo"
                            />
                        </div>
                    </div>

                    {/* Right: Prompt & Action */}
                    <div className="lg:col-span-8 flex flex-col gap-6">
                        <div className="flex flex-col gap-2 bg-white/5 p-6 rounded-3xl border border-white/5">
                            <label className="text-xs font-bold text-[var(--color-accent)] uppercase tracking-widest">Campaign Goal & Brand Vision</label>
                            <textarea
                                value={project.prompt}
                                onChange={(e) => setProject(s => ({ ...s, prompt: e.target.value }))}
                                placeholder="e.g. 'Luxury watch brand launching a new collection for professionals. Focus on time, elegance, and success.'"
                                className="w-full bg-transparent border-none p-0 text-lg font-medium focus:ring-0 placeholder:text-white/20 min-h-[120px] suggestions-scrollbar"
                            />
                        </div>
                        <button
                            onClick={onCreatePlan}
                            disabled={project.isGeneratingPlan || project.productImages.length === 0}
