import React, { useState, useRef, useCallback } from 'react';
import { EditStudioProject, ImageFile, EditLayer, EditAdjustments } from '../types';
import { resizeImage } from '../utils';

const ARABIC_FONTS = ['Cairo', 'Tajawal', 'Amiri', 'Reem Kufi', 'Lateef'];
const ENGLISH_FONTS = ['Montserrat', 'Bebas Neue', 'Playfair Display', 'Oswald', 'Rubik'];

const TrashIcon = () => <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>;
const PlusIcon = () => <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>;
const TextIcon = () => <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h7" /></svg>;
const DownloadIcon = () => <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>;

const EditStudio: React.FC<{
    project: EditStudioProject;
    setProject: React.Dispatch<React.SetStateAction<EditStudioProject>>;
}> = ({ project, setProject }) => {

    const [draggedLayerId, setDraggedLayerId] = useState<string | null>(null);

    const handleBaseUpload = async (files: File[]) => {
        if (!files || files.length === 0) return;
        setProject(s => ({ ...s, isUploading: true }));
        try {
            const uploaded = await Promise.all(files.map(async file => {
                const resized = await resizeImage(file, 2048, 2048);
                const reader = new FileReader();
                return new Promise<ImageFile>(res => {
                    reader.onloadend = () => res({ base64: (reader.result as string).split(',')[1], mimeType: resized.type, name: resized.name });
                    reader.readAsDataURL(resized);
                });
            }));

            setProject(s => {
                const newBase = [...s.baseImages];
                let uploadedIdx = 0;
                for (let i = 0; i < 6 && uploadedIdx < uploaded.length; i++) {
                    if (!newBase[i]) {
                        newBase[i] = uploaded[uploadedIdx];
                        uploadedIdx++;
                    }
                }
                return { ...s, baseImages: newBase, isUploading: false };
            });
        } catch (err) {
            setProject(s => ({ ...s, isUploading: false, error: "Failed to upload" }));
        }
    };

    const handleAssetUpload = async (files: File[]) => {
        if (!files || files.length === 0) return;
        try {
            const uploaded = await Promise.all(files.map(async file => {
                const resized = await resizeImage(file, 1024, 1024);
                const reader = new FileReader();
                return new Promise<ImageFile>(res => {
                    reader.onloadend = () => res({ base64: (reader.result as string).split(',')[1], mimeType: resized.type, name: resized.name });
                    reader.readAsDataURL(resized);
                });
            }));
            setProject(s => ({ ...s, assets: [...s.assets, ...uploaded] }));
        } catch (err) { console.error(err); }
    };

    const addTextLayer = () => {
        const newLayer: EditLayer = {
            id: Date.now().toString(),
            type: 'text',
            content: 'Write something...',
            x: 50, y: 50, width: 200, height: 50, rotation: 0, opacity: 1,
            style: {
                fontSize: 40,
                fontFamily: 'Tajawal',
                color: '#ffffff',
                shadow: '0px 4px 10px rgba(0,0,0,0.5)',
                fontWeight: 'bold'
            }
        };
        setProject(s => ({ ...s, layers: [...s.layers, newLayer] }));
    };

    const addImageLayer = (asset: ImageFile) => {
        const newLayer: EditLayer = {
            id: Date.now().toString(),
            type: 'image',
            content: asset.base64,
            x: 50, y: 50, width: 150, height: 150, rotation: 0, opacity: 1
        };
        setProject(s => ({ ...s, layers: [...s.layers, newLayer] }));
    };

    const updateAdjustment = (field: keyof EditAdjustments, value: number) => {
        setProject(s => ({ ...s, adjustments: { ...s.adjustments, [field]: value } }));
    };

    const toggleSelection = (idx: number) => {
        setProject(s => ({
            ...s,
            selectedIndices: s.selectedIndices.includes(idx) 
                ? s.selectedIndices.filter(i => i !== idx) 
                : [...s.selectedIndices, idx]
        }));
    };

    const handleDownload = (img: ImageFile, resolution: '2k' | '4k') => {
        // Simple download for now, complex rendering on canvas can be added later
        const link = document.createElement('a');
        link.href = `data:${img.mimeType};base64,${img.base64}`;
        link.download = `Jenta-Edit-${resolution}-${Date.now()}.png`;
        link.click();
    };

    const filterString = `brightness(${project.adjustments.brightness}%) contrast(${project.adjustments.contrast}%) saturate(${project.adjustments.saturation}%) hue-rotate(${project.adjustments.hue}deg) blur(${project.adjustments.blur}px)`;

    return (
        <main className="w-full h-[calc(100vh-120px)] flex flex-col lg:flex-row gap-4 pt-2 overflow-hidden">

            {/* Sidebar Left: Assets & Uploads */}
            <div className="lg:w-72 flex flex-col gap-4 overflow-y-auto suggestions-scrollbar pr-2">
                <div className="glass-card rounded-2xl p-5">
                    <h3 className="text-xs font-black text-white/40 uppercase tracking-widest mb-4">Base Images (Canvas)</h3>
                    <label className="w-full h-12 border-2 border-dashed border-white/10 rounded-xl flex items-center justify-center cursor-pointer hover:border-[var(--color-accent)] transition-all mb-4">
                        <PlusIcon /> <span className="ml-2 text-xs font-bold">Import Photos</span>
                        <input type="file" multiple className="hidden" accept="image/*" onChange={(e) => handleBaseUpload(Array.from(e.target.files || []))} />
                    </label>
                    <div className="space-y-2">
                        {project.baseImages.map((img, i) => (
                            <div 
                                key={i} 
                                onClick={() => toggleSelection(i)}
                                className={`h-16 rounded-xl overflow-hidden cursor-pointer border-2 transition-all relative ${project.selectedIndices.includes(i) ? 'border-[var(--color-accent)]' : 'border-transparent bg-white/5'}`}
                            >
                                {img ? <img src={`data:${img.mimeType};base64,${img.base64}`} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-[10px] opacity-20">Empty Slot</div>}
                                <div className={`absolute top-1 left-1 w-4 h-4 rounded-full flex items-center justify-center text-[8px] font-black ${project.selectedIndices.includes(i) ? 'bg-[var(--color-accent)] text-white' : 'bg-black/50 text-white/50'}`}>{i+1}</div>
                            </div>
                        ))}
                    </div>
                </div>

                <div className="glass-card rounded-2xl p-5 flex-grow">
                    <h3 className="text-xs font-black text-white/40 uppercase tracking-widest mb-4">Library Assets</h3>
                    <label className="w-full h-10 bg-white/5 rounded-lg flex items-center justify-center cursor-pointer hover:bg-white/10 transition-all mb-4">
                         <span className="text-[10px] font-bold">Import Asset</span>
                         <input type="file" multiple className="hidden" accept="image/*" onChange={(e) => handleAssetUpload(Array.from(e.target.files || []))} />
                    </label>
                    <div className="grid grid-cols-2 gap-2">
                        {project.assets.map((asset, i) => (
                            <div key={i} onClick={() => addImageLayer(asset)} className="aspect-square bg-black/20 rounded-lg overflow-hidden cursor-pointer hover:scale-105 transition-transform border border-white/5">
                                <img src={`data:${asset.mimeType};base64,${asset.base64}`} className="w-full h-full object-contain" />
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            {/* Center: Main Canvas Grid */}
            <div className="flex-grow glass-card rounded-[2.5rem] p-6 bg-black/30 overflow-y-auto suggestions-scrollbar">
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {project.baseImages.map((img, idx) => (
                        <div key={idx} className={`flex flex-col gap-2 relative ${!img && 'opacity-20 pointer-events-none'}`}>
                            <div className={`aspect-[3/4] rounded-3xl bg-black overflow-hidden relative border-4 transition-all ${project.selectedIndices.includes(idx) ? 'border-[var(--color-accent)]' : 'border-transparent'}`}>
                                {img && (
                                    <>
                                        <img 
                                            src={`data:${img.mimeType};base64,${img.base64}`} 
                                            className="w-full h-full object-cover transition-all" 
                                            style={{ filter: filterString }}
                                        />
                                        {/* Layer Overlays */}
                                        <div className="absolute inset-0 pointer-events-none overflow-hidden">
                                            {project.layers.map(layer => (
                                                <div 
                                                    key={layer.id}
                                                    style={{
                                                        position: 'absolute',
                                                        left: `${layer.x}%`,
                                                        top: `${layer.y}%`,
                                                        transform: `translate(-50%, -50%) rotate(${layer.rotation}deg)`,
                                                        opacity: layer.opacity,
                                                        width: layer.type === 'image' ? `${layer.width}px` : 'auto',
                                                        zIndex: 10
                                                    }}
                                                >
                                                    {layer.type === 'text' ? (
                                                        <span style={{
                                                            fontSize: `${layer.style?.fontSize}px`,
                                                            fontFamily: layer.style?.fontFamily,
                                                            color: layer.style?.color,
                                                            textShadow: layer.style?.shadow,
                                                            fontWeight: layer.style?.fontWeight as any,
                                                            whiteSpace: 'nowrap'
                                                        }} className="block">{layer.content}</span>
                                                    ) : (
                                                        <img src={`data:image/png;base64,${layer.content}`} className="w-full h-full object-contain" />
                                                    )}
                                                </div>
                                            ))}
                                        </div>
                                    </>
                                )}
                            </div>
                            <div className="flex gap-1">
                                <button onClick={() => img && handleDownload(img, '2k')} className="flex-1 bg-white/5 hover:bg-white/10 text-[10px] font-bold py-2 rounded-xl transition-all">2K</button>
                                <button onClick={() => img && handleDownload(img, '4k')} className="flex-1 bg-[var(--color-accent)] hover:bg-[var(--color-accent-dark)] text-[10px] font-bold py-2 rounded-xl transition-all">4K</button>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            {/* Sidebar Right: Controls & Layers */}
            <div className="lg:w-80 flex flex-col gap-4 overflow-y-auto suggestions-scrollbar pl-2">

                {/* Text Tool Panel */}
                <div className="glass-card rounded-2xl p-5">
                    <div className="flex justify-between items-center mb-4">
                        <h3 className="text-xs font-black text-white/40 uppercase tracking-widest">Text Tools</h3>
                        <button onClick={addTextLayer} className="p-2 bg-[var(--color-accent)] text-white rounded-full hover:scale-110 transition-transform">
                            <TextIcon />
                        </button>
                    </div>
                    {project.layers.find(l => l.type === 'text') && (
                        <div className="space-y-4">
                            <input 
                                type="text"
                                placeholder="Edit selected text..."
                                className="w-full glass-input rounded-xl px-4 py-2 text-sm"
                                onChange={(e) => {
                                    const lastText = project.layers.filter(l => l.type === 'text').pop();
                                    if (lastText) {
                                        setProject(s => ({
                                            ...s,
                                            layers: s.layers.map(l => l.id === lastText.id ? { ...l, content: e.target.value } : l)
                                        }));
                                    }
                                }}
                            />
                            <div className="grid grid-cols-2 gap-2">
                                <select 
                                    className="bg-black/20 border-none rounded-lg text-xs p-2"
                                    onChange={(e) => {
                                        const lastText = project.layers.filter(l => l.type === 'text').pop();
                                        if (lastText) {
                                            setProject(s => ({
                                                ...s,
                                                layers: s.layers.map(l => l.id === lastText.id ? { ...l, style: { ...l.style, fontFamily: e.target.value } } : l)
                                            }));
                                        }
                                    }}
                                >
                                    <optgroup label="Arabic">
                                        {ARABIC_FONTS.map(f => <option key={f} value={f}>{f}</option>)}
                                    </optgroup>
                                    <optgroup label="English">
                                        {ENGLISH_FONTS.map(f => <option key={f} value={f}>{f}</option>)}
                                    </optgroup>
                                </select>
                                <input 
                                    type="color" 
                                    className="w-full h-8 bg-transparent border-none cursor-pointer"
                                    onChange={(e) => {
                                        const lastText = project.layers.filter(l => l.type === 'text').pop();
                                        if (lastText) {
                                            setProject(s => ({
                                                ...s,
                                                layers: s.layers.map(l => l.id === lastText.id ? { ...l, style: { ...l.style, color: e.target.value } } : l)
                                            }));
                                        }
                                    }}
                                />
                            </div>
                            <div className="flex flex-col gap-1">
                                <label className="text-[10px] opacity-40 uppercase">Text Rotation</label>
                                <input 
                                    type="range" min="-180" max="180" 
                                    className="w-full h-1 accent-[var(--color-accent)]"
                                    onChange={(e) => {
                                        const lastText = project.layers.filter(l => l.type === 'text').pop();
                                        if (lastText) {
                                            setProject(s => ({
                                                ...s,
                                                layers: s.layers.map(l => l.id === lastText.id ? { ...l, rotation: parseInt(e.target.value) } : l)
                                            }));
                                        }
                                    }}
                                />
                            </div>
                        </div>
                    )}
                </div>

                {/* Adjustments Panel */}
                <div className="glass-card rounded-2xl p-5">
                    <h3 className="text-xs font-black text-white/40 uppercase tracking-widest mb-4">Adjustments</h3>
                    <div className="space-y-4">
                        {[
                            { label: 'Brightness', field: 'brightness' as keyof EditAdjustments, min: 0, max: 200 },
                            { label: 'Contrast', field: 'contrast' as keyof EditAdjustments, min: 0, max: 200 },
                            { label: 'Saturation', field: 'saturation' as keyof EditAdjustments, min: 0, max: 200 },
                            { label: 'Blur', field: 'blur' as keyof EditAdjustments, min: 0, max: 10 },
                            { label: 'Hue Rotate', field: 'hue' as keyof EditAdjustments, min: 0, max: 360 },
                        ].map(adj => (
                            <div key={adj.field} className="flex flex-col gap-1">
                                <div className="flex justify-between text-[10px] font-bold">
                                    <span className="opacity-40 uppercase">{adj.label}</span>
                                    <span>{project.adjustments[adj.field]}</span>
                                </div>
                                <input 
                                    type="range" min={adj.min} max={adj.max} 
                                    value={project.adjustments[adj.field]}
                                    onChange={(e) => updateAdjustment(adj.field, parseInt(e.target.value))}
                                    className="w-full h-1 accent-[var(--color-accent)] appearance-none bg-white/10 rounded-full"
                                />
                            </div>
                        ))}
                    </div>
                </div>

                {/* Layers Panel */}
                <div className="glass-card rounded-2xl p-5 flex-grow">
                    <h3 className="text-xs font-black text-white/40 uppercase tracking-widest mb-4">Active Layers</h3>
                    <div className="space-y-2">
                        {project.layers.map(layer => (
                            <div key={layer.id} className="flex items-center gap-3 bg-white/5 p-2 rounded-xl group">
                                <div className="w-8 h-8 rounded bg-black/40 flex items-center justify-center">
                                    {layer.type === 'text' ? <TextIcon /> : <img src={`data:image/png;base64,${layer.content}`} className="w-full h-full object-contain" />}
                                </div>
                                <div className="flex-grow truncate text-xs font-bold">
                                    {layer.type === 'text' ? layer.content : 'Image Layer'}
                                </div>
                                <button 
                                    onClick={() => setProject(s => ({ ...s, layers: s.layers.filter(l => l.id !== layer.id) }))}
                                    className="opacity-0 group-hover:opacity-100 text-red-400 hover:scale-110 transition-all"
                                >
                                    <TrashIcon />
                                </button>
                            </div>
                        ))}
                        {project.layers.length === 0 && <p className="text-center text-[10px] opacity-20 py-4 italic">No layers added yet</p>}
                    </div>
                </div>
            </div>
        </main>
    );
};

