import React, { useState, useEffect } from 'react';
import { EditStudioProject, ImageFile, EditAdjustments, LocalText } from '../types';
import { resizeImage } from '../utils';

const ARABIC_FONTS = ['Cairo', 'Tajawal', 'Amiri', 'Reem Kufi', 'Lateef'];
const ENGLISH_FONTS = ['Montserrat', 'Bebas Neue', 'Playfair Display', 'Oswald', 'Rubik'];

const TrashIcon = () => <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>;
const PlusIcon = () => <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>;
const TextIcon = () => <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h7" /></svg>;
const DownloadIcon = () => <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>;

const DEFAULT_TEXT: LocalText = {
    content: 'اضغط للتعديل',
    fontSize: 28,
    color: '#ffffff',
    fontFamily: 'Cairo',
    x: 50,
    y: 80,
    isVisible: true,
    rotation: 0
};

const EditStudio: React.FC<{
    project: EditStudioProject;
    setProject: React.Dispatch<React.SetStateAction<EditStudioProject>>;
}> = ({ project, setProject }) => {

    const [isDownloading, setIsDownloading] = useState<string | null>(null);

    const handleUpload = async (files: File[]) => {
        if (!files || files.length === 0) return;
        setProject(s => ({ ...s, isUploading: true }));
        try {
            const uploaded = await Promise.all(files.map(async file => {
                const resized = await resizeImage(file, 2048, 2048);
                const reader = new FileReader();
                return new Promise<ImageFile>(res => {
                    reader.onloadend = () => res({ base64: (reader.result as string).split(',')[1], mimeType: resized.type, name: resized.name });
                    reader.readAsDataURL(resized);
                });
            }));

            setProject(s => {
                const newBase = [...s.baseImages];
                let upIdx = 0;
                for (let i = 0; i < 6 && upIdx < uploaded.length; i++) {
                    if (!newBase[i]) {
                        newBase[i] = uploaded[upIdx];
                        upIdx++;
                    }
                }
                return { ...s, baseImages: newBase, isUploading: false };
            });
        } catch (err) {
            setProject(s => ({ ...s, isUploading: false, error: "Upload failed" }));
        }
    };

    const updateAdjustment = (field: keyof EditAdjustments, value: number) => {
        setProject(s => ({ ...s, adjustments: { ...s.adjustments, [field]: value } }));
    };

    const updateLocalText = (idx: number, updates: Partial<LocalText>) => {
        setProject(s => ({
            ...s,
            localTexts: {
                ...s.localTexts,
                [idx]: { ...(s.localTexts[idx] || DEFAULT_TEXT), ...updates }
            }
        }));
    };

    const toggleText = (idx: number) => {
        const current = project.localTexts[idx];
        if (current) {
            updateLocalText(idx, { isVisible: !current.isVisible });
        } else {
            setProject(s => ({
                ...s,
                localTexts: { ...s.localTexts, [idx]: { ...DEFAULT_TEXT, isVisible: true } }
            }));
        }
    };

    const handleDownload = (idx: number, resolution: '2k' | '4k') => {
        const imgFile = project.baseImages[idx];
        if (!imgFile) return;

        setIsDownloading(`${idx}-${resolution}`);
        const img = new Image();
        img.src = `data:${imgFile.mimeType};base64,${imgFile.base64}`;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const ctx = canvas.getContext('2d');
            if (!ctx) return;

            const targetWidth = resolution === '4k' ? 4096 : 2048;
            canvas.width = targetWidth;
            canvas.height = targetWidth * (img.height / img.width);

            // Apply Adjustments
            ctx.filter = `brightness(${project.adjustments.brightness}%) contrast(${project.adjustments.contrast}%) saturate(${project.adjustments.saturation}%) hue-rotate(${project.adjustments.hue}deg)`;
            ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
            ctx.filter = 'none';

            // Add Text Layer
            const text = project.localTexts[idx];
            if (text && text.isVisible) {
                const scale = canvas.width / 1000; // Relative sizing
                ctx.save();
                ctx.translate((text.x / 100) * canvas.width, (text.y / 100) * canvas.height);
                ctx.rotate((text.rotation * Math.PI) / 180);
                ctx.fillStyle = text.color;
                ctx.font = `${text.fontSize * scale}px ${text.fontFamily}`;
                ctx.textAlign = 'center';
                ctx.fillText(text.content, 0, 0);
                ctx.restore();
            }

            const link = document.createElement('a');
            link.download = `Jenta-Edit-${idx + 1}-${resolution}.png`;
            link.href = canvas.toDataURL('image/png');
            link.click();
            setIsDownloading(null);
        };
    };

    const filterStyle = {
        filter: `brightness(${project.adjustments.brightness}%) contrast(${project.adjustments.contrast}%) saturate(${project.adjustments.saturation}%) hue-rotate(${project.adjustments.hue}deg)`
    };

    return (
        <main className="w-full flex flex-col lg:flex-row gap-6 pt-4 pb-20 animate-in fade-in duration-500">

            {/* Right Panel: Batch Adjustments (Control Panel) */}
            <div className="lg:w-80 lg:order-2 space-y-6">
                <div className="glass-card rounded-[2rem] p-6 shadow-xl border border-white/5 sticky top-20">
                    <h2 className="text-xs font-black text-white/30 uppercase tracking-[0.2em] mb-6 flex items-center gap-2">
                        <div className="w-1.5 h-1.5 bg-[var(--color-accent)] rounded-full"></div> Batch Adjustments
                    </h2>

                    <div className="space-y-6">
                        {[
                            { label: 'Brightness', field: 'brightness' as keyof EditAdjustments, min: 0, max: 200 },
                            { label: 'Contrast', field: 'contrast' as keyof EditAdjustments, min: 0, max: 200 },
                            { label: 'Saturation', field: 'saturation' as keyof EditAdjustments, min: 0, max: 200 },
                            { label: 'Hue', field: 'hue' as keyof EditAdjustments, min: -180, max: 180 },
                        ].map(adj => (
                            <div key={adj.field} className="flex flex-col gap-2">
                                <div className="flex justify-between items-center text-[10px] font-bold px-1">
                                    <span className="text-white/40 uppercase tracking-widest">{adj.label}</span>
                                    <span className="text-[var(--color-accent)]">{project.adjustments[adj.field]}</span>
                                </div>
                                <input 
                                    type="range" min={adj.min} max={adj.max} 
                                    value={project.adjustments[adj.field]}
                                    onChange={(e) => updateAdjustment(adj.field, parseInt(e.target.value))}
                                    className="w-full h-1 bg-white/5 rounded-full appearance-none accent-[var(--color-accent)]"
                                />
                            </div>
                        ))}
                    </div>

                    <div className="mt-8 pt-6 border-t border-white/5">
                        <label className="w-full h-14 bg-[rgba(var(--color-accent-rgb),0.1)] hover:bg-[rgba(var(--color-accent-rgb),0.15)] border border-[rgba(var(--color-accent-rgb),0.2)] rounded-2xl flex items-center justify-center cursor-pointer transition-all gap-3 group">
                            <PlusIcon />
                            <span className="text-xs font-black text-white group-hover:tracking-widest transition-all uppercase">Batch Import</span>
                            <input type="file" multiple className="hidden" accept="image/*" onChange={(e) => handleUpload(Array.from(e.target.files || []))} />
                        </label>
                        <p className="text-[9px] text-center text-white/20 mt-3 font-medium uppercase tracking-tighter">Support up to 6 images at once</p>
                    </div>
                </div>
            </div>

            {/* Left/Center Area: The Grid */}
            <div className="flex-grow lg:order-1">
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {project.baseImages.map((img, idx) => (
                        <div key={idx} className={`flex flex-col gap-3 group/card relative ${!img && 'opacity-20'}`}>
                            {/* The Card Container */}
                            <div className="glass-card rounded-[2.5rem] overflow-hidden aspect-[3/4] relative bg-black/20 shadow-2xl border border-white/5 group-hover/card:border-[var(--color-accent)]/30 transition-all duration-500">
                                {img ? (
                                    <>
                                        <img 
                                            src={`data:${img.mimeType};base64,${img.base64}`} 
                                            className="w-full h-full object-cover select-none pointer-events-none transition-all duration-700" 
                                            style={filterStyle}
                                        />

                                        {/* Text Layer (Optional) */}
                                        {project.localTexts[idx]?.isVisible && (
                                            <div 
                                                className="absolute inset-0 flex items-center justify-center pointer-events-none overflow-hidden"
                                                style={{ zIndex: 10 }}
                                            >
                                                <div 
                                                    style={{
                                                        position: 'absolute',
                                                        left: `${project.localTexts[idx].x}%`,
                                                        top: `${project.localTexts[idx].y}%`,
                                                        transform: `translate(-50%, -50%) rotate(${project.localTexts[idx].rotation}deg)`,
                                                        color: project.localTexts[idx].color,
                                                        fontSize: `${project.localTexts[idx].fontSize}px`,
                                                        fontFamily: project.localTexts[idx].fontFamily,
                                                        textAlign: 'center',
                                                        textShadow: '0 4px 12px rgba(0,0,0,0.5)',
                                                        pointerEvents: 'auto'
                                                    }}
                                                    className="px-4 py-2 border-2 border-transparent hover:border-white/20 rounded-lg cursor-move select-none"
                                                >
                                                    {project.localTexts[idx].content}
                                                </div>
                                            </div>
                                        )}

                                        {/* Overlay Local Controls (Shown on hover) */}
                                        <div className="absolute inset-x-0 bottom-0 p-6 bg-gradient-to-t from-black/80 to-transparent translate-y-full group-hover/card:translate-y-0 transition-transform duration-500">
                                            <div className="flex flex-col gap-4">
                                                {/* Text Input Row */}
                                                <div className="flex gap-2">
                                                    <input 
                                                        type="text" 
                                                        value={project.localTexts[idx]?.content || ''}
                                                        onChange={(e) => updateLocalText(idx, { content: e.target.value, isVisible: true })}
