const DEFAULT_TEXT: LocalText = {
    content: 'اضغط للتعديل',
    fontSize: 28,
    color: '#ffffff',
    fontFamily: 'Cairo',
    x: 50,
    y: 80,
    isVisible: true,
    rotation: 0
