                                    <div className="relative group/asset aspect-square w-20 h-20 rounded-xl overflow-hidden bg-black/40 border border-white/10 mx-auto">
                                        <img src={`data:${project.globalAsset.mimeType};base64,${project.globalAsset.base64}`} className="w-full h-full object-contain" />
                                        <button 
                                            onClick={() => setProject(s => ({ ...s, globalAsset: null }))}
