const DEFAULT_TEXT: LocalText = {
    content: 'اضغط للتعديل',
    fontSize: 40,
    color: '#ffffff',
    fontFamily: 'Cairo',
    x: 50,
    y: 80,
    isVisible: true,
    rotation: 0
};

const EditStudio: React.FC<{
    project: EditStudioProject;
    setProject: React.Dispatch<React.SetStateAction<EditStudioProject>>;
}> = ({ project, setProject }) => {

    const [isDownloading, setIsDownloading] = useState<string | null>(null);
    const [draggingIdx, setDraggingIdx] = useState<number | null>(null);
    const [selectedLayerId, setSelectedLayerId] = useState<string | null>(null);
    const containerRefs = useRef<(HTMLDivElement | null)[]>([]);

    const handleUpload = async (files: File[]) => {
        if (!files || files.length === 0) return;
        setProject(s => ({ ...s, isUploading: true }));
        try {
            const uploaded = await Promise.all(files.map(async file => {
                const resized = await resizeImage(file, 2048, 2048);
                const reader = new FileReader();
                return new Promise<ImageFile>(res => {
                    reader.onloadend = () => res({ base64: (reader.result as string).split(',')[1], mimeType: resized.type, name: resized.name });
                    reader.readAsDataURL(resized);
                });
            }));

            setProject(s => {
                const newBase = [...s.baseImages];
                let upIdx = 0;
                for (let i = 0; i < 6 && upIdx < uploaded.length; i++) {
                    if (!newBase[i]) {
                        newBase[i] = uploaded[upIdx];
                        upIdx++;
                    }
                }
                return { ...s, baseImages: newBase, isUploading: false };
            });
        } catch (err) {
            setProject(s => ({ ...s, isUploading: false, error: "Upload failed" }));
        }
    };

    const handleGlobalAssetUpload = async (files: File[]) => {
        if (!files || files.length === 0) return;
        try {
            const uploaded = await Promise.all(files.map(async file => {
                const resized = await resizeImage(file, 1024, 1024);
                const reader = new FileReader();
                return new Promise<GlobalLayer>(res => {
                    reader.onloadend = () => {
                        const base64 = (reader.result as string).split(',')[1];
                        res({ 
                            id: Math.random().toString(36).substr(2, 9),
                            file: { base64, mimeType: resized.type, name: resized.name },
                            scale: 20,
                            x: 50,
                            y: 50
                        });
                    };
                    reader.readAsDataURL(resized);
                });
            }));

            setProject(s => {
                const newList = [...s.globalLayers, ...uploaded];
                if (!selectedLayerId && newList.length > 0) {
                    setSelectedLayerId(newList[newList.length - 1].id);
                }
                return { ...s, globalLayers: newList };
            });
        } catch (err) { console.error(err); }
    };

    const removeLayer = (id: string) => {
        setProject(s => {
            const newList = s.globalLayers.filter(l => l.id !== id);
            if (selectedLayerId === id) {
                setSelectedLayerId(newList.length > 0 ? newList[0].id : null);
            }
            return { ...s, globalLayers: newList };
        });
    };

    const updateLayer = (id: string, updates: Partial<GlobalLayer>) => {
        setProject(s => ({
            ...s,
            globalLayers: s.globalLayers.map(l => l.id === id ? { ...l, ...updates } : l)
        }));
    };

    const updateAdjustment = (field: keyof EditAdjustments, value: any) => {
        setProject(s => ({ ...s, adjustments: { ...s.adjustments, [field]: value } }));
    };

    const updateLocalText = (idx: number, updates: Partial<LocalText>) => {
        setProject(s => ({
            ...s,
            localTexts: {
                ...s.localTexts,
                [idx]: { ...(s.localTexts[idx] || DEFAULT_TEXT), ...updates }
            }
        }));
    };

    const toggleText = (idx: number) => {
        const current = project.localTexts[idx];
        if (current) {
            updateLocalText(idx, { isVisible: !current.isVisible });
        } else {
            setProject(s => ({
                ...s,
                localTexts: { ...s.localTexts, [idx]: { ...DEFAULT_TEXT, isVisible: true } }
            }));
        }
    };

    const handleTextPointerDown = (e: React.PointerEvent, idx: number) => {
        e.stopPropagation();
        setDraggingIdx(idx);
        (e.target as HTMLElement).setPointerCapture(e.pointerId);
    };

    const handleTextPointerMove = (e: React.PointerEvent, idx: number) => {
        if (draggingIdx !== idx) return;
        const container = containerRefs.current[idx];
        if (!container) return;

        const rect = container.getBoundingClientRect();
        const x = ((e.clientX - rect.left) / rect.width) * 100;
        const y = ((e.clientY - rect.top) / rect.height) * 100;

        updateLocalText(idx, { x: Math.max(0, Math.min(100, x)), y: Math.max(0, Math.min(100, y)) });
    };

    const handleTextPointerUp = (e: React.PointerEvent) => {
        setDraggingIdx(null);
    };

    const handleDownload = (idx: number, resolution: '2k' | '4k') => {
        const imgFile = project.baseImages[idx];
        const container = containerRefs.current[idx];
        if (!imgFile || !container) return;

        setIsDownloading(`${idx}-${resolution}`);
        const img = new Image();
        img.src = `data:${imgFile.mimeType};base64,${imgFile.base64}`;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const ctx = canvas.getContext('2d');
            if (!ctx) return;

            const targetWidth = resolution === '4k' ? 4096 : 2048;
            canvas.width = targetWidth;
            canvas.height = targetWidth * (img.height / img.width);

            const previewWidth = container.offsetWidth;
            const scaleMultiplier = targetWidth / previewWidth;

            // 1. Base Image
            const activeLut = LUTS.find(l => l.name === project.adjustments.lut);
            const sharpness = project.adjustments.sharpness / 100;
            ctx.filter = `${activeLut?.filter || ''} contrast(${1 + (sharpness - 1) * 0.2}) brightness(${1 + (sharpness - 1) * 0.05})`;
            ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
            ctx.filter = 'none';

            // 2. Global Layers (All of them)
            const renderLayers = async () => {
                for (const layer of project.globalLayers) {
                    await new Promise<void>(resolve => {
                        const lImg = new Image();
                        lImg.src = `data:${layer.file.mimeType};base64,${layer.file.base64}`;
                        lImg.onload = () => {
                            const scale = (layer.scale / 100) * canvas.width;
                            const aspect = lImg.width / lImg.height;
                            const drawW = scale;
                            const drawH = scale / aspect;
                            ctx.drawImage(lImg, (layer.x / 100) * canvas.width - drawW/2, (layer.y / 100) * canvas.height - drawH/2, drawW, drawH);
                            resolve();
                        };
                    });
                }
                finishRendering();
            };

            const finishRendering = () => {
                // 3. Local Text
                const text = project.localTexts[idx];
                if (text && text.isVisible) {
                    ctx.save();
                    ctx.translate((text.x / 100) * canvas.width, (text.y / 100) * canvas.height);
                    ctx.rotate((text.rotation * Math.PI) / 180);
                    ctx.fillStyle = text.color;
                    const scaledFontSize = text.fontSize * scaleMultiplier;
                    ctx.font = `bold ${scaledFontSize}px ${text.fontFamily}`;
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';
                    ctx.shadowColor = 'rgba(0,0,0,0.5)';
                    ctx.shadowBlur = 10 * (scaleMultiplier * (previewWidth / 1000));
                    ctx.shadowOffsetY = 4 * (scaleMultiplier * (previewWidth / 1000));
                    ctx.fillText(text.content, 0, 0);
                    ctx.restore();
                }

                const link = document.createElement('a');
                link.download = `Jenta-Edit-${idx + 1}-${resolution}.png`;
                link.href = canvas.toDataURL('image/png');
                link.click();
                setIsDownloading(null);
            };

            renderLayers();
        };
    };

    const activeLut = LUTS.find(l => l.name === project.adjustments.lut);
    const sharpness = project.adjustments.sharpness / 100;
    const filterStyle = {
        filter: `${activeLut?.filter || ''} contrast(${1 + (sharpness - 1) * 0.2}) brightness(${1 + (sharpness - 1) * 0.05})`
    };

    const selectedLayer = project.globalLayers.find(l => l.id === selectedLayerId);

    return (
        <main className="w-full flex flex-col lg:flex-row gap-6 pt-4 pb-20 animate-in fade-in duration-500">

            {/* Sidebar Controls */}
            <div className="lg:w-80 lg:order-2 space-y-6">
                <div className="glass-card rounded-[2rem] p-6 shadow-xl border border-white/5 sticky top-20">
                    <h2 className="text-xs font-black text-white/30 uppercase tracking-[0.2em] mb-6 flex items-center gap-2">
                        <div className="w-1.5 h-1.5 bg-[var(--color-accent)] rounded-full"></div> Studio Controls
                    </h2>

                    <div className="space-y-6">
                        <div className="pb-6 border-b border-white/5">
                            <label className="w-full h-14 bg-[rgba(var(--color-accent-rgb),0.1)] hover:bg-[rgba(var(--color-accent-rgb),0.15)] border border-[rgba(var(--color-accent-rgb),0.2)] rounded-2xl flex flex-col items-center justify-center cursor-pointer transition-all group">
                                <div className="flex items-center gap-2">
                                    <PlusIcon />
                                    <span className="text-xs font-black text-white group-hover:tracking-widest transition-all uppercase">UPLOAD BATCH</span>
                                </div>
                                <span className="text-[8px] opacity-40 font-bold mt-1 tracking-tighter">(Up to 6 images)</span>
                                <input type="file" multiple className="hidden" accept="image/*" onChange={(e) => handleUpload(Array.from(e.target.files || []))} />
                            </label>
                        </div>

                        <div className="flex flex-col gap-2">
                             <label className="text-[10px] font-bold text-white/40 uppercase tracking-widest ml-1">Color Style (LUT)</label>
                             <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto suggestions-scrollbar">
                                 {LUTS.map(lut => (
                                     <button 
                                        key={lut.name}
                                        onClick={() => updateAdjustment('lut', lut.name)}
                                        className={`px-2 py-2.5 rounded-xl text-[10px] font-bold transition-all border ${project.adjustments.lut === lut.name ? 'bg-[var(--color-accent)] border-[var(--color-accent)] text-white shadow-lg' : 'bg-white/5 border-white/5 text-white/50 hover:border-white/20'}`}
                                     >
                                         {lut.name}
                                     </button>
                                 ))}
                             </div>
                        </div>

                        <div className="flex flex-col gap-2">
                            <div className="flex justify-between items-center text-[10px] font-bold px-1">
                                <span className="text-white/40 uppercase tracking-widest">Global Sharpness</span>
                                <span className="text-[var(--color-accent)]">{project.adjustments.sharpness}%</span>
                            </div>
                            <input 
                                type="range" min="0" max="200" 
                                value={project.adjustments.sharpness}
                                onChange={(e) => updateAdjustment('sharpness', parseInt(e.target.value))}
                                className="w-full h-1 bg-white/5 rounded-full appearance-none accent-[var(--color-accent)]"
                            />
                        </div>

                        <div className="pt-4 border-t border-white/5">
                            <label className="text-[10px] font-bold text-white/40 uppercase tracking-widest ml-1 mb-2 block">Global Layers</label>

                            {/* Layers List */}
                            <div className="flex flex-wrap gap-2 mb-4">
                                {project.globalLayers.map((layer) => (
                                    <div key={layer.id} className="relative group/l">
                                        <div 
                                            onClick={() => setSelectedLayerId(layer.id)}
                                            className={`w-12 h-12 rounded-lg border-2 overflow-hidden cursor-pointer transition-all ${selectedLayerId === layer.id ? 'border-[var(--color-accent)] scale-110 shadow-lg' : 'border-white/10 opacity-60 hover:opacity-100'}`}
                                        >
                                            <img src={`data:${layer.file.mimeType};base64,${layer.file.base64}`} className="w-full h-full object-contain bg-black/20" />
                                        </div>
                                        <button 
                                            onClick={(e) => { e.stopPropagation(); removeLayer(layer.id); }}
                                            className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full p-0.5 opacity-0 group-hover/l:opacity-100 transition-opacity shadow-lg"
                                        >
                                            <XIcon />
                                        </button>
                                    </div>
                                ))}
                                <label className="w-12 h-12 rounded-lg border-2 border-dashed border-white/10 hover:border-white/30 flex items-center justify-center cursor-pointer transition-all">
                                    <PlusIcon />
                                    <input type="file" multiple className="hidden" accept="image/*" onChange={(e) => handleGlobalAssetUpload(Array.from(e.target.files || []))} />
                                </label>
                            </div>

                            {selectedLayer ? (
                                <div className="space-y-3 animate-in fade-in slide-in-from-top-1 duration-300">
                                    <div className="flex flex-col gap-1">
                                        <label className="text-[8px] font-black text-white/30 uppercase">Layer Scale ({selectedLayer.scale}%)</label>
                                        <input type="range" min="5" max="100" value={selectedLayer.scale} onChange={e => updateLayer(selectedLayer.id, { scale: parseInt(e.target.value) })} className="w-full h-1 bg-white/5 rounded-full appearance-none accent-white" />
                                    </div>
                                    <div className="grid grid-cols-2 gap-2">
                                        <div className="flex flex-col gap-1">
                                            <label className="text-[8px] font-black text-white/30 uppercase">X Position</label>
                                            <input type="range" min="0" max="100" value={selectedLayer.x} onChange={e => updateLayer(selectedLayer.id, { x: parseInt(e.target.value) })} className="w-full h-1 bg-white/5 rounded-full appearance-none accent-white" />
                                        </div>
                                        <div className="flex flex-col gap-1">
                                            <label className="text-[8px] font-black text-white/30 uppercase">Y Position</label>
                                            <input type="range" min="0" max="100" value={selectedLayer.y} onChange={e => updateLayer(selectedLayer.id, { y: parseInt(e.target.value) })} className="w-full h-1 bg-white/5 rounded-full appearance-none accent-white" />
                                        </div>
                                    </div>
                                </div>
                            ) : (
                                <p className="text-[9px] text-white/20 italic">Upload or select a layer to adjust</p>
                            )}
                        </div>
                    </div>
                </div>
            </div>

            {/* Grid Area */}
            <div className="flex-grow lg:order-1">
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {project.baseImages.map((img, idx) => (
                        <div key={idx} className={`flex flex-col gap-3 group/card relative ${!img && 'opacity-20'}`}>

                            <div 
                                ref={el => containerRefs.current[idx] = el}
                                className="glass-card rounded-[2.5rem] overflow-hidden aspect-[3/4] relative bg-black/20 shadow-2xl border border-white/5 group-hover/card:border-[var(--color-accent)]/30 transition-all duration-500 cursor-default"
                            >
                                {img ? (
                                    <>
                                        <img 
                                            src={`data:${img.mimeType};base64,${img.base64}`} 
                                            className="w-full h-full object-cover select-none pointer-events-none" 
                                            style={filterStyle}
                                        />

                                        {/* Render All Global Layers */}
                                        {project.globalLayers.map((layer) => (
                                            <div 
                                                key={layer.id}
                                                style={{
                                                    position: 'absolute',
                                                    left: `${layer.x}%`,
                                                    top: `${layer.y}%`,
                                                    width: `${layer.scale}%`,
                                                    transform: 'translate(-50%, -50%)',
                                                    pointerEvents: 'none',
                                                    zIndex: 5
                                                }}
                                            >
                                                <img src={`data:${layer.file.mimeType};base64,${layer.file.base64}`} className="w-full h-auto drop-shadow-xl" />
                                            </div>
                                        ))}

                                        {/* Tappable/Draggable Text Layer */}
                                        {project.localTexts[idx]?.isVisible && (
                                            <div 
                                                style={{
                                                    position: 'absolute',
                                                    left: `${project.localTexts[idx].x}%`,
                                                    top: `${project.localTexts[idx].y}%`,
                                                    transform: `translate(-50%, -50%) rotate(${project.localTexts[idx].rotation}deg)`,
                                                    color: project.localTexts[idx].color,
                                                    fontSize: `${project.localTexts[idx].fontSize}px`,
                                                    fontFamily: project.localTexts[idx].fontFamily,
                                                    textAlign: 'center',
                                                    textShadow: '0 4px 12px rgba(0,0,0,0.5)',
                                                    zIndex: 10,
                                                    fontWeight: 'bold',
                                                    whiteSpace: 'nowrap',
                                                    touchAction: 'none'
                                                }}
                                                onPointerDown={(e) => handleTextPointerDown(e, idx)}
                                                onPointerMove={(e) => handleTextPointerMove(e, idx)}
                                                onPointerUp={handleTextPointerUp}
                                                className={`px-4 py-2 border-2 rounded-lg cursor-move select-none transition-border ${draggingIdx === idx ? 'border-[var(--color-accent)]' : 'border-transparent hover:border-white/20'}`}
                                            >
                                                {project.localTexts[idx].content}
                                            </div>
                                        )}

                                        {/* Bottom Controls Overlay */}
                                        <div className="absolute inset-x-0 bottom-0 p-5 bg-gradient-to-t from-black/90 via-black/40 to-transparent translate-y-full group-hover/card:translate-y-0 transition-transform duration-500">
                                            <div className="flex flex-col gap-3">
                                                <div className="flex gap-2">
                                                    <input 
                                                        type="text" 
                                                        value={project.localTexts[idx]?.content || ''}
                                                        onChange={(e) => updateLocalText(idx, { content: e.target.value, isVisible: true })}
                                                        placeholder="Edit text..."
                                                        className="flex-grow bg-white/10 border border-white/10 rounded-xl px-4 py-2 text-xs text-white focus:outline-none focus:border-[var(--color-accent)]"
                                                    />
                                                    <button 
                                                        onClick={() => toggleText(idx)}
                                                        className={`p-2 rounded-xl transition-all ${project.localTexts[idx]?.isVisible ? 'bg-[var(--color-accent)] text-white' : 'bg-white/10 text-white/40'}`}
                                                    >
                                                        <TextIcon />
                                                    </button>
                                                </div>

                                                <div className="grid grid-cols-2 gap-3">
                                                    <div className="space-y-1">
                                                        <label className="text-[8px] font-black text-white/30 uppercase ml-1 tracking-tighter">Font Style</label>
                                                        <select 
                                                            value={project.localTexts[idx]?.fontFamily || 'Cairo'}
                                                            onChange={(e) => updateLocalText(idx, { fontFamily: e.target.value })}
                                                            className="w-full bg-black/40 border border-white/10 rounded-lg text-[10px] p-1 text-white"
                                                        >
                                                            <optgroup label="Arabic" className="bg-gray-900">
                                                                {ARABIC_FONTS.map(f => <option key={f} value={f}>{f}</option>)}
                                                            </optgroup>
                                                            <optgroup label="English" className="bg-gray-900">
                                                                {ENGLISH_FONTS.map(f => <option key={f} value={f}>{f}</option>)}
                                                            </optgroup>
                                                        </select>
                                                    </div>
                                                    <div className="space-y-1">
                                                        <label className="text-[8px] font-black text-white/30 uppercase ml-1 tracking-tighter">Color</label>
                                                        <div className="flex items-center gap-2 bg-black/40 border border-white/10 rounded-lg p-1">
                                                            <input 
                                                                type="color" 
                                                                value={project.localTexts[idx]?.color || '#ffffff'} 
                                                                onChange={(e) => updateLocalText(idx, { color: e.target.value })}
                                                                className="w-full h-4 bg-transparent border-none cursor-pointer"
                                                            />
                                                        </div>
                                                    </div>
                                                    <div className="space-y-1">
                                                        <label className="text-[8px] font-black text-white/30 uppercase ml-1 tracking-tighter">Size ({project.localTexts[idx]?.fontSize || 40}px)</label>
                                                        <input type="range" min="10" max="200" value={project.localTexts[idx]?.fontSize || 40} onChange={(e) => updateLocalText(idx, { fontSize: parseInt(e.target.value) })} className="w-full h-1 bg-white/10 rounded-full appearance-none accent-white" />
                                                    </div>
                                                    <div className="space-y-1">
                                                        <label className="text-[8px] font-black text-white/30 uppercase ml-1 tracking-tighter">Rotate</label>
                                                        <input type="range" min="-180" max="180" value={project.localTexts[idx]?.rotation || 0} onChange={(e) => updateLocalText(idx, { rotation: parseInt(e.target.value) })} className="w-full h-1 bg-white/10 rounded-full appearance-none accent-white" />
                                                    </div>
                                                </div>

                                                <button 
                                                    onClick={() => handleDownload(idx, '4k')}
                                                    disabled={isDownloading !== null}
                                                    className="w-full bg-[var(--color-accent)] hover:bg-[var(--color-accent-dark)] text-white font-black py-2 rounded-xl text-[10px] uppercase tracking-widest shadow-lg flex items-center justify-center gap-1 transition-all"
                                                >
                                                    {isDownloading === `${idx}-4k` ? 'Saving...' : <><SaveIcon /> Final Save</>}
                                                </button>
                                            </div>
                                        </div>

                                        <div className="absolute top-4 left-4 bg-black/60 backdrop-blur-md px-3 py-1 rounded-full text-[10px] font-black text-white/80 border border-white/10">
                                            {project.adjustments.lut !== 'Original' ? project.adjustments.lut : `SLOT 0${idx + 1}`}
                                        </div>
                                    </>
                                ) : (
                                    <div className="w-full h-full flex flex-col items-center justify-center p-8 gap-4 opacity-30">
                                        <div className="w-12 h-12 rounded-full border-2 border-dashed border-white/20 flex items-center justify-center">
                                            <PlusIcon />
                                        </div>
                                        <span className="text-[10px] font-black uppercase tracking-widest text-center">Empty Slot</span>
                                    </div>
                                )}
                            </div>

                            {/* Export Actions */}
                            {img && (
                                <div className="flex gap-2">
                                    <button onClick={() => handleDownload(idx, '2k')} disabled={isDownloading !== null} className="flex-1 bg-white/5 hover:bg-white/10 border border-white/5 text-[10px] font-black py-2.5 rounded-2xl transition-all text-white/60 flex items-center justify-center gap-1">
                                        <DownloadIcon /> {isDownloading === `${idx}-2k` ? '...' : '2K'}
                                    </button>
                                    <button onClick={() => handleDownload(idx, '4k')} disabled={isDownloading !== null} className="flex-1 bg-[var(--color-accent)] hover:bg-[var(--color-accent-dark)] text-[10px] font-black py-2.5 rounded-2xl transition-all text-white flex items-center justify-center gap-1 shadow-lg shadow-[var(--color-accent)]/20">
                                        <DownloadIcon /> {isDownloading === `${idx}-4k` ? '...' : '4K'}
                                    </button>
                                    <button onClick={() => setProject(s => ({ ...s, baseImages: s.baseImages.map((b, i) => i === idx ? null : b) }))} className="p-2.5 rounded-2xl bg-white/5 text-white/20 hover:text-red-500 hover:bg-red-500/10 transition-all border border-white/5">
                                        <TrashIcon />
                                    </button>
                                </div>
                            )}
                        </div>
                    ))}
                </div>
            </div>

            {project.error && (
                <div className="fixed bottom-10 left-1/2 -translate-x-1/2 z-[100] bg-red-500/90 text-white px-8 py-4 rounded-2xl shadow-2xl backdrop-blur-md animate-in slide-in-from-bottom-4">
                    <p className="text-sm font-bold flex items-center gap-2">
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                        {project.error}
                    </p>
                </div>
            )}
        </main>
    );
};

