                                                    <div className="space-y-1">
                                                        <label className="text-[8px] font-black text-white/30 uppercase ml-1 tracking-tighter">Weight</label>
                                                        <select 
                                                            value={project.localTexts[idx]?.fontWeight || '700'}
                                                            onChange={(e) => updateLocalText(idx, { fontWeight: e.target.value })}
                                                            className="w-full bg-black/40 border border-white/10 rounded-lg text-[10px] p-1 text-white"
                                                        >
                                                            {FONT_WEIGHTS.map(w => <option key={w.value} value={w.value}>{w.label}</option>)}
