                                    </div>
                                ))}
                                <label className="w-10 h-10 rounded-lg border-2 border-dashed border-white/10 flex items-center justify-center cursor-pointer hover:border-white/30 transition-all">
                                    <PlusIcon />
                                    <input type="file" multiple className="hidden" accept="image/*" onChange={(e) => handleGlobalAssetUpload(Array.from(e.target.files || []))} />
                                </label>
                            </div>

                            {selectedLayer && (
                                <div className="space-y-3 p-3 bg-white/5 rounded-xl border border-white/5">
                                    <input type="range" min="5" max="100" value={selectedLayer.scale} onChange={e => setProject(s => ({...s, globalLayers: s.globalLayers.map(l => l.id === selectedLayerId ? {...l, scale: parseInt(e.target.value)} : l)}))} className="w-full h-1 accent-white" />
                                    <div className="grid grid-cols-2 gap-2">
                                        <input type="range" min="0" max="100" value={selectedLayer.x} onChange={e => setProject(s => ({...s, globalLayers: s.globalLayers.map(l => l.id === selectedLayerId ? {...l, x: parseInt(e.target.value)} : l)}))} className="w-full h-1 accent-white" />
                                        <input type="range" min="0" max="100" value={selectedLayer.y} onChange={e => setProject(s => ({...s, globalLayers: s.globalLayers.map(l => l.id === selectedLayerId ? {...l, y: parseInt(e.target.value)} : l)}))} className="w-full h-1 accent-white" />
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>

            {/* Grid Area */}
            <div className="flex-grow lg:order-1">
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {project.baseImages.map((img, idx) => (
                        <div key={idx} className="flex flex-col gap-3">
                            <div 
                                ref={el => containerRefs.current[idx] = el}
                                onClick={() => setActiveSlotIdx(idx)}
                                className={`glass-card rounded-[2.5rem] overflow-hidden aspect-[3/4] relative bg-black/20 shadow-2xl border transition-all duration-500 cursor-pointer ${activeSlotIdx === idx ? 'border-[var(--color-accent)] ring-4 ring-[var(--color-accent)]/20 scale-[1.02]' : 'border-white/5 hover:border-white/20'}`}
                            >
                                {img ? (
                                    <>
                                        <img src={`data:${img.mimeType};base64,${img.base64}`} className="w-full h-full object-cover select-none pointer-events-none" style={filterStyle} />

                                        {/* Overlays */}
                                        {project.globalLayers.map(layer => (
                                            <div key={layer.id} style={{ position: 'absolute', left: `${layer.x}%`, top: `${layer.y}%`, width: `${layer.scale}%`, transform: 'translate(-50%, -50%)', pointerEvents: 'none', zIndex: 5 }}>
                                                <img src={`data:${layer.file.mimeType};base64,${layer.file.base64}`} className="w-full h-auto drop-shadow-2xl" />
                                            </div>
                                        ))}

                                        {/* Local Text */}
                                        {project.localTexts[idx]?.isVisible && (
                                            <div 
                                                style={{
                                                    position: 'absolute', left: `${project.localTexts[idx].x}%`, top: `${project.localTexts[idx].y}%`,
                                                    transform: `translate(-50%, -50%) rotate(${project.localTexts[idx].rotation}deg)`,
                                                    color: project.localTexts[idx].color, fontSize: `${project.localTexts[idx].fontSize}px`,
                                                    fontFamily: project.localTexts[idx].fontFamily, fontWeight: project.localTexts[idx].fontWeight,
                                                    textAlign: 'center', textShadow: '0 4px 12px rgba(0,0,0,0.5)', zIndex: 10,
                                                    whiteSpace: 'pre-wrap', touchAction: 'none', lineHeight: '1.1'
                                                }}
                                                onPointerDown={(e) => { e.stopPropagation(); setDraggingIdx(idx); (e.target as HTMLElement).setPointerCapture(e.pointerId); }}
                                                onPointerMove={(e) => {
                                                    if (draggingIdx !== idx) return;
                                                    const rect = containerRefs.current[idx]!.getBoundingClientRect();
                                                    const x = ((e.clientX - rect.left) / rect.width) * 100;
                                                    const y = ((e.clientY - rect.top) / rect.height) * 100;
                                                    updateLocalText(idx, { x: Math.max(0, Math.min(100, x)), y: Math.max(0, Math.min(100, y)) });
                                                }}
                                                onPointerUp={() => setDraggingIdx(null)}
                                                className={`px-4 py-2 border-2 rounded-lg cursor-move select-none transition-border ${draggingIdx === idx ? 'border-[var(--color-accent)]' : 'border-transparent hover:border-white/20'}`}
                                            >
                                                {project.localTexts[idx].content}
                                            </div>
                                        )}

                                        <div className="absolute top-4 left-4 bg-black/60 backdrop-blur-md px-3 py-1 rounded-full text-[10px] font-black text-white/80 border border-white/10 z-20">
                                            SLOT 0{idx + 1}
                                        </div>
                                    </>
                                ) : (
                                    <div className="w-full h-full flex flex-col items-center justify-center p-8 gap-4 opacity-20 group">
                                        <div className="w-12 h-12 rounded-full border-2 border-dashed border-white flex items-center justify-center group-hover:scale-110 transition-transform">
                                            <PlusIcon />
                                        </div>
                                        <span className="text-[10px] font-black uppercase tracking-widest">Empty Slot</span>
                                    </div>
                                )}
                            </div>

                            {img && (
                                <div className="flex gap-2 animate-in fade-in duration-300">
                                    <button onClick={() => handleDownload(idx, '2k')} disabled={isDownloading !== null} className="flex-1 bg-white/5 hover:bg-white/10 border border-white/5 text-[10px] font-black py-2.5 rounded-2xl transition-all text-white/60 flex items-center justify-center gap-1 uppercase">
                                        <DownloadIcon /> {isDownloading === `${idx}-2k` ? '...' : '2K'}
                                    </button>
                                    <button onClick={() => handleDownload(idx, '4k')} disabled={isDownloading !== null} className="flex-1 bg-[var(--color-accent)] hover:bg-[var(--color-accent-dark)] text-[10px] font-black py-2.5 rounded-2xl transition-all text-white flex items-center justify-center gap-1 shadow-lg shadow-[var(--color-accent)]/20 uppercase">
                                        <SaveIcon /> {isDownloading === `${idx}-4k` ? 'Saving' : '4K'}
                                    </button>
                                    <button onClick={() => setProject(s => ({ ...s, baseImages: s.baseImages.map((b, i) => i === idx ? null : b) }))} className="p-2.5 rounded-2xl bg-white/5 text-white/20 hover:text-red-500 hover:bg-red-500/10 transition-all border border-white/5">
                                        <TrashIcon />
                                    </button>
                                </div>
                            )}
                        </div>
                    ))}
                </div>
            </div>

            {project.error && (
                <div className="fixed bottom-10 left-1/2 -translate-x-1/2 z-[100] bg-red-500/90 text-white px-8 py-4 rounded-2xl shadow-2xl backdrop-blur-md animate-in slide-in-from-bottom-4 flex items-center gap-3">
                    <XIcon />
                    <p className="text-sm font-bold">{project.error}</p>
                </div>
            )}
        </main>
    );
};

