                                className={`glass-card rounded-[3rem] overflow-hidden aspect-[3/4] relative bg-black/20 shadow-2xl border transition-all duration-500 cursor-pointer group/slot ${activeSlotIdx === idx ? 'border-[var(--color-accent)] ring-8 ring-[var(--color-accent)]/10 scale-[1.02]' : 'border-white/5 hover:border-white/10'}`}
