                                    <>
                                        <img src={`data:${img.mimeType};base64,${img.base64}`} className="w-full h-full object-cover select-none pointer-events-none" style={filterStyle} />

                                        {/* Global Overlays */}
                                        {project.globalLayers.map(layer => (
                                            <div key={layer.id} style={{ position: 'absolute', left: `${layer.x}%`, top: `${layer.y}%`, width: `${layer.scale}%`, transform: 'translate(-50%, -50%)', pointerEvents: 'none', zIndex: 5 }}>
                                                <img src={`data:${layer.file.mimeType};base64,${layer.file.base64}`} className="w-full h-auto drop-shadow-2xl" />
                                            </div>
                                        ))}

                                        {/* Multiple Local Text Layers */}
                                        {(project.localTexts[idx] || []).map(text => (
                                            text.isVisible && (
                                                <div 
                                                    key={text.id}
                                                    style={{
                                                        position: 'absolute', left: `${text.x}%`, top: `${text.y}%`,
                                                        transform: `translate(-50%, -50%) rotate(${text.rotation}deg)`,
                                                        color: text.color, fontSize: `${text.fontSize}px`,
                                                        fontFamily: text.fontFamily, fontWeight: text.fontWeight,
                                                        textAlign: 'center', textShadow: '0 4px 16px rgba(0,0,0,0.6)', zIndex: 10,
                                                        whiteSpace: 'pre-wrap', touchAction: 'none', lineHeight: '1.1'
                                                    }}
                                                    onPointerDown={(e) => { 
                                                        e.stopPropagation(); 
                                                        setSelectedTextId(text.id);
                                                        setDraggingId(text.id);
                                                        setDraggingSlot(idx);
                                                        setActiveSlotIdx(idx);
                                                        (e.target as HTMLElement).setPointerCapture(e.pointerId); 
                                                    }}
                                                    onPointerMove={(e) => {
                                                        if (draggingId !== text.id || draggingSlot !== idx) return;
                                                        const rect = containerRefs.current[idx]!.getBoundingClientRect();
                                                        const x = ((e.clientX - rect.left) / rect.width) * 100;
                                                        const y = ((e.clientY - rect.top) / rect.height) * 100;
                                                        updateSlotText(idx, text.id, { x: Math.max(0, Math.min(100, x)), y: Math.max(0, Math.min(100, y)) });
                                                    }}
                                                    onPointerUp={() => { setDraggingId(null); setDraggingSlot(null); }}
                                                    className={`px-6 py-3 border-2 rounded-2xl cursor-move select-none transition-all ${selectedTextId === text.id ? 'border-[var(--color-accent)] bg-[var(--color-accent)]/5 ring-4 ring-[var(--color-accent)]/20' : 'border-transparent hover:border-white/30 hover:bg-white/5'}`}
                                                >
                                                    {text.content}
                                                </div>
                                            )
                                        ))}

                                        <div className="absolute top-6 left-6 bg-black/60 backdrop-blur-xl px-5 py-2 rounded-full text-[10px] font-black text-white/90 border border-white/10 z-20 shadow-xl">
                                            SLOT 0{idx + 1}
                                        </div>

                                        {/* Status Badge */}
                                        <div className={`absolute bottom-6 left-6 px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest backdrop-blur-md transition-all duration-500 border ${activeSlotIdx === idx ? 'bg-[var(--color-accent)] text-white border-[var(--color-accent)] shadow-lg' : 'bg-black/40 text-white/40 border-white/5'}`}>
                                            {activeSlotIdx === idx ? 'Active Focus' : 'Inactive'}
                                        </div>
                                    </>
                                ) : (
                                    <div className="w-full h-full flex flex-col items-center justify-center p-8 gap-4 opacity-30 group transition-all">
                                        <div className="w-16 h-16 rounded-full border-2 border-dashed border-white/40 flex items-center justify-center group-hover:scale-110 group-hover:border-white group-hover:bg-white/5 transition-all duration-500">
                                            <PlusIcon />
                                        </div>
                                        <div className="flex flex-col items-center gap-1">
                                            <span className="text-[10px] font-black uppercase tracking-[0.3em]">Empty Studio</span>
                                        </div>
                                    </div>
                                )}
                            </div>

                            {img && (
                                <div className="flex gap-2 animate-in fade-in duration-500">
                                    <button onClick={() => handleDownload(idx, '2k')} disabled={isDownloading !== null} className="flex-1 bg-white/5 hover:bg-white/10 border border-white/5 text-[9px] font-black py-3 rounded-2xl transition-all text-white/60 flex items-center justify-center gap-2 uppercase tracking-tighter">
                                        <DownloadIcon /> {isDownloading === `${idx}-2k` ? '...' : '2K'}
                                    </button>
                                    <button onClick={() => handleDownload(idx, '4k')} disabled={isDownloading !== null} className="flex-1 bg-[var(--color-accent)] hover:bg-[var(--color-accent-dark)] text-[9px] font-black py-3 rounded-2xl transition-all text-white flex items-center justify-center gap-2 shadow-xl shadow-[var(--color-accent)]/20 uppercase tracking-tighter">
                                        <SaveIcon /> {isDownloading === `${idx}-4k` ? 'Saving' : '4K'}
                                    </button>
                                    <button onClick={() => setProject(s => ({ ...s, baseImages: s.baseImages.map((b, i) => i === idx ? null : b) }))} className="p-3 rounded-2xl bg-white/5 text-white/30 hover:text-red-500 hover:bg-red-500/10 transition-all border border-white/5">
                                        <TrashIcon />
                                    </button>
                                </div>
                            )}
                        </div>
                    ))}
                </div>
            </div>

            {project.error && (
                <div className="fixed bottom-12 left-1/2 -translate-x-1/2 z-[100] bg-red-600/90 text-white px-10 py-4 rounded-3xl shadow-2xl backdrop-blur-xl animate-in slide-in-from-bottom-6 flex items-center gap-4 border border-white/20">
                    <div className="w-6 h-6 rounded-full bg-white/20 flex items-center justify-center"><XIcon /></div>
                    <p className="text-sm font-black tracking-tight">{project.error}</p>
                </div>
            )}
        </main>
    );
};

export default EditStudio;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { EditStudioProject, ImageFile, EditAdjustments, LocalText, GlobalLayer } from '../types';
