);
const TextIcon = () => <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h7" /></svg>;
const DownloadIcon = () => <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>;
const SaveIcon = () => <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M8 7H5a2 2 0 00-2 2v9a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-3m-1 4l-3 3m0 0l-3-3m3 3V4" /></svg>;

const createNewText = (): LocalText => ({
    id: Math.random().toString(36).substr(2, 9),
    content: 'نص جديد',
    fontSize: 40,
    color: '#ffffff',
    fontFamily: 'Cairo',
    fontWeight: '700',
    x: 50,
    y: 50,
    isVisible: true,
    rotation: 0
});

const EditStudio: React.FC<{
    project: EditStudioProject;
    setProject: React.Dispatch<React.SetStateAction<EditStudioProject>>;
}> = ({ project, setProject }) => {

    const [isDownloading, setIsDownloading] = useState<string | null>(null);
    const [draggingId, setDraggingId] = useState<string | null>(null);
    const [draggingSlot, setDraggingSlot] = useState<number | null>(null);
    const [selectedLayerId, setSelectedLayerId] = useState<string | null>(null);
    const [activeSlotIdx, setActiveSlotIdx] = useState<number | null>(null);
    const [selectedTextId, setSelectedTextId] = useState<string | null>(null);
    const [customFonts, setCustomFonts] = useState<string[]>([]);
    const [clipboard, setClipboard] = useState<LocalText | null>(null);
    const containerRefs = useRef<(HTMLDivElement | null)[]>([]);

    const addTextToSlot = useCallback((slotIdx: number, customText?: LocalText) => {
        const newText = customText ? { ...customText, id: Math.random().toString(36).substr(2, 9) } : createNewText();
        setProject(s => {
            const currentTexts = s.localTexts[slotIdx] || [];
            return {
                ...s,
                localTexts: { ...s.localTexts, [slotIdx]: [...currentTexts, newText] }
            };
        });
        setSelectedTextId(newText.id);
        setActiveSlotIdx(slotIdx);
    }, [setProject]);

    const handleCopy = useCallback((textObj: LocalText) => {
        setClipboard({ ...textObj });
    }, []);

    const handlePaste = useCallback((slotIdx: number) => {
        if (clipboard) {
            // Offset slightly to distinguish from original if pasted in same place
            const pastedText = { ...clipboard, x: clipboard.x + 2, y: clipboard.y + 2 };
            addTextToSlot(slotIdx, pastedText);
        }
    }, [clipboard, addTextToSlot]);

    // Keyboard Shortcuts
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            const isTyping = ['INPUT', 'TEXTAREA'].includes((e.target as HTMLElement).tagName);
            if (isTyping && (e.target as HTMLElement).tagName === 'TEXTAREA') return;

            // Copy: Ctrl+C
            if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'c') {
                if (activeSlotIdx !== null && selectedTextId) {
                    const texts = project.localTexts[activeSlotIdx] || [];
                    const toCopy = texts.find(t => t.id === selectedTextId);
                    if (toCopy) handleCopy(toCopy);
                }
            }

            // Paste: Ctrl+V
            if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'v') {
                if (activeSlotIdx !== null && clipboard) {
                    handlePaste(activeSlotIdx);
                }
            }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [activeSlotIdx, selectedTextId, project.localTexts, clipboard, handleCopy, handlePaste]);

    const handleUpload = async (files: File[]) => {
        if (!files || files.length === 0) return;
        setProject(s => ({ ...s, isUploading: true }));
        try {
            const uploaded = await Promise.all(files.map(async file => {
                const resized = await resizeImage(file, 2048, 2048);
                const reader = new FileReader();
                return new Promise<ImageFile>(res => {
                    reader.onloadend = () => res({ base64: (reader.result as string).split(',')[1], mimeType: resized.type, name: resized.name });
                    reader.readAsDataURL(resized);
                });
            }));

            setProject(s => {
                const newBase = [...s.baseImages];
                let upIdx = 0;
                for (let i = 0; i < 6 && upIdx < uploaded.length; i++) {
                    if (!newBase[i]) {
                        newBase[i] = uploaded[upIdx];
                        upIdx++;
                    }
                }
                return { ...s, baseImages: newBase, isUploading: false };
            });
        } catch (err) {
            setProject(s => ({ ...s, isUploading: false, error: "Upload failed" }));
        }
    };

    const handleFontUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const files = Array.from(e.target.files || []) as File[];
        for (const file of files) {
            try {
                const fontName = file.name.split('.')[0];
                const reader = new FileReader();
                reader.onload = async (event) => {
                    const data = event.target?.result;
                    if (data) {
                        const fontFace = new FontFace(fontName, data as ArrayBuffer);
                        const loadedFace = await fontFace.load();
                        document.fonts.add(loadedFace);
                        setCustomFonts(prev => [...new Set([...prev, fontName])]);
                    }
                };
                reader.readAsArrayBuffer(file);
            } catch (err) { console.error(err); }
        }
    };

    const handleGlobalAssetUpload = async (files: File[]) => {
        if (!files || files.length === 0) return;
        try {
            const uploaded = await Promise.all(files.map(async file => {
                const resized = await resizeImage(file, 1024, 1024);
                const reader = new FileReader();
                return new Promise<GlobalLayer>(res => {
                    reader.onloadend = () => {
                        const base64 = (reader.result as string).split(',')[1];
                        res({ 
                            id: Math.random().toString(36).substr(2, 9),
                            file: { base64, mimeType: resized.type, name: resized.name },
                            scale: 20,
                            x: 50,
                            y: 50
                        });
                    };
                    reader.readAsDataURL(resized);
                });
            }));
            setProject(s => ({ ...s, globalLayers: [...s.globalLayers, ...uploaded] }));
        } catch (err) { console.error(err); }
    };

    const updateSlotText = (slotIdx: number, textId: string, updates: Partial<LocalText>) => {
        setProject(s => {
            const texts = s.localTexts[slotIdx] || [];
            const updated = texts.map(t => t.id === textId ? { ...t, ...updates } : t);
            return { ...s, localTexts: { ...s.localTexts, [slotIdx]: updated } };
        });
    };

    const deleteSlotText = (slotIdx: number, textId: string) => {
        setProject(s => {
            const texts = (s.localTexts[slotIdx] || []).filter(t => t.id !== textId);
            return { ...s, localTexts: { ...s.localTexts, [slotIdx]: texts } };
        });
        if (selectedTextId === textId) setSelectedTextId(null);
    };

    const handleDownload = (idx: number, resolution: '2k' | '4k') => {
        const imgFile = project.baseImages[idx];
        const container = containerRefs.current[idx];
        if (!imgFile || !container) return;

        setIsDownloading(`${idx}-${resolution}`);
        const img = new Image();
        img.src = `data:${imgFile.mimeType};base64,${imgFile.base64}`;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const ctx = canvas.getContext('2d');
            if (!ctx) return;
            const targetWidth = resolution === '4k' ? 4096 : 2048;
            canvas.width = targetWidth;
            canvas.height = targetWidth * (img.height / img.width);
            const previewWidth = container.offsetWidth;
            const scaleMultiplier = targetWidth / previewWidth;

            const activeLut = LUTS.find(l => l.name === project.adjustments.lut);
            const sharpness = project.adjustments.sharpness / 100;
            ctx.filter = `${activeLut?.filter || ''} contrast(${1 + (sharpness - 1) * 0.2}) brightness(${1 + (sharpness - 1) * 0.05})`;
            ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
            ctx.filter = 'none';

            const renderLayers = async () => {
                // 1. Draw Global Overlays
                for (const layer of project.globalLayers) {
                    await new Promise<void>(res => {
                        const lImg = new Image();
                        lImg.src = `data:${layer.file.mimeType};base64,${layer.file.base64}`;
                        lImg.onload = () => {
                            const scale = (layer.scale / 100) * canvas.width;
                            const aspect = lImg.width / lImg.height;
                            const drawW = scale;
                            const drawH = scale / aspect;
                            ctx.drawImage(lImg, (layer.x / 100) * canvas.width - drawW/2, (layer.y / 100) * canvas.height - drawH/2, drawW, drawH);
                            res();
                        };
                    });
                }

                // 2. Draw Local Texts
                const texts = project.localTexts[idx] || [];
                texts.forEach(text => {
                    if (!text.isVisible) return;
                    ctx.save();
                    ctx.translate((text.x / 100) * canvas.width, (text.y / 100) * canvas.height);
                    ctx.rotate((text.rotation * Math.PI) / 180);
                    ctx.fillStyle = text.color;
                    const scaledFontSize = text.fontSize * scaleMultiplier;
                    ctx.font = `${text.fontWeight} ${scaledFontSize}px ${text.fontFamily}`;
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';
                    ctx.shadowColor = 'rgba(0,0,0,0.5)';
                    ctx.shadowBlur = 10 * (scaleMultiplier * (previewWidth / 1000));
                    ctx.shadowOffsetY = 4 * (scaleMultiplier * (previewWidth / 1000));

                    const lines = text.content.split('\n');
                    const lineHeight = scaledFontSize * 1.15;
                    const totalHeight = lineHeight * (lines.length - 1);
                    lines.forEach((line, i) => {
                        const yOffset = (i * lineHeight) - (totalHeight / 2);
                        ctx.fillText(line, 0, yOffset);
                    });
                    ctx.restore();
                });

                const link = document.createElement('a');
                link.download = `Jenta-Edit-${idx + 1}-${resolution}.png`;
                link.href = canvas.toDataURL('image/png');
                link.click();
                setIsDownloading(null);
            };
            renderLayers();
        };
    };

    const activeLut = LUTS.find(l => l.name === project.adjustments.lut);
    const sharpness = project.adjustments.sharpness / 100;
    const filterStyle = { filter: `${activeLut?.filter || ''} contrast(${1 + (sharpness - 1) * 0.2}) brightness(${1 + (sharpness - 1) * 0.05})` };

    const selectedLayer = project.globalLayers.find(l => l.id === selectedLayerId);

    // Get currently active text from active slot
    const activeSlotTexts = activeSlotIdx !== null ? (project.localTexts[activeSlotIdx] || []) : [];
    const selectedText = activeSlotTexts.find(t => t.id === selectedTextId) || null;

    return (
        <main className="w-full flex flex-col lg:flex-row gap-8 pt-4 pb-20 animate-in fade-in duration-500 items-start">

            {/* Sidebar Controls - WIDTH 450px AND STABLE */}
            <div className="lg:w-[450px] lg:order-2 flex-shrink-0">
                <div className="glass-card rounded-[2.5rem] p-8 shadow-2xl border border-white/5 sticky top-20 max-h-[85vh] overflow-y-auto suggestions-scrollbar">
                    <h2 className="text-sm font-black text-white/40 uppercase tracking-[0.3em] mb-8 flex items-center gap-3">
                        <div className="w-2 h-2 bg-[var(--color-accent)] rounded-full animate-pulse"></div> Studio Controls
                    </h2>

                    <div className="space-y-8">
                        {/* 1. Base Setup */}
                        <div className="space-y-5 pb-8 border-b border-white/5">
                            <label className="w-full h-14 bg-[rgba(var(--color-accent-rgb),0.1)] hover:bg-[rgba(var(--color-accent-rgb),0.15)] border border-[rgba(var(--color-accent-rgb),0.2)] rounded-2xl flex items-center justify-center cursor-pointer transition-all group gap-3">
                                <PlusIcon />
                                <span className="text-xs font-black text-white uppercase tracking-widest">Upload Images</span>
                                <input type="file" multiple className="hidden" accept="image/*" onChange={(e) => handleUpload(Array.from(e.target.files || []))} />
                            </label>

                            <div className="flex flex-col gap-2">
                                <label className="text-[10px] font-bold text-white/50 uppercase tracking-widest ml-1">Master Style (LUT)</label>
                                <select 
                                    value={project.adjustments.lut}
                                    onChange={(e) => setProject(s => ({ ...s, adjustments: { ...s.adjustments, lut: e.target.value } }))}
                                    className="w-full bg-black/40 border border-white/10 rounded-xl text-xs p-3 text-white focus:outline-none focus:border-[var(--color-accent)] transition-all"
                                >
                                    {LUTS.map(l => <option key={l.name} value={l.name}>{l.name}</option>)}
                                </select>
                            </div>
                        </div>

                        {/* 2. TEXT LAYERS ENGINE */}
                        <div className="pb-8 border-b border-white/5 space-y-6">
                            <div className="flex justify-between items-center">
                                <h3 className="text-xs font-black text-[var(--color-accent)] uppercase tracking-widest ml-1 flex items-center gap-2">
                                    <TextIcon /> Text Engine {activeSlotIdx !== null ? `(Slot 0${activeSlotIdx + 1})` : ''}
                                </h3>
                                <div className="flex gap-2">
                                    {clipboard && activeSlotIdx !== null && (
                                        <button 
                                            onClick={() => handlePaste(activeSlotIdx)}
                                            className="p-2 bg-emerald-500 text-white rounded-xl hover:scale-110 active:scale-95 transition-all shadow-lg shadow-emerald-500/20"
                                            title="Paste Copied Text"
                                        >
                                            <PasteIcon />
                                        </button>
                                    )}
                                    {activeSlotIdx !== null && (
                                        <button 
                                            onClick={() => addTextToSlot(activeSlotIdx)}
                                            className="p-2 bg-[var(--color-accent)] text-white rounded-xl hover:scale-110 active:scale-95 transition-all shadow-lg shadow-[var(--color-accent)]/20"
                                            title="Add New Text Layer"
                                        >
                                            <PlusIcon />
                                        </button>
                                    )}
                                </div>
                            </div>

                            {activeSlotIdx !== null ? (
                                <div className="space-y-6 animate-in fade-in slide-in-from-right-3 duration-300">
                                    {/* Layers List */}
                                    <div className="flex flex-col gap-2 max-h-48 overflow-y-auto suggestions-scrollbar pr-1">
                                        {activeSlotTexts.map((txt, i) => (
                                            <div 
                                                key={txt.id} 
                                                onClick={() => setSelectedTextId(txt.id)}
                                                className={`flex items-center justify-between p-3 rounded-xl cursor-pointer border transition-all ${selectedTextId === txt.id ? 'bg-[rgba(var(--color-accent-rgb),0.15)] border-[var(--color-accent)]' : 'bg-white/5 border-transparent hover:bg-white/10'}`}
                                            >
                                                <div className="flex items-center gap-3">
                                                    <div className={`w-2 h-2 rounded-full ${selectedTextId === txt.id ? 'bg-[var(--color-accent)]' : 'bg-white/20'}`}></div>
                                                    <span className="text-[11px] font-bold text-white/70 truncate max-w-[140px]">{txt.content || `Layer ${i+1}`}</span>
                                                </div>
                                                <div className="flex gap-2 opacity-40 group-hover:opacity-100">
                                                    <button 
                                                        onClick={(e) => { e.stopPropagation(); handleCopy(txt); }} 
                                                        className="text-white hover:text-[var(--color-accent)] p-1 transition-colors"
                                                        title="Copy Layer"
                                                    >
                                                        <CopyIcon />
                                                    </button>
                                                    <button 
                                                        onClick={(e) => { e.stopPropagation(); deleteSlotText(activeSlotIdx, txt.id); }} 
                                                        className="text-white/60 hover:text-red-500 p-1 transition-colors"
                                                        title="Delete Layer"
                                                    >
                                                        <TrashIcon />
                                                    </button>
                                                </div>
                                            </div>
                                        ))}
                                    </div>

                                    {selectedText && (
                                        <div className="space-y-5 p-6 bg-black/30 rounded-3xl border border-white/5 animate-in zoom-in-95 duration-200">
                                            <div className="space-y-2">
                                                <div className="flex justify-between items-center">
                                                    <label className="text-[10px] font-black text-white/30 uppercase tracking-widest">Layer Content</label>
                                                    <div className="flex gap-2">
                                                        <span className="text-[8px] font-bold text-white/20 uppercase tracking-tighter">Ctrl+C / Ctrl+V</span>
                                                        <button onClick={() => handleCopy(selectedText)} className="text-[9px] font-black text-[var(--color-accent)] uppercase hover:underline">Copy This</button>
                                                    </div>
                                                </div>
                                                <textarea 
                                                    value={selectedText.content}
                                                    onChange={(e) => updateSlotText(activeSlotIdx, selectedText.id, { content: e.target.value })}
                                                    className="w-full h-24 bg-black/40 border border-white/10 rounded-2xl p-4 text-sm text-white focus:border-[var(--color-accent)] focus:outline-none resize-none suggestions-scrollbar"
                                                    placeholder="كلمة أو جملة..."
                                                />
                                            </div>

                                            <div className="grid grid-cols-2 gap-4">
                                                <div className="space-y-2">
                                                    <label className="text-[10px] font-black text-white/30 uppercase tracking-widest">Font</label>
                                                    <select 
                                                        value={selectedText.fontFamily}
                                                        onChange={(e) => updateSlotText(activeSlotIdx, selectedText.id, { fontFamily: e.target.value })}
                                                        className="w-full bg-black/40 border border-white/10 rounded-xl text-xs p-3 text-white focus:outline-none focus:border-[var(--color-accent)]"
                                                    >
                                                        {customFonts.map(f => <option key={f} value={f}>{f}</option>)}
                                                        <optgroup label="Standard" className="bg-gray-900">
                                                            {ARABIC_FONTS.map(f => <option key={f} value={f}>{f}</option>)}
                                                            {ENGLISH_FONTS.map(f => <option key={f} value={f}>{f}</option>)}
                                                        </optgroup>
                                                    </select>
                                                </div>
                                                <div className="space-y-2">
                                                    <label className="text-[10px] font-black text-white/30 uppercase tracking-widest">Weight</label>
                                                    <select 
                                                        value={selectedText.fontWeight}
                                                        onChange={(e) => updateSlotText(activeSlotIdx, selectedText.id, { fontWeight: e.target.value })}
                                                        className="w-full bg-black/40 border border-white/10 rounded-xl text-xs p-3 text-white focus:outline-none focus:border-[var(--color-accent)]"
                                                    >
                                                        {FONT_WEIGHTS.map(w => <option key={w.value} value={w.value}>{w.label}</option>)}
                                                    </select>
                                                </div>
                                                <div className="space-y-2">
                                                    <label className="text-[10px] font-black text-white/30 uppercase tracking-widest">Color</label>
                                                    <div className="relative h-11 w-full bg-black/40 border border-white/10 rounded-xl overflow-hidden p-1">
                                                        <input 
                                                            type="color" 
                                                            value={selectedText.color}
                                                            onChange={(e) => updateSlotText(activeSlotIdx, selectedText.id, { color: e.target.value })}
                                                            className="absolute inset-0 w-full h-full bg-transparent border-none cursor-pointer p-0 opacity-0"
                                                        />
                                                        <div className="w-full h-full rounded-lg" style={{ backgroundColor: selectedText.color }}></div>
                                                    </div>
                                                </div>
                                                <div className="space-y-2">
                                                    <label className="text-[10px] font-black text-white/30 uppercase tracking-widest">Size ({selectedText.fontSize}px)</label>
                                                    <div className="flex items-center gap-3 h-11">
                                                        <input type="range" min="10" max="300" value={selectedText.fontSize} onChange={(e) => updateSlotText(activeSlotIdx, selectedText.id, { fontSize: parseInt(e.target.value) })} className="w-full accent-[var(--color-accent)] h-1 bg-white/10 rounded-lg" />
                                                    </div>
                                                </div>
                                            </div>
                                            <div className="space-y-2">
                                                <div className="flex justify-between items-center">
                                                    <label className="text-[10px] font-black text-white/30 uppercase tracking-widest">Rotation ({selectedText.rotation}°)</label>
                                                    <button onClick={() => updateSlotText(activeSlotIdx, selectedText.id, { rotation: 0 })} className="text-[8px] font-bold text-[var(--color-accent)] uppercase hover:underline">Reset</button>
                                                </div>
                                                <input type="range" min="-180" max="180" value={selectedText.rotation} onChange={(e) => updateSlotText(activeSlotIdx, selectedText.id, { rotation: parseInt(e.target.value) })} className="w-full accent-[var(--color-accent)] h-1 bg-white/10 rounded-lg" />
                                            </div>

                                            <button 
                                                onClick={() => updateSlotText(activeSlotIdx, selectedText.id, { isVisible: !selectedText.isVisible })}
                                                className={`w-full py-3 rounded-xl text-[10px] font-black uppercase tracking-[0.2em] transition-all border ${selectedText.isVisible ? 'bg-white/5 text-white/60 border-white/5 hover:bg-white/10' : 'bg-[var(--color-accent)] text-white border-[var(--color-accent)]'}`}
                                            >
                                                {selectedText.isVisible ? 'Hide Text Block' : 'Show Text Block'}
                                            </button>
                                        </div>
                                    )}

                                    {activeSlotIdx !== null && !selectedText && (
                                         <div className="text-center py-6 px-6 border border-white/5 border-dashed rounded-2xl bg-black/10 flex flex-col items-center gap-3">
                                            <p className="text-[10px] text-white/30 uppercase tracking-widest">
                                                {clipboard ? 'Layer in clipboard' : 'Ready for text'}
                                            </p>
                                            {clipboard && (
                                                <button 
                                                    onClick={() => handlePaste(activeSlotIdx)}
                                                    className="px-6 py-2 bg-emerald-500/20 hover:bg-emerald-500/40 text-emerald-400 border border-emerald-500/30 rounded-full text-[10px] font-black uppercase transition-all"
                                                >
                                                    Paste Layer Here
                                                </button>
                                            )}
                                         </div>
                                    )}

                                    <label className="w-full h-11 bg-white/5 hover:bg-white/10 border border-white/5 border-dashed rounded-xl flex items-center justify-center cursor-pointer transition-all gap-3 group">
                                        <span className="text-[10px] font-black text-white/40 uppercase tracking-widest">Upload Custom Font (.ttf)</span>
                                        <input type="file" className="hidden" accept=".ttf,.otf" onChange={handleFontUpload} />
                                    </label>
                                </div>
                            ) : (
                                <div className="p-8 border border-white/5 border-dashed rounded-3xl bg-black/20 text-center">
                                    <div className="w-12 h-12 rounded-full bg-white/5 flex items-center justify-center mx-auto mb-3">
                                        <TextIcon />
                                    </div>
                                    <p className="text-xs text-white/30 font-medium italic">Select a photo from the grid to design</p>
                                </div>
                            )}
                        </div>

                        {/* 3. Logos / Graphics */}
                        <div className="pb-4">
                            <label className="text-[10px] font-bold text-white/40 uppercase tracking-widest ml-1 mb-4 block">Graphic Overlays (Logo)</label>
                            <div className="flex flex-wrap gap-3 mb-6">
                                {project.globalLayers.map(layer => (
                                    <div key={layer.id} className="relative group/l">
                                        <div 
                                            onClick={() => setSelectedLayerId(layer.id)}
                                            className={`w-14 h-14 rounded-xl border-2 overflow-hidden cursor-pointer transition-all ${selectedLayerId === layer.id ? 'border-[var(--color-accent)] scale-110 shadow-xl' : 'border-white/10 opacity-50 hover:opacity-100'}`}
                                        >
                                            <img src={`data:${layer.file.mimeType};base64,${layer.file.base64}`} className="w-full h-full object-contain bg-black/20" />
                                        </div>
                                        <button onClick={() => setProject(s => ({ ...s, globalLayers: s.globalLayers.filter(l => l.id !== layer.id) }))} className="absolute -top-1.5 -right-1.5 bg-red-500 text-white rounded-full p-1 opacity-0 group-hover/l:opacity-100 transition-all transform scale-75 hover:scale-100 shadow-lg"><XIcon /></button>
                                    </div>
                                ))}
                                <label className="w-14 h-14 rounded-xl border-2 border-dashed border-white/10 flex items-center justify-center cursor-pointer hover:border-white/30 transition-all bg-white/5">
                                    <PlusIcon />
                                    <input type="file" multiple className="hidden" accept="image/*" onChange={(e) => handleGlobalAssetUpload(Array.from(e.target.files || []))} />
                                </label>
                            </div>

                            {selectedLayer && (
                                <div className="space-y-4 p-5 bg-white/5 rounded-3xl border border-white/5 animate-in slide-in-from-top-3">
                                    <div className="flex justify-between items-center mb-1">
                                        <label className="text-[10px] font-black text-white/40 uppercase tracking-widest">Transform Logo</label>
                                        <button onClick={() => setSelectedLayerId(null)} className="text-[9px] text-white/40 hover:text-white">Close</button>
                                    </div>
                                    <div className="space-y-4">
                                        <div className="space-y-2">
                                            <div className="flex justify-between text-[9px] font-bold text-white/60"><span>Scale</span><span>{selectedLayer.scale}%</span></div>
                                            <input type="range" min="5" max="100" value={selectedLayer.scale} onChange={e => setProject(s => ({...s, globalLayers: s.globalLayers.map(l => l.id === selectedLayerId ? {...l, scale: parseInt(e.target.value)} : l)}))} className="w-full h-1 accent-white bg-white/10 rounded-full appearance-none" />
                                        </div>
                                        <div className="grid grid-cols-2 gap-4">
                                            <div className="space-y-2">
                                                <div className="flex justify-between text-[9px] font-bold text-white/60"><span>X-Pos</span><span>{selectedLayer.x}%</span></div>
                                                <input type="range" min="0" max="100" value={selectedLayer.x} onChange={e => setProject(s => ({...s, globalLayers: s.globalLayers.map(l => l.id === selectedLayerId ? {...l, x: parseInt(e.target.value)} : l)}))} className="w-full h-1 accent-white bg-white/10 rounded-full appearance-none" />
                                            </div>
                                            <div className="space-y-2">
                                                <div className="flex justify-between text-[9px] font-bold text-white/60"><span>Y-Pos</span><span>{selectedLayer.y}%</span></div>
                                                <input type="range" min="0" max="100" value={selectedLayer.y} onChange={e => setProject(s => ({...s, globalLayers: s.globalLayers.map(l => l.id === selectedLayerId ? {...l, y: parseInt(e.target.value)} : l)}))} className="w-full h-1 accent-white bg-white/10 rounded-full appearance-none" />
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>

            {/* Grid Area - 3 COLUMNS ON XL SCREENS */}
            <div className="flex-grow lg:order-1 min-w-0">
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                    {project.baseImages.map((img, idx) => (
                        <div key={idx} className="flex flex-col gap-4 animate-in fade-in duration-700" style={{ animationDelay: `${idx * 100}ms` }}>
                            <div 
                                ref={el => containerRefs.current[idx] = el}
                                onClick={() => setActiveSlotIdx(idx)}
                                className={`glass-card rounded-[3rem] overflow-hidden aspect-[3/4] relative bg-black/20 shadow-2xl border transition-all duration-500 cursor-pointer group/slot ${activeSlotIdx === idx ? 'border-[var(--color-accent)] ring-8 ring-[var(--color-accent)]/10 scale-[1.02]' : 'border-white/5 hover:border-white/10'}`}
                            >
                                {img ? (
                                    <>
                                        <img src={`data:${img.mimeType};base64,${img.base64}`} className="w-full h-full object-cover select-none pointer-events-none" style={filterStyle} />

                                        {/* Global Overlays */}
                                        {project.globalLayers.map(layer => (
                                            <div key={layer.id} style={{ position: 'absolute', left: `${layer.x}%`, top: `${layer.y}%`, width: `${layer.scale}%`, transform: 'translate(-50%, -50%)', pointerEvents: 'none', zIndex: 5 }}>
                                                <img src={`data:${layer.file.mimeType};base64,${layer.file.base64}`} className="w-full h-auto drop-shadow-2xl" />
                                            </div>
                                        ))}

                                        {/* Multiple Local Text Layers */}
                                        {(project.localTexts[idx] || []).map(text => (
                                            text.isVisible && (
                                                <div 
                                                    key={text.id}
                                                    style={{
                                                        position: 'absolute', left: `${text.x}%`, top: `${text.y}%`,
                                                        transform: `translate(-50%, -50%) rotate(${text.rotation}deg)`,
                                                        color: text.color, fontSize: `${text.fontSize}px`,
                                                        fontFamily: text.fontFamily, fontWeight: text.fontWeight,
                                                        textAlign: 'center', textShadow: '0 4px 16px rgba(0,0,0,0.6)', zIndex: 10,
                                                        whiteSpace: 'pre-wrap', touchAction: 'none', lineHeight: '1.1'
                                                    }}
                                                    onPointerDown={(e) => { 
                                                        e.stopPropagation(); 
                                                        setSelectedTextId(text.id);
                                                        setDraggingId(text.id);
                                                        setDraggingSlot(idx);
                                                        setActiveSlotIdx(idx);
                                                        (e.target as HTMLElement).setPointerCapture(e.pointerId); 
                                                    }}
                                                    onPointerMove={(e) => {
                                                        if (draggingId !== text.id || draggingSlot !== idx) return;
                                                        const rect = containerRefs.current[idx]!.getBoundingClientRect();
                                                        const x = ((e.clientX - rect.left) / rect.width) * 100;
                                                        const y = ((e.clientY - rect.top) / rect.height) * 100;
                                                        updateSlotText(idx, text.id, { x: Math.max(0, Math.min(100, x)), y: Math.max(0, Math.min(100, y)) });
                                                    }}
                                                    onPointerUp={() => { setDraggingId(null); setDraggingSlot(null); }}
                                                    className={`px-6 py-3 border-2 rounded-2xl cursor-move select-none transition-all ${selectedTextId === text.id ? 'border-[var(--color-accent)] bg-[var(--color-accent)]/5 ring-4 ring-[var(--color-accent)]/20' : 'border-transparent hover:border-white/30 hover:bg-white/5'}`}
                                                >
                                                    {text.content}
                                                </div>
                                            )
                                        ))}

                                        <div className="absolute top-6 left-6 bg-black/60 backdrop-blur-xl px-5 py-2 rounded-full text-[10px] font-black text-white/90 border border-white/10 z-20 shadow-xl">
                                            SLOT 0{idx + 1}
                                        </div>

                                        {/* Paste Indicator */}
                                        {clipboard && activeSlotIdx === idx && !selectedTextId && (
                                            <div className="absolute top-6 right-6 bg-emerald-500/80 backdrop-blur-md px-4 py-1.5 rounded-full text-[9px] font-black text-white uppercase tracking-widest border border-white/20 z-20 shadow-lg animate-bounce">
                                                Paste Ready
                                            </div>
                                        )}

                                        {/* Status Badge */}
                                        <div className={`absolute bottom-6 left-6 px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest backdrop-blur-md transition-all duration-500 border ${activeSlotIdx === idx ? 'bg-[var(--color-accent)] text-white border-[var(--color-accent)] shadow-lg' : 'bg-black/40 text-white/40 border-white/5'}`}>
                                            {activeSlotIdx === idx ? 'Active Focus' : 'Inactive'}
                                        </div>
                                    </>
                                ) : (
                                    <div className="w-full h-full flex flex-col items-center justify-center p-8 gap-4 opacity-30 group transition-all">
                                        <div className="w-16 h-16 rounded-full border-2 border-dashed border-white/40 flex items-center justify-center group-hover:scale-110 group-hover:border-white group-hover:bg-white/5 transition-all duration-500">
                                            <PlusIcon />
                                        </div>
                                        <div className="flex flex-col items-center gap-1">
                                            <span className="text-[10px] font-black uppercase tracking-[0.3em]">Empty Studio</span>
                                        </div>
                                    </div>
                                )}
                            </div>

                            {img && (
                                <div className="flex gap-2 animate-in fade-in duration-500">
                                    <button onClick={() => handleDownload(idx, '2k')} disabled={isDownloading !== null} className="flex-1 bg-white/5 hover:bg-white/10 border border-white/5 text-[9px] font-black py-3 rounded-2xl transition-all text-white/60 flex items-center justify-center gap-2 uppercase tracking-tighter">
                                        <DownloadIcon /> {isDownloading === `${idx}-2k` ? '...' : '2K'}
                                    </button>
                                    <button onClick={() => handleDownload(idx, '4k')} disabled={isDownloading !== null} className="flex-1 bg-[var(--color-accent)] hover:bg-[var(--color-accent-dark)] text-[9px] font-black py-3 rounded-2xl transition-all text-white flex items-center justify-center gap-2 shadow-xl shadow-[var(--color-accent)]/20 uppercase tracking-tighter">
                                        <SaveIcon /> {isDownloading === `${idx}-4k` ? 'Saving' : '4K'}
                                    </button>
                                    <button onClick={() => setProject(s => ({ ...s, baseImages: s.baseImages.map((b, i) => i === idx ? null : b) }))} className="p-3 rounded-2xl bg-white/5 text-white/30 hover:text-red-500 hover:bg-red-500/10 transition-all border border-white/5">
                                        <TrashIcon />
                                    </button>
                                </div>
                            )}
                        </div>
                    ))}
                </div>
            </div>

            {project.error && (
                <div className="fixed bottom-12 left-1/2 -translate-x-1/2 z-[100] bg-red-600/90 text-white px-10 py-4 rounded-3xl shadow-2xl backdrop-blur-xl animate-in slide-in-from-bottom-6 flex items-center gap-4 border border-white/20">
                    <div className="w-6 h-6 rounded-full bg-white/20 flex items-center justify-center"><XIcon /></div>
                    <p className="text-sm font-black tracking-tight">{project.error}</p>
                </div>
            )}
        </main>
    );
};

export default EditStudio;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { EditStudioProject, ImageFile, EditAdjustments, LocalText, GlobalLayer } from '../types';
import { resizeImage } from '../utils';

const ARABIC_FONTS = ['Cairo', 'Tajawal', 'Amiri', 'Reem Kufi', 'Lateef', 'Changa', 'Harmattan', 'Almarai'];
const ENGLISH_FONTS = ['Montserrat', 'Bebas Neue', 'Playfair Display', 'Oswald', 'Rubik', 'Inter', 'Poppins', 'Roboto'];
const FONT_WEIGHTS = [
    { label: 'Thin (300)', value: '300' },
    { label: 'Regular (400)', value: '400' },
    { label: 'Bold (700)', value: '700' },
    { label: 'Black (900)', value: '900' }
];

const LUTS = [
    { name: 'Original', filter: '' },
    { name: 'Warm Sun', filter: 'sepia(0.3) saturate(1.2) hue-rotate(-10deg)' },
    { name: 'Ice Cold', filter: 'saturate(0.8) hue-rotate(180deg) brightness(1.1)' },
    { name: 'Soft Vintage', filter: 'sepia(0.5) contrast(0.8) brightness(1.05)' },
    { name: 'Deep Cinematic', filter: 'contrast(1.3) saturate(0.8) brightness(0.9) hue-rotate(-5deg)' },
    { name: 'Black & White', filter: 'grayscale(1) contrast(1.1)' },
    { name: 'Pastel Glow', filter: 'brightness(1.1) saturate(1.3) contrast(0.9)' },
    { name: 'Neon Night', filter: 'hue-rotate(45deg) saturate(1.5) contrast(1.1)' },
];

const TrashIcon = () => <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>;
const PlusIcon = () => <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>;
const CopyIcon = () => <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7v8a2 2 0 002 2h6M8 7V5a2 2 0 012-2h4.586a1 1 0 01.707.293l4.414 4.414a1 1 0 01.293.707V15a2 2 0 01-2 2h-2M8 7H6a2 2 0 00-2 2v10a2 2 0 002 2h8a2 2 0 002-2v-2" /></svg>;
const PasteIcon = () => <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" /></svg>;
const XIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
    </svg>
);
const TextIcon = () => <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h7" /></svg>;
const DownloadIcon = () => <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>;
const SaveIcon = () => <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M8 7H5a2 2 0 00-2 2v9a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-3m-1 4l-3 3m0 0l-3-3m3 3V4" /></svg>;

const createNewText = (): LocalText => ({
    id: Math.random().toString(36).substr(2, 9),
    content: 'نص جديد',
    fontSize: 40,
    color: '#ffffff',
    fontFamily: 'Cairo',
    fontWeight: '700',
    x: 50,
    y: 50,
    isVisible: true,
    rotation: 0
});

const EditStudio: React.FC<{
    project: EditStudioProject;
    setProject: React.Dispatch<React.SetStateAction<EditStudioProject>>;
}> = ({ project, setProject }) => {

    const [isDownloading, setIsDownloading] = useState<string | null>(null);
    const [draggingId, setDraggingId] = useState<string | null>(null);
    const [draggingSlot, setDraggingSlot] = useState<number | null>(null);
    const [selectedLayerId, setSelectedLayerId] = useState<string | null>(null);
    const [activeSlotIdx, setActiveSlotIdx] = useState<number | null>(null);
    const [selectedTextId, setSelectedTextId] = useState<string | null>(null);
    const [customFonts, setCustomFonts] = useState<string[]>([]);
    const [clipboard, setClipboard] = useState<LocalText | null>(null);
    const containerRefs = useRef<(HTMLDivElement | null)[]>([]);

    const addTextToSlot = useCallback((slotIdx: number, customText?: LocalText) => {
        const newText = customText ? { ...customText, id: Math.random().toString(36).substr(2, 9) } : createNewText();
        setProject(s => {
            const currentTexts = s.localTexts[slotIdx] || [];
            return {
                ...s,
                localTexts: { ...s.localTexts, [slotIdx]: [...currentTexts, newText] }
            };
        });
        setSelectedTextId(newText.id);
        setActiveSlotIdx(slotIdx);
    }, [setProject]);

    const handleCopy = useCallback((textObj: LocalText) => {
        setClipboard({ ...textObj });
    }, []);

    const handlePaste = useCallback((slotIdx: number) => {
        if (clipboard) {
            const pastedText = { ...clipboard, x: clipboard.x + 2, y: clipboard.y + 2 };
            addTextToSlot(slotIdx, pastedText);
        }
    }, [clipboard, addTextToSlot]);

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            const isTyping = ['INPUT', 'TEXTAREA'].includes((e.target as HTMLElement).tagName);
            if (isTyping && (e.target as HTMLElement).tagName === 'TEXTAREA') return;

            if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'c') {
                if (activeSlotIdx !== null && selectedTextId) {
                    const texts = project.localTexts[activeSlotIdx] || [];
                    const toCopy = texts.find(t => t.id === selectedTextId);
                    if (toCopy) handleCopy(toCopy);
                }
            }

            if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'v') {
                if (activeSlotIdx !== null && clipboard) {
                    handlePaste(activeSlotIdx);
                }
            }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [activeSlotIdx, selectedTextId, project.localTexts, clipboard, handleCopy, handlePaste]);

    const handleUpload = async (files: File[]) => {
        if (!files || files.length === 0) return;
        setProject(s => ({ ...s, isUploading: true }));
        try {
            const uploaded = await Promise.all(files.map(async file => {
                const resized = await resizeImage(file, 2048, 2048);
                const reader = new FileReader();
                return new Promise<ImageFile>(res => {
                    reader.onloadend = () => res({ base64: (reader.result as string).split(',')[1], mimeType: resized.type, name: resized.name });
                    reader.readAsDataURL(resized);
                });
            }));

            setProject(s => {
                const newBase = [...s.baseImages];
                let upIdx = 0;
                for (let i = 0; i < 6 && upIdx < uploaded.length; i++) {
                    if (!newBase[i]) {
                        newBase[i] = uploaded[upIdx];
                        upIdx++;
                    }
                }
                return { ...s, baseImages: newBase, isUploading: false };
            });
        } catch (err) {
            setProject(s => ({ ...s, isUploading: false, error: "Upload failed" }));
        }
    };

    const handleFontUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const files = Array.from(e.target.files || []) as File[];
        for (const file of files) {
            try {
                const fontName = file.name.split('.')[0];
                const reader = new FileReader();
                reader.onload = async (event) => {
                    const data = event.target?.result;
                    if (data) {
                        const fontFace = new FontFace(fontName, data as ArrayBuffer);
                        const loadedFace = await fontFace.load();
                        document.fonts.add(loadedFace);
                        setCustomFonts(prev => [...new Set([...prev, fontName])]);
                    }
                };
                reader.readAsArrayBuffer(file);
            } catch (err) { console.error(err); }
        }
    };

    const handleGlobalAssetUpload = async (files: File[]) => {
        if (!files || files.length === 0) return;
        try {
            const uploaded = await Promise.all(files.map(async file => {
                const resized = await resizeImage(file, 1024, 1024);
                const reader = new FileReader();
                return new Promise<GlobalLayer>(res => {
                    reader.onloadend = () => {
                        const base64 = (reader.result as string).split(',')[1];
                        res({ 
                            id: Math.random().toString(36).substr(2, 9),
                            file: { base64, mimeType: resized.type, name: resized.name },
                            scale: 20,
                            x: 50,
                            y: 50
                        });
                    };
                    reader.readAsDataURL(resized);
                });
            }));
            setProject(s => ({ ...s, globalLayers: [...s.globalLayers, ...uploaded] }));
        } catch (err) { console.error(err); }
    };

    const updateSlotText = (slotIdx: number, textId: string, updates: Partial<LocalText>) => {
        setProject(s => {
            const texts = s.localTexts[slotIdx] || [];
            const updated = texts.map(t => t.id === textId ? { ...t, ...updates } : t);
            return { ...s, localTexts: { ...s.localTexts, [slotIdx]: updated } };
        });
    };

    const deleteSlotText = (slotIdx: number, textId: string) => {
        setProject(s => {
            const texts = (s.localTexts[slotIdx] || []).filter(t => t.id !== textId);
            return { ...s, localTexts: { ...s.localTexts, [slotIdx]: texts } };
        });
        if (selectedTextId === textId) setSelectedTextId(null);
    };

    const handleDownload = (idx: number, resolution: '2k' | '4k') => {
        const imgFile = project.baseImages[idx];
        const container = containerRefs.current[idx];
        if (!imgFile || !container) return;

        setIsDownloading(`${idx}-${resolution}`);
        const img = new Image();
        img.src = `data:${imgFile.mimeType};base64,${imgFile.base64}`;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const ctx = canvas.getContext('2d');
            if (!ctx) return;
            const targetWidth = resolution === '4k' ? 4096 : 2048;
            canvas.width = targetWidth;
            canvas.height = targetWidth * (img.height / img.width);
            const previewWidth = container.offsetWidth;
            const scaleMultiplier = targetWidth / previewWidth;

            const activeLut = LUTS.find(l => l.name === project.adjustments.lut);
            const sharpness = project.adjustments.sharpness / 100;
            ctx.filter = `${activeLut?.filter || ''} contrast(${1 + (sharpness - 1) * 0.2}) brightness(${1 + (sharpness - 1) * 0.05})`;
            ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
            ctx.filter = 'none';

            const renderLayers = async () => {
                for (const layer of project.globalLayers) {
                    await new Promise<void>(res => {
                        const lImg = new Image();
                        lImg.src = `data:${layer.file.mimeType};base64,${layer.file.base64}`;
                        lImg.onload = () => {
                            const scale = (layer.scale / 100) * canvas.width;
                            const aspect = lImg.width / lImg.height;
                            const drawW = scale;
                            const drawH = scale / aspect;
                            ctx.drawImage(lImg, (layer.x / 100) * canvas.width - drawW/2, (layer.y / 100) * canvas.height - drawH/2, drawW, drawH);
                            res();
                        };
                    });
                }

                const texts = project.localTexts[idx] || [];
                texts.forEach(text => {
                    if (!text.isVisible) return;
                    ctx.save();
                    ctx.translate((text.x / 100) * canvas.width, (text.y / 100) * canvas.height);
                    ctx.rotate((text.rotation * Math.PI) / 180);
                    ctx.fillStyle = text.color;
                    const scaledFontSize = text.fontSize * scaleMultiplier;
                    ctx.font = `${text.fontWeight} ${scaledFontSize}px ${text.fontFamily}`;
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';
                    ctx.shadowColor = 'rgba(0,0,0,0.5)';
                    ctx.shadowBlur = 10 * (scaleMultiplier * (previewWidth / 1000));
                    ctx.shadowOffsetY = 4 * (scaleMultiplier * (previewWidth / 1000));

                    const lines = text.content.split('\n');
                    const lineHeight = scaledFontSize * 1.15;
                    const totalHeight = lineHeight * (lines.length - 1);
                    lines.forEach((line, i) => {
                        const yOffset = (i * lineHeight) - (totalHeight / 2);
                        ctx.fillText(line, 0, yOffset);
                    });
                    ctx.restore();
                });

                const link = document.createElement('a');
                link.download = `Jenta-Edit-${idx + 1}-${resolution}.png`;
                link.href = canvas.toDataURL('image/png');
                link.click();
                setIsDownloading(null);
            };
            renderLayers();
        };
    };

    const activeLut = LUTS.find(l => l.name === project.adjustments.lut);
    const sharpness = project.adjustments.sharpness / 100;
    const filterStyle = { filter: `${activeLut?.filter || ''} contrast(${1 + (sharpness - 1) * 0.2}) brightness(${1 + (sharpness - 1) * 0.05})` };

    const selectedLayer = project.globalLayers.find(l => l.id === selectedLayerId);
    const activeSlotTexts = activeSlotIdx !== null ? (project.localTexts[activeSlotIdx] || []) : [];
    const selectedText = activeSlotTexts.find(t => t.id === selectedTextId) || null;

    return (
        <main className="w-full flex flex-col lg:flex-row gap-8 pt-4 pb-20 animate-in fade-in duration-500 items-start">

            <div className="lg:w-[450px] lg:order-2 flex-shrink-0">
                <div className="glass-card rounded-[2.5rem] p-8 shadow-2xl border border-white/5 sticky top-20 max-h-[85vh] overflow-y-auto suggestions-scrollbar">
                    <h2 className="text-sm font-black text-white/40 uppercase tracking-[0.3em] mb-8 flex items-center gap-3">
                        <div className="w-2 h-2 bg-[var(--color-accent)] rounded-full animate-pulse"></div> Studio Controls
                    </h2>

                    <div className="space-y-8">
                        <div className="space-y-5 pb-8 border-b border-white/5">
                            <label className="w-full h-14 bg-[rgba(var(--color-accent-rgb),0.1)] hover:bg-[rgba(var(--color-accent-rgb),0.15)] border border-[rgba(var(--color-accent-rgb),0.2)] rounded-2xl flex items-center justify-center cursor-pointer transition-all group gap-3">
                                <PlusIcon />
                                <span className="text-xs font-black text-white uppercase tracking-widest">Upload Images</span>
                                <input type="file" multiple className="hidden" accept="image/*" onChange={(e) => handleUpload(Array.from(e.target.files || []))} />
                            </label>

                            <div className="flex flex-col gap-2">
                                <label className="text-[10px] font-bold text-white/50 uppercase tracking-widest ml-1">Master Style (LUT)</label>
                                <select 
                                    value={project.adjustments.lut}
                                    onChange={(e) => setProject(s => ({ ...s, adjustments: { ...s.adjustments, lut: e.target.value } }))}
                                    className="w-full bg-black/40 border border-white/10 rounded-xl text-xs p-3 text-white focus:outline-none focus:border-[var(--color-accent)] transition-all"
                                >
                                    {LUTS.map(l => <option key={l.name} value={l.name}>{l.name}</option>)}
                                </select>
                            </div>
                        </div>

                        <div className="pb-8 border-b border-white/5 space-y-6">
                            <div className="flex justify-between items-center">
                                <h3 className="text-xs font-black text-[var(--color-accent)] uppercase tracking-widest ml-1 flex items-center gap-2">
                                    <TextIcon /> Text Engine {activeSlotIdx !== null ? `(Slot 0${activeSlotIdx + 1})` : ''}
                                </h3>
                                <div className="flex gap-2">
                                    {clipboard && activeSlotIdx !== null && (
                                        <button 
                                            onClick={() => handlePaste(activeSlotIdx)}
                                            className="p-2 bg-emerald-500 text-white rounded-xl hover:scale-110 active:scale-95 transition-all shadow-lg shadow-emerald-500/20"
                                            title="Paste Copied Text"
                                        >
                                            <PasteIcon />
                                        </button>
                                    )}
                                    {activeSlotIdx !== null && (
                                        <button 
                                            onClick={() => addTextToSlot(activeSlotIdx)}
                                            className="p-2 bg-[var(--color-accent)] text-white rounded-xl hover:scale-110 active:scale-95 transition-all shadow-lg shadow-[var(--color-accent)]/20"
                                            title="Add New Text Layer"
                                        >
                                            <PlusIcon />
                                        </button>
                                    )}
                                </div>
                            </div>

                            {activeSlotIdx !== null ? (
                                <div className="space-y-6 animate-in fade-in slide-in-from-right-3 duration-300">
                                    <div className="flex flex-col gap-2 max-h-48 overflow-y-auto suggestions-scrollbar pr-1">
                                        {activeSlotTexts.map((txt, i) => (
                                            <div 
                                                key={txt.id} 
                                                onClick={() => setSelectedTextId(txt.id)}
                                                className={`flex items-center justify-between p-3 rounded-xl cursor-pointer border transition-all ${selectedTextId === txt.id ? 'bg-[rgba(var(--color-accent-rgb),0.15)] border-[var(--color-accent)]' : 'bg-white/5 border-transparent hover:bg-white/10'}`}
                                            >
                                                <div className="flex items-center gap-3">
                                                    <div className={`w-2 h-2 rounded-full ${selectedTextId === txt.id ? 'bg-[var(--color-accent)]' : 'bg-white/20'}`}></div>
                                                    <span className="text-[11px] font-bold text-white/70 truncate max-w-[140px]">{txt.content || `Layer ${i+1}`}</span>
                                                </div>
                                                <div className="flex gap-2 opacity-40 group-hover:opacity-100">
                                                    <button 
                                                        onClick={(e) => { e.stopPropagation(); handleCopy(txt); }} 
                                                        className="text-white hover:text-[var(--color-accent)] p-1 transition-colors"
                                                        title="Copy Layer"
                                                    >
                                                        <CopyIcon />
                                                    </button>
                                                    <button 
                                                        onClick={(e) => { e.stopPropagation(); deleteSlotText(activeSlotIdx, txt.id); }} 
                                                        className="text-white/60 hover:text-red-500 p-1 transition-colors"
                                                        title="Delete Layer"
                                                    >
                                                        <TrashIcon />
                                                    </button>
                                                </div>
                                            </div>
                                        ))}
                                    </div>

                                    {selectedText && (
                                        <div className="space-y-5 p-6 bg-black/30 rounded-3xl border border-white/5 animate-in zoom-in-95 duration-200">
                                            <div className="space-y-2">
                                                <div className="flex justify-between items-center">
                                                    <label className="text-[10px] font-black text-white/30 uppercase tracking-widest">Layer Content</label>
                                                    <div className="flex gap-2">
                                                        <span className="text-[8px] font-bold text-white/20 uppercase tracking-tighter">Ctrl+C / Ctrl+V</span>
                                                        <button onClick={() => handleCopy(selectedText)} className="text-[9px] font-black text-[var(--color-accent)] uppercase hover:underline">Copy This</button>
                                                    </div>
                                                </div>
                                                <textarea 
                                                    value={selectedText.content}
                                                    onChange={(e) => updateSlotText(activeSlotIdx, selectedText.id, { content: e.target.value })}
                                                    className="w-full h-24 bg-black/40 border border-white/10 rounded-2xl p-4 text-sm text-white focus:border-[var(--color-accent)] focus:outline-none resize-none suggestions-scrollbar"
                                                    placeholder="كلمة أو جملة..."
                                                />
                                            </div>

                                            <div className="grid grid-cols-2 gap-4">
                                                <div className="space-y-2">
                                                    <label className="text-[10px] font-black text-white/30 uppercase tracking-widest">Font</label>
                                                    <select 
                                                        value={selectedText.fontFamily}
                                                        onChange={(e) => updateSlotText(activeSlotIdx, selectedText.id, { fontFamily: e.target.value })}
                                                        className="w-full bg-black/40 border border-white/10 rounded-xl text-xs p-3 text-white focus:outline-none focus:border-[var(--color-accent)]"
                                                    >
                                                        {customFonts.map(f => <option key={f} value={f}>{f}</option>)}
                                                        <optgroup label="Standard" className="bg-gray-900">
                                                            {ARABIC_FONTS.map(f => <option key={f} value={f}>{f}</option>)}
                                                            {ENGLISH_FONTS.map(f => <option key={f} value={f}>{f}</option>)}
                                                        </optgroup>
                                                    </select>
                                                </div>
                                                <div className="space-y-2">
                                                    <label className="text-[10px] font-black text-white/30 uppercase tracking-widest">Weight</label>
                                                    <select 
                                                        value={selectedText.fontWeight}
                                                        onChange={(e) => updateSlotText(activeSlotIdx, selectedText.id, { fontWeight: e.target.value })}
                                                        className="w-full bg-black/40 border border-white/10 rounded-xl text-xs p-3 text-white focus:outline-none focus:border-[var(--color-accent)]"
                                                    >
                                                        {FONT_WEIGHTS.map(w => <option key={w.value} value={w.value}>{w.label}</option>)}
                                                    </select>
                                                </div>
                                                <div className="space-y-2">
                                                    <label className="text-[10px] font-black text-white/30 uppercase tracking-widest">Color</label>
                                                    <div className="relative h-11 w-full bg-black/40 border border-white/10 rounded-xl overflow-hidden p-1">
                                                        <input 
                                                            type="color" 
                                                            value={selectedText.color}
                                                            onChange={(e) => updateSlotText(activeSlotIdx, selectedText.id, { color: e.target.value })}
                                                            className="absolute inset-0 w-full h-full bg-transparent border-none cursor-pointer p-0 opacity-0"
                                                        />
                                                        <div className="w-full h-full rounded-lg" style={{ backgroundColor: selectedText.color }}></div>
                                                    </div>
                                                </div>
                                                <div className="space-y-2">
                                                    <label className="text-[10px] font-black text-white/30 uppercase tracking-widest">Size ({selectedText.fontSize}px)</label>
                                                    <div className="flex items-center gap-3 h-11">
                                                        <input type="range" min="10" max="300" value={selectedText.fontSize} onChange={(e) => updateSlotText(activeSlotIdx, selectedText.id, { fontSize: parseInt(e.target.value) })} className="w-full accent-[var(--color-accent)] h-1 bg-white/10 rounded-lg" />
                                                    </div>
                                                </div>
                                            </div>
                                            <div className="space-y-2">
                                                <div className="flex justify-between items-center">
                                                    <label className="text-[10px] font-black text-white/30 uppercase tracking-widest">Rotation ({selectedText.rotation}°)</label>
                                                    <button onClick={() => updateSlotText(activeSlotIdx, selectedText.id, { rotation: 0 })} className="text-[8px] font-bold text-[var(--color-accent)] uppercase hover:underline">Reset</button>
                                                </div>
                                                <input type="range" min="-180" max="180" value={selectedText.rotation} onChange={(e) => updateSlotText(activeSlotIdx, selectedText.id, { rotation: parseInt(e.target.value) })} className="w-full accent-[var(--color-accent)] h-1 bg-white/10 rounded-lg" />
                                            </div>

                                            <button 
                                                onClick={() => updateSlotText(activeSlotIdx, selectedText.id, { isVisible: !selectedText.isVisible })}
                                                className={`w-full py-3 rounded-xl text-[10px] font-black uppercase tracking-[0.2em] transition-all border ${selectedText.isVisible ? 'bg-white/5 text-white/60 border-white/5 hover:bg-white/10' : 'bg-[var(--color-accent)] text-white border-[var(--color-accent)]'}`}
                                            >
                                                {selectedText.isVisible ? 'Hide Text Block' : 'Show Text Block'}
                                            </button>
                                        </div>
                                    )}

                                    {activeSlotIdx !== null && !selectedText && (
                                         <div className="text-center py-6 px-6 border border-white/5 border-dashed rounded-2xl bg-black/10 flex flex-col items-center gap-3">
                                            <p className="text-[10px] text-white/30 uppercase tracking-widest">
                                                {clipboard ? 'Layer in clipboard' : 'Ready for text'}
                                            </p>
                                            {clipboard && (
                                                <button 
                                                    onClick={() => handlePaste(activeSlotIdx)}
                                                    className="px-6 py-2 bg-emerald-500/20 hover:bg-emerald-500/40 text-emerald-400 border border-emerald-500/30 rounded-full text-[10px] font-black uppercase transition-all"
                                                >
                                                    Paste Layer Here
                                                </button>
                                            )}
                                         </div>
                                    )}

                                    <label className="w-full h-11 bg-white/5 hover:bg-white/10 border border-white/5 border-dashed rounded-xl flex items-center justify-center cursor-pointer transition-all gap-3 group">
                                        <span className="text-[10px] font-black text-white/40 uppercase tracking-widest">Upload Custom Font (.ttf)</span>
                                        <input type="file" className="hidden" accept=".ttf,.otf" onChange={handleFontUpload} />
                                    </label>
                                </div>
                            ) : (
                                <div className="p-8 border border-white/5 border-dashed rounded-3xl bg-black/20 text-center">
                                    <div className="w-12 h-12 rounded-full bg-white/5 flex items-center justify-center mx-auto mb-3">
                                        <TextIcon />
                                    </div>
                                    <p className="text-xs text-white/30 font-medium italic">Select a photo from the grid to design</p>
                                </div>
                            )}
                        </div>

                        <div className="pb-4">
                            <label className="text-[10px] font-bold text-white/40 uppercase tracking-widest ml-1 mb-4 block">Graphic Overlays (Logo)</label>
                            <div className="flex flex-wrap gap-3 mb-6">
                                {project.globalLayers.map(layer => (
                                    <div key={layer.id} className="relative group/l">
                                        <div 
                                            onClick={() => setSelectedLayerId(layer.id)}
                                            className={`w-14 h-14 rounded-xl border-2 overflow-hidden cursor-pointer transition-all ${selectedLayerId === layer.id ? 'border-[var(--color-accent)] scale-110 shadow-xl' : 'border-white/10 opacity-50 hover:opacity-100'}`}
                                        >
                                            <img src={`data:${layer.file.mimeType};base64,${layer.file.base64}`} className="w-full h-full object-contain bg-black/20" />
                                        </div>
                                        <button onClick={() => setProject(s => ({ ...s, globalLayers: s.globalLayers.filter(l => l.id !== layer.id) }))} className="absolute -top-1.5 -right-1.5 bg-red-500 text-white rounded-full p-1 opacity-0 group-hover/l:opacity-100 transition-all transform scale-75 hover:scale-100 shadow-lg"><XIcon /></button>
                                    </div>
                                ))}
                                <label className="w-14 h-14 rounded-xl border-2 border-dashed border-white/10 flex items-center justify-center cursor-pointer hover:border-white/30 transition-all bg-white/5">
                                    <PlusIcon />
                                    <input type="file" multiple className="hidden" accept="image/*" onChange={(e) => handleGlobalAssetUpload(Array.from(e.target.files || []))} />
                                </label>
                            </div>

                            {selectedLayer && (
                                <div className="space-y-4 p-5 bg-white/5 rounded-3xl border border-white/5 animate-in slide-in-from-top-3">
                                    <div className="flex justify-between items-center mb-1">
                                        <label className="text-[10px] font-black text-white/40 uppercase tracking-widest">Transform Logo</label>
                                        <button onClick={() => setSelectedLayerId(null)} className="text-[9px] text-white/40 hover:text-white">Close</button>
                                    </div>
                                    <div className="space-y-4">
                                        <div className="space-y-2">
                                            <div className="flex justify-between text-[9px] font-bold text-white/60"><span>Scale</span><span>{selectedLayer.scale}%</span></div>
                                            <input type="range" min="5" max="100" value={selectedLayer.scale} onChange={e => setProject(s => ({...s, globalLayers: s.globalLayers.map(l => l.id === selectedLayerId ? {...l, scale: parseInt(e.target.value)} : l)}))} className="w-full h-1 accent-white bg-white/10 rounded-full appearance-none" />
                                        </div>
                                        <div className="grid grid-cols-2 gap-4">
                                            <div className="space-y-2">
                                                <div className="flex justify-between text-[9px] font-bold text-white/60"><span>X-Pos</span><span>{selectedLayer.x}%</span></div>
                                                <input type="range" min="0" max="100" value={selectedLayer.x} onChange={e => setProject(s => ({...s, globalLayers: s.globalLayers.map(l => l.id === selectedLayerId ? {...l, x: parseInt(e.target.value)} : l)}))} className="w-full h-1 accent-white bg-white/10 rounded-full appearance-none" />
                                            </div>
                                            <div className="space-y-2">
                                                <div className="flex justify-between text-[9px] font-bold text-white/60"><span>Y-Pos</span><span>{selectedLayer.y}%</span></div>
                                                <input type="range" min="0" max="100" value={selectedLayer.y} onChange={e => setProject(s => ({...s, globalLayers: s.globalLayers.map(l => l.id === selectedLayerId ? {...l, y: parseInt(e.target.value)} : l)}))} className="w-full h-1 accent-white bg-white/10 rounded-full appearance-none" />
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>

            <div className="flex-grow lg:order-1 min-w-0">
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
                    {project.baseImages.map((img, idx) => (
                        <div key={idx} className="flex flex-col gap-3 animate-in fade-in duration-700" style={{ animationDelay: `${idx * 100}ms` }}>

                            <div className="flex justify-between items-center px-2">
                                <span className="text-[10px] font-black text-white/40 uppercase tracking-[0.2em]">Slot 0{idx + 1}</span>
                                {clipboard && activeSlotIdx === idx && !selectedTextId && (
                                    <span className="text-[9px] font-black text-emerald-400 uppercase tracking-widest animate-pulse">Paste Ready</span>
                                )}
                            </div>

                            <div 
                                ref={el => containerRefs.current[idx] = el}
                                onClick={() => setActiveSlotIdx(idx)}
                                className={`glass-card rounded-2xl overflow-hidden aspect-[4/3] relative bg-black/40 shadow-2xl border transition-all duration-500 cursor-pointer group/slot ${activeSlotIdx === idx ? 'border-[var(--color-accent)] ring-4 ring-[var(--color-accent)]/10' : 'border-white/5 hover:border-white/10'}`}
                            >
                                {img ? (
                                    <>
                                        <img src={`data:${img.mimeType};base64,${img.base64}`} className="w-full h-full object-contain select-none pointer-events-none" style={filterStyle} />

                                        {project.globalLayers.map(layer => (
                                            <div key={layer.id} style={{ position: 'absolute', left: `${layer.x}%`, top: `${layer.y}%`, width: `${layer.scale}%`, transform: 'translate(-50%, -50%)', pointerEvents: 'none', zIndex: 5 }}>
                                                <img src={`data:${layer.file.mimeType};base64,${layer.file.base64}`} className="w-full h-auto drop-shadow-2xl" />
                                            </div>
                                        ))}

                                        {(project.localTexts[idx] || []).map(text => (
                                            text.isVisible && (
                                                <div 
                                                    key={text.id}
                                                    style={{
                                                        position: 'absolute', left: `${text.x}%`, top: `${text.y}%`,
                                                        transform: `translate(-50%, -50%) rotate(${text.rotation}deg)`,
                                                        color: text.color, fontSize: `${text.fontSize}px`,
                                                        fontFamily: text.fontFamily, fontWeight: text.fontWeight,
                                                        textAlign: 'center', textShadow: '0 4px 16px rgba(0,0,0,0.6)', zIndex: 10,
                                                        whiteSpace: 'pre-wrap', touchAction: 'none', lineHeight: '1.1'
                                                    }}
                                                    onPointerDown={(e) => { 
                                                        e.stopPropagation(); 
                                                        setSelectedTextId(text.id);
                                                        setDraggingId(text.id);
                                                        setDraggingSlot(idx);
                                                        setActiveSlotIdx(idx);
                                                        (e.target as HTMLElement).setPointerCapture(e.pointerId); 
                                                    }}
                                                    onPointerMove={(e) => {
                                                        if (draggingId !== text.id || draggingSlot !== idx) return;
                                                        const rect = containerRefs.current[idx]!.getBoundingClientRect();
                                                        const x = ((e.clientX - rect.left) / rect.width) * 100;
                                                        const y = ((e.clientY - rect.top) / rect.height) * 100;
                                                        updateSlotText(idx, text.id, { x: Math.max(0, Math.min(100, x)), y: Math.max(0, Math.min(100, y)) });
                                                    }}
                                                    onPointerUp={() => { setDraggingId(null); setDraggingSlot(null); }}
                                                    className={`px-6 py-3 border-2 rounded-2xl cursor-move select-none transition-all ${selectedTextId === text.id ? 'border-[var(--color-accent)] bg-[var(--color-accent)]/5 ring-4 ring-[var(--color-accent)]/20' : 'border-transparent hover:border-white/30 hover:bg-white/5'}`}
                                                >
                                                    {text.content}
                                                </div>
                                            )
                                        ))}
                                    </>
                                ) : (
                                    <div className="w-full h-full flex flex-col items-center justify-center p-8 gap-4 opacity-30 group transition-all">
                                        <div className="w-16 h-16 rounded-full border-2 border-dashed border-white/40 flex items-center justify-center group-hover:scale-110 group-hover:border-white group-hover:bg-white/5 transition-all duration-500">
                                            <PlusIcon />
                                        </div>
                                        <div className="flex flex-col items-center gap-1">
                                            <span className="text-[10px] font-black uppercase tracking-[0.3em]">Empty Studio</span>
                                        </div>
                                    </div>
                                )}
                            </div>

                            <div className="flex justify-between items-center px-2 min-h-[16px]">
                                <div className={`flex items-center gap-2 text-[9px] font-black uppercase tracking-widest transition-all duration-500 ${activeSlotIdx === idx ? 'text-[var(--color-accent)]' : 'text-white/20'}`}>
                                    <div className={`w-1.5 h-1.5 rounded-full ${activeSlotIdx === idx ? 'bg-[var(--color-accent)] shadow-[0_0_8px_var(--color-accent)]' : 'bg-white/10'}`}></div>
                                    {activeSlotIdx === idx ? 'Active Focus' : 'Inactive'}
                                </div>
                            </div>

                            {img && (
                                <div className="flex gap-2 animate-in fade-in duration-500">
                                    <button onClick={() => handleDownload(idx, '2k')} disabled={isDownloading !== null} className="flex-1 bg-white/5 hover:bg-white/10 border border-white/5 text-[9px] font-black py-3 rounded-xl transition-all text-white/60 flex items-center justify-center gap-2 uppercase tracking-tighter">
                                        <DownloadIcon /> {isDownloading === `${idx}-2k` ? '...' : '2K'}
                                    </button>
                                    <button onClick={() => handleDownload(idx, '4k')} disabled={isDownloading !== null} className="flex-1 bg-[var(--color-accent)] hover:bg-[var(--color-accent-dark)] text-[9px] font-black py-3 rounded-xl transition-all text-white flex items-center justify-center gap-2 shadow-xl shadow-[var(--color-accent)]/20 uppercase tracking-tighter">
                                        <SaveIcon /> {isDownloading === `${idx}-4k` ? 'Saving' : '4K'}
                                    </button>
                                    <button onClick={() => setProject(s => ({ ...s, baseImages: s.baseImages.map((b, i) => i === idx ? null : b) }))} className="p-3 rounded-xl bg-white/5 text-white/30 hover:text-red-500 hover:bg-red-500/10 transition-all border border-white/5">
                                        <TrashIcon />
                                    </button>
                                </div>
                            )}
                        </div>
                    ))}
                </div>
            </div>

            {project.error && (
                <div className="fixed bottom-12 left-1/2 -translate-x-1/2 z-[100] bg-red-600/90 text-white px-10 py-4 rounded-3xl shadow-2xl backdrop-blur-xl animate-in slide-in-from-bottom-6 flex items-center gap-4 border border-white/20">
                    <div className="w-6 h-6 rounded-full bg-white/20 flex items-center justify-center"><XIcon /></div>
                    <p className="text-sm font-black tracking-tight">{project.error}</p>
                </div>
            )}
        </main>
    );
};

export default EditStudio;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { EditStudioProject, ImageFile, EditAdjustments, LocalText, GlobalLayer } from '../types';
import { resizeImage } from '../utils';

const ARABIC_FONTS = ['Cairo', 'Tajawal', 'Amiri', 'Reem Kufi', 'Lateef', 'Changa', 'Harmattan', 'Almarai'];
const ENGLISH_FONTS = ['Montserrat', 'Bebas Neue', 'Playfair Display', 'Oswald', 'Rubik', 'Inter', 'Poppins', 'Roboto'];
const FONT_WEIGHTS = [
    { label: 'Thin (300)', value: '300' },
    { label: 'Regular (400)', value: '400' },
    { label: 'Bold (700)', value: '700' },
    { label: 'Black (900)', value: '900' }
];

const LUTS = [
    { name: 'Original', filter: '' },
    { name: 'Warm Sun', filter: 'sepia(0.3) saturate(1.2) hue-rotate(-10deg)' },
    { name: 'Ice Cold', filter: 'saturate(0.8) hue-rotate(180deg) brightness(1.1)' },
    { name: 'Soft Vintage', filter: 'sepia(0.5) contrast(0.8) brightness(1.05)' },
    { name: 'Deep Cinematic', filter: 'contrast(1.3) saturate(0.8) brightness(0.9) hue-rotate(-5deg)' },
    { name: 'Black & White', filter: 'grayscale(1) contrast(1.1)' },
    { name: 'Pastel Glow', filter: 'brightness(1.1) saturate(1.3) contrast(0.9)' },
    { name: 'Neon Night', filter: 'hue-rotate(45deg) saturate(1.5) contrast(1.1)' },
];

const TrashIcon = () => <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>;
const PlusIcon = () => <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>;
const CopyIcon = () => <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7v8a2 2 0 002 2h6M8 7V5a2 2 0 012-2h4.586a1 1 0 01.707.293l4.414 4.414a1 1 0 01.293.707V15a2 2 0 01-2 2h-2M8 7H6a2 2 0 00-2 2v10a2 2 0 002 2h8a2 2 0 002-2v-2" /></svg>;
const PasteIcon = () => <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" /></svg>;
const XIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
    </svg>
);
const TextIcon = () => <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h7" /></svg>;
const DownloadIcon = () => <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>;
const SaveIcon = () => <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M8 7H5a2 2 0 00-2 2v9a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-3m-1 4l-3 3m0 0l-3-3m3 3V4" /></svg>;

const createNewText = (): LocalText => ({
    id: Math.random().toString(36).substr(2, 9),
    content: 'نص جديد',
    fontSize: 40,
    color: '#ffffff',
    fontFamily: 'Cairo',
    fontWeight: '700',
    x: 50,
    y: 50,
    isVisible: true,
    rotation: 0
});

const EditStudio: React.FC<{
    project: EditStudioProject;
    setProject: React.Dispatch<React.SetStateAction<EditStudioProject>>;
}> = ({ project, setProject }) => {

    const [isDownloading, setIsDownloading] = useState<string | null>(null);
    const [draggingId, setDraggingId] = useState<string | null>(null);
    const [draggingSlot, setDraggingSlot] = useState<number | null>(null);
    const [selectedLayerId, setSelectedLayerId] = useState<string | null>(null);
    const [activeSlotIdx, setActiveSlotIdx] = useState<number | null>(null);
    const [selectedTextId, setSelectedTextId] = useState<string | null>(null);
    const [customFonts, setCustomFonts] = useState<string[]>([]);
    const [clipboard, setClipboard] = useState<LocalText | null>(null);
    const containerRefs = useRef<(HTMLDivElement | null)[]>([]);

    const addTextToSlot = useCallback((slotIdx: number, customText?: LocalText) => {
        const newText = customText ? { ...customText, id: Math.random().toString(36).substr(2, 9) } : createNewText();
        setProject(s => {
            const currentTexts = s.localTexts[slotIdx] || [];
            return {
                ...s,
                localTexts: { ...s.localTexts, [slotIdx]: [...currentTexts, newText] }
            };
        });
        setSelectedTextId(newText.id);
        setActiveSlotIdx(slotIdx);
    }, [setProject]);

    const handleCopy = useCallback((textObj: LocalText) => {
        setClipboard({ ...textObj });
    }, []);

    const handlePaste = useCallback((slotIdx: number) => {
        if (clipboard) {
            const pastedText = { ...clipboard, x: clipboard.x + 2, y: clipboard.y + 2 };
            addTextToSlot(slotIdx, pastedText);
        }
    }, [clipboard, addTextToSlot]);

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            const isTyping = ['INPUT', 'TEXTAREA'].includes((e.target as HTMLElement).tagName);
            if (isTyping && (e.target as HTMLElement).tagName === 'TEXTAREA') return;

            if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'c') {
                if (activeSlotIdx !== null && selectedTextId) {
                    const texts = project.localTexts[activeSlotIdx] || [];
                    const toCopy = texts.find(t => t.id === selectedTextId);
                    if (toCopy) handleCopy(toCopy);
                }
            }

            if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'v') {
                if (activeSlotIdx !== null && clipboard) {
                    handlePaste(activeSlotIdx);
                }
            }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [activeSlotIdx, selectedTextId, project.localTexts, clipboard, handleCopy, handlePaste]);

    const handleUpload = async (files: File[]) => {
        if (!files || files.length === 0) return;
        setProject(s => ({ ...s, isUploading: true }));
        try {
            const uploaded = await Promise.all(files.map(async file => {
                const resized = await resizeImage(file, 2048, 2048);
                const reader = new FileReader();
                return new Promise<ImageFile>(res => {
                    reader.onloadend = () => res({ base64: (reader.result as string).split(',')[1], mimeType: resized.type, name: resized.name });
                    reader.readAsDataURL(resized);
                });
            }));

            setProject(s => {
                const newBase = [...s.baseImages];
                let upIdx = 0;
                for (let i = 0; i < 6 && upIdx < uploaded.length; i++) {
                    if (!newBase[i]) {
                        newBase[i] = uploaded[upIdx];
                        upIdx++;
                    }
                }
                return { ...s, baseImages: newBase, isUploading: false };
            });
        } catch (err) {
            setProject(s => ({ ...s, isUploading: false, error: "Upload failed" }));
        }
    };

    const handleFontUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const files = Array.from(e.target.files || []) as File[];
        for (const file of files) {
            try {
                const fontName = file.name.split('.')[0];
                const reader = new FileReader();
                reader.onload = async (event) => {
                    const data = event.target?.result;
                    if (data) {
                        const fontFace = new FontFace(fontName, data as ArrayBuffer);
                        const loadedFace = await fontFace.load();
                        document.fonts.add(loadedFace);
                        setCustomFonts(prev => [...new Set([...prev, fontName])]);
                    }
                };
                reader.readAsArrayBuffer(file);
            } catch (err) { console.error(err); }
        }
    };

    const handleGlobalAssetUpload = async (files: File[]) => {
        if (!files || files.length === 0) return;
        try {
            const uploaded = await Promise.all(files.map(async file => {
                const resized = await resizeImage(file, 1024, 1024);
                const reader = new FileReader();
                return new Promise<GlobalLayer>(res => {
                    reader.onloadend = () => {
                        const base64 = (reader.result as string).split(',')[1];
                        res({ 
                            id: Math.random().toString(36).substr(2, 9),
                            file: { base64, mimeType: resized.type, name: resized.name },
                            scale: 20,
                            x: 50,
                            y: 50
                        });
                    };
                    reader.readAsDataURL(resized);
                });
            }));
            setProject(s => ({ ...s, globalLayers: [...s.globalLayers, ...uploaded] }));
        } catch (err) { console.error(err); }
    };

    const updateSlotText = (slotIdx: number, textId: string, updates: Partial<LocalText>) => {
        setProject(s => {
            const texts = s.localTexts[slotIdx] || [];
            const updated = texts.map(t => t.id === textId ? { ...t, ...updates } : t);
            return { ...s, localTexts: { ...s.localTexts, [slotIdx]: updated } };
        });
    };

    const deleteSlotText = (slotIdx: number, textId: string) => {
        setProject(s => {
            const texts = (s.localTexts[slotIdx] || []).filter(t => t.id !== textId);
            return { ...s, localTexts: { ...s.localTexts, [slotIdx]: texts } };
        });
        if (selectedTextId === textId) setSelectedTextId(null);
    };

    const handleDownload = (idx: number, resolution: '2k' | '4k') => {
        const imgFile = project.baseImages[idx];
        const container = containerRefs.current[idx];
        if (!imgFile || !container) return;

        setIsDownloading(`${idx}-${resolution}`);
        const img = new Image();
        img.src = `data:${imgFile.mimeType};base64,${imgFile.base64}`;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const ctx = canvas.getContext('2d');
            if (!ctx) return;
            const targetWidth = resolution === '4k' ? 4096 : 2048;
            canvas.width = targetWidth;
            canvas.height = targetWidth * (img.height / img.width);
            const previewWidth = container.offsetWidth;
            const scaleMultiplier = targetWidth / previewWidth;

            const activeLut = LUTS.find(l => l.name === project.adjustments.lut);
            const sharpness = project.adjustments.sharpness / 100;
            ctx.filter = `${activeLut?.filter || ''} contrast(${1 + (sharpness - 1) * 0.2}) brightness(${1 + (sharpness - 1) * 0.05})`;
            ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
            ctx.filter = 'none';

            const renderLayers = async () => {
                for (const layer of project.globalLayers) {
                    await new Promise<void>(res => {
                        const lImg = new Image();
                        lImg.src = `data:${layer.file.mimeType};base64,${layer.file.base64}`;
                        lImg.onload = () => {
                            const scale = (layer.scale / 100) * canvas.width;
                            const aspect = lImg.width / lImg.height;
                            const drawW = scale;
                            const drawH = scale / aspect;
                            ctx.drawImage(lImg, (layer.x / 100) * canvas.width - drawW/2, (layer.y / 100) * canvas.height - drawH/2, drawW, drawH);
                            res();
                        };
                    });
                }

                const texts = project.localTexts[idx] || [];
                texts.forEach(text => {
                    if (!text.isVisible) return;
                    ctx.save();
                    ctx.translate((text.x / 100) * canvas.width, (text.y / 100) * canvas.height);
                    ctx.rotate((text.rotation * Math.PI) / 180);
                    ctx.fillStyle = text.color;
                    const scaledFontSize = text.fontSize * scaleMultiplier;
                    ctx.font = `${text.fontWeight} ${scaledFontSize}px ${text.fontFamily}`;
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';
                    ctx.shadowColor = 'rgba(0,0,0,0.5)';
                    ctx.shadowBlur = 10 * (scaleMultiplier * (previewWidth / 1000));
                    ctx.shadowOffsetY = 4 * (scaleMultiplier * (previewWidth / 1000));

                    const lines = text.content.split('\n');
                    const lineHeight = scaledFontSize * 1.15;
                    const totalHeight = lineHeight * (lines.length - 1);
                    lines.forEach((line, i) => {
                        const yOffset = (i * lineHeight) - (totalHeight / 2);
                        ctx.fillText(line, 0, yOffset);
                    });
                    ctx.restore();
                });

                const link = document.createElement('a');
                link.download = `Jenta-Edit-${idx + 1}-${resolution}.png`;
                link.href = canvas.toDataURL('image/png');
                link.click();
                setIsDownloading(null);
            };
            renderLayers();
        };
    };

    const activeLut = LUTS.find(l => l.name === project.adjustments.lut);
    const sharpness = project.adjustments.sharpness / 100;
    const filterStyle = { filter: `${activeLut?.filter || ''} contrast(${1 + (sharpness - 1) * 0.2}) brightness(${1 + (sharpness - 1) * 0.05})` };

    const selectedLayer = project.globalLayers.find(l => l.id === selectedLayerId);
    const activeSlotTexts = activeSlotIdx !== null ? (project.localTexts[activeSlotIdx] || []) : [];
    const selectedText = activeSlotTexts.find(t => t.id === selectedTextId) || null;

    return (
        <main className="w-full flex flex-col lg:flex-row gap-8 pt-4 pb-20 animate-in fade-in duration-500 items-start">

            <div className="lg:w-[450px] lg:order-2 flex-shrink-0">
