                                                className={`flex items-center justify-between p-3 rounded-xl cursor-pointer border transition-all ${selectedTextId === txt.id ? 'bg-[rgba(var(--color-accent-rgb),0.15)] border-[var(--color-accent)]' : 'bg-white/5 border-transparent hover:bg-white/10'}`}
