                                        <TextIcon />
                                    </div>
                                    <p className="text-xs text-white/30 font-medium italic">Select a photo from the grid to design</p>
                                </div>
                            )}
                        </div>

                        <div className="pb-4">
                            <label className="text-[10px] font-bold text-white/40 uppercase tracking-widest ml-1 mb-4 block">Graphic Overlays (Logo)</label>
                            <div className="flex flex-wrap gap-3 mb-6">
                                {project.globalLayers.map(layer => (
                                    <div key={layer.id} className="relative group/l">
                                        <div 
                                            onClick={() => setSelectedLayerId(layer.id)}
                                            className={`w-14 h-14 rounded-xl border-2 overflow-hidden cursor-pointer transition-all ${selectedLayerId === layer.id ? 'border-[var(--color-accent)] scale-110 shadow-xl' : 'border-white/10 opacity-50 hover:opacity-100'}`}
                                        >
                                            <img src={`data:${layer.file.mimeType};base64,${layer.file.base64}`} className="w-full h-full object-contain bg-black/20" />
                                        </div>
                                        <button onClick={() => setProject(s => ({ ...s, globalLayers: s.globalLayers.filter(l => l.id !== layer.id) }))} className="absolute -top-1.5 -right-1.5 bg-red-500 text-white rounded-full p-1 opacity-0 group-hover/l:opacity-100 transition-all transform scale-75 hover:scale-100 shadow-lg"><XIcon /></button>
                                    </div>
                                ))}
                                <label className="w-14 h-14 rounded-xl border-2 border-dashed border-white/10 flex items-center justify-center cursor-pointer hover:border-white/30 transition-all bg-white/5">
                                    <PlusIcon />
                                    <input type="file" multiple className="hidden" accept="image/*" onChange={(e) => handleGlobalAssetUpload(Array.from(e.target.files || []))} />
                                </label>
                            </div>

                            {selectedLayer && (
                                <div className="space-y-4 p-5 bg-white/5 rounded-3xl border border-white/5 animate-in slide-in-from-top-3">
                                    <div className="flex justify-between items-center mb-1">
                                        <label className="text-[10px] font-black text-white/40 uppercase tracking-widest">Transform Logo</label>
                                        <button onClick={() => setSelectedLayerId(null)} className="text-[9px] text-white/40 hover:text-white">Close</button>
                                    </div>
                                    <div className="space-y-4">
                                        <div className="space-y-2">
                                            <div className="flex justify-between text-[9px] font-bold text-white/60"><span>Scale</span><span>{selectedLayer.scale}%</span></div>
                                            <input type="range" min="5" max="100" value={selectedLayer.scale} onChange={e => setProject(s => ({...s, globalLayers: s.globalLayers.map(l => l.id === selectedLayerId ? {...l, scale: parseInt(e.target.value)} : l)}))} className="w-full h-1 accent-white bg-white/10 rounded-full appearance-none" />
                                        </div>
                                        <div className="grid grid-cols-2 gap-4">
                                            <div className="space-y-2">
                                                <div className="flex justify-between text-[9px] font-bold text-white/60"><span>X-Pos</span><span>{selectedLayer.x}%</span></div>
                                                <input type="range" min="0" max="100" value={selectedLayer.x} onChange={e => setProject(s => ({...s, globalLayers: s.globalLayers.map(l => l.id === selectedLayerId ? {...l, x: parseInt(e.target.value)} : l)}))} className="w-full h-1 accent-white bg-white/10 rounded-full appearance-none" />
                                            </div>
                                            <div className="space-y-2">
                                                <div className="flex justify-between text-[9px] font-bold text-white/60"><span>Y-Pos</span><span>{selectedLayer.y}%</span></div>
                                                <input type="range" min="0" max="100" value={selectedLayer.y} onChange={e => setProject(s => ({...s, globalLayers: s.globalLayers.map(l => l.id === selectedLayerId ? {...l, y: parseInt(e.target.value)} : l)}))} className="w-full h-1 accent-white bg-white/10 rounded-full appearance-none" />
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>

            <div className="flex-grow lg:order-1 min-w-0">
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                    {project.baseImages.map((img, idx) => {
                        const currentTexts = project.localTexts[idx] || [];
                        const committedTexts = project.committedTexts[idx] || [];
                        const isModified = JSON.stringify(currentTexts) !== JSON.stringify(committedTexts);

                        return (
                            <div key={idx} className="flex flex-col gap-4 animate-in fade-in duration-700" style={{ animationDelay: `${idx * 100}ms` }}>

                                <div className="flex justify-between items-center px-1">
                                    <div className="flex items-center gap-3">
                                        <span className="text-[10px] font-black text-white/40 uppercase tracking-[0.3em]">Slot 0{idx + 1}</span>
                                        {isModified && (
                                            <span className="text-[8px] font-black text-[var(--color-accent)] uppercase animate-pulse">Unsaved Changes</span>
                                        )}
                                        {justSavedSlot === idx && (
                                            <span className="text-[8px] font-black text-emerald-400 uppercase">Changes Saved!</span>
                                        )}
                                    </div>
                                    {clipboard && activeSlotIdx === idx && !selectedTextId && (
                                        <span className="text-[9px] font-black text-emerald-400 uppercase tracking-widest animate-pulse flex items-center gap-1.5">
                                            <div className="w-1 h-1 bg-emerald-400 rounded-full"></div> Paste Ready
                                        </span>
                                    )}
                                </div>

                                <div 
                                    ref={el => containerRefs.current[idx] = el}
                                    onClick={() => setActiveSlotIdx(idx)}
                                    className={`glass-card rounded-2xl overflow-hidden relative bg-black/40 shadow-2xl border transition-all duration-500 cursor-pointer group/slot w-full ${activeSlotIdx === idx ? 'border-[var(--color-accent)] ring-4 ring-[var(--color-accent)]/10 scale-[1.01]' : 'border-white/5 hover:border-white/10'}`}
                                >
                                    {img ? (
                                        <div className={`w-full relative transition-opacity duration-300 ${justSavedSlot === idx ? 'opacity-50' : 'opacity-100'}`}>
                                            <img src={`data:${img.mimeType};base64,${img.base64}`} className="w-full h-auto block select-none pointer-events-none" style={filterStyle} />

                                            {project.globalLayers.map(layer => (
                                                <div key={layer.id} style={{ position: 'absolute', left: `${layer.x}%`, top: `${layer.y}%`, width: `${layer.scale}%`, transform: 'translate(-50%, -50%)', pointerEvents: 'none', zIndex: 5 }}>
                                                    <img src={`data:${layer.file.mimeType};base64,${layer.file.base64}`} className="w-full h-auto drop-shadow-2xl" />
                                                </div>
                                            ))}

                                            {currentTexts.map(text => (
                                                text.isVisible && (
                                                    <div 
                                                        key={text.id}
                                                        style={{
                                                            position: 'absolute', left: `${text.x}%`, top: `${text.y}%`,
                                                            transform: `translate(-50%, -50%) rotate(${text.rotation}deg)`,
                                                            color: text.color, fontSize: `${text.fontSize}px`,
                                                            fontFamily: text.fontFamily, fontWeight: text.fontWeight,
                                                            textAlign: 'center', textShadow: '0 4px 16px rgba(0,0,0,0.6)', zIndex: 10,
                                                            whiteSpace: 'pre-wrap', touchAction: 'none', lineHeight: '1.1'
                                                        }}
                                                        onPointerDown={(e) => { 
                                                            e.stopPropagation(); 
                                                            setSelectedTextId(text.id);
                                                            setDraggingId(text.id);
                                                            setDraggingSlot(idx);
                                                            setActiveSlotIdx(idx);
                                                            (e.target as HTMLElement).setPointerCapture(e.pointerId); 
                                                        }}
                                                        onPointerMove={(e) => {
                                                            if (draggingId !== text.id || draggingSlot !== idx) return;
                                                            const rect = containerRefs.current[idx]!.getBoundingClientRect();
                                                            const x = ((e.clientX - rect.left) / rect.width) * 100;
                                                            const y = ((e.clientY - rect.top) / rect.height) * 100;
                                                            updateSlotText(idx, text.id, { x: Math.max(0, Math.min(100, x)), y: Math.max(0, Math.min(100, y)) });
                                                        }}
                                                        onPointerUp={() => { setDraggingId(null); setDraggingSlot(null); }}
                                                        className={`px-6 py-3 border-2 rounded-2xl cursor-move select-none transition-all ${selectedTextId === text.id ? 'border-[var(--color-accent)] bg-[var(--color-accent)]/5 ring-4 ring-[var(--color-accent)]/20' : 'border-transparent hover:border-white/30 hover:bg-white/5'}`}
                                                    >
                                                        {text.content}
                                                    </div>
                                                )
                                            ))}
                                        </div>
                                    ) : (
                                        <div className="w-full aspect-square flex flex-col items-center justify-center p-8 gap-4 opacity-30 group transition-all">
                                            <div className="w-16 h-16 rounded-full border-2 border-dashed border-white/40 flex items-center justify-center group-hover:scale-110 group-hover:border-white group-hover:bg-white/5 transition-all duration-500">
                                                <PlusIcon />
