        <div className="flex flex-col gap-2">
            <span className="text-[9px] font-black text-white/30 uppercase tracking-widest ml-1">Step 2: Accent Rim Light</span>
            <div className="flex flex-wrap gap-1.5">
                {STOCK_COLORS.map((color) => (
                    <button
                        key={color.label}
                        onClick={() => onApplyRimColor?.(color.text)}
                        className="group flex items-center gap-2 px-3 py-1.5 bg-black/40 hover:bg-black/60 border border-white/5 hover:border-[var(--color-accent)]/50 rounded-full transition-all"
                        title={`Select ${color.label} lighting`}
                    >
                        <div className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: color.hex, boxShadow: `0 0 8px ${color.hex}66` }}></div>
                        <span className="text-[10px] font-bold text-white/50 group-hover:text-white uppercase">{color.label}</span>
                    </button>
                ))}
            </div>
        </div>
      </div>

      {(isTranslating || translatedPrompt) && (
        <div className="mt-2 p-3 glass-input rounded-lg bg-black/10 border-emerald-500/20">
            <div className="flex justify-between items-center mb-2">
                <h4 className="text-[10px] font-black text-emerald-400 uppercase tracking-widest flex items-center gap-1.5">
                    <SwapIcon /> Translation Intelligence
                </h4>
                {isTranslating && <TranslationSpinner />}
            </div>
            {translatedPrompt && !isTranslating && (
            <div className="flex flex-col gap-3">
                <p className="text-xs text-[var(--color-text-base)] italic opacity-80 leading-relaxed">{translatedPrompt}</p>
                <div className="flex items-center gap-2">
                    <button
                        onClick={() => onUseTranslation(translatedPrompt)}
                        className="flex items-center text-[10px] px-3 py-1.5 rounded-md bg-emerald-500/20 text-emerald-400 hover:bg-emerald-500/30 transition-colors font-black uppercase"
                    >
                        <CheckIcon /> Apply to Prompt
                    </button>
                    <button
