                                </label>
                                <select 
                                    value={project.targetMarket}
                                    onChange={(e) => setProject(s => ({ ...s, targetMarket: e.target.value }))}
                                    className="bg-transparent border-none p-0 text-sm font-bold text-white focus:ring-0 cursor-pointer"
